import type { ForecastPreset } from '@content/weather'
import { TICK_RATE, type Rng } from '../core'
import { WEATHER_TUNING } from './tuning'
import type { Sky } from './types'

// The sky (F-601): a chain over the four skies in which the sky stays for a random time and then moves to a
// neighbour, never further. How long it stays and which way it goes are the forecast's.

/** The skies from the driest to the wettest. A sky's place here is its number wherever it is hashed. */
export const SKIES: readonly Sky[] = ['sunny', 'cloudy', 'light-rain', 'heavy-rain']

/** How many steps apart two skies are in that order. */
export function skySteps(from: Sky, to: Sky): number {
  return Math.abs(SKIES.indexOf(to) - SKIES.indexOf(from))
}

/**
 * The sky that follows `sky` under the forecast: its drier or its wetter neighbour by the forecast's odds, or the
 * only neighbour there is at either end. Null when the forecast gives it nowhere to go, so that it stays.
 */
export function nextSky(preset: ForecastPreset, sky: Sky, rng: Rng): Sky | null {
  const at = SKIES.indexOf(sky)
  const odds = preset.drift[sky]
  const drier = at > 0 ? Math.max(0, odds.drier) : 0
  const wetter = at < SKIES.length - 1 ? Math.max(0, odds.wetter) : 0
  if (drier + wetter <= 0) return null
  return rng.next() * (drier + wetter) < drier ? SKIES[at - 1] : SKIES[at + 1]
}

/**
 * How long a sky that has just begun stays, s: never less than the least time a sky lasts, and beyond that
 * exponentially distributed, with the forecast's mean for the whole. A sky whose mean is shorter than twice the
 * least time has half its mean for a least time.
 */
export function drawDwellS(preset: ForecastPreset, sky: Sky, rng: Rng): number {
  const mean = Math.max(0, preset.dwellS[sky])
  const least = Math.min(WEATHER_TUNING.sky.minDwellS, mean / 2)
  return least - (mean - least) * Math.log(1 - rng.next())
}

/** The sky as it stands, and how long it has left. */
export interface SkyChain {
  sky: Sky
  /** Ticks until the sky changes; counted down once a tick. */
  ticksLeft: number
}

export function createSkyChain(preset: ForecastPreset, sky: Sky, rng: Rng): SkyChain {
  return { sky, ticksLeft: dwellTicks(preset, sky, rng) }
}

function dwellTicks(preset: ForecastPreset, sky: Sky, rng: Rng): number {
  return Math.max(1, Math.round(drawDwellS(preset, sky, rng) * TICK_RATE))
}

/**
 * One tick of the sky. Returns the sky it changed from on the tick it changes, else null. A sky with nowhere to go
 * under the forecast begins another stay of its own.
 */
export function stepSky(chain: SkyChain, preset: ForecastPreset, rng: Rng): Sky | null {
  chain.ticksLeft -= 1
  if (chain.ticksLeft > 0) return null
  const from = chain.sky
  const to = nextSky(preset, from, rng)
  if (to !== null) chain.sky = to
  chain.ticksLeft = dwellTicks(preset, chain.sky, rng)
  return to === null ? null : from
}

/** Puts the sky where it is told to be (the development seam, and a session's first sky), with a new stay ahead of it. */
export function setSky(chain: SkyChain, preset: ForecastPreset, sky: Sky, rng: Rng): void {
  chain.sky = sky
  chain.ticksLeft = dwellTicks(preset, sky, rng)
}
