import { clamp, DT, type CarId, type Vec2 } from '../core'
import type { ControlInput } from '../session/controls'
import type { CarSnapshot } from '../session/types'
import type { CarParams } from '../vehicle/types'
import { steerToward } from './pursuit'
import type { LinePoint, RacingLine } from './racing-line'
import { carLimits } from './speed-profile'
import { AI_TUNING } from './tuning'

// What drives a car once it has finished (F-303): not a racing driver but a small controller that takes the car
// over as it crosses the line, chooses a place ahead where a car can stand at the side of the lane with the
// racing line clear, rolls it there and stops it. Finished cars fill the places from the far end back, at the
// edge of the lane first and then in a second row inside it, so that each parks behind the ones before it. It
// sees what a driver sees, the session's snapshot, and gives back pedals and steering. Any car has one, the
// human's too. Everything it remembers is in the object `createPullOver` returns, and it draws no random numbers.

export interface PullOver {
  /**
   * One tick of a finished car. `all` is every car of the session, this one included. The first call is the
   * moment it takes the car over. `grip` is what the asphalt at the side of the lane has of its dry grip (F-604);
   * left out, it is dry. The object returned is reused by the next call.
   */
  control(self: CarSnapshot, all: readonly CarSnapshot[], grip?: number): ControlInput
  /** Appends everything the controller remembers between ticks, in a fixed order. */
  hashInto(buffer: number[]): void
}

/** The place a finished car means to stand: where, how far along the line that is, and how far to the line's right. */
export interface ParkingPlace extends Vec2 {
  s: number
  lateralM: number
}

/**
 * The places the finished cars of one session have chosen, by car id; null for a car that has not chosen. Shared
 * by the session's controllers, so that no two choose the same place.
 */
export type ParkingBoard = Array<ParkingPlace | null>

const P = AI_TUNING.pullOver
const X = AI_TUNING.traffic
/** The two sides of the line, the roomier first; and the rows on a side: 0 at the edge of the lane, 1 inside the cars that stand there. */
const RIGHT_FIRST: readonly number[] = Object.freeze([1, -1])
const LEFT_FIRST: readonly number[] = Object.freeze([-1, 1])
const ROWS: readonly number[] = Object.freeze([0, 1])
/** The two ways across to a place: at once, or as late as will still get there (to go by cars parked on the way). */
const WAYS: readonly boolean[] = Object.freeze([false, true])

/** A controller for car `id`, parking clear of `line`, that writes the place it chooses on `board` and keeps off the others'. */
export function createPullOver(id: CarId, car: CarParams, line: RacingLine, board: ParkingBoard): PullOver {
  const points = line.points
  const count = points.length
  const limits = carLimits(car, 1)
  const brakeMS2 = limits.brakeMS2(0, 0, 1)
  /** The most it corners at on its way, m/s²: a share of what the tyres can do. */
  let bendMS2 = P.bendShare * limits.lateralMS2
  /** How hard it slows for its place, and for a car in its way, m/s²: shares of what the car's brakes can do. */
  let slowingMS2 = P.slowingShare * brakeMS2
  let hardMS2 = P.hardSlowingShare * brakeMS2
  /** Two cars whose centres are this far apart sideways do not touch, m. */
  const clearM = car.widthM + X.touchClearM
  /** A car standing at the side leaves the line clear when the line is at least this far from where its centre is, m. */
  const needM = car.widthM + P.clearOfLineM
  /** From one parked car's centre to the next, m, nose to tail; and from one row to the next. */
  const pitchM = car.lengthM + P.gapM
  const rowM = car.widthM + P.rowGapM
  const halfCarPoints = Math.ceil(car.lengthM / 2 / line.stepM)
  /** A place has to be clear of the line over the length of a car and a little either way: it may stop a little off it. */
  const standPoints = Math.ceil((car.lengthM / 2 + P.stopSlackM) / line.stepM)
  /** How far across the lane it gets for each step along the line. */
  const stepAcrossM = P.acrossShare * P.acrossUse * line.stepM
  const furthestPoints = Math.round(P.aheadM / line.stepM)
  const settlePoints = Math.round(P.settleM / line.stepM)
  /** The brake may be held this many ticks below the speed at which it turns into reverse, and no longer. */
  const brakeSlowTicks = Math.floor((car.shaping.reverseAfterS * P.reverseGuardShare) / DT)

  /** Ticks since it took the car over; zero until it has. */
  let ticks = 0
  /** The speed it rolls the car to its place at, m/s: the speed the car finished at, or `rollMS` if that is more. */
  let rollMS = 0
  /**
   * Where it means the car to stand, as the board has it: how far along the line, m, how far to the line's right,
   * and the place itself. `chosen` once it has a place.
   */
  let chosen = false
  let stopS = 0
  let standM = 0
  let standX = 0
  let standY = 0
  /** It goes across to its place as late as it can, to go by the cars parked on the way. */
  let late = false
  /** Whether the place can be reached in the time a finished car has to come to rest. If not, it takes the time it needs. */
  let inTime = true
  /** Where it means the car to be by now, to the right of the line, m. It moves toward its place at a limited rate. */
  let offsetM = 0
  /** For how many ticks running the brake has been held with the car all but stopped. */
  let slowTicks = 0
  /** For how many ticks running the car has stood still short of its place, held up by another. */
  let waitTicks = 0
  /** The car has come to rest for good, and the board has where it stands and not where it meant to. */
  let settled = false
  /** It has had to start again from a standstill at least once. */
  let again = false

  const target: Vec2 = { x: 0, y: 0 }
  const out: ControlInput = { throttle: 0, brake: 0, steer: 0 }
  // The way to the place being tried: how far to the line's right the car is at each step along the line.
  const way = new Float64Array(furthestPoints + 1)
  // What stands in the way of a choice: the places other cars have taken, and cars that are standing still.
  let taken = 0
  const takenAhead: number[] = []
  const takenLateral: number[] = []
  const takenX: number[] = []
  const takenY: number[] = []

  /** A distance along the line, taken the short way round: positive ahead. */
  const ahead = (fromS: number, toS: number): number => {
    const gap = (((toS - fromS) % line.lengthM) + line.lengthM) % line.lengthM
    return gap > line.lengthM / 2 ? gap - line.lengthM : gap
  }
  const pointAt = (index: number): LinePoint => points[((index % count) + count) % count]
  /** Where a car's centre stands at a point of the line, on one side (-1 left, 1 right) and in one row: that far to the line's right. */
  const standsAt = (point: LinePoint, toSide: number, row: number): number => (toSide > 0 ? point.roomRightM : -point.roomLeftM) - toSide * row * rowM

  /**
   * Whether the car can stand `k` steps of the line on from point `first`, `atM` to the line's right, getting there
   * in `withinM` of driving by going across at once or as late as it can: the car can get across by then; on the way
   * it goes by every place that is taken with room to spare; and the place itself overlaps none. Leaves the way in
   * `way` and where the place is in `standX` and `standY`.
   */
  const canReach = (first: number, k: number, atM: number, lateralM: number, goLate: boolean, withinM: number): boolean => {
    // Off the line a bend is longer round the outside and shorter round the inside, so the way is not as long as the line.
    let acrossM = lateralM
    let wayM = 0
    for (let j = 0; j < k; j++) {
      way[j] = acrossM
      const on = pointAt(first + j)
      // Going late, it stays where it is across the lane for as long as what is left will still get it there, and
      // either way it is to be there a little before its place, to straighten up in.
      const reachM = Math.max(0, k - settlePoints - j - 1) * stepAcrossM
      const toward = goLate ? clamp(acrossM, atM - reachM, atM + reachM) : atM
      const next = clamp(acrossM + clamp(toward - acrossM, -stepAcrossM, stepAcrossM), -on.roomLeftM, on.roomRightM)
      wayM += Math.hypot(line.stepM * Math.max(P.leastPathShare, 1 - on.curvature * acrossM), next - acrossM)
      acrossM = next
    }
    way[k] = acrossM
    if (Math.abs(way[Math.max(0, k - settlePoints)] - atM) > P.nearEnoughM || Math.abs(acrossM - atM) > P.nearEnoughM || wayM > withinM) return false

    const point = pointAt(first + k)
    const cos = Math.cos(point.headingRad)
    const sin = Math.sin(point.headingRad)
    standX = point.x - sin * atM
    standY = point.y + cos * atM
    for (let o = 0; o < taken; o++) {
      const dx = takenX[o] - standX
      const dy = takenY[o] - standY
      if (Math.abs(dx * cos + dy * sin) < pitchM && Math.abs(-dx * sin + dy * cos) < rowM - P.rowSlackM) return false
      // Going by it: clear of it sideways from its tail to its nose.
      const at = Math.round(takenAhead[o] / line.stepM)
      if (at <= 0 || at >= k - halfCarPoints) continue
      for (let j = Math.max(0, at - halfCarPoints); j <= at + halfCarPoints; j += halfCarPoints) {
        if (Math.abs(way[j] - takenLateral[o]) < clearM + P.passClearM) return false
      }
    }
    return true
  }

  /**
   * Chooses where to stand. First the furthest place ahead that the car can reach and stop at in the time it has:
   * at the edge of the lane if there is one, else in the row inside that. With none, or when it is starting again
   * from a standstill, the nearest it can stand at, however long that takes: a car left on the racing line is
   * worse than one that is late to rest.
   * With none at all, it stops as soon as it comfortably can, on the side with more room. A place has to be far
   * enough from the line, over the length of a car, for the line to be clear.
   */
  const choose = (s: number, lateralM: number, leftS: number): void => {
    const first = line.indexAt(s)
    const nearest = Math.ceil((rollMS * P.brakeLagS + (rollMS * rollMS) / (2 * slowingMS2)) / line.stepM)
    // Holding its speed and then slowing, this is as far as it gets in the time it has left.
    const reachM = rollMS * (leftS - rollMS / (2 * slowingMS2))
    const furthest = Math.min(furthestPoints, Math.floor(reachM / (line.stepM * P.leastPathShare)))
    const tryAt = (k: number, row: number, withinM: number): boolean => {
      const point = pointAt(first + k)
      for (const toSide of point.roomRightM > point.roomLeftM ? RIGHT_FIRST : LEFT_FIRST) {
        const atM = standsAt(point, toSide, row)
        if (atM * toSide < needM || standsAt(pointAt(first + k - standPoints), toSide, row) * toSide < needM || standsAt(pointAt(first + k + standPoints), toSide, row) * toSide < needM) continue
        for (const goLate of WAYS) {
          if (!canReach(first, k, atM, lateralM, goLate, withinM)) continue
          stopS = point.s
          standM = atM
          late = goLate
          return true
        }
      }
      return false
    }
    // Starting again from a standstill it wants the nearest place, not the furthest: it is in the way where it is.
    inTime = !again
    if (inTime) for (const row of ROWS) for (let k = furthest; k >= nearest; k--) if (tryAt(k, row, reachM)) return
    inTime = false
    for (let k = nearest; k <= furthestPoints; k++) for (const row of ROWS) if (tryAt(k, row, Infinity)) return
    const point = pointAt(first + nearest)
    stopS = point.s
    standM = standsAt(point, point.roomRightM > point.roomLeftM ? 1 : -1, 0)
    standX = point.x - Math.sin(point.headingRad) * standM
    standY = point.y + Math.cos(point.headingRad) * standM
    late = false
  }

  /**
   * The most speed the car may have at `s` if it is to be slow enough for every bend of the line ahead by the time
   * it is there: each point's own speed for its curvature, and what the brakes it slows with can shed on the way to it.
   */
  const bendLimitMS = (s: number, speedMS: number): number => {
    const first = line.indexAt(s)
    const reach = Math.min(furthestPoints, Math.ceil((speedMS * speedMS) / (2 * slowingMS2) / line.stepM) + 1)
    let most = Infinity
    for (let k = 0; k <= reach; k++) {
      const bend = Math.abs(pointAt(first + k).curvature)
      if (bend <= 0) continue
      most = Math.min(most, Math.sqrt(bendMS2 / bend + 2 * slowingMS2 * k * line.stepM))
    }
    return most
  }

  return {
    control(self, all, grip = 1) {
      // On a wet track the tyres have that much less of everything: it corners and slows by the grip there is.
      bendMS2 = P.bendShare * limits.lateralMS2 * grip
      slowingMS2 = P.slowingShare * brakeMS2 * grip
      hardMS2 = P.hardSlowingShare * brakeMS2 * grip
      const near = line.nearest(self.pose.x, self.pose.y, line.sAtRoute(self.routeS))
      const s = near.s
      const lateralM = near.lateralM
      const speedNow = Math.max(0, self.speedMS)
      if (ticks === 0) {
        rollMS = Math.max(speedNow, P.rollMS)
        offsetM = lateralM
      }
      ticks++
      const leftS = P.restByS - ticks * DT

      // Where it is going: chosen as it takes the car over.
      if (!chosen) {
        taken = 0
        for (const other of all) {
          if (other.id === id) continue
          const place = board[other.id]
          if (place === null && Math.abs(other.speedMS) >= X.stationaryMS) continue
          const its = place ?? line.nearest(other.pose.x, other.pose.y, line.sAtRoute(other.routeS))
          takenAhead[taken] = ahead(s, its.s)
          takenLateral[taken] = its.lateralM
          takenX[taken] = place === null ? other.pose.x : place.x
          takenY[taken] = place === null ? other.pose.y : place.y
          taken++
        }
        choose(s, lateralM, leftS)
        chosen = true
        board[id] = { x: standX, y: standY, s: stopS, lateralM: standM }
      }

      // At its rolling speed until it has to slow for its place, and at rest by the time it has if the place allows.
      // What is left of the way is longer or shorter than it is along the line, by where the car is across the bend.
      const here = points[line.indexAt(s)]
      const toStopM = Math.max(0, ahead(s, stopS))
      const leftM = Math.max(0, toStopM * Math.max(P.leastPathShare, 1 - here.curvature * lateralM) - speedNow * P.brakeLagS)
      let wantedMS = Math.min(rollMS, Math.sqrt(2 * slowingMS2 * leftM))
      // Never while it is still on the line, though: there it keeps going to its place.
      if (inTime && Math.abs(lateralM) >= needM) wantedMS = Math.min(wantedMS, slowingMS2 * Math.max(0, leftS))
      // Once it stands still with nowhere further to go, or has waited long enough behind a car that is not going
      // to move, that is where it is parked, so long as the line is clear of it there: the board is told, so that
      // the cars still to come choose around it. Standing too near the line, because its way was blocked or because
      // it has been pushed there since it parked, it starts again from where it stands and goes on to another place.
      const still = speedNow < P.stillMS
      if (still && (settled || wantedMS === 0 || waitTicks >= P.waitS / DT)) {
        if (Math.abs(lateralM) < P.leastFromLineM) {
          ticks = 0
          chosen = false
          again = true
          settled = false
          waitTicks = 0
          slowTicks = 0
          board[id] = null
          out.throttle = 0
          out.brake = 0
          out.steer = 0
          return out
        }
        // Parked; or parked already and pushed to somewhere else that will do.
        if (!settled || Math.hypot(self.pose.x - standX, self.pose.y - standY) > P.pushedM) {
          settled = true
          stopS = s
          standM = lateralM
          standX = self.pose.x
          standY = self.pose.y
          board[id] = { x: standX, y: standY, s: stopS, lateralM: standM }
        }
      }
      if (settled) wantedMS = 0
      waitTicks = still && !settled ? waitTicks + 1 : 0

      // Across to its place: at once, or only when what is left of the way is just enough to get across in.
      const slope = P.acrossShare * P.acrossUse
      const holdM = late ? Math.max(0, toStopM - P.settleM - Math.abs(standM - offsetM) / slope) : 0
      const cos = Math.cos(self.pose.angle)
      const sin = Math.sin(self.pose.angle)
      let least = -Infinity
      let most = Infinity
      for (const other of all) {
        if (other.id === self.id) continue
        const dx = other.pose.x - self.pose.x
        const dy = other.pose.y - self.pose.y
        const apartM = Math.hypot(dx, dy)
        if (apartM > P.aheadM) continue
        const its = line.nearest(other.pose.x, other.pose.y, line.sAtRoute(other.routeS))
        const gapM = ahead(s, its.s)
        // In its way: ahead of it, short of its place, and where the car will be across the lane by then; or right
        // in front of it now. It stops behind.
        if (gapM > 0 && gapM <= toStopM + pitchM) {
          const byThenM = Math.max(0, gapM - holdM) * slope
          if (Math.abs(its.lateralM - (offsetM + clamp(standM - offsetM, -byThenM, byThenM))) < clearM || (gapM < P.nearM && Math.abs(its.lateralM - lateralM) < clearM)) {
            // With room in hand, as fast as will still stop short of it; with none, slower than it is going, to open the gap.
            const roomM = apartM - car.lengthM - P.gapM
            const itsSpeed = Math.max(0, other.speedMS)
            wantedMS = Math.min(wantedMS, roomM > 0 ? Math.sqrt(itsSpeed * itsSpeed + 2 * hardMS2 * roomM) : Math.max(0, itsSpeed + X.gapGainPerS * roomM))
          }
        }
        // Alongside, to one side of its nose: not to be moved into.
        const asideM = -dx * sin + dy * cos
        if (Math.abs(dx * cos + dy * sin) <= car.lengthM + X.alongsideM && Math.abs(asideM) >= clearM) {
          if (asideM < 0) least = Math.max(least, lateralM + asideM + clearM)
          else most = Math.min(most, lateralM + asideM - clearM)
        }
      }
      const wantedM = least > most ? lateralM : clamp(holdM > 0 ? offsetM : standM, least, most)
      const acrossM = P.acrossShare * speedNow * DT
      offsetM += clamp(wantedM - offsetM, -acrossM, acrossM)

      const aim = line.at(s + P.lookaheadM)
      const aside = clamp(offsetM, -aim.roomLeftM, aim.roomRightM)
      target.x = aim.x - Math.sin(aim.headingRad) * aside
      target.y = aim.y + Math.cos(aim.headingRad) * aside

      // While it is slowing for its place the brake is held at what that takes, and trimmed by how far off the car
      // is. A brake held with the car all but stopped turns into reverse: below that speed it is held only for a
      // moment, and then the car is left to roll to rest.
      // No faster than the bends of the way ahead allow (F-604). It rolls at the speed the car finished at, and a car
      // that crossed the line flat out, at the apex of a hairpin, would otherwise carry that speed off the lane.
      wantedMS = Math.min(wantedMS, bendLimitMS(s, speedNow))
      const short = wantedMS - speedNow
      const slow = speedNow < car.shaping.reverseBelowMS
      const slowing = wantedMS < rollMS
      const braking = (slowing ? short < P.brakeAheadMS : short < 0) && (!slow || slowTicks < brakeSlowTicks)
      if (braking) slowTicks = slow ? slowTicks + 1 : 0
      out.steer = wantedMS > 0 || !slow ? steerToward(self.pose, self.speedMS, target, car) : 0
      out.throttle = (slowing ? short > P.brakeAheadMS : short > 0) ? Math.min(P.mostThrottle, P.throttlePerMS * short) : 0
      out.brake = braking ? clamp((slowing ? P.slowingShare : 0) + P.brakePerMS * -short, 0, 1) : 0
      return out
    },

    hashInto(buffer) {
      buffer.push(ticks, rollMS, chosen ? 1 : 0, stopS, standM, standX, standY, late ? 1 : 0, inTime ? 1 : 0, offsetM, slowTicks, waitTicks, settled ? 1 : 0, again ? 1 : 0)
    },
  }
}
