import { DT } from '../core'
import { neutralEnvironment } from '../session/stepper'
import { vehicleModel } from './model'
import type { CarParams } from './types'

// What a class does in a straight line, measured by driving it: the figures behind the garage's stat bars.
// A pure function of the resolved car, so a caller computes it once per class and keeps the answer.

export interface ClassFacts {
  /** Speed after `RUN_S` of full throttle on dry asphalt, m/s. */
  topSpeedMS: number
  /** Seconds from a standing start, full throttle from the first tick, to cover 10 m. Infinite if it never does. */
  zeroToTenMetresS: number
}

/** Long enough for every class to be within a hair of its top speed; a measurement window, not a handling number. */
const RUN_S = 20
const SPRINT_M = 10
const FLAT_OUT = { throttle: 1, brake: 0, steer: 0 }

/**
 * Drives the car flat out along +x from rest and reads off its top speed and its time over 10 m. The body is
 * integrated the way the physics world integrates one that touches nothing — velocity from force, then
 * position from the new velocity — so the figures are the ones a car on the track gives.
 */
export function classFacts(p: CarParams): ClassFacts {
  const env = neutralEnvironment()
  const body = { pose: { x: 0, y: 0, angle: 0 }, velocity: { x: 0, y: 0 }, yawRate: 0 }
  let zeroToTenMetresS = Number.POSITIVE_INFINITY
  const ticks = Math.round(RUN_S / DT)
  for (let tick = 0; tick < ticks; tick++) {
    const { fx } = vehicleModel.step(body, FLAT_OUT, p, env, DT)
    const previousX = body.pose.x
    body.velocity.x += (DT * fx) / p.massKg
    body.pose.x += DT * body.velocity.x
    if (zeroToTenMetresS === Number.POSITIVE_INFINITY && body.pose.x >= SPRINT_M) {
      zeroToTenMetresS = (tick + (SPRINT_M - previousX) / (body.pose.x - previousX)) * DT
    }
  }
  return { topSpeedMS: body.velocity.x, zeroToTenMetresS }
}
