import { availableDriveForceN } from '../vehicle/motor'
import { brakedStaticBudgetN, frontAxleDriven, gripLimitMS2, rearAxleDriven, topSpeedMS } from '../vehicle/resolve'
import type { CarParams } from '../vehicle/types'
import type { RacingLine } from './racing-line'
import { AI_TUNING } from './tuning'

// The speed a car can carry along a racing line (F-301): at each point the cornering limit for the bend there, then
// a pass backward round the lap so that no point is entered faster than the brakes can bring the car down to the
// next, and a pass forward so that none is faster than the motor can get it to from the one before. What the car
// can do is read from its resolved parameters; how much of that a driver plans on is the `PacePlan`.

/** How much of the car a driver plans on using. */
export interface PacePlan {
  /** Share of the car's cornering limit that bends are planned at. */
  cornerShare: number
  /** Share of the brake pedal that braking zones are planned at. */
  brakeShare: number
  /** Share of the throttle that the way out of a bend is planned at. */
  driveShare: number
  /** The most speed planned wherever the line has a wheel on a kerb, m/s; `Infinity` for no limit. */
  kerbCapMS: number
}

/** A driver who uses all the planning allows. */
export const FULL_PACE: PacePlan = Object.freeze({
  cornerShare: AI_TUNING.pace.cornerShare[1],
  brakeShare: AI_TUNING.pace.brakeShare[1],
  driveShare: AI_TUNING.pace.driveShare[1],
  kerbCapMS: Infinity,
})

/** What a car can do in a straight line and in a bend, as accelerations, from its resolved parameters and the grip of the day. */
export interface CarLimits {
  /** Cornering limit, m/s². */
  lateralMS2: number
  topSpeedMS: number
  /** Slowing at a speed and a share of the cornering limit in use, with the brake pedal at `share`, m/s². */
  brakeMS2(speedMS: number, lateralUse: number, share: number): number
  /** Speeding up at a speed and a share of the cornering limit in use, with the throttle at `share`, m/s²; may be negative near top speed. */
  driveMS2(speedMS: number, lateralUse: number, share: number): number
  /** The most throttle, 0..1, the driven tyres can take at a speed with a share of the cornering limit in use. */
  throttleRoom(speedMS: number, lateralUse: number): number
  /** The most brake pedal, 0..1, the braked tyres can take with a share of the cornering limit in use. */
  brakeRoom(lateralUse: number): number
}

export function carLimits(car: CarParams, grip: number): CarLimits {
  const weightN = car.massKg * car.gEff
  const frontLoadN = (weightN * car.cgToRearAxleM) / car.wheelbaseM
  const rearLoadN = weightN - frontLoadN
  // What the driven tyres can put down at static loads: all of it for the friction ellipse, the traction share of it for drive.
  const drivenBudgetN = ((frontAxleDriven(car) ? car.muFront * frontLoadN : 0) + (rearAxleDriven(car) ? car.muRear * rearLoadN : 0)) * grip
  const brakedBudgetN = brakedStaticBudgetN(car) * grip
  const resistN = (speedMS: number): number => car.rollForceN + car.aeroK * speedMS * speedMS
  /** What is left of a tyre's grip for driving or braking when a share of it is spent cornering. */
  const left = (lateralUse: number): number => Math.sqrt(Math.max(0, 1 - Math.min(1, lateralUse) ** 2))
  return {
    lateralMS2: gripLimitMS2(car) * grip,
    topSpeedMS: topSpeedMS(car),
    brakeMS2: (speedMS, lateralUse, share) => (Math.min(share * car.brakeForceN * grip, brakedBudgetN * left(lateralUse)) + resistN(speedMS)) / car.massKg,
    driveMS2: (speedMS, lateralUse, share) =>
      (Math.min(share * availableDriveForceN(car, 1, speedMS), car.tractionShareMax * drivenBudgetN, drivenBudgetN * left(lateralUse)) - resistN(speedMS)) / car.massKg,
    throttleRoom: (speedMS, lateralUse) => {
      const motorN = availableDriveForceN(car, 1, speedMS)
      return motorN <= 0 ? 1 : Math.min(1, Math.min(car.tractionShareMax * drivenBudgetN, drivenBudgetN * left(lateralUse)) / motorN)
    },
    brakeRoom: (lateralUse) => (car.brakeForceN <= 0 ? 1 : Math.min(1, (brakedBudgetN * left(lateralUse)) / (car.brakeForceN * grip))),
  }
}

/** Target speed, m/s, at each point of the line. `grip` multiplies the car's tyre grip: 1 on a dry track. */
export function buildSpeedProfile(line: RacingLine, car: CarParams, grip: number, plan: PacePlan = FULL_PACE): Float64Array {
  const limits = carLimits(car, grip)
  const count = line.points.length
  const speed = new Float64Array(count)
  const cornerMS2 = limits.lateralMS2 * plan.cornerShare
  // The ellipse is entered with a little in hand: a car planned to the last of its grip has none left to correct with.
  const ellipseMS2 = limits.lateralMS2 * AI_TUNING.pace.ellipseShare
  for (let i = 0; i < count; i++) {
    const point = line.points[i]
    const bend = Math.abs(point.curvature)
    let most = bend < AI_TUNING.pace.straightCurvature ? limits.topSpeedMS : Math.min(limits.topSpeedMS, Math.sqrt(cornerMS2 / bend))
    if (point.onKerb) most = Math.min(most, plan.kerbCapMS)
    speed[i] = most
  }
  const use = (speedMS: number, i: number): number => (speedMS * speedMS * Math.abs(line.points[i].curvature)) / ellipseMS2

  // Braking: backward, twice round, so that the limit carries across the start of the line.
  for (let round = 0; round < 2; round++) {
    for (let i = count - 1; i >= 0; i--) {
      const next = speed[(i + 1) % count]
      const slowing = limits.brakeMS2(next, use(next, i), plan.brakeShare)
      speed[i] = Math.min(speed[i], Math.sqrt(next * next + 2 * slowing * line.stepM))
    }
  }
  // Acceleration: forward, twice round for the same reason.
  for (let round = 0; round < 2; round++) {
    for (let i = 0; i < count; i++) {
      const j = (i + 1) % count
      const gaining = Math.max(0, limits.driveMS2(speed[i], use(speed[i], i), plan.driveShare))
      speed[j] = Math.min(speed[j], Math.sqrt(speed[i] * speed[i] + 2 * gaining * line.stepM))
    }
  }
  return speed
}
