import { angleDiff, wrapAngle } from '../core'
import type { Pose } from '../core'
import type { RoutePoint, TrackData, TrackRuntime } from './types'

// The lap as a curve: where it goes, which way it points, how hard it bends, and what is nearest a point (F-104).
// The runtime hands these out; the validator uses them to judge which way a start slot should face.

/** Spacing of the resampled route. */
const ROUTE_STEP_M = 0.05
/** Points taken along the curve between two route points before resampling by distance. */
const ROUTE_SUBDIVISIONS = 8
/**
 * Curvature at a route sample is that of the circle through it and the samples this many steps either side:
 * 0.4 m in all, about two route points. Positions are what the trace knows best, so this reads the bend from
 * them rather than from the direction of the curve drawn through them, which runs a little ahead of itself
 * wherever a straight meets a corner.
 */
const CURVATURE_REACH = 4
/** With a hint, the nearest route point is looked for this far either side of it. */
const HINT_WINDOW_M = 2

export interface Route {
  length: number
  nearest: TrackRuntime['nearestRoute']
  pose: TrackRuntime['routePose']
  curvature: TrackRuntime['curvatureAt']
}

/** The lap. Sample 0 is the first route point, on the timing line; distances wrap round the lap. */
export function buildRoute(data: TrackData): Route {
  return buildPath(data.route.points, true)
}

/**
 * The pit route, from where it leaves the lap to where it rejoins. It is an open path: a distance before its start
 * or past its end is taken as that end, and no hint is needed to tell one stretch of it from another.
 */
export function buildPitRoute(points: readonly RoutePoint[]): Route {
  return buildPath(points, false)
}

/**
 * The route's points are joined by a smooth curve through every one of them (a Catmull-Rom spline), which is then
 * cut into equal steps of distance. A closed path runs on from its last point to its first; an open one leaves
 * each end along the line to its neighbour.
 */
function buildPath(points: readonly RoutePoint[], closed: boolean): Route {
  const n = points.length
  /** The point a spline span reaches for beyond an end of an open path: its neighbour, mirrored in the end. */
  const at = (i: number): readonly [number, number, number] => {
    if (closed) return points[((i % n) + n) % n]
    if (i < 0) return [2 * points[0][0] - points[1][0], 2 * points[0][1] - points[1][1], points[0][2]]
    if (i >= n) return [2 * points[n - 1][0] - points[n - 2][0], 2 * points[n - 1][1] - points[n - 2][1], points[n - 1][2]]
    return points[i]
  }
  const spans = closed ? n : n - 1
  const dense = spans * ROUTE_SUBDIVISIONS
  const denseX = new Float64Array(dense + 1)
  const denseY = new Float64Array(dense + 1)
  const denseHeading = new Float64Array(dense + 1)
  const denseHalfWidth = new Float64Array(dense + 1)
  for (let k = 0; k <= dense; k++) {
    // The last sample of a closed path is its first again; of an open one, the end of its last span.
    const i = k === dense && !closed ? spans - 1 : Math.floor(k / ROUTE_SUBDIVISIONS) % spans
    const t = k === dense && !closed ? 1 : (k % ROUTE_SUBDIVISIONS) / ROUTE_SUBDIVISIONS
    const p0 = at(i - 1)
    const p1 = at(i)
    const p2 = at(i + 1)
    const p3 = at(i + 2)
    let dx = 0
    let dy = 0
    for (let axis = 0; axis < 2; axis++) {
      const a = p2[axis] - p0[axis]
      const b = 2 * p0[axis] - 5 * p1[axis] + 4 * p2[axis] - p3[axis]
      const c = -p0[axis] + 3 * p1[axis] - 3 * p2[axis] + p3[axis]
      const position = 0.5 * (2 * p1[axis] + a * t + b * t * t + c * t * t * t)
      const slope = 0.5 * (a + 2 * b * t + 3 * c * t * t)
      if (axis === 0) {
        denseX[k] = position
        dx = slope
      } else {
        denseY[k] = position
        dy = slope
      }
    }
    denseHeading[k] = Math.atan2(dy, dx)
    denseHalfWidth[k] = p1[2] + (p2[2] - p1[2]) * t
  }

  const travelled = new Float64Array(dense + 1)
  for (let k = 0; k < dense; k++) travelled[k + 1] = travelled[k] + Math.hypot(denseX[k + 1] - denseX[k], denseY[k + 1] - denseY[k])
  const length = travelled[dense]

  // A closed path has `steps` samples, the last one a step short of the first; an open one has a sample at each end.
  const steps = Math.max(closed ? 8 : 1, Math.round(length / ROUTE_STEP_M))
  const step = length / steps
  const count = closed ? steps : steps + 1
  const xs = new Float64Array(count)
  const ys = new Float64Array(count)
  const headings = new Float64Array(count)
  const halfWidths = new Float64Array(count)
  for (let i = 0, k = 0; i < count; i++) {
    const target = i * step
    while (k < dense - 1 && travelled[k + 1] < target) k++
    const span = travelled[k + 1] - travelled[k]
    const f = span === 0 ? 0 : Math.min(1, (target - travelled[k]) / span)
    xs[i] = denseX[k] + (denseX[k + 1] - denseX[k]) * f
    ys[i] = denseY[k] + (denseY[k + 1] - denseY[k]) * f
    headings[i] = denseHeading[k] + angleDiff(denseHeading[k], denseHeading[k + 1]) * f
    halfWidths[i] = denseHalfWidth[k] + (denseHalfWidth[k + 1] - denseHalfWidth[k]) * f
  }
  /** The sample `offset` places on from sample i: round the lap on a closed path, stopping at the ends of an open one. */
  const neighbour = (i: number, offset: number): number => (closed ? (((i + offset) % count) + count) % count : Math.min(count - 1, Math.max(0, i + offset)))
  const curvatures = new Float64Array(count)
  for (let i = 0; i < count; i++) {
    const before = neighbour(i, -CURVATURE_REACH)
    const after = neighbour(i, CURVATURE_REACH)
    const inX = xs[i] - xs[before]
    const inY = ys[i] - ys[before]
    const outX = xs[after] - xs[i]
    const outY = ys[after] - ys[i]
    const chord = Math.hypot(xs[after] - xs[before], ys[after] - ys[before])
    const product = Math.hypot(inX, inY) * Math.hypot(outX, outY) * chord
    // Twice the triangle's signed area over the product of its sides, doubled: positive when turning right.
    curvatures[i] = product === 0 ? 0 : (2 * (inX * outY - inY * outX)) / product
  }

  /** Sample index and fraction for an arc length: wrapped into the lap, or held at the ends of an open path. */
  const locate = (s: number): { i: number; j: number; f: number } => {
    if (!closed) {
      const u = Math.min(steps, Math.max(0, s / step))
      const i = Math.min(steps - 1, Math.floor(u))
      return { i, j: i + 1, f: u - i }
    }
    const u = ((((s % length) + length) % length) / step) % count
    const i = Math.min(count - 1, Math.floor(u))
    return { i, j: (i + 1) % count, f: u - i }
  }

  const pose = (s: number): Pose => {
    const { i, j, f } = locate(s)
    return {
      x: xs[i] + (xs[j] - xs[i]) * f,
      y: ys[i] + (ys[j] - ys[i]) * f,
      angle: wrapAngle(headings[i] + angleDiff(headings[i], headings[j]) * f),
    }
  }

  const curvature = (s: number): number => {
    const { i, j, f } = locate(s)
    return curvatures[i] + (curvatures[j] - curvatures[i]) * f
  }

  const segments = closed ? count : count - 1
  const window = Math.ceil(HINT_WINDOW_M / step)
  const nearest: TrackRuntime['nearestRoute'] = (x, y, hintS) => {
    let first = 0
    let span = segments
    if (closed && hintS !== undefined && 2 * window + 1 < count) {
      first = locate(hintS).i - window
      span = 2 * window + 1
    }
    let bestSq = Infinity
    let bestIndex = 0
    let bestT = 0
    for (let k = 0; k < span; k++) {
      const i = closed ? (((first + k) % count) + count) % count : k
      const j = closed ? (i + 1) % count : i + 1
      const dx = xs[j] - xs[i]
      const dy = ys[j] - ys[i]
      const lengthSq = dx * dx + dy * dy
      const t = lengthSq === 0 ? 0 : Math.min(1, Math.max(0, ((x - xs[i]) * dx + (y - ys[i]) * dy) / lengthSq))
      const gapX = x - (xs[i] + dx * t)
      const gapY = y - (ys[i] + dy * t)
      const gapSq = gapX * gapX + gapY * gapY
      if (gapSq < bestSq) {
        bestSq = gapSq
        bestIndex = i
        bestT = t
      }
    }
    const i = bestIndex
    const j = closed ? (i + 1) % count : i + 1
    const dx = xs[j] - xs[i]
    const dy = ys[j] - ys[i]
    // Positive to the right of the direction of travel: y is down, so right is a quarter turn clockwise.
    const side = dx * (y - ys[i]) - dy * (x - xs[i])
    const along = (i + bestT) * step
    return {
      s: closed ? along % length : along,
      lateralM: Math.sign(side) * Math.sqrt(bestSq),
      headingRad: wrapAngle(headings[i] + angleDiff(headings[i], headings[j]) * bestT),
      halfWidthM: halfWidths[i] + (halfWidths[j] - halfWidths[i]) * bestT,
    }
  }

  return { length, nearest, pose, curvature }
}
