import type { ControlInput } from '../session/controls'
import { gripLimitMS2 } from './resolve'
import type { CarParams, ShapedControls } from './types'

// Turns a driver's raw input (four digital keys, or an AI's analogue demand) into what a radio would send:
// steering that slews and self-centres, lock that falls with speed, pedals that ramp, and a brake that
// becomes reverse once the car has stopped, in a session whose cars have reverse (F-508). The state is one small
// record per car, owned by whoever steps the cars and advanced by fixed ticks only, so a replay shapes its inputs
// exactly as the original run did.

export interface ShapingState {
  /** -1..1 share of the lock available at the current speed. */
  steer: number
  /** -reverseLimit..1; negative only while reversing. */
  throttle: number
  /** 0..1 */
  brake: number
  /** How long the brake has been held with the car all but stopped. */
  stoppedForS: number
  reversing: boolean
}

/** Everything released, wheels straight. */
export function shapingAtRest(): ShapingState {
  return { steer: 0, throttle: 0, brake: 0, stoppedForS: 0, reversing: false }
}

function approach(value: number, target: number, maxStep: number): number {
  return value < target ? Math.min(target, value + maxStep) : Math.max(target, value - maxStep)
}

/** Below this speed² the lock formula would divide by nearly nothing; full lock is available long before. */
const MIN_SPEED_SQ = 1e-6

/**
 * Speed-sensitive lock, as a fraction of full lock. A held key asks for the steer angle that corners at
 * `lockGripFactor` times the car's own grip limit (geometry: wheelbase × a / v²) plus an allowance to build
 * front slip, never more than full lock. At parking speed that is full lock; at top speed a few degrees.
 */
export function lockFraction(speedMS: number, p: CarParams): number {
  const speedSq = Math.max(speedMS * speedMS, MIN_SPEED_SQ)
  const wantedRad = (p.wheelbaseM * p.shaping.lockGripFactor * gripLimitMS2(p)) / speedSq + p.shaping.lockSlipAllowRad
  return Math.min(1, wantedRad / p.maxSteerRad)
}

/**
 * One tick of shaping. Pure: `prev` is not changed, and the same arguments always give the same result.
 * `speedLongMS` is the car's speed along its heading, negative when rolling backwards. `reverse` is whether the
 * session's cars have reverse (F-508), which is the session's to say and no car's: with false the brake is only
 * ever a brake, and held at rest it keeps the car at rest.
 */
export function shape(
  prev: ShapingState,
  raw: ControlInput,
  speedLongMS: number,
  p: CarParams,
  dt: number,
  reverse = true,
): { state: ShapingState; controls: ShapedControls } {
  const s = p.shaping

  // Steering: slew toward where the wheel is held; centre faster than it winds on.
  const unwinding = raw.steer === 0 || Math.sign(raw.steer) !== Math.sign(prev.steer)
  const steerRate = unwinding ? Math.max(s.steerRatePerS, s.steerReturnPerS) : s.steerRatePerS
  const steer = approach(prev.steer, raw.steer, steerRate * dt)

  // The brake is a brake while the car rolls forwards, then reverse once it has been all but stopped for a
  // moment — the way an RC speed controller behaves. Releasing the brake always leaves reverse. With reverse off
  // nothing is counted and nothing is ever reversing.
  const braking = raw.brake > 0
  let stoppedForS = 0
  let reversing = false
  if (braking && reverse) {
    reversing = prev.reversing
    stoppedForS = prev.stoppedForS
    if (!reversing) {
      stoppedForS = speedLongMS < s.reverseBelowMS ? prev.stoppedForS + dt : 0
      if (stoppedForS >= s.reverseAfterS) reversing = true
    }
  }

  let throttleTarget = 0
  let brakeTarget = 0
  if (braking && reversing) throttleTarget = -p.reverseLimit * raw.brake
  else if (braking) brakeTarget = raw.brake
  else throttleTarget = raw.throttle

  const throttleRate = Math.abs(throttleTarget) > Math.abs(prev.throttle) ? s.throttleRisePerS : s.throttleFallPerS
  const throttle = approach(prev.throttle, throttleTarget, throttleRate * dt)
  const brake = approach(prev.brake, brakeTarget, (brakeTarget > prev.brake ? s.brakeRisePerS : s.brakeFallPerS) * dt)

  return {
    state: { steer, throttle, brake, stoppedForS, reversing },
    controls: { throttle, brake, steer: steer * lockFraction(Math.abs(speedLongMS), p) },
  }
}
