import { FORECASTS, type ForecastPreset } from '@content/weather'
import { clamp, createRng, DT, TICK_RATE, wrapAngle, type Rng, type Tick, type Vec2 } from '../core'
import type { SimEvent } from '../session/events'
import type { Mutable } from '../session/types'
import type { TrackData } from '../track'
import { createSkyChain, drawDwellS, nextSky, setSky, SKIES, stepSky } from './sky'
import { advanceGround, announcePuddles, createGroundWater, groundRates, puddleRadius, type GroundWater } from './surface'
import { WEATHER_TUNING } from './tuning'
import type { Forecast, SettledForecast, Sky, WeatherForce, WeatherPlan, WeatherSnapshot } from './types'
import { baseCeilingMS, baseFloorMS, createWind, hashWind, settledWindMS, stepWind, windRates, windSpeedMS } from './wind'

// The weather of one session (F-601): a sky that moves as the forecast has it, the rain and the wetness that
// follow the sky, the puddles, and the wind. It is a small simulation of its own, stepped once a tick before
// anything else moves, and it reads nothing of the cars but how many are circulating. What the cars feel of it is
// not here (F-602), nor what is drawn of it (F-603).

const SETTLED: readonly SettledForecast[] = ['dry', 'changeable', 'wet']
const TICK_S = DT
const NO_EVENTS: readonly SimEvent[] = Object.freeze([])

export interface WeatherSystem {
  /**
   * Tick step 2. `tick` is the tick the session is on once the step is done, which is the tick the events carry;
   * `traffic.carsOnLine` is how many cars are circulating, which dries the racing line and changes nothing else.
   */
  update(tick: Tick, traffic: { carsOnLine: number }): readonly SimEvent[]
  /** The weather as the snapshot has it. The same object and the same arrays on every call, refilled. */
  snapshot(): WeatherSnapshot
  /**
   * State to hand to the next session of the same event: the weather as it stands, moved on by a pause of `gapS`
   * seconds. Over the pause the sky moves at most one step and the wetness by at most
   * `WEATHER_TUNING.carryOver.maxWetnessChange`. It draws from a stream of its own, so asking changes nothing
   * here, and asking twice at the same tick gives the same answer.
   */
  carryOver(gapS: number): WeatherPlan
  /**
   * Development and tests: sets the fields given and holds them there while the rest goes on by itself; a second
   * call adds to what is held, and `null` lets everything go from where it stands. A held sky that differs from
   * the sky is told as a `sky` event on the next tick, however far apart the two are.
   */
  force(hold: WeatherForce | null): void
  /** The tick of the last change of sky; null until there has been one. */
  readonly skyChangedTick: Tick | null
  /**
   * True while there is no weather for a car to feel and none can come: a calm session in which nothing has ever
   * been held. Such a session's cars are stepped exactly as they were before there was weather (F-602).
   */
  readonly still: boolean
  /** Appends every number of the weather's state, in a fixed order. */
  hashInto(buffer: number[]): void
}

/** The forecast a session follows: the one asked for, or for `surprise` one of the other three, drawn from the seed. */
export function settleForecast(forecast: Forecast, seed: number): SettledForecast {
  return forecast === 'surprise' ? createRng(seed).fork('forecast').pick(SETTLED) : forecast
}

/**
 * The weather an event, or a session that stands alone, begins with: its first sky drawn by the forecast's odds,
 * the track as wet as the forecast has it under that sky, the wind from anywhere at about the forecast's speed.
 * A pure function of the forecast and the seed. The plan names the forecast that was settled on, never `surprise`.
 */
export function firstWeatherPlan(forecast: Forecast, seed: number): WeatherPlan {
  const settled = settleForecast(forecast, seed)
  const preset = FORECASTS[settled]
  const rng = createRng(seed).fork('weather-plan')
  const initialSky = drawFirstSky(preset, rng)
  const [driest, wettest] = preset.initialWetness[initialSky]
  const windSpeedMS = clamp(settledWindMS(preset.wind, initialSky) * rng.range(0.7, 1.3), baseFloorMS(preset.wind), baseCeilingMS(preset.wind))
  return { forecast: settled, initialSky, initialWetness: rng.range(driest, wettest), windDirRad: rng.range(-Math.PI, Math.PI), windSpeedMS }
}

function drawFirstSky(preset: ForecastPreset, rng: Rng): Sky {
  const total = preset.initial.reduce((sum, one) => sum + Math.max(0, one.weight), 0)
  let left = rng.next() * total
  for (const one of preset.initial) {
    left -= Math.max(0, one.weight)
    if (left < 0) return one.sky
  }
  return preset.initial.at(-1)?.sky ?? 'sunny'
}

/**
 * The weather of a session that begins as `plan` says, with a puddle for each of the track's `puddleSpots`. `rng` is
 * the session's `weather` stream; the sky, the wind's wander, the gusts and the puddles each draw from a fork of it.
 *
 * A calm plan (`WeatherPlan.calm`) begins sunny and dry whatever else it says, and stays so: its sky never changes
 * by itself and its air is still, so nothing is ever told and the snapshot never moves. What is held from outside
 * (`force`) is still held, and the ground still follows a sky that is held: that is how a test puts rain on a
 * practice session.
 */
export function createWeather(plan: WeatherPlan, track: TrackData, rng: Rng): WeatherSystem {
  const forecast: SettledForecast = plan.forecast === 'surprise' ? rng.fork('forecast').pick(SETTLED) : plan.forecast
  const preset = FORECASTS[forecast]
  const skyRng = rng.fork('sky')
  const wanderRng = rng.fork('wind')
  const gustRng = rng.fork('gusts')
  const spots = track.puddleSpots

  const calm = plan.calm === true
  const firstSky: Sky = calm ? 'sunny' : plan.initialSky
  const chain = createSkyChain(preset, firstSky, skyRng)
  // A calm session draws nothing: it is the same session whatever its seed.
  const ground = createGroundWater(firstSky, calm || !Number.isFinite(plan.initialWetness) ? 0 : plan.initialWetness, spots.length, calm ? null : rng.fork('puddles'))
  const wind = createWind(preset.wind, plan.windDirRad, plan.windSpeedMS, gustRng)
  // What the ground and the wind are stepped by under the sky there is: looked up again whenever it changes.
  let underSky = groundRates(chain.sky)
  let inWind = windRates(preset.wind, chain.sky)
  let skyChangedTick: Tick | null = null
  let hold: WeatherForce | null = null
  // Once anything has been held, what it left behind (water on the ground, a sky) is weather like any other.
  let everHeld = false

  const view: Mutable<WeatherSnapshot> = {
    sky: chain.sky,
    rainIntensity: 0,
    wetness: 0,
    lineWetness: 0,
    wind: { x: 0, y: 0 },
    puddles: spots.map((spot) => ({ x: spot.x, y: spot.y, r: 0, depth: 0 })),
    cloudCover: 0,
  }
  const announced: number[] = []

  /** Everything that is held is put where it is held. */
  const applyHold = (held: WeatherForce): void => {
    if (held.rainIntensity !== undefined) ground.rain = clamp(held.rainIntensity, 0, 1)
    if (held.wetness !== undefined) ground.wetness = clamp(held.wetness, 0, 1)
    if (held.lineWetness !== undefined) ground.lineWetness = clamp(held.lineWetness, 0, 1)
    if (held.puddles !== undefined) {
      for (let i = 0; i < ground.depth.length && i < held.puddles.length; i++) ground.depth[i] = clamp(held.puddles[i], 0, 1)
    }
  }

  return {
    update(tick, traffic) {
      let events: SimEvent[] | null = null

      // The sky: held where it is told to be, else moving as the forecast has it.
      const before = chain.sky
      if (hold?.sky !== undefined) {
        if (hold.sky !== before) setSky(chain, preset, hold.sky, skyRng)
      } else if (!calm) {
        stepSky(chain, preset, skyRng)
      }
      if (chain.sky !== before) {
        underSky = groundRates(chain.sky)
        inWind = windRates(preset.wind, chain.sky)
        skyChangedTick = tick
        ;(events ??= []).push({ type: 'sky', tick, from: before, to: chain.sky })
      }

      // The wind, unless it is held: then it stands as it was put, with no gusts. A calm session has none.
      let windMS: number
      if (hold?.wind !== undefined) {
        windMS = Math.hypot(hold.wind.x, hold.wind.y)
      } else if (calm) {
        windMS = 0
      } else {
        const gust = stepWind(wind, inWind, wanderRng, gustRng)
        if (gust !== null) (events ??= []).push({ type: 'gust', tick, speedMS: gust.speedMS, dirRad: wrapAngle(gust.dirRad) })
        windMS = windSpeedMS(wind, preset.wind.maxMS)
      }

      // The ground under that sky and in that wind; then whatever of it is held; then the puddles that are new.
      advanceGround(ground, underSky, windMS, traffic.carsOnLine, TICK_S)
      if (hold !== null) applyHold(hold)
      announced.length = 0
      announcePuddles(ground, announced)
      for (const index of announced) (events ??= []).push({ type: 'puddle', tick, index })

      return events ?? NO_EVENTS
    },

    snapshot() {
      view.sky = chain.sky
      view.rainIntensity = ground.rain
      view.wetness = ground.wetness
      view.lineWetness = ground.lineWetness
      view.cloudCover = ground.cloud
      if (hold?.wind !== undefined) {
        view.wind.x = hold.wind.x
        view.wind.y = hold.wind.y
      } else if (calm) {
        view.wind.x = 0
        view.wind.y = 0
      } else {
        const speed = windSpeedMS(wind, preset.wind.maxMS)
        view.wind.x = Math.cos(wind.dirRad) * speed
        view.wind.y = Math.sin(wind.dirRad) * speed
      }
      for (let i = 0; i < spots.length; i++) {
        view.puddles[i].depth = ground.depth[i]
        view.puddles[i].r = puddleRadius(spots[i].r, ground.depth[i])
      }
      return view
    },

    carryOver(gapS) {
      // A calm session hands calm on.
      if (calm) return { ...plan, initialSky: 'sunny', initialWetness: 0, windSpeedMS: 0 }
      const draw = rng.fork('carry-over')
      const limits = WEATHER_TUNING.carryOver
      const later: GroundWater = { ...ground, depth: ground.depth.slice(), told: ground.told.slice() }
      let sky = chain.sky
      let rates = underSky
      let speedMS = wind.baseMS
      let untilChangeS = chain.ticksLeft / TICK_RATE
      let skySteps = 0
      // Over the pause the wind settles to the mean of whatever sky there is, the way it is drawn to it in a session.
      const easing = 1 - Math.exp(-limits.stepS / WEATHER_TUNING.wind.speedEaseS)
      for (let leftS = Math.max(0, gapS); leftS > 0; leftS -= limits.stepS) {
        const stepS = Math.min(limits.stepS, leftS)
        if (untilChangeS <= 0 && skySteps < limits.maxSkySteps) {
          const next = nextSky(preset, sky, draw)
          if (next !== null) {
            sky = next
            rates = groundRates(sky)
            skySteps += 1
          }
          untilChangeS = drawDwellS(preset, sky, draw)
        }
        speedMS += (settledWindMS(preset.wind, sky) - speedMS) * easing
        advanceGround(later, rates, speedMS, 0, stepS)
        untilChangeS -= stepS
      }
      return {
        forecast,
        initialSky: sky,
        initialWetness: clamp(later.wetness, Math.max(0, ground.wetness - limits.maxWetnessChange), Math.min(1, ground.wetness + limits.maxWetnessChange)),
        windDirRad: wrapAngle(wind.dirRad),
        windSpeedMS: speedMS,
      }
    },

    force(next) {
      if (next === null) {
        hold = null
        return
      }
      everHeld = true
      const merged: WeatherForce = { ...hold, ...next }
      if (next.puddles !== undefined) merged.puddles = next.puddles.slice()
      if (next.wind !== undefined) {
        const held: Vec2 = { x: next.wind.x, y: next.wind.y }
        merged.wind = held
        // The wind goes on from where it was put once it is let go: no gust, and its direction kept if it was put to nothing.
        const speed = Math.hypot(held.x, held.y)
        wind.baseMS = speed
        if (speed > 0) wind.dirRad = Math.atan2(held.y, held.x)
        if (wind.gustTicksLeft > 0) {
          wind.gustShare = 0
          wind.gustTicks = 0
          wind.gustTicksLeft = 0
          wind.nextGustTicks = Math.round(WEATHER_TUNING.gust.minGapS * TICK_RATE)
        }
      }
      hold = merged
      applyHold(merged)
    },

    get skyChangedTick() {
      return skyChangedTick
    },

    get still() {
      return calm && !everHeld
    },

    hashInto(buffer) {
      buffer.push(SKIES.indexOf(chain.sky), skyChangedTick ?? NaN, ground.rain, ground.cloud, ground.wetness, ground.lineWetness)
      for (let i = 0; i < ground.depth.length; i++) buffer.push(ground.depth[i], ground.told[i] ? 1 : 0, ground.fill[i])
      // What a calm session never steps is not part of its state: how long the sky has left, and the wind.
      if (calm) return
      buffer.push(chain.ticksLeft)
      hashWind(wind, buffer)
    },
  }
}
