import { TICK_RATE, type Tick } from '../core'
import { RULES } from './rules'
import type { SessionKind, SessionPhase } from './types'

// The phases of a session (F-303). A practice session is running from its first step. A qualifying heat and a
// final stand in `staging`, count down, and run from the start tone; the time that is up and the finish are not
// decided here but by the clocks and by the cars (clocks.ts, finish.ts), at the end of the step they happen on.

const STAGING_TICKS = Math.round(RULES.stagingS * TICK_RATE)
const COUNTDOWN_TICKS = Math.round(RULES.countdownS * TICK_RATE)

/**
 * The session tick at the start tone: the last tick before the cars may go. The step after it is the first that is
 * `running`, and the shared clock of a final reads zero as that step begins. Zero for a practice session.
 */
export function startTickOf(kind: SessionKind): Tick {
  return kind === 'practice' ? 0 : STAGING_TICKS + COUNTDOWN_TICKS
}

/** The phase a session is in before its first step. */
export function firstPhase(kind: SessionKind): SessionPhase {
  return kind === 'practice' ? 'running' : 'staging'
}

/**
 * The phase the step that takes the session to tick `step` is run in, given the phase before it. A phase begins
 * with the step that starts at its time: `countdown` with the step that begins `stagingS` in, so a `phase` event
 * carries the first tick of its phase. Once time is up this changes nothing.
 */
export function phaseAsStepStarts(kind: SessionKind, step: Tick, phase: SessionPhase): SessionPhase {
  if (phase === 'time-up' || phase === 'finished' || kind === 'practice') return phase
  const elapsedTicks = step - 1
  if (elapsedTicks < STAGING_TICKS) return 'staging'
  return elapsedTicks < STAGING_TICKS + COUNTDOWN_TICKS ? 'countdown' : 'running'
}
