import { DT, wrapAngle, type CarId } from '../core'
import { createPhysicsWorld, type MarkerCircle, type WallPolyline } from '../physics'
import type { WorldContact } from '../physics/world'
import type { CarStepper } from '../session/stepper'
import { vehicleModel } from './model'
import { resolveCar } from './resolve'
import { shape, shapingAtRest, type ShapingState } from './shaping'
import type { CarClass, CarClassId, CarParams, ShapedControls, Tuning, VehicleTelemetry } from './types'

// What moves the cars: keyboard shaping and the vehicle model per car, then one step of the physics world for
// all of them. Everything it remembers between ticks is in the object it returns — one per session.

/** The session's stepper seam, plus the one thing the real stepper needs that the seam does not carry. */
export interface VehicleStepper extends CarStepper {
  /**
   * The track's solid things: its walls and its markers (tyres, cones). Call before the first step; calling again
   * replaces them all. Leaving the markers out leaves the track with none. A marker of kind `dot` is a tyre lying
   * loose, which gives as the tuning says (F-308); any other stands where it is.
   */
  setWalls(walls: readonly WallPolyline[], markers?: readonly MarkerCircle[]): void
  /** The resolved parameters car `id` is being driven with now. */
  params(id: CarId): CarParams
  /**
   * Development only (F-206): replaces a car's resolved parameters while it runs. Position, velocity, yaw rate and
   * input shaping carry on; the next step is the first to use the new parameters.
   */
  setParams(id: CarId, next: CarParams): void
  /**
   * Development only (F-206): replaces what the walls, the tyres and the cars are made of, and how the loose tyres
   * give. The next touch of each kind uses the new figures; nothing is rebuilt and nothing moves.
   */
  setContact(next: WorldContact): void
}

/** The classes that exist so far, by id. */
export type CarClasses = Readonly<Partial<Record<CarClassId, CarClass>>>

/**
 * `reverse` is whether the session's cars have reverse (F-508): a setting of the session and the same for every car
 * in it, whatever its class. Left out, they have. A car that has it may still be denied it tick by tick
 * (`StepEnvironment.noReverse`): one that has not been released.
 */
export function createCarStepper(tuning: Tuning, classes: CarClasses, reverse = true): VehicleStepper {
  const world = createPhysicsWorld(tuning.contact, tuning.carContact)
  // One slot per car, indexed by CarId.
  const params: CarParams[] = []
  const shaping: ShapingState[] = []
  // What each car was asked for and what its tyres did on the tick in progress; read back after the step.
  const controls: ShapedControls[] = []
  const telemetry: VehicleTelemetry[] = []
  // A class is resolved once, however many cars share it.
  const resolved = new Map<CarClassId, CarParams>()

  const paramsFor = (id: CarClassId): CarParams => {
    const known = resolved.get(id)
    if (known !== undefined) return known
    const cls = classes[id]
    if (cls === undefined) throw new Error(`No car class '${id}' in the content this stepper was given`)
    const fresh = resolveCar(cls, tuning)
    resolved.set(id, fresh)
    return fresh
  }

  return {
    add(id, carClass, pose, own) {
      if (id !== params.length) throw new Error(`Cars must be added in id order: expected ${params.length}, got ${id}`)
      const p = own ?? paramsFor(carClass)
      world.addCar(id, p, pose)
      params.push(p)
      shaping.push(shapingAtRest())
    },

    setWalls(walls, markers) {
      world.setWalls(walls, markers, tuning.marker, tuning.marker)
    },

    params(id) {
      const p = params[id]
      if (p === undefined) throw new RangeError(`There is no car ${id}`)
      return p
    },

    setParams(id, next) {
      if (params[id] === undefined) throw new RangeError(`There is no car ${id}`)
      params[id] = next
      world.reshape(id, next)
    },

    setContact(next) {
      world.setContact(next)
    },

    step(inputs, env, out, contacts) {
      // Per car: shape the input, ask the model for this tick's force and torque, hand them to the world.
      for (let id = 0; id < params.length; id++) {
        const p = params[id]
        const body = world.body(id)
        const speedLong = Math.cos(body.pose.angle) * body.velocity.x + Math.sin(body.pose.angle) * body.velocity.y
        // With reverse, unless the session has none or withholds it from this car for the tick (F-508).
        const shaped = shape(shaping[id], inputs[id], speedLong, p, DT, reverse && env[id].noReverse !== true)
        shaping[id] = shaped.state
        const result = vehicleModel.step(body, shaped.controls, p, env[id], DT)
        world.apply(id, result)
        controls[id] = shaped.controls
        telemetry[id] = result.tel
      }

      world.step()
      // The world keeps adding to its reports until they are taken, so they are taken on every step, wanted or not.
      const touched = world.drainContacts()
      if (contacts !== undefined) for (const report of touched) contacts.push(report)

      for (let id = 0; id < params.length; id++) {
        const body = world.body(id)
        const kin = out[id]
        kin.pose.x = body.pose.x
        kin.pose.y = body.pose.y
        // The world's own heading keeps counting turns; what is handed out stays in (-π, π].
        kin.pose.angle = wrapAngle(body.pose.angle)
        kin.velocity.x = body.velocity.x
        kin.velocity.y = body.velocity.y
        kin.yawRate = body.yawRate
        kin.steerRad = telemetry[id].steerRad
        // The shaped throttle is negative in reverse; the snapshot's is how hard the motor is driven, 0..1.
        kin.throttle = Math.abs(controls[id].throttle)
        kin.brake = controls[id].brake
        kin.motorRadS = telemetry[id].motorRadS
        kin.slipFront = telemetry[id].satFront
        kin.slipRear = telemetry[id].satRear
      }
    },

    setPose(id, pose, zeroVelocity) {
      world.setPose(id, pose, zeroVelocity)
    },

    setMarshals(marshals) {
      world.setMarshals(marshals)
    },

    resetControls(id) {
      if (params[id] === undefined) throw new RangeError(`There is no car ${id}`)
      shaping[id] = shapingAtRest()
    },

    markersInto(out) {
      world.markersInto(out)
    },

    hashInto(buffer) {
      for (const state of shaping) buffer.push(state.steer, state.throttle, state.brake, state.stoppedForS, state.reversing ? 1 : 0)
      world.hashInto(buffer)
    },
  }
}
