import { TICK_RATE, type CarId, type Tick } from '../core'
import { startTickOf } from './phases'
import type { SessionConfig } from './types'

// The clocks of a race (F-303). Session time is counted in ticks; a clock is the instant it started, in ms of
// session time, and everything read off it is the session's time less that. A final has one clock, started by the
// tone, which every car shares. In qualifying each car has its own, started when the car first crosses the timing
// line, at the instant inside the tick that lap timing found for the crossing; or, for a car that has not crossed
// it by then, a fixed time after the car's release (`RULES.clockStartLatestS`).

/** Session time at the end of a tick, ms. */
export function msOfTick(tick: Tick): number {
  return (tick * 1000) / TICK_RATE
}

/**
 * When a car's clock starts, if that is known before the session begins: the start tone in a final. Null in
 * qualifying, where it starts as the session runs, and in practice, which has no clock.
 */
export function clockStartOf(config: Pick<SessionConfig, 'kind'>): number | null {
  return config.kind === 'final' ? msOfTick(startTickOf('final')) : null
}

/** What a clock that started at `startMs` reads at `atMs`, in whole ms; zero before it has started. */
export function clockMs(startMs: number | null, atMs: number): number {
  return startMs === null ? 0 : Math.max(0, Math.round(atMs - startMs))
}

/** Whether a clock that started at `startMs` has reached the session's length by `atMs`. */
export function timeIsUp(startMs: number | null, atMs: number, durationS: number): boolean {
  return startMs !== null && atMs - startMs >= durationS * 1000
}

/** What is left on a clock at `atMs`, s: the whole length until it starts, and never less than nothing. */
export function remainingS(startMs: number | null, atMs: number, durationS: number): number {
  return startMs === null ? durationS : Math.min(durationS, Math.max(0, durationS - (atMs - startMs) / 1000))
}

/**
 * The car whose clock the on-screen timer shows in qualifying: the human's; with no human in the heat, the car
 * that is released first.
 */
export function timerCarOf(config: Pick<SessionConfig, 'entries'>): CarId {
  const human = config.entries.findIndex((entry) => entry.controller === 'human')
  if (human !== -1) return human
  let first = 0
  config.entries.forEach((entry, id) => {
    if (entry.startSlot < config.entries[first].startSlot) first = id
  })
  return first
}
