import type { SettledForecast, Sky } from '@sim'

// The forecasts (F-601): what each one makes of the sky over an event. Data only; the weather model that reads it
// is src/sim/weather/, and the rates that are the same under every forecast are its `WEATHER_TUNING`.

export interface ForecastPreset {
  /** The sky an event begins under: relative odds. */
  initial: Array<{ sky: Sky; weight: number }>
  /** How wet the track is when an event begins under each sky, 0..1: drawn between the two. */
  initialWetness: Record<Sky, readonly [min: number, max: number]>
  /** Mean dwell time in seconds per sky, and where it goes next. */
  dwellS: Record<Sky, number>
  /** Relative odds of the next sky being the drier neighbour or the wetter one. Both 0: that sky does not change. */
  drift: Record<Sky, { drier: number; wetter: number }>
  /** The wind, m/s: the mean it blows at under a cloudy sky, the most it ever reaches in a gust, and how often it gusts. */
  wind: { meanMS: number; maxMS: number; gustsPerMinute: number }
}

const BONE_DRY: readonly [number, number] = [0, 0]

/**
 * A session is 3, 5 or 7 minutes and a default event fifteen minutes of racing, so every forecast that changes has
 * to change inside that: the dwell times are minutes, not hours.
 *
 * - `dry`: sun and cloud taking turns; it never rains, and a track that somehow began wet only dries.
 * - `changeable`: all four skies, three and a half minutes apiece on average; a little under half the time it rains.
 * - `wet`: rain nearly nine tenths of the time, heavy for a third of it; the sun never comes out.
 */
export const FORECASTS: Record<SettledForecast, ForecastPreset> = {
  dry: {
    initial: [
      { sky: 'sunny', weight: 0.65 },
      { sky: 'cloudy', weight: 0.35 },
    ],
    initialWetness: { sunny: BONE_DRY, cloudy: BONE_DRY, 'light-rain': BONE_DRY, 'heavy-rain': BONE_DRY },
    dwellS: { sunny: 300, cloudy: 210, 'light-rain': 90, 'heavy-rain': 90 },
    drift: { sunny: { drier: 0, wetter: 1 }, cloudy: { drier: 1, wetter: 0 }, 'light-rain': { drier: 1, wetter: 0 }, 'heavy-rain': { drier: 1, wetter: 0 } },
    wind: { meanMS: 1.5, maxMS: 5, gustsPerMinute: 1 },
  },
  changeable: {
    initial: [
      { sky: 'sunny', weight: 0.3 },
      { sky: 'cloudy', weight: 0.35 },
      { sky: 'light-rain', weight: 0.25 },
      { sky: 'heavy-rain', weight: 0.1 },
    ],
    initialWetness: { sunny: BONE_DRY, cloudy: [0, 0.2], 'light-rain': [0.25, 0.5], 'heavy-rain': [0.7, 0.95] },
    dwellS: { sunny: 240, cloudy: 180, 'light-rain': 210, 'heavy-rain': 150 },
    drift: { sunny: { drier: 0, wetter: 1 }, cloudy: { drier: 0.45, wetter: 0.55 }, 'light-rain': { drier: 0.6, wetter: 0.4 }, 'heavy-rain': { drier: 1, wetter: 0 } },
    wind: { meanMS: 2.5, maxMS: 7, gustsPerMinute: 2 },
  },
  wet: {
    initial: [
      { sky: 'cloudy', weight: 0.1 },
      { sky: 'light-rain', weight: 0.55 },
      { sky: 'heavy-rain', weight: 0.35 },
    ],
    initialWetness: { sunny: [0.35, 0.5], cloudy: [0.35, 0.55], 'light-rain': [0.4, 0.55], 'heavy-rain': [0.75, 0.95] },
    dwellS: { sunny: 90, cloudy: 90, 'light-rain': 180, 'heavy-rain': 150 },
    drift: { sunny: { drier: 0, wetter: 1 }, cloudy: { drier: 0, wetter: 1 }, 'light-rain': { drier: 0.4, wetter: 0.6 }, 'heavy-rain': { drier: 1, wetter: 0 } },
    // Brought down from 3.5 and 9 (F-602 rulings): a 9 m/s gust was half of what a soaked F1 car's tyres hold.
    wind: { meanMS: 3, maxMS: 7, gustsPerMinute: 3 },
  },
}
