import { DT, TICK_RATE, type Rng, type Tick, type Vec2 } from '../core'
import type { SurfaceEnvironment } from '../surface/surface'
import type { SurfaceTuning } from '../vehicle/types'
import { INCIDENT_TUNING } from './tuning'
import type { FlipCause, RollCase } from './types'

// Rolling over (F-501, rewritten by F-507). The vehicle model has no roll axis (ADR-003), so a roll is an outcome
// decided on top of it, in the five ways the owner listed and no others: the middle of the nose run onto the start
// of a kerb, a hop that comes down on the kerb it left (both decided by the surfaces, with what is here), a car run
// into by one alongside it at speed, a nose driven into a side, and a car pushed along from behind. No chance is
// drawn for any of them: above the numbers a car goes over, below them it does not. How readily a car goes over
// comes from its own width and the height of its centre of gravity, through `CarParams.stabilityFactor`.
// Everything here is a pure function of its arguments; nothing reads a car's class.

type RollTuning = SurfaceTuning['roll']

/**
 * How much harder than a car of reference stability a car is to roll: its stability factor over the reference,
 * raised to the tuning's exponent. 1 for the touring body, more for a wider or lower car, less for a narrower or
 * taller one. Every speed and impulse that rolls a car is multiplied by it.
 */
export function stabilityScale(stabilityFactor: number): number {
  const { reference, exponent } = INCIDENT_TUNING.stability
  return Math.pow(stabilityFactor / reference, exponent)
}

/** The speed along its own heading, m/s, above which a car of this stability that runs the middle of its nose onto a kerb's start goes over. */
export function kerbRollSpeedMS(stabilityFactor: number, kerb: Pick<SurfaceTuning['kerb'], 'rollSpeedMS'>): number {
  return kerb.rollSpeedMS * stabilityScale(stabilityFactor)
}

/** What a way of rolling is told as: a kerb's doing, or another car's. */
export function causeOf(how: RollCase): FlipCause {
  return how === 'kerb-start' || how === 'kerb-landing' ? 'kerb' : 'impact'
}

/** Where on a car a touch lands. */
export type TouchPlace = 'nose' | 'side' | 'tail'

/**
 * Where on a car a touch lands, from the way it presses: `towardOther` points from the car to what it touched, world
 * frame. On the side when that is more across the car's heading than along it; otherwise on the nose if the other
 * is ahead of it, and on the tail if behind.
 */
export function touchPlace(towardOther: Readonly<Vec2>, headingRad: number): TouchPlace {
  const cos = Math.cos(headingRad)
  const sin = Math.sin(headingRad)
  const along = towardOther.x * cos + towardOther.y * sin
  const across = -towardOther.x * sin + towardOther.y * cos
  if (Math.abs(across) > Math.abs(along)) return 'side'
  return along > 0 ? 'nose' : 'tail'
}

/** One car of a touch between two: how it was moving as the tick of the touch began, which way it points, and its shape. */
export interface TouchingCar {
  /** World frame, m/s. */
  velocity: Readonly<Vec2>
  headingRad: number
  stabilityFactor: number
}

/** What one step of a touch between two cars does toward rolling either. */
export interface TouchVerdict {
  /** The way each car goes over on this step, first car then second; null for one that does not. */
  rolls: [first: RollCase | null, second: RollCase | null]
  /** The car that has the other's nose against its tail and is going faster than its push speed: 0 the first, 1 the second, null neither. It rolls once that has lasted the push time. */
  pushed: 0 | 1 | null
  /**
   * For each car that goes over, the car that rolled it (F-512): side by side, the one that ran into it; nose into
   * side, the one whose nose it was, for both of them. Null beside a car that does not go over.
   */
  rolledBy: [first: 0 | 1 | null, second: 0 | 1 | null]
}

/**
 * One step of a touch between two cars (F-507). `normal` is the way it pressed, from `first` toward `second`, and
 * `impulseNs` how hard. Where it landed on each car (`touchPlace`) says which case it can be:
 *
 * - **Side to side.** Both going faster than their side-by-side speed along their own headings, and the touch at
 *   least the side-by-side impulse: the car that was run into goes over. Of the two, the one that ran into the
 *   other is the one moving toward it faster along the touch, over the ground; it stays on its wheels. Moving at
 *   each other alike, both were run into.
 * - **Nose into side.** The car whose nose it is, closing along the touch faster than the hit speed: both go over.
 * - **Nose on tail.** Nobody goes over on the step; the car in front is being pushed if it is going faster than its
 *   push speed.
 *
 * Anything else (nose to nose, tail to side) rolls nobody. Each car is held to its own numbers: the tuning's, times
 * its `stabilityScale`.
 */
export function judgeTouch(first: TouchingCar, second: TouchingCar, normal: Readonly<Vec2>, impulseNs: number, roll: RollTuning): TouchVerdict {
  const verdict: TouchVerdict = { rolls: [null, null], pushed: null, rolledBy: [null, null] }
  const back = { x: -normal.x, y: -normal.y }
  const placeFirst = touchPlace(normal, first.headingRad)
  const placeSecond = touchPlace(back, second.headingRad)
  const scaleFirst = stabilityScale(first.stabilityFactor)
  const scaleSecond = stabilityScale(second.stabilityFactor)
  // How fast each was moving toward the other along the touch, over the ground.
  const closingFirst = first.velocity.x * normal.x + first.velocity.y * normal.y
  const closingSecond = second.velocity.x * back.x + second.velocity.y * back.y

  if (placeFirst === 'side' && placeSecond === 'side') {
    const fast = forwardMS(first) > roll.sideBySideSpeedMS * scaleFirst && forwardMS(second) > roll.sideBySideSpeedMS * scaleSecond
    if (!fast) return verdict
    if (closingSecond > 0 && closingSecond >= closingFirst && impulseNs >= roll.sideBySideImpulseNs * scaleFirst) {
      verdict.rolls[0] = 'side-by-side'
      verdict.rolledBy[0] = 1
    }
    if (closingFirst > 0 && closingFirst >= closingSecond && impulseNs >= roll.sideBySideImpulseNs * scaleSecond) {
      verdict.rolls[1] = 'side-by-side'
      verdict.rolledBy[1] = 0
    }
  } else if ((placeFirst === 'nose' && placeSecond === 'side') || (placeFirst === 'side' && placeSecond === 'nose')) {
    const nose = placeFirst === 'nose' ? 0 : 1
    const closingMS = nose === 0 ? closingFirst : closingSecond
    if (closingMS > roll.noseHitSpeedMS * scaleFirst) {
      verdict.rolls[0] = 'nose-into-side'
      verdict.rolledBy[0] = nose
    }
    if (closingMS > roll.noseHitSpeedMS * scaleSecond) {
      verdict.rolls[1] = 'nose-into-side'
      verdict.rolledBy[1] = nose
    }
  } else if (placeFirst === 'nose' && placeSecond === 'tail') {
    if (forwardMS(second) > roll.pushSpeedMS * scaleSecond) verdict.pushed = 1
  } else if (placeFirst === 'tail' && placeSecond === 'nose') {
    if (forwardMS(first) > roll.pushSpeedMS * scaleFirst) verdict.pushed = 0
  }
  return verdict
}

/** A car's speed along its own heading, m/s. */
function forwardMS(car: TouchingCar): number {
  return car.velocity.x * Math.cos(car.headingRad) + car.velocity.y * Math.sin(car.headingRad)
}

/**
 * The count of ticks a car has been pushed along from behind, after one more tick: one up if during it another
 * car's nose was against its tail and it was going faster than its push speed, and nothing as soon as either is not so.
 */
export function pushTicksAfter(ticks: number, pushed: boolean): number {
  return pushed ? ticks + 1 : 0
}

/** Whether a car that has been pushed along for `ticks` ticks running has been pushed for longer than the push time, and goes over. */
export function pushedOver(ticks: number, roll: Pick<RollTuning, 'pushTimeS'>): boolean {
  return ticks * DT > roll.pushTimeS
}

/**
 * How a rolled car moves (F-512): the speed it went over at, m/s; and, drawn as it went over, how far it is to be
 * dragged on its roof, m, and how far it is to turn while it is, rad, positive to the right.
 */
export interface RollSlide {
  fromMS: number
  lengthM: number
  turnRad: number
}

/**
 * The slide of a car that goes over moving at `velocity`: its length, the size of its turn and the way it turns,
 * drawn in that order, each as likely anywhere in its range as anywhere else. Three draws from `rng`, always.
 */
export function beginSlide(velocity: Readonly<Vec2>, rng: Pick<Rng, 'range' | 'chance'>, roll: Pick<RollTuning, 'slideMinM' | 'slideMaxM' | 'turnMinRad' | 'turnMaxRad'>): RollSlide {
  const lengthM = drawBetween(rng, roll.slideMinM, roll.slideMaxM)
  const turnRad = drawBetween(rng, roll.turnMinRad, roll.turnMaxRad)
  return { fromMS: Math.hypot(velocity.x, velocity.y), lengthM, turnRad: rng.chance(0.5) ? turnRad : -turnRad }
}

/** A number drawn between two, whichever way round the tuning has them; one draw even when they are the same. */
function drawBetween(rng: Pick<Rng, 'range'>, a: number, b: number): number {
  const value = rng.range(Math.min(a, b), Math.max(a, b))
  return a === b ? a : value
}

/**
 * The speed its slide on the roof begins at, m/s: the one that drags it its drawn length in the slide time, slowing
 * evenly to rest; or, for a car that went over slower than that, the speed it went over at, which takes it less far.
 */
export function slideStartMS(slide: Readonly<RollSlide>, roll: Pick<RollTuning, 'slideTimeS'>): number {
  return roll.slideTimeS > 0 ? Math.min(slide.fromMS, (2 * slide.lengthM) / roll.slideTimeS) : 0
}

/**
 * What a car on its roof is given in place of the ground, `sinceS` seconds after it went over (F-512): no grip at
 * all, so that neither the tyres, the motor nor the brake reach it and nothing its driver does matters; a drag; and a
 * yaw rate it is held to.
 *
 * - **Going over**, for the going-over time: it carries on along its way, slowing evenly from the speed it went over
 *   at to the speed its slide begins at, and does not turn.
 * - **Dragged on its roof**, for the slide time: it slows evenly to rest over that time, and turns its drawn turn
 *   one way, smoothly: from no turn, to its fastest halfway through, and back to none, never faster than the
 *   slow-turn rate.
 * - **Lying there**, from then on: the lying drag, and held to no turn at all, whatever shoves it.
 */
export function rolledEnvironment(massKg: number, slide: Readonly<RollSlide>, sinceS: number, roll: RollTuning): SurfaceEnvironment & { yawRateRadS: number } {
  const startMS = slideStartMS(slide, roll)
  if (sinceS < roll.goingOverS) {
    return { grip: 0, dragN: (massKg * (slide.fromMS - startMS)) / roll.goingOverS, airborne: false, steerScale: 1, yawRateRadS: 0 }
  }
  const share = roll.slideTimeS > 0 ? (sinceS - roll.goingOverS) / roll.slideTimeS : 1
  const decelMS2 = share >= 1 ? roll.lyingDecelMS2 : startMS / roll.slideTimeS
  const turning = share < 1 ? Math.min(roll.slowTurnRadS, (Math.abs(slide.turnRad) / roll.slideTimeS) * (1 - Math.cos(2 * Math.PI * share))) : 0
  return { grip: 0, dragN: massKg * decelMS2, airborne: false, steerScale: 1, yawRateRadS: turning > 0 ? Math.sign(slide.turnRad) * turning : 0 }
}

/** The tick a car that went over on `flipTick` begins its slide on its roof: its going over ends there. */
export function slideBeginsTick(flipTick: Tick, roll: Pick<RollTuning, 'goingOverS'>): Tick {
  return flipTick + Math.ceil(roll.goingOverS * TICK_RATE - 1e-9)
}
