import type { Vec2 } from '../core'

// Weather (contracts.md §7). The sky, how wet the track is, the puddles in its low spots and the wind, as the
// session's snapshot hands them out and as a session is told to begin.

/** The four skies, in order from the driest to the wettest (`SKIES`): the sky only ever moves to a neighbour. */
export type Sky = 'sunny' | 'cloudy' | 'light-rain' | 'heavy-rain'

/** What the event's settings ask of the sky. `surprise` is one of the other three, drawn from the event's seed. */
export type Forecast = 'dry' | 'changeable' | 'wet' | 'surprise'

/** A forecast that has a preset of its own: every one but `surprise`. */
export type SettledForecast = Exclude<Forecast, 'surprise'>

/** The weather a session begins with, and the forecast it then follows. */
export interface WeatherPlan {
  forecast: Forecast
  initialSky: Sky
  /** 0..1, of the surface and of the racing line alike. */
  initialWetness: number
  /** Where the wind blows towards, radians clockwise from +x in the world frame; the direction it then wanders about. */
  windDirRad: number
  /** m/s, before any gust. */
  windSpeedMS: number
  /**
   * A calm session: a sunny sky, a dry track and still air from its first tick to its last, whatever the other
   * fields say, with no `sky`, `gust` or `puddle` event and no weather notice. Practice is always calm, so that a
   * lap is comparable with a lap: a wind that differed by seed would make a best lap a matter of luck.
   */
  calm?: boolean
}

/** The plan of a calm session (`WeatherPlan.calm`): what practice runs under. */
export const CALM_WEATHER: Readonly<WeatherPlan> = Object.freeze({ forecast: 'dry', initialSky: 'sunny', initialWetness: 0, windDirRad: 0, windSpeedMS: 0, calm: true })

export interface WeatherSnapshot {
  readonly sky: Sky
  /** 0..1: none under a dry sky, 0.4 in light rain and 1 in heavy, eased from one to the next. */
  readonly rainIntensity: number
  /** 0..1 track average. */
  readonly wetness: number
  /** 0..1 on the racing line (dries first). */
  readonly lineWetness: number
  /** m/s, world frame, including gust: the way the air moves, not where it comes from. */
  readonly wind: Readonly<Vec2>
  /**
   * One for each of the track's `puddleSpots`, in their order, dry ones included (depth 0, radius 0). `x`, `y`: the
   * spot's centre, m. `depth`: 0..1. `r`: the radius of the water now, m, from 0 up to the spot's own.
   */
  readonly puddles: ReadonlyArray<{ readonly x: number; readonly y: number; readonly r: number; readonly depth: number }>
  /** 0..1 (view only). */
  readonly cloudCover: number
}

/**
 * Weather held from outside (development and tests only, `forceWeather`): each field that is given is set to its
 * value and kept there while everything not given goes on by itself.
 */
export interface WeatherForce {
  sky?: Sky
  /** 0..1 */
  rainIntensity?: number
  /** 0..1 */
  wetness?: number
  /** 0..1 */
  lineWetness?: number
  /** m/s, world frame; while it is held there are no gusts. */
  wind?: Readonly<Vec2>
  /** The depth of each puddle, 0..1, in the order of the track's `puddleSpots`; a spot left out is not held. */
  puddles?: readonly number[]
}
