import { Chain, Circle, Polygon, RopeJoint, World, type Body, type Contact, type ContactImpulse, type Fixture } from 'planck'
import { DT, type CarId, type Pose, type Vec2 } from '../core'
import type { Point } from '../track'
import type { BodyState, CarParams, Tuning, Wrench } from '../vehicle/types'
import {
  CORNER_CHAMFER_M,
  HELD_TYRE_MASS_KG,
  HELD_TYRE_SPIN_KG_M2,
  MIN_TYRE_TRAVEL_M,
  MIN_WALL_VERTEX_GAP_M,
  POSITION_ITERATIONS,
  TYRE_ARRIVAL_TICKS,
  TYRE_HOLD_MARGIN,
  TYRE_LIMIT_SKIN_M,
  TYRE_REST_M,
  TYRE_REST_MS,
  VELOCITY_ITERATIONS,
} from './tuning'

// The rigid-body and collision substrate (ADR-002): planck, and the only file in the simulation that knows it.
// Cars are dynamic boxes with cut corners; walls are chains on one static body and the track's fixed markers
// (cones) are circles on another. A tyre lying loose (F-308) is a light body of its own, sprung to where it lay.
// The vehicle model's force and torque go in before each step and plain numbers come out after it; no planck type
// crosses this boundary.

/** A wall as the track hands it over: a run of points, closed into a ring or left open. */
export interface WallPolyline {
  polyline: readonly Point[]
  closed: boolean
}

/** A solid round obstacle as the track hands it over: a tyre lying flat, a cone. Metres. */
export interface MarkerCircle {
  x: number
  y: number
  r: number
  /**
   * What it is, in the track's own words. A `dot` is a tyre lying loose: in a world that is told how tyres give
   * (`setWalls`) a car can push it. Anything else, and anything unnamed, stands where it is.
   */
  kind?: 'dot' | 'cone'
}

/** What one pair of things did to each other since contacts were last drained. */
export interface ContactRecord {
  a: CarId
  b: CarId | 'wall' | 'marker' | 'marshal'
  /** Which marshal, where `b` is one (F-502). */
  marshal?: number
  /** Normal impulse, N·s, summed over the steps since the last drain. */
  impulseNs: number
  /** Where, and which way from `a` toward `b` (unit vector), at the hardest moment of the contact. */
  point: Vec2
  normal: Vec2
}

export interface PhysicsWorld {
  /** Cars are added in `CarId` order, so the solver sees the same sequence every run. */
  addCar(id: CarId, p: CarParams, pose: Pose): void
  /**
   * Development only (F-206): gives a car already in the world the mass, yaw inertia and footprint of new parameters.
   * Its position, velocity and yaw rate are left alone.
   */
  reshape(id: CarId, p: CarParams): void
  /**
   * Development only (F-206): replaces what the walls, the markers and the cars are made of, and how the loose tyres
   * give, from the next step on. The next touch of each kind uses the new figures; nothing is rebuilt and nothing
   * moves. Until it is first called a world behaves exactly as it was made.
   */
  setContact(next: WorldContact): void
  /**
   * Replaces every wall and every marker. A marker is as solid as a wall, with friction and restitution of its
   * own where a car touches it: `markerContact`, or what the walls are made of if that is left out. Leaving
   * `markers` out leaves the world with none.
   *
   * With `give`, the markers of kind `dot` are tyres lying loose (F-308): each starts at rest where the track has
   * it, moves and turns when a car pushes it, is pulled back there by a spring and a damper, and can go no further
   * from there than `give.travelM`, where it is as solid as any other marker. Tyres meet cars only: they pass over
   * walls and over each other. Without `give`, or with no mass or no travel in it, every marker stands where it is.
   */
  setWalls(walls: readonly WallPolyline[], markers?: readonly MarkerCircle[], markerContact?: MarkerContact, give?: MarkerGive): void
  /** Adds to the force and torque that the next step applies to a car, then forgets. */
  apply(id: CarId, wrench: Wrench): void
  /** Advance exactly DT. */
  step(): void
  body(id: CarId): BodyState
  /** Marshals and starts use this. It moves the car and nothing else: a tyre stays where it is. */
  setPose(id: CarId, pose: Pose, zeroVelocity: boolean): void
  /**
   * The marshals who are out on the track (F-502), each a solid circle a car bounces off as it does off a wall, and
   * that nothing moves. Call before a step with all of them: one that is named is put where it is said to be, and
   * one that is no longer named is gone. They meet cars only; a loose tyre passes under their feet.
   */
  setMarshals(marshals: ReadonlyArray<{ id: number; pos: Readonly<Vec2>; radiusM: number }>): void
  /**
   * Where the centre of each marker is now, written into `out` in the order the markers were given to `setWalls`
   * (every one of them, loose or not). `out` is made the right length and its objects are reused.
   */
  markersInto(out: Vec2[]): void
  /** Every contact since the last call, one record per pair, in the order the pairs first touched. Empties the list. */
  drainContacts(): ContactRecord[]
  /**
   * Appends position, heading, velocity and yaw rate of every car, in `CarId` order; then, of every loose tyre in
   * marker order, its position, how far it has turned, its velocity, how fast it is turning, and for how many more
   * steps it is held at the end of its travel (zero while it lies loose).
   */
  hashInto(buffer: number[]): void
}

/** The three contact blocks of the tuning, as `setContact` takes them. */
export type WorldContact = Readonly<Pick<Tuning, 'contact' | 'marker' | 'carContact'>>

/** What the markers are made of where a car touches one: the tuning's two contact figures for them. */
export type MarkerContact = Readonly<Pick<Tuning['marker'], 'friction' | 'restitution'>>

/** How a loose tyre gives (F-308): the tuning's other figures for the markers. */
export type MarkerGive = Readonly<Omit<Tuning['marker'], 'friction' | 'restitution'>>

/** What two cars are made of where they touch each other: the tuning's figures for that. */
export type CarContact = Readonly<Tuning['carContact']>

/** A loose tyre's mass is never taken below this when it is changed while a session runs (F-206): a tyre of no mass has no motion to give. */
const MIN_LIVE_TYRE_MASS_KG = 0.001

const WALL = 'wall'
const MARKER = 'marker'
/** A marshal's body is tagged with this and his id. */
const MARSHAL = 'marshal:'
const marshalTag = (tag: unknown): number | null => (typeof tag === 'string' && tag.startsWith(MARSHAL) ? Number(tag.slice(MARSHAL.length)) : null)

// Who can touch whom. A loose tyre meets cars and nothing else; everything else meets everything, as it always has.
const SOLID_BITS = 0x0001
const CAR_BITS = 0x0002
const TYRE_BITS = 0x0004
const EVERYTHING = 0xffff

const STILL: Readonly<Vec2> = { x: 0, y: 0 }

/** A tyre lying loose (F-308). */
interface LooseTyre {
  body: Body
  /** The tie that limits its travel. */
  tie: RopeJoint
  /** Its radius, m. */
  radiusM: number
  /** How hard it is to turn about its own middle while it lies loose, kg·m²: that of a flat disc of its weight and size. */
  spinKgM2: number
  /**
   * More than zero while it is held at the end of its travel, where it stands as a post does: the steps it will go
   * on standing there if no car presses it outward. One once a car has pressed it there, so that it is let go on
   * the first step that no car does; more while it waits for the car that pushed it to arrive. Zero while it lies loose.
   */
  holdTicks: number
  /** What the cars pressing on it gave it during the step in progress, N·s. */
  pushed: Vec2
}

/** A marker as the world keeps it: where it lay, and what moves if it is a loose tyre. */
interface Placed {
  home: Vec2
  tyre: LooseTyre | null
}

/** The car's footprint: its length × width box with the four corners cut off. Eight vertices, planck's limit. */
function carOutline(lengthM: number, widthM: number): Vec2[] {
  const halfLength = lengthM / 2
  const halfWidth = widthM / 2
  const cut = Math.min(CORNER_CHAMFER_M, halfLength / 2, halfWidth / 2)
  return [
    { x: halfLength - cut, y: -halfWidth },
    { x: halfLength, y: -halfWidth + cut },
    { x: halfLength, y: halfWidth - cut },
    { x: halfLength - cut, y: halfWidth },
    { x: -halfLength + cut, y: halfWidth },
    { x: -halfLength, y: halfWidth - cut },
    { x: -halfLength, y: -halfWidth + cut },
    { x: -halfLength + cut, y: -halfWidth },
  ]
}

/** A polyline's points with any that sit on top of their neighbour removed. */
function distinctVertices(polyline: readonly Point[], closed: boolean): Vec2[] {
  const minGapSq = MIN_WALL_VERTEX_GAP_M * MIN_WALL_VERTEX_GAP_M
  const apart = (a: Vec2, b: Vec2): boolean => (a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y) >= minGapSq
  const kept: Vec2[] = []
  for (const [x, y] of polyline) {
    const vertex = { x, y }
    if (kept.length === 0 || apart(kept[kept.length - 1], vertex)) kept.push(vertex)
  }
  // A ring written with its first point repeated at the end.
  while (closed && kept.length > 1 && !apart(kept[0], kept[kept.length - 1])) kept.pop()
  return kept
}

/**
 * `contact` is what cars and walls are made of. `carContact` is what a car meets in another car; left out, two cars
 * meet as a car meets a wall.
 */
export function createPhysicsWorld(contact: Tuning['contact'], carContact?: CarContact): PhysicsWorld {
  // Sleeping is off: a parked car must answer the instant a force arrives, and a sleep timer would be state
  // that the hash does not cover.
  const world = new World({ gravity: { x: 0, y: 0 }, allowSleep: false })
  const wallBody = world.createBody({ type: 'static', userData: WALL })
  const markerBody = world.createBody({ type: 'static', userData: MARKER })
  const cars: Body[] = []
  // The footprint each car was last built with, so that a change of mass alone does not rebuild its fixture.
  const footprints: Array<{ lengthM: number; widthM: number }> = []
  // Every marker in the order it was given, and how the loose tyres among them give; null while none does.
  let placed: Placed[] = []
  let gives: MarkerGive | null = null
  const looseBy = new Map<Body, LooseTyre>()
  // Contacts since the last drain, and beside each the hardest single impulse that went into it.
  let contacts: ContactRecord[] = []
  let hardestNs: number[] = []

  const carAt = (id: CarId): Body => {
    const body = cars[id]
    if (body === undefined) throw new RangeError(`No car ${id} in the physics world`)
    return body
  }

  // The marshals who are out on the track, by id.
  const marshals = new Map<number, Body>()

  const record = (a: CarId, b: ContactRecord['b'], impulseNs: number, point: Vec2, normal: Vec2, marshal?: number): void => {
    for (let i = 0; i < contacts.length; i++) {
      const existing = contacts[i]
      if (existing.a !== a || existing.b !== b || existing.marshal !== marshal) continue
      existing.impulseNs += impulseNs
      if (impulseNs > hardestNs[i]) {
        hardestNs[i] = impulseNs
        existing.point = point
        existing.normal = normal
      }
      return
    }
    contacts.push(marshal === undefined ? { a, b, impulseNs, point, normal } : { a, b, impulseNs, point, normal, marshal })
    hardestNs.push(impulseNs)
  }

  // A car on a marker, or a car on a car: the pair's friction and restitution are that pairing's own figures, as
  // they stand. planck would otherwise mix the two fixtures' values (the greater restitution, the mean friction),
  // and a tyre or a body shell could then never be softer than a barrier. The two are told apart by what each
  // body is, not by whether it can move: a loose tyre moves, and is a marker still.
  let markersMadeOf: MarkerContact | null = null
  // What a car meets in a wall. Null until `setContact` first says: until then the pair is left to the mix of the two
  // fixtures' figures, which are the same, so that a world nobody has tuned is exactly what it always was.
  let wallsMadeOf: MarkerContact | null = null
  let carsMadeOf: CarContact | null = carContact === undefined ? null : { friction: carContact.friction, restitution: carContact.restitution }
  world.on('pre-solve', (touching: Contact) => {
    const tagA = touching.getFixtureA().getBody().getUserData()
    const tagB = touching.getFixtureB().getBody().getUserData()
    const pairing =
      tagA === MARKER || tagB === MARKER
        ? markersMadeOf
        : tagA === WALL || tagB === WALL
          ? wallsMadeOf
          : typeof tagA === 'number' && typeof tagB === 'number'
            ? carsMadeOf
            : null
    if (pairing === null) return
    touching.setFriction(pairing.friction)
    touching.setRestitution(pairing.restitution)
  })

  world.on('post-solve', (touching: Contact, impulse: ContactImpulse) => {
    const pointCount = touching.getManifold().pointCount
    const normalImpulses = impulse.normalImpulses
    let impulseNs = 0
    for (let i = 0; i < pointCount; i++) impulseNs += normalImpulses[i]
    if (!(impulseNs > 0)) return
    const manifold = touching.getWorldManifold(null)
    if (manifold === undefined || manifold.pointCount === 0) return

    let x = 0
    let y = 0
    for (let i = 0; i < manifold.pointCount; i++) {
      x += manifold.points[i].x
      y += manifold.points[i].y
    }
    const point = { x: x / manifold.pointCount, y: y / manifold.pointCount }
    // planck's normal points from its fixture A to its fixture B.
    const bodyA = touching.getFixtureA().getBody()
    const bodyB = touching.getFixtureB().getBody()
    const tagA = bodyA.getUserData()
    const tagB = bodyB.getUserData()
    const forward = { x: manifold.normal.x, y: manifold.normal.y }
    const backward = { x: -manifold.normal.x, y: -manifold.normal.y }
    const tyre = looseBy.get(typeof tagA === 'number' ? bodyB : bodyA)
    if (tyre !== undefined) {
      const toTyre = typeof tagA === 'number' ? forward : backward
      tyre.pushed.x += impulseNs * toTyre.x
      tyre.pushed.y += impulseNs * toTyre.y
    }
    if (typeof tagA === 'number' && typeof tagB === 'number') {
      if (tagA < tagB) record(tagA, tagB, impulseNs, point, forward)
      else record(tagB, tagA, impulseNs, point, backward)
    } else if (typeof tagA === 'number') {
      const marshal = marshalTag(tagB)
      if (marshal !== null) record(tagA, 'marshal', impulseNs, point, forward, marshal)
      else record(tagA, tagB === MARKER ? MARKER : WALL, impulseNs, point, forward)
    } else if (typeof tagB === 'number') {
      const marshal = marshalTag(tagA)
      if (marshal !== null) record(tagB, 'marshal', impulseNs, point, backward, marshal)
      else record(tagB, tagA === MARKER ? MARKER : WALL, impulseNs, point, backward)
    }
  })

  const carFixture = (p: CarParams) => ({
    shape: new Polygon(carOutline(p.lengthM, p.widthM)),
    density: 1,
    friction: contact.friction,
    restitution: contact.restitution,
    filterCategoryBits: CAR_BITS,
    filterMaskBits: EVERYTHING,
  })

  /**
   * A tyre lying loose at `marker`: a light disc, tied to where it lies so that it can go no further than its travel.
   * It is free to turn about its own middle, which is what lets it roll off the corner of a car that catches it:
   * a disc that could not turn would be gripped by the car's corner and carried along in front of it.
   */
  const looseTyre = (marker: MarkerCircle, give: MarkerGive): LooseTyre => {
    const body = world.createBody({ type: 'dynamic', position: { x: marker.x, y: marker.y }, linearDamping: 0, angularDamping: 0, userData: MARKER })
    body.createFixture({
      shape: new Circle(marker.r),
      density: 1,
      friction: contact.friction,
      restitution: contact.restitution,
      filterCategoryBits: TYRE_BITS,
      filterMaskBits: CAR_BITS,
    })
    const spinKgM2 = 0.5 * give.massKg * marker.r * marker.r
    body.setMassData({ mass: give.massKg, center: STILL, I: spinKgM2 })
    // The travel limit, held inside the solver: a clamp applied after the step alone would let a car lean its way
    // through, a little of the tyre's travel given back on every step.
    const tie = new RopeJoint({ bodyA: markerBody, bodyB: body, localAnchorA: { x: marker.x, y: marker.y }, localAnchorB: { x: 0, y: 0 }, maxLength: give.travelM })
    world.createJoint(tie)
    // At home and at rest it sleeps: it costs nothing until a car touches it, which wakes it within the same step.
    body.setAwake(false)
    const tyre = { body, tie, radiusM: marker.r, spinKgM2, holdTicks: 0, pushed: { x: 0, y: 0 } }
    looseBy.set(body, tyre)
    return tyre
  }

  /** Before the step: the spring and the damper that take a displaced tyre home, as a plain force. A tyre a car is holding at the end of its travel is left to the car. */
  const pullHome = (give: MarkerGive): void => {
    for (const { home, tyre } of placed) {
      if (tyre === null || tyre.holdTicks > 0 || !tyre.body.isAwake()) continue
      const at = tyre.body.getPosition()
      const velocity = tyre.body.getLinearVelocity()
      tyre.body.applyForceToCenter(
        { x: give.springNPerM * (home.x - at.x) - give.dampingNsPerM * velocity.x, y: give.springNPerM * (home.y - at.y) - give.dampingNsPerM * velocity.y },
        false,
      )
    }
  }

  /**
   * After the step. A tyre past its travel is put back on the limit with none of its speed outward left. One that a
   * car has pushed to the end of its travel, or to within a step of it, and presses outward harder than its spring
   * pulls it back, is held at the limit: it stands as a fixed marker does, unable to move or turn, until the car
   * that was pushing it has caught it up and for as long as a car then goes on pressing it outward. One that is
   * home and all but still is put exactly home, at rest, asleep.
   */
  const settle = (give: MarkerGive): void => {
    for (const { home, tyre } of placed) {
      if (tyre === null) continue
      const { body, pushed } = tyre
      const pushedX = pushed.x
      const pushedY = pushed.y
      pushed.x = 0
      pushed.y = 0
      if (!body.isAwake()) continue

      const at = body.getPosition()
      const velocity = body.getLinearVelocity()
      const dx = at.x - home.x
      const dy = at.y - home.y
      const away = Math.hypot(dx, dy)
      const ux = away > 0 ? dx / away : 0
      const uy = away > 0 ? dy / away : 0
      const outwardMS = velocity.x * ux + velocity.y * uy
      if (away > give.travelM) {
        body.setTransform({ x: home.x + ux * give.travelM, y: home.y + uy * give.travelM }, body.getAngle())
        if (outwardMS > 0) body.setLinearVelocity({ x: velocity.x - outwardMS * ux, y: velocity.y - outwardMS * uy })
      }

      // How hard the cars pressed it away from home during the step, N·s.
      const outwardNs = pushedX * ux + pushedY * uy
      if (tyre.holdTicks > 0) {
        body.setLinearVelocity(STILL)
        body.setAngularVelocity(0)
        if (outwardNs > 0) tyre.holdTicks = 1
        else if (--tyre.holdTicks === 0) body.setMassData({ mass: give.massKg, center: STILL, I: tyre.spinKgM2 })
      } else if (outwardNs > TYRE_HOLD_MARGIN * give.springNPerM * give.travelM * DT && away + Math.max(0, outwardMS) * DT > give.travelM - TYRE_LIMIT_SKIN_M) {
        // At the end of its travel, or within a step of it: it is put there now, so that the car meets a post at the
        // limit itself instead of running on into a tyre that is still light for the step in which it gets there.
        tyre.holdTicks = 1 + TYRE_ARRIVAL_TICKS
        body.setTransform({ x: home.x + ux * give.travelM, y: home.y + uy * give.travelM }, body.getAngle())
        body.setLinearVelocity(STILL)
        body.setAngularVelocity(0)
        body.setMassData({ mass: HELD_TYRE_MASS_KG, center: STILL, I: HELD_TYRE_SPIN_KG_M2 })
      } else if (away < TYRE_REST_M && Math.hypot(velocity.x, velocity.y) < TYRE_REST_MS) {
        body.setTransform(home, 0)
        body.setAwake(false)
      }
    }
  }

  return {
    addCar(id, p, pose) {
      if (id !== cars.length) throw new Error(`Cars must be added in id order: expected ${cars.length}, got ${id}`)
      // `bullet` asks for time-of-impact sweeps against other cars too; sweeps against the static walls happen
      // for every dynamic body. No damping: all resistance comes from the vehicle model.
      const body = world.createBody({
        type: 'dynamic',
        position: { x: pose.x, y: pose.y },
        angle: pose.angle,
        bullet: true,
        linearDamping: 0,
        angularDamping: 0,
        userData: id,
      })
      body.createFixture(carFixture(p))
      // planck derives mass and inertia from the fixture; the vehicle model needs the car's own.
      body.setMassData({ mass: p.massKg, center: { x: 0, y: 0 }, I: p.yawInertiaKgM2 })
      cars.push(body)
      footprints.push({ lengthM: p.lengthM, widthM: p.widthM })
    },

    reshape(id, p) {
      const body = carAt(id)
      const was = footprints[id]
      if (was.lengthM !== p.lengthM || was.widthM !== p.widthM) {
        for (let fixture = body.getFixtureList(); fixture !== null; fixture = body.getFixtureList()) body.destroyFixture(fixture)
        body.createFixture(carFixture(p))
        footprints[id] = { lengthM: p.lengthM, widthM: p.widthM }
      }
      body.setMassData({ mass: p.massKg, center: { x: 0, y: 0 }, I: p.yawInertiaKgM2 })
    },

    setContact(next) {
      wallsMadeOf = { friction: next.contact.friction, restitution: next.contact.restitution }
      markersMadeOf = { friction: next.marker.friction, restitution: next.marker.restitution }
      carsMadeOf = { friction: next.carContact.friction, restitution: next.carContact.restitution }
      // The tyres' spring and damper are read on every step. Their mass and their travel are held by the bodies and
      // by the ties, so those are written through. A world with no loose tyres, or one that was made to give none,
      // has nothing to give.
      if (gives === null) return
      const { massKg, springNPerM, dampingNsPerM, travelM } = next.marker
      gives = { massKg: Math.max(massKg, MIN_LIVE_TYRE_MASS_KG), springNPerM, dampingNsPerM, travelM: Math.max(travelM, 2 * MIN_TYRE_TRAVEL_M) }
      for (const { tyre } of placed) {
        if (tyre === null) continue
        tyre.tie.setMaxLength(gives.travelM)
        tyre.spinKgM2 = 0.5 * gives.massKg * tyre.radiusM * tyre.radiusM
        // A tyre held at the end of its travel is as heavy as a post until it is let go, and is given its own mass then.
        if (tyre.holdTicks === 0) tyre.body.setMassData({ mass: gives.massKg, center: STILL, I: tyre.spinKgM2 })
      }
    },

    setWalls(walls, markers = [], markerContact, give) {
      markersMadeOf = markerContact === undefined ? null : { friction: markerContact.friction, restitution: markerContact.restitution }
      gives =
        give !== undefined && give.massKg > 0 && give.travelM > MIN_TYRE_TRAVEL_M
          ? { massKg: give.massKg, springNPerM: give.springNPerM, dampingNsPerM: give.dampingNsPerM, travelM: give.travelM }
          : null
      // The loose tyres go, each with the tie that holds it; then the fixed things, fixture by fixture.
      for (const { tyre } of placed) if (tyre !== null) world.destroyBody(tyre.body)
      looseBy.clear()
      for (const body of [wallBody, markerBody]) {
        const old: Fixture[] = []
        for (let fixture = body.getFixtureList(); fixture !== null; fixture = fixture.getNext()) old.push(fixture)
        for (const fixture of old) body.destroyFixture(fixture)
      }
      for (const wall of walls) {
        const vertices = distinctVertices(wall.polyline, wall.closed)
        if (vertices.length < 2) continue
        // A chain carries each edge's neighbours, which is what lets a car slide across a joint between two
        // pieces of the same wall without catching on it. A "ring" of two points is just a segment.
        const shape = new Chain(vertices, wall.closed && vertices.length >= 3)
        wallBody.createFixture({ shape, friction: contact.friction, restitution: contact.restitution, filterCategoryBits: SOLID_BITS, filterMaskBits: EVERYTHING })
      }
      // Made as the walls are; what a car feels on touching one is set pair by pair, above.
      placed = markers.map((marker) => {
        const home = { x: marker.x, y: marker.y }
        if (!(marker.r > 0)) return { home, tyre: null }
        if (gives !== null && marker.kind === 'dot') return { home, tyre: looseTyre(marker, gives) }
        markerBody.createFixture({
          shape: new Circle(home, marker.r),
          friction: contact.friction,
          restitution: contact.restitution,
          filterCategoryBits: SOLID_BITS,
          filterMaskBits: EVERYTHING,
        })
        return { home, tyre: null }
      })
    },

    apply(id, wrench) {
      const body = carAt(id)
      body.applyForceToCenter({ x: wrench.fx, y: wrench.fy }, true)
      body.applyTorque(wrench.torque, true)
    },

    step() {
      if (gives !== null) pullHome(gives)
      world.step(DT, VELOCITY_ITERATIONS, POSITION_ITERATIONS)
      if (gives !== null) settle(gives)
    },

    body(id) {
      const body = carAt(id)
      const position = body.getPosition()
      const velocity = body.getLinearVelocity()
      return {
        pose: { x: position.x, y: position.y, angle: body.getAngle() },
        velocity: { x: velocity.x, y: velocity.y },
        yawRate: body.getAngularVelocity(),
      }
    },

    setPose(id, pose, zeroVelocity) {
      const body = carAt(id)
      body.setTransform({ x: pose.x, y: pose.y }, pose.angle)
      if (zeroVelocity) {
        body.setLinearVelocity({ x: 0, y: 0 })
        body.setAngularVelocity(0)
      }
    },

    setMarshals(named) {
      if (named.length === 0 && marshals.size === 0) return
      for (const [was, body] of marshals) {
        if (named.some(({ id: still }) => still === was)) continue
        world.destroyBody(body)
        marshals.delete(was)
      }
      for (const marshal of named) {
        let body = marshals.get(marshal.id)
        if (body === undefined) {
          // Kinematic: a car that runs into him is turned aside and he is not moved. He is made of what a wall is.
          body = world.createBody({ type: 'kinematic', position: { x: marshal.pos.x, y: marshal.pos.y }, userData: `${MARSHAL}${marshal.id}` })
          body.createFixture({ shape: new Circle(marshal.radiusM), friction: contact.friction, restitution: contact.restitution, filterCategoryBits: SOLID_BITS, filterMaskBits: EVERYTHING })
          marshals.set(marshal.id, body)
        }
        const at = body.getPosition()
        if (at.x !== marshal.pos.x || at.y !== marshal.pos.y) body.setTransform({ x: marshal.pos.x, y: marshal.pos.y }, 0)
      }
    },

    drainContacts() {
      const drained = contacts
      contacts = []
      hardestNs = []
      return drained
    },

    markersInto(out) {
      out.length = placed.length
      for (let i = 0; i < placed.length; i++) {
        const { home, tyre } = placed[i]
        const at = tyre === null ? home : tyre.body.getPosition()
        const slot = out[i] ?? (out[i] = { x: 0, y: 0 })
        slot.x = at.x
        slot.y = at.y
      }
    },

    hashInto(buffer) {
      for (const body of cars) {
        const position = body.getPosition()
        const velocity = body.getLinearVelocity()
        buffer.push(position.x, position.y, body.getAngle(), velocity.x, velocity.y, body.getAngularVelocity())
      }
      for (const { tyre } of placed) {
        if (tyre === null) continue
        const position = tyre.body.getPosition()
        const velocity = tyre.body.getLinearVelocity()
        buffer.push(position.x, position.y, tyre.body.getAngle(), velocity.x, velocity.y, tyre.body.getAngularVelocity(), tyre.holdTicks)
      }
    },
  }
}
