import type { Vec2 } from './types'

export const TWO_PI = 2 * Math.PI

export function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max)
}

/** Blend from `a` (t = 0) to `b` (t = 1); exact at both ends. */
export function lerp(a: number, b: number, t: number): number {
  return a * (1 - t) + b * t
}

/** The same direction as `angle`, in (-π, π]. */
export function wrapAngle(angle: number): number {
  const turn = angle % TWO_PI
  if (turn > Math.PI) return turn - TWO_PI
  if (turn <= -Math.PI) return turn + TWO_PI
  return turn
}

/** Signed shortest rotation that takes heading `from` to heading `to`, in (-π, π]. Positive is to the right. */
export function angleDiff(from: number, to: number): number {
  return wrapAngle(to - from)
}

export function vecAdd(a: Readonly<Vec2>, b: Readonly<Vec2>): Vec2 {
  return { x: a.x + b.x, y: a.y + b.y }
}

export function vecSub(a: Readonly<Vec2>, b: Readonly<Vec2>): Vec2 {
  return { x: a.x - b.x, y: a.y - b.y }
}

export function vecScale(v: Readonly<Vec2>, factor: number): Vec2 {
  return { x: v.x * factor, y: v.y * factor }
}

export function vecDot(a: Readonly<Vec2>, b: Readonly<Vec2>): number {
  return a.x * b.x + a.y * b.y
}

/** z of the cross product. Positive when `b` lies to the right of `a` (y is down, angles run clockwise). */
export function vecCross(a: Readonly<Vec2>, b: Readonly<Vec2>): number {
  return a.x * b.y - a.y * b.x
}

export function vecLength(v: Readonly<Vec2>): number {
  return Math.sqrt(v.x * v.x + v.y * v.y)
}

/** Turn `v` by `angle` radians, positive to the right. */
export function vecRotate(v: Readonly<Vec2>, angle: number): Vec2 {
  const cos = Math.cos(angle)
  const sin = Math.sin(angle)
  return { x: v.x * cos - v.y * sin, y: v.x * sin + v.y * cos }
}

/** The vector of the given length along heading `angle`. */
export function vecFromAngle(angle: number, length = 1): Vec2 {
  return { x: Math.cos(angle) * length, y: Math.sin(angle) * length }
}
