import type { DriverId } from '../core'
import type { DriverProfile } from '../ai'
import type { CarColour } from '../session'

/** The seven body colours in the game design's order. "The next free colour" is found by walking this ring. */
const COLOUR_RING: readonly CarColour[] = ['red', 'blue', 'yellow', 'green', 'white', 'orange', 'pink']

/**
 * Colours for a field (contracts.md §9): the player keeps `playerColour`; each AI driver in `drivers` gets their
 * preferred colour if nobody has it, else the next free one round the ring, so that every car on track is a
 * different colour. Preferences are settled first, in the order given, and only then are the drivers whose colour
 * was taken placed, so that one driver's second choice never costs another driver their first. Pure: the same
 * arguments give the same answer. Throws for a field larger than the seven colours, a driver listed twice, or one
 * the roster does not know.
 */
export function assignColours(drivers: readonly DriverId[], playerColour: CarColour, roster: readonly DriverProfile[]): Record<DriverId, CarColour> {
  if (drivers.length > COLOUR_RING.length - 1) {
    throw new Error(`assignColours: ${drivers.length} AI drivers and the player need more than the ${COLOUR_RING.length} colours there are`)
  }
  const taken = new Set<CarColour>([playerColour])
  const given: Record<DriverId, CarColour> = {}
  const preferred = (id: DriverId): CarColour => {
    const profile = roster.find((driver) => driver.id === id)
    if (profile === undefined) throw new Error(`assignColours: '${id}' is not in the roster`)
    return profile.preferredColour
  }

  for (const id of drivers) {
    if (id in given) throw new Error(`assignColours: '${id}' is listed twice`)
    const wanted = preferred(id)
    if (!taken.has(wanted)) {
      given[id] = wanted
      taken.add(wanted)
    }
  }
  for (const id of drivers) {
    if (id in given) continue
    const from = COLOUR_RING.indexOf(preferred(id))
    for (let step = 1; step <= COLOUR_RING.length; step++) {
      const colour = COLOUR_RING[(from + step) % COLOUR_RING.length]
      if (colour !== undefined && !taken.has(colour)) {
        given[id] = colour
        taken.add(colour)
        break
      }
    }
  }
  return given
}
