import { clamp, DT, TICK_RATE, type CarId, type Pose, type Tick, type Vec2 } from '../core'
import { kerbRollSpeedMS } from '../incidents/roll'
import type { RollCase } from '../incidents/types'
import type { SimEvent } from '../session/events'
import type { SurfaceKind, TrackRuntime } from '../track'
import type { StepEnvironment, SurfaceTuning } from '../vehicle/types'
import { grassStuckAfterM, surfaceGrip } from '../weather/coupling'
import { kerbUnder, onKerbStrip, ontoKerbStart } from './kerbs'

// What the ground does to a car (F-207). Grass grabs at once and drags harder the further the car has gone on
// it, until the car is stuck; a kerb taken at speed throws the car into a short hop, during which its tyres do
// next to nothing. Grass is read under the car's centre, and only past a narrow grace band along the lane's
// edge, so two wheels on the green or a brush with the edge cost nothing by themselves; a kerb is felt at the
// wheels, so clipping one with the inside pair is enough. One small record per car
// remembers how far it has gone on the grass and how long it has left in the air. Everything here is a pure
// function of its arguments: the state is the session's to keep and to hash, and every number comes from
// `SurfaceTuning`. Nothing reads the car's class.
//
// A kerb puts a car on its roof in two ways, and no others (F-507). The first is the whole nose into the start of a
// kerb: the middle of the nose, between the two front tyres, comes onto a kerb over its start, with the car heading
// along the kerb faster than its shape's roll speed. The second is a hop off one side of a kerb that comes down on
// the same kerb: the tyres of one side met the kerb, and when the hop ends the car's centre is over it and the car is
// still going faster than its roll speed. Slower than the roll speed no kerb rolls a car; and a wheel on a kerb, or
// the wheels of one side, at the kerb's start, along it or leaving it, rolls nobody at any speed.
//
// In the wet (F-602) every surface has less grip, a kerb far less, and grass sticks a car sooner. How wet it is
// under the car is the caller's to say; a dry step is to the last bit the step it was before there was weather.
// Wetness has no part in whether a car hops or rolls: a roll stays the driver's mistake, not the weather's.

/** What the surfaces remember about one car. All of it is part of the session's state hash. */
export interface SurfaceState {
  /** Distance travelled on grass since the car left the lane, m. It drains once the car is back on the lane. */
  offLaneM: number
  /** 0..1: how far toward stuck. `offLaneM` over the tuning's `stuckAfterM`, and 1 once stuck. */
  bog: number
  /** Ticks of the hop in progress still to come, this one included; 0 on the ground. */
  airborneTicks: number
  /** The tick the last hop began on; before any hop, long enough ago for the next to be allowed. */
  lastHopTick: Tick
  /**
   * What the car was on when it was last looked at, as far as the ground's effect on it goes: grass if its centre
   * was on grass past the grace band at the lane's edge, else kerb if its centre or any wheel was on one, else asphalt.
   */
  lastSurface: SurfaceKind
  /** Whether its centre or any wheel was on a kerb then, whatever its centre was on. A hop starts when this turns true. */
  onKerb: boolean
  /** Whether the middle of its nose (the point halfway between its front tyres) was on a kerb then (F-507). A car can go over on the tick this turns true. */
  noseOnKerb: boolean
  /**
   * The kerb whose side threw it into the hop in progress, as its place in the track's `kerbs` (F-507): the hop began
   * with the tyres of one side of the car on that kerb and its centre clear of it. -1 on the ground, and in a hop that
   * began any other way (astride a kerb, or square onto one).
   */
  hopKerb: number
}

/** The part of the model's environment the surfaces decide. */
export type SurfaceEnvironment = Required<Pick<StepEnvironment, 'grip' | 'dragN' | 'airborne' | 'steerScale'>>

/** What `stepSurface` needs to know of a car: where its centre is, how it is moving, how heavy it is and where its axles are. */
export interface SurfaceCar {
  pose: Readonly<Pose>
  /** World frame, m/s. */
  velocity: Readonly<Vec2>
  massKg: number
  /** From the car's centre forward to the front axle and back to the rear one, and the width of the body, m. */
  cgToFrontAxleM: number
  cgToRearAxleM: number
  widthM: number
  /**
   * `CarParams.stabilityFactor`: how hard the car's shape makes it to roll (F-501). Left out, the car is not one
   * that can be rolled just now, and a kerb only ever makes it hop.
   */
  stabilityFactor?: number
  /** How fast it is turning, rad/s, positive to the right. Only tells where its nose was a tick ago a little better; left out, it is taken not to be turning. */
  yawRateRadS?: number
}

/**
 * What a session needs to put ground under its cars: the tuning, and each car's weight and outline as they are
 * now. A session that is given none runs every car on dry asphalt whatever its track says.
 */
export interface SurfaceSetup {
  tuning: SurfaceTuning
  car(id: CarId): { massKg: number; lengthM: number; widthM: number; cgToFrontAxleM: number; cgToRearAxleM: number; stabilityFactor: number }
}

export interface SurfaceStep {
  state: SurfaceState
  env: SurfaceEnvironment
  /** The car has bogged down for good on this tick: it is to stop being driven and wait to be fetched. */
  stuck: boolean
  /**
   * The car has gone over on a kerb on this tick (F-507), and which of the two ways: it is to be put on its roof.
   * No hop begins, and one in progress is over. Null on every other tick.
   */
  rolled: KerbRoll | null
  events: readonly SimEvent[]
}

/** The two ways a kerb rolls a car. */
export type KerbRoll = Extract<RollCase, 'kerb-start' | 'kerb-landing'>

const NO_EVENTS: readonly SimEvent[] = Object.freeze([])
/** Dry asphalt: nothing taken from the tyres and nothing added to the drag. */
const ASPHALT: SurfaceEnvironment = Object.freeze({ grip: 1, dragN: 0, airborne: false, steerScale: 1 })

/** A car that has never left the asphalt. */
export function initialSurfaceState(): SurfaceState {
  return { offLaneM: 0, bog: 0, airborneTicks: 0, lastHopTick: -Infinity, lastSurface: 'asphalt', onKerb: false, noseOnKerb: false, hopKerb: -1 }
}

/**
 * How many ticks a kerb met at `speedMS` throws a car into the air for: the tuning's hop at the speed a hop
 * starts at, growing with speed to twice that at double the speed, and no longer however hard the kerb is hit.
 */
export function hopTicks(speedMS: number, kerb: SurfaceTuning['kerb']): number {
  const harder = kerb.hopSpeedMS > 0 ? clamp((speedMS - kerb.hopSpeedMS) / kerb.hopSpeedMS, 0, 1) : 1
  return Math.round(kerb.hopDurationS * (1 + harder) * TICK_RATE)
}

/**
 * The drag of grass on a car that has gone `offLaneM` on it and is moving at `speedMS`, N. It is there from the
 * first centimetre and grows with every one after. At the tuning's `dragFullAtMS` and faster it is that in full;
 * slower, it falls away in proportion to the speed, which leaves a car that has been slowed right down able to
 * crawl on under its own power.
 */
export function grassDragN(massKg: number, offLaneM: number, speedMS: number, grass: SurfaceTuning['grass']): number {
  const fullN = massKg * (grass.dragNPerKg + grass.dragGrowthPerM * offLaneM)
  return grass.dragFullAtMS > 0 ? fullN * Math.min(1, speedMS / grass.dragFullAtMS) : fullN
}

/**
 * What a stuck car is given: grass under its tyres and the full drag of the whole distance at any speed, so that
 * whatever speed it has left is gone in a few ticks.
 */
export function stuckEnvironment(massKg: number, t: SurfaceTuning): SurfaceEnvironment {
  const dragN = massKg * (t.grass.dragNPerKg + t.grass.dragGrowthPerM * t.grass.stuckAfterM)
  return { grip: t.grass.gripScale, dragN, airborne: false, steerScale: 1 }
}

/**
 * Where a car's four tyres touch the ground, world frame: the two axles, each `wheelTrackShare` of the body's
 * width across.
 */
export function wheelContacts(car: Pick<SurfaceCar, 'pose' | 'cgToFrontAxleM' | 'cgToRearAxleM' | 'widthM'>, kerb: SurfaceTuning['kerb']): Vec2[] {
  const cos = Math.cos(car.pose.angle)
  const sin = Math.sin(car.pose.angle)
  const half = (car.widthM * kerb.wheelTrackShare) / 2
  const contacts: Vec2[] = []
  for (const along of [car.cgToFrontAxleM, -car.cgToRearAxleM]) {
    for (const across of [-half, half]) {
      contacts.push({ x: car.pose.x + cos * along - sin * across, y: car.pose.y + sin * along + cos * across })
    }
  }
  return contacts
}

/**
 * One tick for one car, before the vehicle model runs: looks at what is under the car's centre, its wheels and the middle of its
 * nose and returns what the surfaces now remember, what the model is to be told, whether the car has just become stuck or gone over, and any event.
 * `tick` is the session tick this step will end on, which is the tick its events carry. `wetness` is how wet the
 * ground under the car is, 0..1 (F-602); left out, dry.
 */
export function stepSurface(prev: SurfaceState, car: SurfaceCar, track: TrackRuntime, t: SurfaceTuning, tick: Tick, carId: CarId, wetness = 0): SurfaceStep {
  const centre = track.surfaceAt(car.pose.x, car.pose.y)
  // A kerb is felt at the wheels: under the centre, or under any of the four tyres.
  const wheels = wheelContacts(car, t.kerb)
  const onKerb = centre === 'kerb' || wheels.some((wheel) => track.surfaceAt(wheel.x, wheel.y) === 'kerb')
  // Grass has hold of a car only once its centre is past the grace band along the lane's edge; short of that
  // the car is, for everything the ground does to it, still on the lane.
  const inGrass = centre === 'grass' && !(t.grass.edgeGraceM > 0 && track.distanceOffLane(car.pose.x, car.pose.y) <= t.grass.edgeGraceM)
  const surface: SurfaceKind = inGrass ? 'grass' : onKerb ? 'kerb' : 'asphalt'
  const speedMS = Math.sqrt(car.velocity.x * car.velocity.x + car.velocity.y * car.velocity.y)
  const cos = Math.cos(car.pose.angle)
  const sin = Math.sin(car.pose.angle)
  // The middle of the nose: halfway between the two front tyres.
  const noseX = car.pose.x + cos * car.cgToFrontAxleM
  const noseY = car.pose.y + sin * car.cgToFrontAxleM
  const noseOnKerb = track.surfaceAt(noseX, noseY) === 'kerb'

  // Going over (F-507), for a car that can be rolled. The whole nose into the start of a kerb: on the tick the middle
  // of the nose comes onto a kerb, if it came on over the kerb's start with the car heading along the kerb, faster
  // along its own heading than its shape's roll speed. Or a hop off one side of a kerb that ends, as this tick begins,
  // with the car's centre over that kerb and the car still going faster than its roll speed, whichever way it points.
  let rolled: KerbRoll | null = null
  if (car.stabilityFactor !== undefined) {
    const rollSpeedMS = kerbRollSpeedMS(car.stabilityFactor, t.kerb)
    if (noseOnKerb && !prev.noseOnKerb && cos * car.velocity.x + sin * car.velocity.y > rollSpeedMS) {
      // Where the nose was a tick ago: back along the way the car's centre is moving, and round the centre the way it is turning.
      const yaw = car.yawRateRadS ?? 0
      const from = { x: noseX - (car.velocity.x - yaw * sin * car.cgToFrontAxleM) * DT, y: noseY - (car.velocity.y + yaw * cos * car.cgToFrontAxleM) * DT }
      if (ontoKerbStart(track, from, { x: noseX, y: noseY }, car.pose.angle)) rolled = 'kerb-start'
    }
    if (rolled === null && prev.airborneTicks === 1 && prev.hopKerb >= 0 && speedMS > rollSpeedMS && onKerbStrip(track.data, prev.hopKerb, car.pose.x, car.pose.y)) rolled = 'kerb-landing'
  }

  // A hop in progress runs out whatever is underneath. A new one starts on the tick the car comes onto a kerb,
  // if it is quick enough and has not just hopped. A car that goes over is in no hop.
  let airborneTicks = rolled !== null ? 0 : prev.airborneTicks > 0 ? prev.airborneTicks - 1 : 0
  let hopKerb = airborneTicks > 0 ? prev.hopKerb : -1
  let lastHopTick = prev.lastHopTick
  let events = NO_EVENTS
  if (
    rolled === null &&
    onKerb &&
    !prev.onKerb &&
    airborneTicks === 0 &&
    speedMS >= t.kerb.hopSpeedMS &&
    tick - lastHopTick >= t.kerb.hopRearmS * TICK_RATE
  ) {
    airborneTicks = hopTicks(speedMS, t.kerb)
    lastHopTick = tick
    // A hop off one side of a kerb is one that the tyres of the car's left side, or of its right, began, with its
    // centre clear of the kerb: that kerb is remembered, for where the car comes down. Astride a kerb, or square
    // onto one with both front tyres, it is thrown by no side of it.
    const kerbs = wheels.map((wheel) => (track.surfaceAt(wheel.x, wheel.y) === 'kerb' ? kerbUnder(track.data, wheel.x, wheel.y) : -1))
    const left = Math.max(kerbs[0], kerbs[2])
    const right = Math.max(kerbs[1], kerbs[3])
    hopKerb = centre === 'kerb' || (left >= 0 && right >= 0) ? -1 : Math.max(left, right)
    events = [{ type: 'kerb-hop', tick, car: carId, speedMS, airborneTicks }]
  }
  const airborne = airborneTicks > 0

  // Distance on the grass counts while the tyres are in it, whichever way the car is going, so reversing does
  // not undo it and running along the edge costs as much as driving in. It drains only on the lane.
  let offLaneM = prev.offLaneM
  if (surface !== 'grass') offLaneM = t.grass.bogClearS > 0 ? Math.max(0, offLaneM - (t.grass.stuckAfterM * DT) / t.grass.bogClearS) : 0
  else if (!airborne) offLaneM += speedMS * DT

  // What the tyres have under them: the surface's own dry grip, and in the wet what the water leaves of it. Wet
  // grass sticks a car after less distance. A hop is a hop in any weather: its tyres are off the ground.
  const wet = wetness > 0
  const stuckAfterM = wet ? grassStuckAfterM(t.grass.stuckAfterM, wetness) : t.grass.stuckAfterM
  let env = ASPHALT
  let stuck = false
  if (airborne) {
    env = { grip: t.kerb.hopGripScale, dragN: 0, airborne: true, steerScale: t.kerb.hopSteerScale }
  } else if (surface === 'grass') {
    env = { grip: wet ? surfaceGrip('grass', wetness, t) : t.grass.gripScale, dragN: grassDragN(car.massKg, offLaneM, speedMS, t.grass), airborne: false, steerScale: 1 }
    stuck = offLaneM >= stuckAfterM || (offLaneM > t.grass.stuckMinM && speedMS < t.grass.stuckBelowMS)
  } else if (surface === 'kerb') {
    env = { grip: wet ? surfaceGrip('kerb', wetness, t) : t.kerb.gripScale, dragN: 0, airborne: false, steerScale: 1 }
  } else if (wet) {
    env = { grip: surfaceGrip('asphalt', wetness, t), dragN: 0, airborne: false, steerScale: 1 }
  }

  const bog = stuck ? 1 : Math.min(1, offLaneM / stuckAfterM)
  return { state: { offLaneM, bog, airborneTicks, lastHopTick, lastSurface: surface, onKerb, noseOnKerb, hopKerb }, env, stuck, rolled, events }
}
