import { TICK_RATE, type Tick } from '../core'
import type { RaceControlCall } from './events'
import { RULES } from './rules'
import { WEATHER_TUNING } from '../weather/tuning'
import type { SessionKind, SessionPhase } from './types'

// Race control (F-404): the calls a race director makes from the PA, as events on the tick they fall due. A race
// meeting is run in this order: cars to the line (as the staging begins), the ten-second and the three-second warning, the start tone,
// halfway, the last minute, time is up, the provisional result, thanks to the marshals. The scheduler does not
// decide when a phase begins or ends, or when a clock runs out; it observes them (phases.ts, clocks.ts, finish.ts)
// and says which calls those moments have made due. It remembers what it has called, so that nothing is called
// twice and the calls come in this order; that memory is part of the session's state hash.
//
// One call is not on that list (F-601): the weather notice, made a moment after every change of sky, at whatever point
// of the meeting the sky changes, as often as it does, until the session is over.

const STAGING_TICKS = Math.round(RULES.stagingS * TICK_RATE)
const COUNTDOWN_TICKS = Math.round(RULES.countdownS * TICK_RATE)

/** The warnings are called this long, s, before the start tone. */
const TEN_SECONDS = 10
const THREE_SECONDS = 3
/** The last minute is called with this long, s, left on the clock; a session no longer than that has none. */
export const LAST_MINUTE_S = 60
/** A weather notice is called this many ticks after the sky changes. */
const WEATHER_NOTICE_TICKS = Math.round(WEATHER_TUNING.notice.delayS * TICK_RATE)
/** A clock is compared with these to within this much, s: a tick is 1/120 s, so no clock is ever as close as this and not at the mark. */
const CLOCK_EPSILON_S = 1e-9

/** What the scheduler needs to know about the tick it is asked about. */
export interface RaceControlInput {
  tick: Tick
  phase: SessionPhase
  /**
   * Ticks since the phase began, 0 on its first tick; read in staging, countdown and running only. A phase after
   * the start is counted from the start tone's tick, which is the first of running.
   */
  phaseTick: Tick
  kind: SessionKind
  durationS: number
  /**
   * What the clock on screen reads, s: the shared clock in a final, the timer car's own in qualifying. Null before
   * that clock has started, and where the caller has no clock to offer (the start of a tick, before the clocks move).
   */
  referenceClockS: number | null
  /** The tick the session finished on, once it has: the last car in, or the last allowance run out. Null before. */
  allFinishedTick: Tick | null
  /** The tick of the last change of sky (F-601); null until there has been one. */
  skyChangedTick: Tick | null
}

export interface RaceControlSchedule {
  /**
   * Calls due at this tick, in the order they are made. A pure function of the input and of what has already been
   * called; it marks what it returns as called, so asking again for the same moment returns nothing. A practice
   * session has no race control: nothing is ever due. The weather notice comes after any other call of its tick;
   * a change of sky that falls due once the session has finished is not called.
   */
  due(input: RaceControlInput): readonly RaceControlCall[]
  /** Appends what the scheduler remembers, for the session's state hash. */
  hashInto(buffer: number[]): void
}

const NONE: readonly RaceControlCall[] = Object.freeze([])

/** One row of the schedule: the call, and whether the moment for it has come. */
interface Row {
  readonly call: RaceControlCall
  readonly reached: (input: RaceControlInput) => boolean
}

const inCountdownOrLater = (input: RaceControlInput): boolean => input.phase !== 'staging'
const started = (input: RaceControlInput): boolean => input.phase !== 'staging' && input.phase !== 'countdown'

/** The clock on screen has come down to `leftS`. */
const clockAt =
  (leftS: (durationS: number) => number | null) =>
  (input: RaceControlInput): boolean => {
    const mark = leftS(input.durationS)
    return mark !== null && input.referenceClockS !== null && input.referenceClockS <= mark + CLOCK_EPSILON_S
  }

/** The schedule, in the order its calls are made. A call that cannot fall in this order for a session's length is left out for it (see `halfwayAt`). */
const SCHEDULE: readonly Row[] = [
  // The cars are called up on the first tick of staging; the warnings follow in the countdown.
  { call: 'cars-to-line', reached: () => true },
  { call: 'ten-seconds', reached: (input) => inCountdownOrLater(input) && (input.phase !== 'countdown' || input.phaseTick >= COUNTDOWN_TICKS - TEN_SECONDS * TICK_RATE) },
  { call: 'three-seconds', reached: (input) => inCountdownOrLater(input) && (input.phase !== 'countdown' || input.phaseTick >= COUNTDOWN_TICKS - THREE_SECONDS * TICK_RATE) },
  { call: 'start-tone', reached: started },
  { call: 'halfway', reached: clockAt(halfwayAt) },
  { call: 'last-minute', reached: clockAt(lastMinuteAt) },
  // The clock on screen reaching zero; or, if the session is over, the moment that must already have passed.
  { call: 'time-up', reached: (input) => input.allFinishedTick !== null || clockAt(() => 0)(input) },
  { call: 'provisional-result', reached: (input) => input.allFinishedTick !== null },
  { call: 'thank-marshals', reached: (input) => input.allFinishedTick !== null },
]

/**
 * What is left on the clock when the halfway is called: half the session. A session of two minutes or less has none:
 * halfway would come with the last minute or after it, and the calls are made in order.
 */
function halfwayAt(durationS: number): number | null {
  return durationS / 2 > LAST_MINUTE_S ? durationS / 2 : null
}

/** What is left on the clock when the last minute is called; null for a session no longer than a minute, whose whole length it would be. */
function lastMinuteAt(durationS: number): number | null {
  return durationS > LAST_MINUTE_S ? LAST_MINUTE_S : null
}

/** A new scheduler, with nothing called yet. */
export function createRaceControlSchedule(): RaceControlSchedule {
  let called = 0
  // The change of sky a weather notice was last called for (or, once the session is over, let pass), by its tick.
  let noticedSkyTick = 0
  return {
    due(input) {
      if (input.kind === 'practice') return NONE
      let due: RaceControlCall[] | null = null
      // One bit of `called` for each row of the schedule.
      for (let index = 0; index < SCHEDULE.length; index++) {
        const row = SCHEDULE[index]
        const bit = 1 << index
        if ((called & bit) !== 0 || !row.reached(input)) continue
        called |= bit
        ;(due ??= []).push(row.call)
      }
      const changed = input.skyChangedTick
      if (changed !== null && changed !== noticedSkyTick && (input.phase === 'finished' || input.tick >= changed + WEATHER_NOTICE_TICKS)) {
        noticedSkyTick = changed
        if (input.phase !== 'finished') (due ??= []).push('weather-notice')
      }
      return due ?? NONE
    },
    hashInto(buffer) {
      buffer.push(called, noticedSkyTick)
    },
  }
}

/**
 * The first tick of the phase the session is in, for `RaceControlInput.phaseTick`: the staging begins on the first
 * step, the countdown and the running when their phase events say. A phase after the start is counted from the
 * start tone.
 */
export function phaseStartTick(phase: SessionPhase): Tick {
  if (phase === 'staging') return 1
  if (phase === 'countdown') return STAGING_TICKS + 1
  return STAGING_TICKS + COUNTDOWN_TICKS + 1
}
