import { TICK_RATE, type CarId, type DriverId, type Tick } from '../core'
import { RULES } from './rules'
import type { ResultRow, SessionConfig, SessionResult } from './types'

// How a race ends (F-303). Each car finishes at its first crossing of the line after its time is up; that is
// decided where the crossing is timed. This file holds what follows from it: when the session itself is over,
// and the result.

const ALLOWANCE_TICKS = Math.round(RULES.finishAllowanceS * TICK_RATE)

/** What the end of a session remembers between ticks. Part of the state hash. */
export interface FinishWatch {
  /**
   * The tick from which the cars that are still out are on their allowance: the later of the tick the last of
   * them ran out of time and the tick a car last finished. Null while any car still out has time on its clock.
   */
  allowanceFromTick: Tick | null
}

/** One car as the end of the session sees it. */
export interface StillOut {
  finished: boolean
  /** Its time is up: its clock has reached the session's length. A car whose clock has yet to start still has all its time. */
  outOfTime: boolean
}

/**
 * Whether the session is over at the end of tick `tick`: every car has finished, or the cars that have not have
 * had their allowance. The allowance runs from when nobody still out has time left, and starts again whenever a
 * car finishes (`finishedNow`): a car that cannot finish does not keep a session open, and one that is still
 * racing its last lap behind another is not cut off by it.
 */
export function sessionOver(watch: FinishWatch, cars: readonly StillOut[], finishedNow: boolean, tick: Tick): boolean {
  let out = 0
  let racing = 0
  for (const car of cars) {
    if (car.finished) continue
    out++
    if (!car.outOfTime) racing++
  }
  if (out === 0) return true
  if (racing > 0) {
    watch.allowanceFromTick = null
    return false
  }
  if (watch.allowanceFromTick === null || finishedNow) watch.allowanceFromTick = tick
  return tick - watch.allowanceFromTick >= ALLOWANCE_TICKS
}

/** One car as the result sees it. */
export interface Classified {
  carId: CarId
  driverId: DriverId
  number: number
  startSlot: number
  /** Laps that counted. */
  laps: number
  /** What its clock read when it completed the last of them, ms, not rounded; null with no lap. */
  raceMs: number | null
  bestLapMs: number | null
  /** It crossed the line after its time was up. */
  finished: boolean
  /** Pit stops it still owed when the session ended (F-306); left out, none. */
  pitStopsMissed?: number
}

/** Whether a car ended the session owing a pit stop. */
const missedStop = (car: Classified): boolean => (car.pitStopsMissed ?? 0) > 0

/**
 * The order of a result: a car that missed a pit stop after every car that missed none (F-306); then more laps
 * first; for equal laps the lower time; a car with no lap after every car with one. Cars that are level on all of
 * it keep their starting order.
 */
export function inResultOrder(a: Classified, b: Classified): number {
  if (missedStop(a) !== missedStop(b)) return missedStop(a) ? 1 : -1
  if (a.laps !== b.laps) return b.laps - a.laps
  const aMs = a.raceMs ?? Infinity
  const bMs = b.raceMs ?? Infinity
  if (aMs !== bMs) return aMs < bMs ? -1 : 1
  return a.startSlot - b.startSlot
}

/** The result of a session: its rows in order, each car that missed a pit stop saying so, and the fastest single lap of any car. */
export function buildResult(config: Pick<SessionConfig, 'kind' | 'label'>, cars: readonly Classified[]): SessionResult {
  const rows: ResultRow[] = [...cars].sort(inResultOrder).map((car) => ({
    carId: car.carId,
    driverId: car.driverId,
    number: car.number,
    laps: car.laps,
    timeMs: car.raceMs === null ? 0 : Math.round(car.raceMs),
    bestLapMs: car.bestLapMs,
    finished: car.finished,
    // Why a car is where it is, on its row and on no other.
    ...(car.pitStopsMissed !== undefined && missedStop(car) ? { pitStopsMissed: car.pitStopsMissed } : {}),
  }))
  let fastestLap: SessionResult['fastestLap'] = null
  for (const row of rows) {
    if (row.bestLapMs !== null && (fastestLap === null || row.bestLapMs < fastestLap.lapMs)) fastestLap = { driverId: row.driverId, lapMs: row.bestLapMs }
  }
  return { kind: config.kind, label: config.label, rows, fastestLap }
}
