import { TICK_RATE, type CarId, type Tick } from '../core'
import type { SimEvent } from './events'
import { RULES } from './rules'
import type { CarState, SessionKind } from './types'

// Who is where while a race runs (F-303): each car's position, the gap to the car ahead of it, and the `position`
// and `lead-change` events of a final.
//
// - **A final** is ordered on the road: laps that counted, then how far round the lap in progress each car is.
//   A car that has finished is placed by its result against any car level with it on laps. A car that has finished
//   still owing a pit stop (F-306) is behind every car that has not: that is where the result will have it.
// - **A qualifying heat** is ordered by the result each car would have if it stopped now: laps, then what its own
//   clock read at its last crossing. Cars there are racing the clock, not each other, so it tells of no passes
//   and gives no gaps.

/** What the standings read of a car, and the two things they keep on it. */
export interface Placed {
  /** Laps that counted. */
  readonly lap: number
  /** How far along the route it has come since it last crossed the line, m; below zero on the way to its first crossing. */
  readonly sinceLineM: number
  readonly state: CarState
  /** What its clock read when it completed its last counted lap, ms, not rounded; null with no lap. */
  readonly raceMs: number | null
  /** Pit stops it still owes (F-306); left out, none. */
  readonly pitStopsOwed?: number
  /** 1-based. */
  position: number
  gapAheadMs: number | null
}

/** What the standings remember between ticks. All of it is part of the state hash. */
export interface Standings {
  /** Car ids in order, the best placed first. */
  readonly order: CarId[]
  /**
   * In a final, per car: the distance it had raced at each of the last samples, as a ring. Sample n is at index
   * n modulo the ring's length. Empty in qualifying.
   */
  readonly history: Float64Array[]
  /** How many samples have been taken. */
  samples: number
}

const SAMPLE_TICKS = RULES.gap.sampleTicks
const HISTORY_SAMPLES = Math.ceil((RULES.gap.historyS * TICK_RATE) / SAMPLE_TICKS)

/** The standings before the start: the cars in the order of their start slots. */
export function createStandings(kind: SessionKind, startSlots: readonly number[]): Standings {
  const order = startSlots.map((_, id) => id).sort((a, b) => startSlots[a] - startSlots[b])
  return {
    order,
    history: kind === 'final' ? startSlots.map(() => new Float64Array(HISTORY_SAMPLES).fill(NaN)) : [],
    samples: 0,
  }
}

/** Whether a car has finished still owing a pit stop: nothing it does now can serve it. */
const missedStop = (car: Placed): boolean => car.state === 'finished' && (car.pitStopsOwed ?? 0) > 0

/** Whether `a` is to be placed ahead of `b` in a final, when `b` is ahead of it now. */
function aheadOnTheRoad(a: Placed, b: Placed): boolean {
  if (missedStop(a) !== missedStop(b)) return missedStop(b)
  if (a.lap !== b.lap) return a.lap > b.lap
  // Level on laps with a car that has finished: whichever completed that many first.
  if (a.state === 'finished' || b.state === 'finished') return (a.raceMs ?? Infinity) < (b.raceMs ?? Infinity)
  return a.sinceLineM > b.sinceLineM + RULES.positionMarginM
}

/** The same in qualifying: by the result each would have if it stopped now. */
function aheadOnTheClock(a: Placed, b: Placed): boolean {
  if (a.lap !== b.lap) return a.lap > b.lap
  return (a.raceMs ?? Infinity) < (b.raceMs ?? Infinity)
}

/**
 * Brings the order up to date at the end of tick `tick` and writes each car's position. In a final it also
 * appends a `position` event for every car that gained a place, naming the nearest car now behind it that was
 * ahead of it before, and a `lead-change` when first place changed hands.
 */
export function placeCars(standings: Standings, cars: readonly Placed[], kind: SessionKind, tick: Tick, events: SimEvent[]): void {
  const order = standings.order
  const ahead = kind === 'final' ? aheadOnTheRoad : aheadOnTheClock
  const leader = order[0]
  // The order changes little from one tick to the next: each car moves up past those it is now ahead of.
  for (let i = 1; i < order.length; i++) {
    const id = order[i]
    let at = i
    while (at > 0 && ahead(cars[id], cars[order[at - 1]])) {
      order[at] = order[at - 1]
      at--
    }
    order[at] = id
  }
  for (let i = 0; i < order.length; i++) {
    const car = cars[order[i]]
    const to = i + 1
    if (to < car.position && kind === 'final') {
      let passed: CarId | null = null
      for (let behind = i + 1; behind < order.length && passed === null; behind++) {
        if (cars[order[behind]].position < car.position) passed = order[behind]
      }
      events.push({ type: 'position', tick, car: order[i], from: car.position, to, passed })
    }
  }
  for (let i = 0; i < order.length; i++) cars[order[i]].position = i + 1
  if (kind === 'final' && order[0] !== leader) events.push({ type: 'lead-change', tick, car: order[0], previous: leader })
}

/** How far a car has raced, m: its counted laps and its way round the lap in progress. */
function raced(car: Placed, lapLengthM: number): number {
  return car.lap * lapLengthM + car.sinceLineM
}

/**
 * How long ago the car whose history this is was at `distanceM`, in samples: zero if it has not got that far,
 * null if it was there before the history begins.
 */
function samplesSince(history: Float64Array, samples: number, distanceM: number): number | null {
  const kept = Math.min(samples, history.length)
  let newer = history[(samples - 1) % history.length]
  if (!(newer > distanceM)) return 0
  for (let back = 1; back < kept; back++) {
    const older = history[(samples - 1 - back) % history.length]
    if (older <= distanceM) return back - (distanceM - older) / (newer - older)
    newer = older
  }
  return null
}

/**
 * The gaps of a final, to be called once the cars are placed. Every few ticks it notes how far each car has
 * raced and gives each car the time since the car ahead of it was where it is now; between those ticks the gaps
 * stand. A car that has finished is given the difference between its time and that of the car ahead, when that
 * one has finished on the same lap, and no gap otherwise; nor is there one between a car that missed a pit stop
 * and a car that did not, which are not placed by their times. The leader has none.
 */
export function measureGaps(standings: Standings, cars: readonly Placed[], lapLengthM: number, tick: Tick): void {
  if (tick % SAMPLE_TICKS !== 0) return
  const slot = standings.samples % HISTORY_SAMPLES
  for (let id = 0; id < cars.length; id++) standings.history[id][slot] = raced(cars[id], lapLengthM)
  standings.samples++

  const order = standings.order
  cars[order[0]].gapAheadMs = null
  for (let i = 1; i < order.length; i++) {
    const car = cars[order[i]]
    const ahead = cars[order[i - 1]]
    if (car.state === 'finished') {
      const level = ahead.state === 'finished' && ahead.lap === car.lap && car.raceMs !== null && ahead.raceMs !== null && missedStop(ahead) === missedStop(car)
      car.gapAheadMs = level ? Math.round(car.raceMs - ahead.raceMs) : null
      continue
    }
    const since = samplesSince(standings.history[order[i - 1]], standings.samples, raced(car, lapLengthM))
    car.gapAheadMs = since === null ? null : Math.round((since * SAMPLE_TICKS * 1000) / TICK_RATE)
  }
}

/** Appends everything the standings remember, in a fixed order. */
export function hashStandings(standings: Standings, buffer: number[]): void {
  for (const id of standings.order) buffer.push(id)
  buffer.push(standings.samples)
  for (const history of standings.history) for (let i = 0; i < history.length; i++) buffer.push(history[i])
}
