import { angleDiff, clamp, type Pose, type Vec2 } from '../core'
import { lockFraction } from '../vehicle/shaping'
import type { CarParams } from '../vehicle/types'

/**
 * The steering input that points a car at a place: pure pursuit, as a share of the lock the car has at its speed.
 * Shared by the AI drivers and by the controller that parks a finished car.
 */
export function steerToward(pose: Readonly<Pose>, speedMS: number, target: Readonly<Vec2>, car: CarParams): number {
  const dx = target.x - pose.x
  const dy = target.y - pose.y
  const bearing = angleDiff(pose.angle, Math.atan2(dy, dx))
  const wheelRad = Math.atan2(2 * car.wheelbaseM * Math.sin(bearing), Math.hypot(dx, dy))
  return clamp(wheelRad / (lockFraction(Math.abs(speedMS), car) * car.maxSteerRad), -1, 1)
}
