import { TICK_RATE, type CarId, type Rng, type Tick, type Vec2 } from '../core'
import { INCIDENT_TUNING } from './tuning'
import type { MarshalSnapshot, MarshalState } from './types'

// The marshals (F-502, F-508). One stands at each of the track's posts. When a car is stricken the nearest free one
// notices, walks out to it in a straight line (he runs to a car stuck in the grass round the outside) and round to
// the far side of it from its lane, bends to it for a moment, lifts it and walks with it to where it is set down; then he takes the nearest car that is still
// waiting, or walks back. At his post with nothing to do he takes to his phone now and then, and a car that falls
// to him while he has it out waits until he puts it away. The system owns the marshals and nothing else: the
// session tells it which cars want fetching and which marshals were run into, and it says what it wants done about
// the cars, which the session does.

const M = INCIDENT_TUNING.marshal
/** What a marshal is doing, as the system keeps it: the snapshot's states, and walking with a car, which the snapshot tells as 'righting' with `carrying` set. */
type Doing = MarshalState | 'carrying'
const DOINGS: readonly Doing[] = ['idle', 'distracted', 'walking-out', 'righting', 'walking-back', 'carrying']
const RIGHTING_TICKS = Math.round(M.rightingS * TICK_RATE)
const FLINCH_TICKS = Math.round(M.flinchS * TICK_RATE)

/** A car that wants fetching. */
export interface MarshalCall {
  car: CarId
  /** Where its centre is now. */
  at: Readonly<Vec2>
  /** It is to be run to: stuck in the grass round the outside of the track. */
  run: boolean
  /**
   * The point of the lane it left that is nearest it (F-508): where it will be set down, unless that place is taken.
   * Given, its marshal goes to the far side of the car from there, so that he walks to the lane behind the car and
   * sets it down in front of him, without stepping onto the middle of the lane himself. Left out, or with the car
   * lying on that very point, he stops at the car on the side he comes from.
   */
  lane?: Readonly<Vec2>
}

/** What the session tells the marshals on a tick, and what they tell it back. */
export interface MarshalContext {
  tick: Tick
  /** Every car that wants fetching as the tick ends, in car order: the ones waiting and the ones a marshal already has. */
  calls: readonly MarshalCall[]
  /** The marshals a car that is on its wheels and moving under its driver ran into during the step, by id. */
  hit: readonly number[]
  /** A marshal at his post was given a car while he is on his phone: he will not set off until he puts it away. */
  distracted(marshal: number, car: CarId): void
  /** A marshal has set off for a car. */
  dispatched(marshal: number, car: CarId): void
  /** A marshal has reached a car and has it from this tick. */
  reached(marshal: number, car: CarId): void
  /**
   * Where the centre of a car a marshal has is to be set down, as things stand (F-508). Asked when he has had it for
   * the righting time and lifts it, and again each time he gets there with it: the same place, with the same
   * numbers, if it is still good, and another if it has been taken meanwhile.
   */
  setDownPlace(marshal: number, car: CarId): Readonly<Vec2>
  /** A marshal has walked a step with a car (F-508): its centre is now at `at`. */
  carried(marshal: number, car: CarId, at: Readonly<Vec2>): void
  /** A marshal is at a car's set-down place with it, and the place is still good: it is to be set down now. */
  putDown(marshal: number, car: CarId): void
}

export interface MarshalSystem {
  /** Tick step 6, once the cars that rolled, stuck or wedged on the tick are settled: gives out the work, moves the marshals, and says which cars are reached and which are to be put down. */
  update(ctx: MarshalContext): void
  /** The marshals as the snapshot has them. The same array and objects on every call, refilled. */
  snapshot(): readonly MarshalSnapshot[]
  /** The marshals who are away from their posts: solid things, for the physics and for the AI drivers. The same array on every call, refilled. */
  onTrack(): ReadonlyArray<{ id: number; pos: Readonly<Vec2>; radiusM: number }>
  /** Whether a marshal has reached this car and has it: bent to it, or walking with it. */
  hasInHand(car: CarId): boolean
  /** The marshal who is walking with this car, by id; null when nobody is. */
  carrierOf(car: CarId): number | null
  /** Appends every number of the marshals' state, in a fixed order. */
  hashInto(buffer: number[]): void
}

interface Marshal {
  readonly id: number
  readonly post: Readonly<Vec2>
  readonly pos: Vec2
  facingRad: number
  state: Doing
  targetCar: CarId | null
  running: boolean
  /** Ticks still to go: of noticing, at his post; of bending to the car, while righting. */
  waitTicks: number
  flinchTicks: number
  /** He has gone on with what he was doing since he last flinched: until he has, being hit again does not stop him again. */
  steady: boolean
  /** His own stream (F-508): when he takes to his phone and for how long. And how many numbers he has drawn from it, which is the stream's whole state. */
  readonly phone: Rng
  phoneDraws: number
  /** On his phone: ticks of the spell still to run. Otherwise: ticks he has still to stand at his post with nothing to do before he takes it out. */
  phoneTicks: number
  /** While he walks with a car: where he stands from its centre, which he keeps, and where its centre is to be set down. */
  readonly beside: Vec2
  readonly carryTo: Vec2
  /**
   * And, when the place it is to be set down is not the nearest of its lane (that one being taken): the point abeam
   * of the place, as far from the lane as the car lay, which he walks it to first, and whether he is still on his way
   * there. From it he walks straight in to the place, across the lane and not along it past whatever stands there.
   */
  readonly abeam: Vec2
  viaAbeam: boolean
  /**
   * Where he last set a car down, and whether he has yet to get clear of it: his way from there, to his post or to
   * the next car, may lie straight through the car he has just put on its wheels, and he walks round it instead.
   */
  readonly setDownAt: Vec2
  leaving: boolean
}

const between = (a: Readonly<Vec2>, b: Readonly<Vec2>): number => Math.hypot(a.x - b.x, a.y - b.y)
/** A car lying nearer its lane's point than this, m, has no far side from it to speak of. */
const ON_ITS_PLACE_M = 1e-6
/** A marshal within this of an arm's length from a car, m, is at an arm's length from it. */
const AT_ARMS_LENGTH_M = 1e-9

/**
 * The marshals of one session: one at each of `posts`. Their randomness is `rng`, which the session forks for them
 * (`rng.fork('marshals')`): how long a marshal takes to set off, from the stream itself, and each marshal's spells
 * on his phone from his own fork of it (`phone/` and his id), so that no marshal's phone depends on another's or on
 * what the cars do.
 */
export function createMarshalSystem(posts: ReadonlyArray<Readonly<Vec2>>, rng: Rng): MarshalSystem {
  const marshals: Marshal[] = posts.map((post, id) => ({
    id,
    post: { x: post.x, y: post.y },
    pos: { x: post.x, y: post.y },
    facingRad: 0,
    state: 'idle',
    targetCar: null,
    running: false,
    waitTicks: 0,
    flinchTicks: 0,
    steady: true,
    phone: rng.fork(`phone/${id}`),
    phoneDraws: 0,
    phoneTicks: 0,
    beside: { x: 0, y: 0 },
    carryTo: { x: 0, y: 0 },
    abeam: { x: 0, y: 0 },
    viaAbeam: false,
    setDownAt: { x: 0, y: 0 },
    leaving: false,
  }))
  /** How many numbers have been drawn from the shared stream: its whole state. */
  let draws = 0
  const draw = (min: number, max: number): number => {
    draws++
    return rng.range(min, max)
  }
  /** How long he stands at his post before he next takes his phone out, in ticks: as likely at one moment as at another, `phoneEveryS` on average. */
  const phoneGap = (marshal: Marshal): number => {
    marshal.phoneDraws++
    return Math.max(1, Math.round(-Math.log(1 - marshal.phone.next()) * M.phoneEveryS * TICK_RATE))
  }
  /** How long a spell on his phone lasts, in ticks. */
  const phoneSpell = (marshal: Marshal): number => {
    marshal.phoneDraws++
    return Math.max(1, Math.round(marshal.phone.range(M.phoneMinS, M.phoneMaxS) * TICK_RATE))
  }
  for (const marshal of marshals) marshal.phoneTicks = phoneGap(marshal)
  const view: Array<{ id: number; pos: Vec2; facingRad: number; state: MarshalState; targetCar: CarId | null; carrying: CarId | null }> = marshals.map((marshal) => ({
    id: marshal.id,
    pos: { x: marshal.pos.x, y: marshal.pos.y },
    facingRad: 0,
    state: 'idle',
    targetCar: null,
    carrying: null,
  }))
  const solid: Array<{ id: number; pos: Readonly<Vec2>; radiusM: number }> = []
  // Worked out afresh on every step of a carry and kept by nobody: where he is walking to, and where the car is.
  const stands: Vec2 = { x: 0, y: 0 }
  const carriedTo: Vec2 = { x: 0, y: 0 }
  // And, on a step of his way to a car: the point beyond it from its lane.
  const behind: Vec2 = { x: 0, y: 0 }

  const atPost = (marshal: Marshal): boolean => marshal.state === 'idle' || marshal.state === 'distracted'
  /** Free to be given a car: at his post with none, on his phone or not, or on his way back to it. */
  const free = (marshal: Marshal): boolean => marshal.targetCar === null && (atPost(marshal) || marshal.state === 'walking-back')
  const callFor = (calls: readonly MarshalCall[], car: CarId | null): MarshalCall | undefined => (car === null ? undefined : calls.find((call) => call.car === car))
  /** The cars put down on the tick in progress: the session's list still has them, and nobody is to be sent for them. */
  const putDown: CarId[] = []
  const taken = (car: CarId): boolean => putDown.includes(car) || marshals.some((marshal) => marshal.targetCar === car)

  /**
   * He sets off for the car he has been given. From here he is a solid thing, so a car that lies nearer him than
   * an arm's length (one stuck right beside his post) has him step back to that at once: he never stands in it.
   */
  const setOff = (marshal: Marshal, call: MarshalCall, ctx: MarshalContext): void => {
    marshal.state = 'walking-out'
    marshal.running = call.run
    marshal.waitTicks = 0
    standOff(marshal, call.at)
    ctx.dispatched(marshal.id, call.car)
  }

  /** If he is nearer `car` than he reaches from, he is put at that distance from it, on the side he is on. */
  const standOff = (marshal: Marshal, car: Readonly<Vec2>): void => {
    const dx = marshal.pos.x - car.x
    const dy = marshal.pos.y - car.y
    const apartM = Math.hypot(dx, dy)
    if (apartM >= M.reachM) return
    // Right on top of it, there is no side he is on: he takes the one toward his post, or failing that any.
    const awayX = apartM > 0 ? dx / apartM : 1
    const awayY = apartM > 0 ? dy / apartM : 0
    marshal.pos.x = car.x + awayX * M.reachM
    marshal.pos.y = car.y + awayY * M.reachM
  }

  /** One step toward `to` at `speedMS`; true once he is within `withinM` of it. He faces the way he goes. */
  const stepToward = (marshal: Marshal, to: Readonly<Vec2>, speedMS: number, withinM: number): boolean => {
    const dx = to.x - marshal.pos.x
    const dy = to.y - marshal.pos.y
    const apartM = Math.hypot(dx, dy)
    if (apartM > 0) marshal.facingRad = Math.atan2(dy, dx)
    if (apartM <= withinM) return true
    const stepM = Math.min(speedMS / TICK_RATE, apartM - withinM)
    marshal.pos.x += (dx / apartM) * stepM
    marshal.pos.y += (dy / apartM) * stepM
    return apartM - stepM <= withinM
  }

  /**
   * One step round a car at arm's length from its centre `about`, at `speedMS`, the shorter way toward the bearing
   * `toRad` from it; true if that brings him to that bearing. He faces the way he goes.
   */
  const stepRound = (marshal: Marshal, about: Readonly<Vec2>, toRad: number, speedMS: number): boolean => {
    const fromRad = Math.atan2(marshal.pos.y - about.y, marshal.pos.x - about.x)
    const roundRad = Math.atan2(Math.sin(toRad - fromRad), Math.cos(toRad - fromRad))
    const stepRad = speedMS / TICK_RATE / M.reachM
    const there = Math.abs(roundRad) <= stepRad
    const atRad = there ? toRad : fromRad + Math.sign(roundRad) * stepRad
    marshal.pos.x = about.x + Math.cos(atRad) * M.reachM
    marshal.pos.y = about.y + Math.sin(atRad) * M.reachM
    marshal.facingRad = atRad + (Math.sign(roundRad) * Math.PI) / 2
    return there
  }

  /**
   * Getting clear of the car he has just set down, on his way to `to` (F-508): while the straight line there from
   * where he stands leads in toward that car, he walks round it at arm's length instead, the shorter way. True if
   * this tick's step was such a one; false once his way is clear, and from then on.
   */
  const leave = (marshal: Marshal, to: Readonly<Vec2>, speedMS: number): boolean => {
    if (!marshal.leaving) return false
    const outX = marshal.pos.x - marshal.setDownAt.x
    const outY = marshal.pos.y - marshal.setDownAt.y
    const inward = outX * (to.x - marshal.pos.x) + outY * (to.y - marshal.pos.y) < 0
    if (!inward || Math.hypot(outX, outY) > M.reachM + AT_ARMS_LENGTH_M) {
      marshal.leaving = false
      return false
    }
    stepRound(marshal, marshal.setDownAt, Math.atan2(to.y - marshal.setDownAt.y, to.x - marshal.setDownAt.x), speedMS)
    return true
  }

  /**
   * One step of his way to the car he has been given, at `speedMS`; true once he is where he will have it from. With
   * no lane to go by he walks straight at the car and stops an arm's length short of it. Told where its lane is
   * (F-508), he makes for the point an arm's length beyond the car from there: straight for it while that keeps him
   * an arm's length from the car, and round the car at that distance, the shorter way, when it does not. There he
   * turns to face the car.
   */
  const approach = (marshal: Marshal, call: MarshalCall, speedMS: number): boolean => {
    const lane = call.lane
    const fromLaneM = lane === undefined ? 0 : between(call.at, lane)
    if (lane === undefined || fromLaneM <= ON_ITS_PLACE_M) return stepToward(marshal, call.at, speedMS, M.reachM)
    behind.x = call.at.x + ((call.at.x - lane.x) / fromLaneM) * M.reachM
    behind.y = call.at.y + ((call.at.y - lane.y) / fromLaneM) * M.reachM
    let there: boolean
    if (between(marshal.pos, call.at) > M.reachM + AT_ARMS_LENGTH_M) {
      there = stepToward(marshal, behind, speedMS, 0)
      // A step that would take him through the car leaves him at arm's length from it, to go round from there.
      if (!there) standOff(marshal, call.at)
    } else {
      there = stepRound(marshal, call.at, Math.atan2(behind.y - call.at.y, behind.x - call.at.x), speedMS)
    }
    if (!there) return false
    marshal.pos.x = behind.x
    marshal.pos.y = behind.y
    marshal.facingRad = Math.atan2(call.at.y - behind.y, call.at.x - behind.x)
    return true
  }

  /**
   * A step with the car he has lifted (F-508), at walking speed, to where he stands when it is at its set-down
   * place, by way of the point abeam of that if he has one to go by; the car goes with him, as far from him as it
   * was when he lifted it. At the place, the place is asked for again: if it stands, the car is set down and he goes
   * on to his next work; if it has been taken, he walks on to the new one.
   */
  const carry = (marshal: Marshal, call: MarshalCall, ctx: MarshalContext): void => {
    const to = marshal.viaAbeam ? marshal.abeam : marshal.carryTo
    stands.x = to.x + marshal.beside.x
    stands.y = to.y + marshal.beside.y
    const dx = stands.x - marshal.pos.x
    const dy = stands.y - marshal.pos.y
    const apartM = Math.hypot(dx, dy)
    const stepM = M.walkSpeedMS / TICK_RATE
    if (apartM > 0) marshal.facingRad = Math.atan2(dy, dx)
    if (apartM > stepM) {
      marshal.pos.x += (dx / apartM) * stepM
      marshal.pos.y += (dy / apartM) * stepM
      carriedTo.x = marshal.pos.x - marshal.beside.x
      carriedTo.y = marshal.pos.y - marshal.beside.y
      ctx.carried(marshal.id, call.car, carriedTo)
      return
    }
    marshal.pos.x = stands.x
    marshal.pos.y = stands.y
    ctx.carried(marshal.id, call.car, to)
    if (marshal.viaAbeam) {
      // Abeam of the place: the rest of the way is straight in.
      marshal.viaAbeam = false
      return
    }
    // The last step, or no step at all: he is there, and the car is exactly at its place.
    const place = ctx.setDownPlace(marshal.id, call.car)
    if (place.x !== marshal.carryTo.x || place.y !== marshal.carryTo.y) {
      marshal.carryTo.x = place.x
      marshal.carryTo.y = place.y
      return
    }
    putDown.push(call.car)
    ctx.putDown(marshal.id, call.car)
    marshal.setDownAt.x = marshal.carryTo.x
    marshal.setDownAt.y = marshal.carryTo.y
    marshal.leaving = true
    next(marshal, ctx)
  }

  /** With nobody to fetch: the nearest car still waiting, or home. */
  const next = (marshal: Marshal, ctx: MarshalContext): void => {
    marshal.targetCar = null
    marshal.running = false
    marshal.waitTicks = 0
    let nearest: MarshalCall | null = null
    for (const call of ctx.calls) {
      if (taken(call.car)) continue
      if (nearest === null || between(marshal.pos, call.at) < between(marshal.pos, nearest.at)) nearest = call
    }
    if (nearest === null) {
      marshal.state = atPost(marshal) ? 'idle' : 'walking-back'
      return
    }
    marshal.targetCar = nearest.car
    setOff(marshal, nearest, ctx)
  }

  return {
    update(ctx) {
      putDown.length = 0
      // A marshal who is hit stops for the flinch time. One who is flinching already, or has not yet gone on since
      // he last did, is not stopped again: a car that leans on him holds him up, and does not hold him for good.
      for (const id of ctx.hit) {
        const marshal = marshals[id]
        if (marshal === undefined || atPost(marshal) || !marshal.steady) continue
        marshal.flinchTicks = FLINCH_TICKS
        marshal.steady = false
      }

      // A car that no longer wants fetching (a wedged car that drove off, one that was set back some other way)
      // lets its marshal go: he stays at his post if he had not left it, on his phone if he was, and otherwise
      // looks for other work.
      for (const marshal of marshals) {
        if (marshal.targetCar === null || callFor(ctx.calls, marshal.targetCar) !== undefined) continue
        if (atPost(marshal)) {
          marshal.targetCar = null
          marshal.waitTicks = 0
        } else next(marshal, ctx)
      }

      // The cars that nobody has yet are given the free marshals, nearest pair first by the straight line, until
      // one or the other runs out: so the nearer car is served first, and a car with nobody free for it waits.
      for (;;) {
        let nearest: Marshal | null = null
        let nearestCall: MarshalCall | null = null
        let nearestM = Infinity
        for (const call of ctx.calls) {
          if (taken(call.car)) continue
          for (const marshal of marshals) {
            if (!free(marshal)) continue
            const apartM = between(marshal.pos, call.at)
            if (apartM < nearestM) {
              nearest = marshal
              nearestCall = call
              nearestM = apartM
            }
          }
        }
        if (nearest === null || nearestCall === null) break
        nearest.targetCar = nearestCall.car
        if (nearest.state === 'walking-back') {
          // On his feet already: he turns round and goes.
          setOff(nearest, nearestCall, ctx)
          continue
        }
        // At his post. On his phone, he has not seen it: nothing is drawn, and he sets off when the spell is over.
        // Otherwise he notices, and takes the ordinary moment over it.
        if (nearest.state === 'distracted') ctx.distracted(nearest.id, nearestCall.car)
        else nearest.waitTicks = Math.round(draw(M.noticeMinS, M.noticeMaxS) * TICK_RATE)
      }

      for (const marshal of marshals) {
        if (marshal.flinchTicks > 0) {
          marshal.flinchTicks--
          continue
        }
        marshal.steady = true
        const call = callFor(ctx.calls, marshal.targetCar)
        if (marshal.state === 'distracted') {
          // The spell runs its length whatever happens on the track. When it is over he puts the phone away, and
          // sets off at once for a car that has been waiting for him.
          if (--marshal.phoneTicks <= 0) {
            marshal.state = 'idle'
            marshal.phoneTicks = phoneGap(marshal)
            if (call !== undefined) setOff(marshal, call, ctx)
          }
        } else if (marshal.state === 'idle') {
          if (call !== undefined) {
            if (--marshal.waitTicks <= 0) setOff(marshal, call, ctx)
          } else if (--marshal.phoneTicks <= 0) {
            // Nothing to do, and he has stood his time: out comes the phone.
            marshal.state = 'distracted'
            marshal.phoneTicks = phoneSpell(marshal)
          }
        } else if (marshal.state === 'walking-out' && call !== undefined) {
          marshal.running = call.run
          const speedMS = call.run ? M.runSpeedMS : M.walkSpeedMS
          // From a car he has just set down he first gets clear of it.
          if (leave(marshal, call.at, speedMS)) continue
          // A car that has been shoved up against him is given its arm's length again.
          standOff(marshal, call.at)
          if (approach(marshal, call, speedMS)) {
            marshal.state = 'righting'
            marshal.running = false
            marshal.waitTicks = RIGHTING_TICKS
            ctx.reached(marshal.id, call.car)
          }
        } else if (marshal.state === 'righting' && call !== undefined) {
          standOff(marshal, call.at)
          if (--marshal.waitTicks <= 0) {
            // He lifts it, and has it as far from him as it lay; from here it goes where he goes.
            const place = ctx.setDownPlace(marshal.id, call.car)
            marshal.state = 'carrying'
            marshal.beside.x = marshal.pos.x - call.at.x
            marshal.beside.y = marshal.pos.y - call.at.y
            marshal.carryTo.x = place.x
            marshal.carryTo.y = place.y
            // Its lane's nearest point is taken, and the place is further along the lane: he goes along beside the
            // lane first, to the point abeam of the place, so as not to walk the car past what stands on the lane.
            const lane = call.lane
            marshal.viaAbeam = lane !== undefined && between(place, lane) > ON_ITS_PLACE_M && between(call.at, lane) > ON_ITS_PLACE_M
            if (lane !== undefined && marshal.viaAbeam) {
              marshal.abeam.x = call.at.x + place.x - lane.x
              marshal.abeam.y = call.at.y + place.y - lane.y
            }
            carry(marshal, call, ctx)
          }
        } else if (marshal.state === 'carrying' && call !== undefined) {
          carry(marshal, call, ctx)
        } else if (marshal.state === 'walking-back') {
          if (leave(marshal, marshal.post, M.walkSpeedMS)) continue
          if (stepToward(marshal, marshal.post, M.walkSpeedMS, 0)) {
            marshal.pos.x = marshal.post.x
            marshal.pos.y = marshal.post.y
            marshal.state = 'idle'
          }
        }
      }
    },

    snapshot() {
      for (const marshal of marshals) {
        const out = view[marshal.id]
        out.pos.x = marshal.pos.x
        out.pos.y = marshal.pos.y
        out.facingRad = marshal.facingRad
        out.state = marshal.state === 'carrying' ? 'righting' : marshal.state
        out.targetCar = marshal.targetCar
        out.carrying = marshal.state === 'carrying' ? marshal.targetCar : null
      }
      return view
    },

    onTrack() {
      solid.length = 0
      for (const marshal of marshals) if (!atPost(marshal)) solid.push({ id: marshal.id, pos: marshal.pos, radiusM: M.marshalRadiusM })
      return solid
    },

    hasInHand(car) {
      return marshals.some((marshal) => marshal.targetCar === car && (marshal.state === 'righting' || marshal.state === 'carrying'))
    },

    carrierOf(car) {
      for (const marshal of marshals) if (marshal.targetCar === car && marshal.state === 'carrying') return marshal.id
      return null
    },

    hashInto(buffer) {
      buffer.push(draws)
      for (const marshal of marshals) {
        buffer.push(marshal.pos.x, marshal.pos.y, marshal.facingRad, DOINGS.indexOf(marshal.state), marshal.targetCar ?? -1, marshal.running ? 1 : 0, marshal.waitTicks, marshal.flinchTicks, marshal.steady ? 1 : 0)
        buffer.push(marshal.phoneDraws, marshal.phoneTicks, marshal.beside.x, marshal.beside.y, marshal.carryTo.x, marshal.carryTo.y, marshal.abeam.x, marshal.abeam.y, marshal.viaAbeam ? 1 : 0, marshal.setDownAt.x, marshal.setDownAt.y, marshal.leaving ? 1 : 0)
      }
    },
  }
}
