import type { DriverProfile } from '../ai'
import type { SessionResult } from '../session'
import { assignColours } from './colours'
import { chooseOpponents, PLAYER_DRIVER_ID } from './field'
import { sessionLabel } from './next-session'
import { qualifyingStandings } from './points'
import type { EventSettings, RaceDayEntry, RaceDayState, ScheduleItem } from './types'

// The event itself (F-401): who is entered, what is run in what order, and what has been run so far.

/** The player's car number: 1, as in a quick race. The opponents are 2 to N, the most skilled first. */
const PLAYER_NUMBER = 1

/** The schedule for the settings: every qualifying round, then every final leg. */
function buildSchedule(settings: EventSettings): ScheduleItem[] {
  const rounds = Array.from({ length: settings.qualifyingRounds }, (_, i): ScheduleItem => ({ kind: 'qualifying', round: i + 1 }))
  const legs = Array.from({ length: settings.finalsLegs }, (_, i): ScheduleItem => ({ kind: 'final', leg: i + 1 }))
  return [...rounds, ...legs]
}

/**
 * A race day for the settings, before anything has been run.
 *
 * The field is the player and `carsPerRace − 1` roster drivers, chosen for the difficulty from the event's seed as
 * a quick race chooses them (`chooseOpponents`). The player is car 1 in the colour of the settings; the opponents
 * are cars 2 to N, the most skilled first, each in its preferred colour if free, else the next free one.
 */
export function createRaceDay(settings: EventSettings, roster: readonly DriverProfile[]): RaceDayState {
  const opponents = chooseOpponents(settings.difficulty, settings.carsPerRace - 1, roster, settings.seed)
  const colours = assignColours(
    opponents.map((driver) => driver.id),
    settings.colour,
    roster,
  )
  const entries: RaceDayEntry[] = [
    { driverId: PLAYER_DRIVER_ID, number: PLAYER_NUMBER, colour: settings.colour },
    ...opponents.map((driver, i) => ({ driverId: driver.id, number: PLAYER_NUMBER + 1 + i, colour: colours[driver.id] })),
  ]
  return { settings: { ...settings }, entries, schedule: buildSchedule(settings), cursor: 0, results: [], finalGrid: null }
}

/** Throws unless the result is the session of `item` with exactly the event's drivers in it, each once, in its own car. */
function assertBelongs(state: RaceDayState, item: ScheduleItem, result: SessionResult): void {
  const expected = sessionLabel(item)
  if (result.kind !== item.kind || result.label !== expected) {
    throw new Error(`recordResult: the next session is '${expected}' (${item.kind}) but the result is of '${result.label}' (${result.kind})`)
  }
  if (result.rows.length !== state.entries.length) {
    throw new Error(`recordResult: '${expected}' has ${state.entries.length} drivers but the result has ${result.rows.length} rows`)
  }
  for (const entry of state.entries) {
    const rows = result.rows.filter((row) => row.driverId === entry.driverId)
    if (rows.length !== 1) throw new Error(`recordResult: the result of '${expected}' has ${rows.length} rows for '${entry.driverId}'`)
    if (rows[0].number !== entry.number) throw new Error(`recordResult: '${entry.driverId}' is car ${entry.number} but the result has car ${rows[0].number}`)
  }
}

/**
 * The state after the next session's result. Pure: `state` is left as it was and nothing of `result` is shared
 * with the new state. The cursor moves on, and the result that ends qualifying sets the grid for the final. The
 * weather the result hands on (F-601) is the next session's; a result that hands none on leaves what was there.
 * Throws when the event is over, or when the result is not the session at the cursor.
 */
export function recordResult(state: RaceDayState, result: SessionResult): RaceDayState {
  const item = state.schedule.at(state.cursor)
  if (item === undefined) throw new Error('recordResult: every session of the event has been recorded')
  assertBelongs(state, item, result)

  const kept: SessionResult = {
    kind: result.kind,
    label: result.label,
    rows: result.rows.map((row) => ({ ...row })),
    fastestLap: result.fastestLap === null ? null : { ...result.fastestLap },
  }
  const next: RaceDayState = { ...state, cursor: state.cursor + 1, results: [...state.results, { item: { ...item }, result: kept }] }
  if (result.weatherNext !== undefined) next.weather = { ...result.weatherNext }
  const qualifyingOver = item.kind === 'qualifying' && state.schedule.at(next.cursor)?.kind !== 'qualifying'
  return qualifyingOver ? { ...next, finalGrid: qualifyingStandings(next).map((standing) => standing.driverId) } : next
}
