import type { DriverId } from '../core'
import type { SessionResult } from '../session'

// How one session's result places its drivers (race-format.md, "Ranking a round" and "The final").

/** A driver's place in one session, and the laps and time it was earned with. The place is also the points. */
export interface Placing {
  driverId: DriverId
  number: number
  laps: number
  timeMs: number
  /** 1..N, no two drivers the same. */
  place: number
}

/**
 * Which of two results is the better: more laps first; for equal laps, lower time first. Negative when `a` is the
 * better, 0 when neither is. A result with no lap is below every result with one, and two such are level: there is
 * no time to tell them apart.
 */
export function compareResults(a: { laps: number; timeMs: number }, b: { laps: number; timeMs: number }): number {
  if (a.laps !== b.laps) return b.laps - a.laps
  return a.laps === 0 ? 0 : a.timeMs - b.timeMs
}

/**
 * A qualifying round ranked: more laps first, then lower time; drivers with no lap last. Drivers who are level (no
 * lap, or the same laps in the same time to the millisecond) are ordered by car number, so that the ranking never
 * depends on the order of the rows it was given. Best first.
 */
export function rankRound(result: SessionResult): Placing[] {
  return [...result.rows]
    .sort((a, b) => compareResults(a, b) || a.number - b.number)
    .map((row, i) => ({ driverId: row.driverId, number: row.number, laps: row.laps, timeMs: row.timeMs, place: i + 1 }))
}

/**
 * A final leg's positions: the result's own row order. The session has already ordered the rows, and put a car that
 * missed its pit stop behind every car that did not (F-306); ranking the leg again from laps and time would put
 * such a car back ahead.
 */
export function legPositions(result: SessionResult): Placing[] {
  return result.rows.map((row, i) => ({ driverId: row.driverId, number: row.number, laps: row.laps, timeMs: row.timeMs, place: i + 1 }))
}
