import { DT, type CarId, type Tick, type Vec2 } from '../core'
import type { SimEvent } from '../session/events'
import { segmentIntersection } from './geometry'
import type { TrackRuntime } from './types'

// Lap timing the way a transponder loop does it (F-107): a gate on the line and one at each sector point, the
// instant a car's centre crosses each worked out inside the tick, and a small state per car that says whether the
// lap in progress is one that was driven.

/** A segment across the lane, and the direction of travel that counts as crossing it. */
export interface TimingGate {
  a: Vec2
  b: Vec2
  /** Unit vector. A crossing is forward when the car goes from the gate's far side to the side this points to. */
  forward: Vec2
}

export interface TimingGates {
  line: TimingGate
  sectors: [TimingGate, TimingGate]
  /**
   * Where the pit lane bypasses the line or a sector point (F-208): the gate across the pit lane that stands in
   * for it, as a timing loop is laid across a real pit lane. Null where the pit lane bypasses nothing.
   */
  pit?: { line: TimingGate | null; sectors: [TimingGate | null, TimingGate | null] }
}

/**
 * How far a gate reaches past the route's half-width, each side. The trace takes a half-width as the distance to
 * the nearer limit of the lane and the lane is not always centred on the route, so a car on the wider side would
 * otherwise drive round the end of a gate it had every right to cross.
 */
const GATE_MARGIN_M = 0.1
/** A pit gate is drawn back in steps of this much until it is clear of the lap's lane. */
const PIT_GATE_TRIM_M = 0.01

const toVec = (point: readonly [number, number]): Vec2 => ({ x: point[0], y: point[1] })
const length = (x: number, y: number): number => Math.sqrt(x * x + y * y)

/**
 * The line is the track's own timing line, a little longer each end, counted in the direction of the route.
 * Each sector gate crosses the lane at the route point that is the sector's fraction of a lap on from the line,
 * square to the route there and as wide as the lane.
 */
export function buildGates(track: TrackRuntime): TimingGates {
  const [first, second] = track.data.timing.line
  const a = toVec(first)
  const b = toVec(second)
  const middle = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }
  const onRoute = track.nearestRoute(middle.x, middle.y)

  const along = length(b.x - a.x, b.y - a.y)
  const unit = { x: (b.x - a.x) / along, y: (b.y - a.y) / along }
  // The line's own normal, turned to face the way the route runs.
  const normal = { x: -unit.y, y: unit.x }
  const facing = normal.x * Math.cos(onRoute.headingRad) + normal.y * Math.sin(onRoute.headingRad) >= 0 ? 1 : -1
  const line: TimingGate = {
    a: { x: a.x - unit.x * GATE_MARGIN_M, y: a.y - unit.y * GATE_MARGIN_M },
    b: { x: b.x + unit.x * GATE_MARGIN_M, y: b.y + unit.y * GATE_MARGIN_M },
    forward: { x: normal.x * facing, y: normal.y * facing },
  }

  const sectorGate = (fraction: number): TimingGate => {
    const pose = track.routePose(onRoute.s + fraction * track.lengthM)
    const forward = { x: Math.cos(pose.angle), y: Math.sin(pose.angle) }
    const reach = track.nearestRoute(pose.x, pose.y).halfWidthM + GATE_MARGIN_M
    // To the right of the direction of travel on a screen with y down is a quarter turn clockwise.
    const right = { x: -forward.y, y: forward.x }
    return {
      a: { x: pose.x - right.x * reach, y: pose.y - right.y * reach },
      b: { x: pose.x + right.x * reach, y: pose.y + right.y * reach },
      forward,
    }
  }
  const [firstSector, secondSector] = track.data.timing.sectorFractions
  return {
    line,
    sectors: [sectorGate(firstSector), sectorGate(secondSector)],
    pit: {
      line: pitGate(track, onRoute.s),
      sectors: [pitGate(track, onRoute.s + firstSector * track.lengthM), pitGate(track, onRoute.s + secondSector * track.lengthM)],
    },
  }
}

/**
 * The gate across the pit lane that stands in for the lap's gate at distance `s`, or null if the pit lane does not
 * bypass that place. It crosses the pit route as far along it, in proportion, as the lap's gate is along the
 * stretch of lap the pit lane bypasses, square to the pit route and as wide as the pit lane. Each end is then drawn
 * back until it stands clear of the lap's own lane and of any wall between the two, so that a car on the lap can
 * never cross it: it would be timed at the same point twice.
 */
function pitGate(track: TrackRuntime, s: number): TimingGate | null {
  const pit = track.data.pitLane
  if (!pit) return null
  const lap = track.lengthM
  const wrap = (distance: number): number => ((distance % lap) + lap) % lap
  // The bypassed stretch runs from the entry on to the exit; it may lie across the start of the lap.
  const bypassed = wrap(pit.exitS - pit.entryS)
  const fromEntry = wrap(s - pit.entryS)
  if (fromEntry <= 0 || fromEntry >= bypassed) return null

  const alongPit = (fromEntry / bypassed) * track.pitLengthM
  const pose = track.pitRoutePose(alongPit)
  const onPit = pose ? track.nearestPitRoute(pose.x, pose.y) : null
  if (!pose || !onPit) return null
  const forward = { x: Math.cos(pose.angle), y: Math.sin(pose.angle) }
  const right = { x: -forward.y, y: forward.x }
  const walls = track.wallSegments()

  const end = (side: 1 | -1): Vec2 => {
    let reach = onPit.halfWidthM + GATE_MARGIN_M
    for (;;) {
      const x = pose.x + right.x * reach * side
      const y = pose.y + right.y * reach * side
      if (reach <= 0) return { x: pose.x, y: pose.y }
      const onRoute = track.nearestRoute(x, y)
      const inLapLane = Math.abs(onRoute.lateralM) <= onRoute.halfWidthM + GATE_MARGIN_M
      if (!inLapLane && !crossesWall(walls, pose, { x, y })) return { x, y }
      reach -= PIT_GATE_TRIM_M
    }
  }
  return { a: end(-1), b: end(1), forward }
}

function crossesWall(walls: ReadonlyArray<{ polyline: ReadonlyArray<readonly [number, number]>; closed: boolean }>, from: Vec2, to: Vec2): boolean {
  for (const wall of walls) {
    const points = wall.polyline
    const sides = wall.closed ? points.length : points.length - 1
    for (let i = 0; i < sides; i++) {
      if (segmentIntersection([from.x, from.y], [to.x, to.y], points[i], points[(i + 1) % points.length]) !== null) return true
    }
  }
  return false
}

/**
 * Where, inside one tick, the straight move from `prev` to `curr` crosses the gate, as a fraction of the tick, and
 * whether it did so going forward. Null if it does not cross.
 *
 * The gate's far side is everything strictly behind it; a point exactly on the gate counts as in front. So a step
 * that lands on the gate has crossed it, and the step after that, which starts on it, has not crossed it again.
 * Only the segment itself counts, end points included; a step along the gate crosses nothing.
 */
export function crossing(gate: TimingGate, prev: Vec2, curr: Vec2): { t: number; forward: boolean } | null {
  const ex = gate.b.x - gate.a.x
  const ey = gate.b.y - gate.a.y
  const span = length(ex, ey)
  if (span === 0) return null
  // The gate's normal, turned to point the way that counts.
  let nx = -ey / span
  let ny = ex / span
  const facing = nx * gate.forward.x + ny * gate.forward.y
  if (facing === 0) return null
  if (facing < 0) {
    nx = -nx
    ny = -ny
  }
  const before = (prev.x - gate.a.x) * nx + (prev.y - gate.a.y) * ny
  const after = (curr.x - gate.a.x) * nx + (curr.y - gate.a.y) * ny
  let forward: boolean
  if (before < 0 && after >= 0) forward = true
  else if (before >= 0 && after < 0) forward = false
  else return null

  const t = before / (before - after)
  const hitX = prev.x + (curr.x - prev.x) * t
  const hitY = prev.y + (curr.y - prev.y) * t
  const u = ((hitX - gate.a.x) * ex + (hitY - gate.a.y) * ey) / (span * span)
  if (u < 0 || u > 1) return null
  return { t, forward }
}

/** What the timing of one car remembers. All of it is part of the session's state hash. */
export interface CarTiming {
  /** Completed laps. */
  lap: number
  /** When the lap in progress began, in ms on the session clock, unrounded; null until the first line crossing. */
  lapStartMs: number | null
  /** How many of the two sector points the lap in progress has passed, in order. */
  nextSector: 0 | 1 | 2
  /** False once the lap in progress cannot be counted: a sector missed or out of order, or the line crossed backwards. */
  valid: boolean
  /** The car has crossed the line backwards and not yet forwards over it again. That forward crossing is not a new start. */
  behindLine: boolean
  lastLapMs: number | null
  bestLapMs: number | null
  /** Metres along the route, 0 up to the track's length. */
  routeS: number
}

export function createCarTiming(routeS = 0): CarTiming {
  return { lap: 0, lapStartMs: null, nextSector: 0, valid: true, behindLine: false, lastLapMs: null, bestLapMs: null, routeS }
}

/** What an event needs that the timing state does not hold. */
export interface TimingContext {
  car: CarId
  /** The session tick after the step being timed: the tick every event of this call carries. */
  tick: Tick
  /** The fastest lap of any car so far, or null if none has finished one. */
  sessionBestMs: number | null
}

const NO_EVENTS: readonly SimEvent[] = Object.freeze([])

interface Hit {
  /** 0 = the line, 1 and 2 = the sector points. */
  gate: 0 | 1 | 2
  t: number
  forward: boolean
}

/**
 * One tick of lap timing for one car whose centre moved from `prev` to `curr`. `tickStartMs` is the session clock
 * at the start of the tick. Changes `state`; returns the `sector` and `lap` events the tick produced.
 *
 * The rules, for the lap in progress:
 * - The first forward crossing of the line starts the clock and completes no lap.
 * - A forward crossing completes a lap only if both sector points were passed forwards, in order, since the last
 *   crossing. Otherwise nothing is counted and the clock restarts from that crossing.
 * - A crossing of the line against the route spoils the lap in progress, and the forward crossing that brings
 *   the car back over the line is not a new start.
 * - A sector point crossed backwards straight after being passed forwards is taken back; crossed backwards at any
 *   other time, or crossed forwards out of order, it spoils the lap.
 * - Before the first crossing of the line nothing is timed.
 */
export function updateTiming(
  state: CarTiming,
  gates: TimingGates,
  prev: Vec2,
  curr: Vec2,
  tickStartMs: number,
  context: TimingContext,
): readonly SimEvent[] {
  const hits: Hit[] = []
  // A gate and the pit gate that stands in for it are one place on the lap: crossing either is crossing it.
  const pit = gates.pit
  const either = (gate: TimingGate, inPits: TimingGate | null | undefined): ReturnType<typeof crossing> =>
    crossing(gate, prev, curr) ?? (inPits ? crossing(inPits, prev, curr) : null)
  const lineHit = either(gates.line, pit?.line)
  if (lineHit !== null) hits.push({ gate: 0, ...lineHit })
  const firstHit = either(gates.sectors[0], pit?.sectors[0])
  if (firstHit !== null) hits.push({ gate: 1, ...firstHit })
  const secondHit = either(gates.sectors[1], pit?.sectors[1])
  if (secondHit !== null) hits.push({ gate: 2, ...secondHit })
  if (hits.length === 0) return NO_EVENTS
  // Two gates in one tick are taken in the order the car reached them.
  hits.sort((p, q) => p.t - q.t)

  const events: SimEvent[] = []
  for (const hit of hits) {
    const atMs = tickStartMs + hit.t * DT * 1000
    if (hit.gate === 0) {
      if (hit.forward) crossLineForward(state, atMs, context, events)
      else crossLineBackward(state)
    } else if (hit.forward) {
      crossSectorForward(state, hit.gate, atMs, context, events)
    } else {
      crossSectorBackward(state, hit.gate)
    }
  }
  return events
}

function startLap(state: CarTiming, atMs: number): void {
  state.lapStartMs = atMs
  state.nextSector = 0
  state.valid = true
}

function crossLineForward(state: CarTiming, atMs: number, context: TimingContext, events: SimEvent[]): void {
  if (state.behindLine) {
    state.behindLine = false
    return
  }
  if (state.lapStartMs !== null && state.valid && state.nextSector === 2) {
    const lapMs = Math.round(atMs - state.lapStartMs)
    const personalBest = state.bestLapMs === null || lapMs < state.bestLapMs
    const sessionBest = context.sessionBestMs === null || lapMs < context.sessionBestMs
    state.lap += 1
    state.lastLapMs = lapMs
    if (personalBest) state.bestLapMs = lapMs
    events.push({ type: 'lap', tick: context.tick, car: context.car, lap: state.lap, lapMs, personalBest, sessionBest })
  }
  startLap(state, atMs)
}

function crossLineBackward(state: CarTiming): void {
  if (state.lapStartMs === null) return
  state.valid = false
  state.behindLine = true
}

function crossSectorForward(state: CarTiming, gate: 1 | 2, atMs: number, context: TimingContext, events: SimEvent[]): void {
  if (state.lapStartMs === null) return
  if (state.valid && state.nextSector === gate - 1) {
    state.nextSector = gate
    events.push({ type: 'sector', tick: context.tick, car: context.car, sector: gate, splitMs: Math.round(atMs - state.lapStartMs) })
  } else {
    state.valid = false
  }
}

function crossSectorBackward(state: CarTiming, gate: 1 | 2): void {
  if (state.lapStartMs === null) return
  if (state.nextSector === gate) state.nextSector = gate === 1 ? 0 : 1
  else state.valid = false
}
