import { clamp } from '../core'
import type { CarClass, CarParams, Tuning } from './types'

// A brushed-DC-style motor curve: torque falls in a straight line from stall to the no-load speed, and the
// speed controller's current limit cuts the top off it. Pure functions; every number comes from the caller.
//
// The exception is the winding rule at the top: how a motor's KV and peak power follow from its turn count.
// Nothing that moves a car reads those constants. A class row states its KV and peak power as data, where
// `resolveCar` and the tuning panel can reach them; the rule is how those two figures were arrived at, and the
// tests hold every row to it.

/** KV × turns for a 1/10 sensored motor: a 17.5T is about 2 200 KV. An assumption of experiment E-01. */
const KV_TURNS = 38500
/** The wind the power rule is pinned at: the Stock motor. */
const STOCK_TURNS = 17.5
/** Battery, speed controller and wiring, ohms. An assumption of experiment E-01. */
const CIRCUIT_OHM = 0.008
/** Winding resistance per turn², ohms. An assumption of experiment E-01. */
const WINDING_OHM_PER_TURN_SQ = 0.000125

/** Resistance the pack sees with a motor of this wind across it. */
function circuitOhm(turns: number): number {
  return CIRCUIT_OHM + WINDING_OHM_PER_TURN_SQ * turns * turns
}

/** RPM per volt from the turn count: fewer turns, more KV. */
export function kvFromTurns(turns: number): number {
  return KV_TURNS / turns
}

/**
 * Peak shaft power of a wind, from the Stock motor's. The most power a motor can take from a pack falls with
 * the resistance of the whole circuit, so power between winds scales as 1 / (circuit + winding resistance).
 */
export function peakPowerW(turns: number, stockPowerW: number): number {
  return (stockPowerW * circuitOhm(STOCK_TURNS)) / circuitOhm(turns)
}

/** Shaft speed with nothing to push against, rad/s. */
export function motorNoLoadRadS(kv: number, packVoltage: number): number {
  return (kv * packVoltage * 2 * Math.PI) / 60
}

/** On a straight torque line peak power sits at half of stall torque and half of no-load speed. */
export function motorStallTorqueNm(peakPowerW: number, noLoadRadS: number): number {
  return (4 * peakPowerW) / noLoadRadS
}

/** Torque per ampere: the reciprocal of KV in SI units, so a low-turn (high-KV) motor gets less from each amp. */
export function motorTorquePerAmpNm(kv: number): number {
  return 60 / (2 * Math.PI * kv)
}

/**
 * A motor at the wheels, at real scale: the force it gives at a standstill and the speed at which it gives
 * none, through the final drive and the tyre. Every class goes through this one function.
 */
export function motorAtWheels(
  m: CarClass['motor'],
  finalDrive: number,
  tyreRadiusM: number,
  t: Pick<Tuning, 'packVoltage' | 'drivetrainEfficiency'>,
): { stallForceN: number; noLoadSpeedMS: number } {
  const noLoadRadS = motorNoLoadRadS(m.kv, t.packVoltage)
  return {
    stallForceN: (motorStallTorqueNm(m.peakPowerW, noLoadRadS) * finalDrive * t.drivetrainEfficiency) / tyreRadiusM,
    noLoadSpeedMS: (noLoadRadS / finalDrive) * tyreRadiusM,
  }
}

/**
 * Wheel force the motor can give, N, never negative. `direction` is the sign of the throttle and `vLong` the
 * car's speed along its heading. In reverse the no-load speed is the reverse share of the forward one.
 */
export function availableDriveForceN(p: CarParams, direction: number, vLong: number): number {
  const noLoadMS = direction < 0 ? p.reverseLimit * p.noLoadSpeedMS : p.noLoadSpeedMS
  return Math.min(p.thrustLimitN, p.stallForceN * clamp(1 - (direction * vLong) / noLoadMS, 0, 1))
}

/** Shaft speed at a wheel speed, rad/s: the wheels are geared to the motor, so one follows the other. */
export function motorSpeedRadS(p: CarParams, vLong: number): number {
  return (p.motorNoLoadRadS * Math.abs(vLong)) / p.noLoadSpeedMS
}
