import { TICK_RATE, type Pose, type Tick } from '../core'
import type { TrackRuntime } from '../track'
import { distanceToPolyline } from '../track/geometry'
import { startTickOf } from './phases'
import { RULES } from './rules'
import type { SessionConfig } from './types'

// How a session starts (F-303): where its cars stand, when each may go, and what counts as going too soon.
//
// - Practice and a final start from the track's grid, every car released together: at once in practice, at the
//   start tone in a final.
// - A qualifying heat starts staggered: the car in start slot n is released n intervals after the tone. Its cars
//   queue in the pit lane, or stand in the numbered boxes on the straight, as the config's `qualifyingStart` says;
//   a track with no pit lane, or one whose pit lane is too short for the heat, uses the boxes.

/** Where a session's cars are put to start. */
export type StartFrom = 'grid' | 'start-boxes' | 'pit-lane'

/** How finely the end of the pit lane is looked for along the pit route, m. */
const PIT_END_STEP_M = 0.01

/**
 * The places of a pit-lane start, first car first: along the pit route, nose to tail, the first as near the pit
 * exit as it can stand without being on the lap's own asphalt. As many as the pit lane has room for, and no more
 * than `most`. Empty on a track with no pit lane.
 */
export function pitQueue(track: TrackRuntime, most: number): Pose[] {
  const { pitchM, clearOfLapM } = RULES.pitQueue
  const inPits = (s: number): Pose | null => {
    const pose = s < 0 ? null : track.pitRoutePose(s)
    return pose !== null && track.inPitLane(pose.x, pose.y) ? pose : null
  }
  // Back from the end of the pit route to the last place that is the pit lane's alone, with clear lane ahead of it.
  let head = track.pitLengthM - clearOfLapM
  while (head > 0 && inPits(head + clearOfLapM) === null) head -= PIT_END_STEP_M
  const places: Pose[] = []
  for (let n = 0; n < most; n++) {
    const pose = inPits(head - n * pitchM)
    if (pose === null) break
    places.push(pose)
  }
  return places
}

/** Where the cars of a session start from, and the place of each start slot. */
export function startPlaces(config: SessionConfig, track: TrackRuntime): { from: StartFrom; places: readonly Pose[] } {
  if (config.kind !== 'qualifying') return { from: 'grid', places: config.track.grid }
  const boxes = config.track.staggerStart
  if ((config.qualifyingStart ?? 'pit-lane') === 'pit-lane') {
    const queue = pitQueue(track, boxes.length)
    if (config.entries.every((entry) => entry.startSlot < queue.length)) return { from: 'pit-lane', places: queue }
  }
  return { from: 'start-boxes', places: boxes }
}

/**
 * Where on the lap to look for the route beside a start place, as a distance along it; undefined for a place on
 * the lap itself, which is simply at the nearest point of the route. A place in the pit lane is beside the stretch
 * the pit lane bypasses, as far along it as the place is along the pit lane: the nearest point of the whole lap
 * may be on another part of the track altogether.
 */
export function routeHintOfPlace(place: Readonly<Pose>, from: StartFrom, track: TrackRuntime): number | undefined {
  const pit = track.data.pitLane
  const onPit = from === 'pit-lane' ? track.nearestPitRoute(place.x, place.y) : null
  if (pit === undefined || onPit === null) return undefined
  const lapM = track.lengthM
  const bypassedM = (((pit.exitS - pit.entryS) % lapM) + lapM) % lapM
  return pit.entryS + (onPit.s / track.pitLengthM) * bypassedM
}

/**
 * The last session tick before the car in a start slot may be driven: the step after it is the first that takes
 * its driver's input. In a final that is the tick of the start tone for every car; in qualifying, slot n waits n
 * release intervals more.
 */
export function releaseTickOf(config: Pick<SessionConfig, 'kind'>, startSlot: number): Tick {
  const tone = startTickOf(config.kind)
  return config.kind === 'qualifying' ? tone + startSlot * Math.round(RULES.releaseIntervalS * TICK_RATE) : tone
}

/** A car of the pit queue that has been free to go this long, in ticks, and has not moved off is in the way (F-309). */
export const START_BLOCK_TICKS = Math.round(RULES.startBlockS * TICK_RATE)

/** A car lifted out of the queue is set down with its centre at least this far off every lane, m: its body is clear of the lane's edge. */
const LIFT_OFF_LANE_M = 0.25
/** And at least this far from every barrier and every other car that has been lifted out, m. */
const LIFT_FROM_WALL_M = 0.2
const LIFT_APART_M = 0.5
/** Places are tried this far apart, m, out to this far from the queue, m. */
const LIFT_STEP_M = 0.05
const LIFT_REACH_M = 3

/**
 * Where a car that is lifted out of the pit queue is set down (F-309): beside its place in the queue, facing as it
 * faced, on the grass with its body clear of every lane, of the barriers and of the cars already lifted out
 * (`taken`): somewhere no car drives. The nearest such place sideways of its own, the right-hand side tried first.
 * Where there is none within reach, as far to the right as was looked.
 */
export function liftedOutPlace(track: TrackRuntime, place: Readonly<Pose>, taken: ReadonlyArray<Readonly<Pose>>): Pose {
  const walls = track.wallSegments()
  const at = (asideM: number): Pose => ({ x: place.x - Math.sin(place.angle) * asideM, y: place.y + Math.cos(place.angle) * asideM, angle: place.angle })
  for (let asideM = LIFT_OFF_LANE_M; asideM <= LIFT_REACH_M; asideM += LIFT_STEP_M) {
    for (const side of [1, -1]) {
      const spot = at(side * asideM)
      if (track.distanceOffLane(spot.x, spot.y) < LIFT_OFF_LANE_M) continue
      if (walls.some((wall) => distanceToPolyline(spot.x, spot.y, wall.polyline, wall.closed) < LIFT_FROM_WALL_M)) continue
      if (taken.some((other) => Math.hypot(other.x - spot.x, other.y - spot.y) < LIFT_APART_M)) continue
      return spot
    }
  }
  return at(LIFT_REACH_M)
}

/** Whether a car's centre has left the box round its start place. */
export function outsideStartBox(pose: Readonly<Pose>, place: Readonly<Pose>): boolean {
  const dx = pose.x - place.x
  const dy = pose.y - place.y
  const ahead = dx * Math.cos(place.angle) + dy * Math.sin(place.angle)
  const aside = -dx * Math.sin(place.angle) + dy * Math.cos(place.angle)
  const box = RULES.startBox
  return ahead > box.aheadM || ahead < -box.behindM || Math.abs(aside) > box.asideM
}
