import type { Rng } from './types'

const UINT32_RANGE = 4294967296

/** The 32-bit finaliser from MurmurHash3: a bijection that spreads every input bit over the whole word. */
function mix32(x: number): number {
  x ^= x >>> 16
  x = Math.imul(x, 0x85ebca6b)
  x ^= x >>> 13
  x = Math.imul(x, 0xc2b2ae35)
  x ^= x >>> 16
  return x >>> 0
}

/**
 * A generator is identified by a 64-bit key. Its stream is a pure function of the key, and so is the key of
 * every fork, which is what makes a fork independent of how many values anything else has drawn.
 */
function fromKey(key0: number, key1: number): Rng {
  // sfc32 (Chris Doty-Humphrey): 96 bits of state plus a 32-bit counter, seeded the standard way.
  let a = 0
  let b = key0 | 0
  let c = key1 | 0
  let counter = 1

  const next = (): number => {
    const out = (a + b + counter) | 0
    counter = (counter + 1) | 0
    a = b ^ (b >>> 9)
    b = (c + (c << 3)) | 0
    c = (((c << 21) | (c >>> 11)) + out) | 0
    return (out >>> 0) / UINT32_RANGE
  }
  for (let i = 0; i < 12; i++) next()

  return {
    next,
    range(min, max) {
      const value = min + next() * (max - min)
      // Rounding can land exactly on `max` when the span is tiny next to the bounds; keep the interval half-open.
      return value >= max && max > min ? min : value
    },
    int(min, maxInclusive) {
      return min + Math.floor(next() * (maxInclusive - min + 1))
    },
    chance(p) {
      return next() < p
    },
    pick<T>(items: readonly T[]): T {
      if (items.length === 0) throw new RangeError('Rng.pick needs at least one item')
      return items[Math.floor(next() * items.length)]
    },
    fork(label) {
      let h0 = 0x811c9dc5
      let h1 = 0x9747b28c
      for (let i = 0; i < label.length; i++) {
        const unit = label.charCodeAt(i)
        h0 = Math.imul(h0 ^ unit, 0x01000193)
        h1 = Math.imul(h1 ^ unit, 0x5bd1e995)
        h1 ^= h1 >>> 15
      }
      h0 = mix32(h0 ^ label.length)
      h1 = mix32(h1 + label.length)
      const child0 = mix32((Math.imul(key0 ^ h0, 0x9e3779b1) + key1 + 0x7f4a7c15) | 0)
      const child1 = mix32((Math.imul(key1 ^ h1, 0x85ebca77) + child0 + 0x165667b1) | 0)
      return fromKey(child0, child1)
    },
  }
}

/**
 * A seeded generator. The seed is read as an integer (its fraction is dropped; a non-finite seed is 0), and
 * distinct integers up to 2^53 in size give distinct streams.
 */
export function createRng(seed: number): Rng {
  const whole = Number.isFinite(seed) ? Math.trunc(seed) : 0
  const low = whole >>> 0
  const high = Math.floor(whole / UINT32_RANGE) >>> 0
  return fromKey(mix32(low ^ 0x9e3779b9), mix32(high ^ 0x85ebca6b))
}
