import type { DriverId } from '../core'
import { compareResults, legPositions, rankRound, type Placing } from './ranking'
import type { Classification, FinalStanding, QualifyingStanding, RaceDayEntry, RaceDayState } from './types'

// Points, standings and the classification (race-format.md, "Qualifying points", "Finals points" and "Event
// classification"). A session's place is its points, 1st = 1 … last = N, and the lowest total wins.

/** How many qualifying rounds count, by rounds run: 1 → 1, 2 → the best 1, 3 → the best 2. */
const QUALIFYING_COUNTED: readonly number[] = [0, 1, 1, 2]
/** How many final legs count, by legs run: 1 → 1, 2 → both, 3 → the best 2. */
const FINALS_COUNTED: readonly number[] = [0, 1, 2, 2]

/** One driver's sessions of a kind, scored. */
interface Scored {
  entry: RaceDayEntry
  /** The points that count, best (lowest) first. */
  counted: number[]
  points: number
  /** Every session run, the driver's best first. */
  bestFirst: Placing[]
}

/**
 * Every driver's sessions of one kind that have been run, scored: the best `countedBy[sessions run]` places count.
 * `better` orders one driver's sessions, best first, for the tie-break.
 */
function score(
  state: RaceDayState,
  kind: 'qualifying' | 'final',
  countedBy: readonly number[],
  better: (a: Placing, b: Placing) => number,
): Scored[] {
  const byDriver = new Map<DriverId, Placing[]>(state.entries.map((entry) => [entry.driverId, []]))
  for (const { item, result } of state.results) {
    if (item.kind !== kind) continue
    for (const placing of kind === 'qualifying' ? rankRound(result) : legPositions(result)) byDriver.get(placing.driverId)?.push(placing)
  }
  return state.entries.map((entry) => {
    const sessions = byDriver.get(entry.driverId) ?? []
    const counted = sessions
      .map((placing) => placing.place)
      .sort((a, b) => a - b)
      .slice(0, countedBy[sessions.length])
    return { entry, counted, points: counted.reduce((total, place) => total + place, 0), bestFirst: [...sessions].sort(better) }
  })
}

/** Two drivers' sessions compared best against best, then next best against next best: the first difference, or 0. */
function compareBestFirst(a: readonly Placing[], b: readonly Placing[], better: (a: Placing, b: Placing) => number): number {
  const count = Math.min(a.length, b.length)
  for (let i = 0; i < count; i++) {
    const difference = better(a[i], b[i])
    if (difference !== 0) return difference
  }
  return 0
}

/** A leg against a leg: the better position, then more laps, then the lower time. */
const betterLeg = (a: Placing, b: Placing): number => a.place - b.place || compareResults(a, b)

/**
 * The qualifying standings, top qualifier first; before any round has been run, the entry list in car-number order.
 *
 * Drivers level on points are separated by their best single round (laps, then time), then by their next best, and
 * so on through every round run, whether it counted for points or not. Drivers the rounds cannot separate are
 * ordered by car number.
 */
export function qualifyingStandings(state: RaceDayState): QualifyingStanding[] {
  return score(state, 'qualifying', QUALIFYING_COUNTED, compareResults)
    .sort((a, b) => a.points - b.points || compareBestFirst(a.bestFirst, b.bestFirst, compareResults) || a.entry.number - b.entry.number)
    .map((row, i) => {
      const best = row.bestFirst.at(0)
      return {
        driverId: row.entry.driverId,
        points: row.points,
        counted: row.counted,
        best: best !== undefined && best.laps > 0 ? { laps: best.laps, timeMs: best.timeMs } : null,
        rank: i + 1,
      }
    })
}

/**
 * The finals standings, winner first; before any leg has been run, the grid (or, before the grid is known, the
 * entry list in car-number order).
 *
 * Drivers level on points are separated by their best single leg (the better position, then more laps, then the
 * lower time in that leg), then by their next best leg in the same way. Drivers the legs cannot separate keep
 * their qualifying order.
 */
export function finalStandings(state: RaceDayState): FinalStanding[] {
  const grid = state.finalGrid ?? []
  return score(state, 'final', FINALS_COUNTED, betterLeg)
    .sort(
      (a, b) =>
        a.points - b.points ||
        compareBestFirst(a.bestFirst, b.bestFirst, betterLeg) ||
        grid.indexOf(a.entry.driverId) - grid.indexOf(b.entry.driverId) ||
        a.entry.number - b.entry.number,
    )
    .map((row, i) => ({ driverId: row.entry.driverId, points: row.points, counted: row.counted, rank: i + 1 }))
}

/** The event's classification, positions 1 to N in finals-standings order; null until every session is recorded. */
export function classification(state: RaceDayState): Classification[] | null {
  if (state.cursor < state.schedule.length) return null
  return finalStandings(state).map((standing) => ({ position: standing.rank, driverId: standing.driverId }))
}
