// A double is hashed as two 32-bit words, low word first, whatever the byte order of the machine.
const LOW_WORD = new Uint8Array(new Uint32Array([1]).buffer)[0] === 1 ? 0 : 1
const HIGH_WORD = 1 - LOW_WORD

/** Every NaN is hashed as this one: the quiet NaN with an empty payload. */
const NAN_HIGH = 0x7ff80000
const NAN_LOW = 0

/**
 * Stable digest of numeric state, identical across engines for identical inputs.
 *
 * 64 bits as two 32-bit lanes, each a multiply-rotate hash over the words of every value, cross-mixed at the
 * end and returned as 16 hex digits. Each round is a bijection of its lane for a given word and of the word for
 * a given lane, so changing any single value always changes the digest. +0 and -0 differ; all NaNs are alike.
 * Not cryptographic.
 */
export function hashState(values: Float64Array | readonly number[]): string {
  const floats = values instanceof Float64Array ? values : Float64Array.from(values)
  const count = floats.length
  const words = new Uint32Array(floats.buffer, floats.byteOffset, count * 2)

  let h1 = 0x9e3779b1 ^ count
  let h2 = 0x27d4eb2f ^ count
  for (let i = 0; i < count; i++) {
    const value = floats[i]
    const nan = value !== value
    const low = nan ? NAN_LOW : words[2 * i + LOW_WORD]
    const high = nan ? NAN_HIGH : words[2 * i + HIGH_WORD]

    let k = Math.imul(low, 0xcc9e2d51)
    k = (k << 15) | (k >>> 17)
    h1 ^= Math.imul(k, 0x1b873593)
    h1 = (h1 << 13) | (h1 >>> 19)
    h1 = (Math.imul(h1, 5) + 0xe6546b64) | 0
    k = Math.imul(high, 0xcc9e2d51)
    k = (k << 15) | (k >>> 17)
    h1 ^= Math.imul(k, 0x1b873593)
    h1 = (h1 << 13) | (h1 >>> 19)
    h1 = (Math.imul(h1, 5) + 0xe6546b64) | 0

    k = Math.imul(high, 0x85ebca77)
    k = (k << 17) | (k >>> 15)
    h2 ^= Math.imul(k, 0xc2b2ae3d)
    h2 = (h2 << 11) | (h2 >>> 21)
    h2 = (Math.imul(h2, 5) + 0x165667b1) | 0
    k = Math.imul(low, 0x85ebca77)
    k = (k << 17) | (k >>> 15)
    h2 ^= Math.imul(k, 0xc2b2ae3d)
    h2 = (h2 << 11) | (h2 >>> 21)
    h2 = (Math.imul(h2, 5) + 0x165667b1) | 0
  }

  const a = avalanche(h1 ^ ((h2 << 16) | (h2 >>> 16)))
  const b = avalanche(h2 ^ ((a << 5) | (a >>> 27)))
  return hex(b) + hex(a)
}

/** The 32-bit finaliser from MurmurHash3: every input bit affects every output bit. */
function avalanche(h: number): number {
  h ^= h >>> 16
  h = Math.imul(h, 0x85ebca6b)
  h ^= h >>> 13
  h = Math.imul(h, 0xc2b2ae35)
  h ^= h >>> 16
  return h
}

function hex(word: number): string {
  return (word >>> 0).toString(16).padStart(8, '0')
}
