import { motorAtWheels, motorNoLoadRadS, motorTorquePerAmpNm } from './motor'
import type { CarClass, CarParams, DriveLayout, Tuning } from './types'

// Folds a class row and the global tuning block into the resolved car the model and the physics world consume
// (ADR-003). Every rule here is the same for every class; the model derives nothing further.

/** Standard gravity, m/s². */
const GRAVITY_MS2 = 9.81

/**
 * Front share of drive torque with no load-following: all of it on a front-drive car, none on a rear-drive
 * car, and the tuning block's share on a 4WD car. A belt-drive 4WD with `beltSplit` on does not use it for
 * drive (torque follows axle load).
 */
function staticFrontDrive(drive: DriveLayout, tuning: Tuning): number {
  if (drive === 'fwd') return 1
  if (drive === 'rwd') return 0
  return tuning.fourWdStaticFrontShare
}

export function resolveCar(cls: CarClass, tuning: Tuning): CarParams {
  const { scale, tyre } = tuning
  const { stallForceN: realStallForceN, noLoadSpeedMS: realNoLoadMS } = motorAtWheels(cls.motor, cls.finalDriveRatio, cls.tyreRadiusM, tuning)
  const realLimitForceN =
    (motorTorquePerAmpNm(cls.motor.kv) * tuning.currentLimitA * cls.finalDriveRatio * tuning.drivetrainEfficiency) / cls.tyreRadiusM

  // Speed compression: one curve for every car, through the anchor, a power law either side of it. A car twice
  // as fast in reality is well under twice as fast on screen. The car's own speed scale is where its real
  // no-load speed falls on that curve.
  const speedScale = (scale.anchorGameMS / scale.anchorRealMS) * Math.pow(realNoLoadMS / scale.anchorRealMS, scale.speedExponent - 1)

  const gEff = GRAVITY_MS2 * scale.grip
  const params: CarParams = {
    classId: cls.id,
    drive: cls.drive,
    massKg: cls.massKg,
    yawInertiaKgM2: cls.massKg * cls.yawGyrationM * cls.yawGyrationM,
    lengthM: cls.lengthM,
    widthM: cls.widthM,
    wheelbaseM: cls.wheelbaseM,
    cgToFrontAxleM: cls.wheelbaseM * (1 - cls.weightFront),
    cgToRearAxleM: cls.wheelbaseM * cls.weightFront,
    cgHeightM: cls.cgHeightM,
    gEff,
    muFront: cls.muFront,
    muRear: cls.muRear,
    // The curve sin(C·atan(B·slip)) peaks where C·atan(B·slip) is a quarter turn.
    tyreB: Math.tan(Math.PI / (2 * tyre.shapeC)) / tyre.peakSlipRad,
    tyreC: tyre.shapeC,
    tractionShareMax: tyre.tractionShareMax,
    postPeakKeep: tyre.postPeakKeep,
    slipSpeedFloorMS: tyre.slipSpeedFloorMS,
    slipCancelShare: tuning.slipCancelShare,
    yawSettle: { belowMS: tuning.yawSettle.belowMS, ratePerS: tuning.yawSettle.ratePerS },
    maxSteerRad: tuning.maxSteerRad,
    centreLocked: cls.drive === '4wd' && tuning.beltSplit,
    driveFront: staticFrontDrive(cls.drive, tuning),
    stallForceN: realStallForceN * scale.thrust,
    thrustLimitN: realLimitForceN * scale.thrust,
    noLoadSpeedMS: realNoLoadMS * speedScale,
    motorNoLoadRadS: motorNoLoadRadS(cls.motor.kv, tuning.packVoltage),
    reverseLimit: tuning.reverseLimit,
    brakeForceN: 0,
    brakeRearReserve: tuning.brakeRearReserve,
    brakeRearReserveShare: tuning.brakeRearReserveShare,
    brakeRearGain: cls.brakeRearGain,
    brakeSlideGive: cls.brakeSlideGive,
    dragBrakeForceN: 0,
    rollForceN: tuning.rollResistance * cls.massKg * GRAVITY_MS2 * scale.thrust,
    // Drag is scaled with the car's own speed scale, so each car keeps the share of its no-load speed that it
    // reaches in reality.
    aeroK: (cls.dragArea * scale.thrust) / (speedScale * speedScale),
    dragArea: cls.dragArea,
    sideArea: cls.sideArea,
    // The wind is the world's, stated at the anchor car's scale; a car's air has its own scale's share of it.
    windShare: speedScale / (scale.anchorGameMS / scale.anchorRealMS),
    stabilityFactor: cls.widthM / (2 * cls.cgHeightM),
    shaping: { ...tuning.shaping },
  }
  // The pedal asks for a share of the braked tyres' friction budget. Stated here as the force that share is at
  // static axle loads, which is what the contract carries and what a braking-distance estimate wants.
  params.brakeForceN = tuning.brakeShare * brakedStaticBudgetN(params)
  params.dragBrakeForceN = tuning.dragBrakeShare * params.brakeForceN
  params.reverseLimit = reverseShare(params, tuning.reverseLimit)
  return params
}

/**
 * The share of forward throttle, and of forward no-load speed, that a car gets in reverse: the tuning block's,
 * or less where the tuning block's would take the car backwards faster than that share of its own forward top
 * speed. Drag grows with the square of speed, so a car that drag holds well short of its no-load speed going
 * forwards is held much less at half that speed; left alone it would reverse at more than the share.
 *
 * In reverse a car is its own motor with force and no-load speed both scaled by the share. The largest share
 * that still balances the resistance at or below the reverse top speed is on the motor's falling line or on the
 * current limit, whichever lets more through.
 */
function reverseShare(
  p: Pick<CarParams, 'stallForceN' | 'thrustLimitN' | 'noLoadSpeedMS' | 'rollForceN' | 'aeroK'>,
  tuningShare: number,
): number {
  const reverseTopMS = tuningShare * topSpeedMS(p)
  if (reverseTopMS <= 0) return tuningShare
  const resistN = p.rollForceN + p.aeroK * reverseTopMS * reverseTopMS
  const onMotorCurve = resistN / p.stallForceN + reverseTopMS / p.noLoadSpeedMS
  const onCurrentLimit = resistN / p.thrustLimitN
  return Math.min(tuningShare, Math.max(onMotorCurve, onCurrentLimit))
}

/**
 * Whether braking and drive reach the front axle, and the rear. Braking goes through the drivetrain. A locked
 * centre drives both axles whatever its static share says.
 */
export function frontAxleDriven(p: Pick<CarParams, 'driveFront' | 'centreLocked'>): boolean {
  return p.centreLocked || p.driveFront > 0
}
export function rearAxleDriven(p: Pick<CarParams, 'driveFront' | 'centreLocked'>): boolean {
  return p.centreLocked || p.driveFront < 1
}

/** The share of the pedal's demand that a braked rear axle is asked for: the rear reserve, times the car's own gain. */
export function rearBrakeShare(p: Pick<CarParams, 'brakeRearReserve' | 'brakeRearReserveShare' | 'brakeRearGain'>): number {
  return (p.brakeRearReserve ? p.brakeRearReserveShare : 1) * p.brakeRearGain
}

type BrakedBudgetInputs = Pick<
  CarParams,
  'massKg' | 'gEff' | 'cgToRearAxleM' | 'wheelbaseM' | 'muFront' | 'muRear' | 'driveFront' | 'centreLocked' | 'brakeRearReserve' | 'brakeRearReserveShare' | 'brakeRearGain'
>

/**
 * The friction budget, at static axle loads on dry asphalt, that full brake demand is a share of: the front
 * axle's if it is driven, plus the rear's (weighted by its reserve) if it is driven.
 */
export function brakedStaticBudgetN(p: BrakedBudgetInputs): number {
  const weightN = p.massKg * p.gEff
  const frontLoadN = (weightN * p.cgToRearAxleM) / p.wheelbaseM
  const rearLoadN = weightN - frontLoadN
  return (frontAxleDriven(p) ? p.muFront * frontLoadN : 0) + (rearAxleDriven(p) ? rearBrakeShare(p) * p.muRear * rearLoadN : 0)
}

/** Steady-state cornering limit, m/s²: the weaker axle decides. */
export function gripLimitMS2(p: Pick<CarParams, 'gEff' | 'muFront' | 'muRear'>): number {
  return p.gEff * Math.min(p.muFront, p.muRear)
}

/**
 * Top speed in a straight line on dry asphalt, m/s: where the motor's falling force (or the current limit, if
 * that is lower there) meets rolling resistance plus aerodynamic drag.
 */
export function topSpeedMS(p: Pick<CarParams, 'stallForceN' | 'thrustLimitN' | 'noLoadSpeedMS' | 'rollForceN' | 'aeroK'>): number {
  const netStallN = p.stallForceN - p.rollForceN
  const netLimitN = p.thrustLimitN - p.rollForceN
  if (netStallN <= 0 || netLimitN <= 0) return 0
  const slope = p.stallForceN / p.noLoadSpeedMS
  if (p.aeroK <= 0) return netStallN / slope
  const onMotorCurve = (Math.sqrt(slope * slope + 4 * p.aeroK * netStallN) - slope) / (2 * p.aeroK)
  const onCurrentLimit = Math.sqrt(netLimitN / p.aeroK)
  return Math.min(onMotorCurve, onCurrentLimit)
}
