import type { Rng } from '../core'
import { AI_TUNING } from './tuning'

// When each AI driver makes the pit stop it owes (F-306), settled before the start: one lap per driver, never the
// first, and no lap given to two drivers while there is a lap nobody has. The laps are counted as each driver
// counts its own: a driver given lap n takes the pit entry when it has completed n laps.

/** What a driver that owes a pit stop is given before the start. */
export interface PitPlan {
  /** The lap it comes in on: how many laps it has completed when it takes the pit entry. Never 0, which is the first lap. */
  lap: number
  /** What its own plan makes a lap, s. */
  lapS: number
}

/** A car as the plan sees it. */
export interface PitPlanCar {
  /** What the driver's own plan makes a lap, s. */
  lapS: number
  /** How far it starts from the timing line along the lap, m. */
  toLineM: number
}

/** The race as the plan sees it. */
export interface PitPlanRace {
  durationS: number
  lapLengthM: number
  /** How far round the lap the pit entry is, m. */
  entryRouteS: number
}

/**
 * The last lap a car can come in on and still have its stop served before the clock runs out: the pit entry of
 * lap n is reached a start, n laps and the way from the line to the entry after the tone, and a stop takes
 * `AI_TUNING.pitStop.reserveS` from there. Never less than 1: the first lap is nobody's.
 */
export function latestPitLap(car: PitPlanCar, race: PitPlanRace): number {
  const P = AI_TUNING.pitStop
  const lapS = car.lapS * P.lapSlack
  const laps = (race.durationS - P.reserveS - P.launchS) / lapS - (car.toLineM + race.entryRouteS) / race.lapLengthM
  return Number.isFinite(laps) ? Math.max(1, Math.floor(laps)) : 1
}

/**
 * The lap each car comes in on, by car, with null for a car that is given none. The cars with the fewest laps to
 * choose from choose first, each at random among the laps open to it that the fewest cars have taken; so no two
 * share a lap unless there are more cars than laps. Everything random comes from `rng`.
 */
export function planPitLaps(cars: ReadonlyArray<PitPlanCar | null>, race: PitPlanRace, rng: Rng): Array<number | null> {
  const latest = cars.map((car) => (car === null ? 0 : latestPitLap(car, race)))
  const draw = cars.map(() => rng.next())
  const order = cars.map((_, id) => id).filter((id) => cars[id] !== null)
  order.sort((a, b) => latest[a] - latest[b] || draw[a] - draw[b] || a - b)
  const taken = new Map<number, number>()
  const laps: Array<number | null> = cars.map(() => null)
  for (const id of order) {
    let fewest = Infinity
    for (let lap = 1; lap <= latest[id]; lap++) fewest = Math.min(fewest, taken.get(lap) ?? 0)
    const open: number[] = []
    for (let lap = 1; lap <= latest[id]; lap++) if ((taken.get(lap) ?? 0) === fewest) open.push(lap)
    const lap = rng.pick(open)
    taken.set(lap, fewest + 1)
    laps[id] = lap
  }
  return laps
}
