import type { Vec2 } from '../core'
import type { SurfaceKind } from '../track'
import type { CarParams, SurfaceTuning } from '../vehicle/types'
import { WEATHER_TUNING } from './tuning'
import type { WeatherSnapshot } from './types'

// What the weather does to a car (F-602), as pure functions of what the weather is and what the car is: how much
// grip a wet surface has left, how wet it is where the car is, the water it is standing in and what that does,
// and the force of the wind. Nothing here keeps anything, and nothing reads the car's class: a car is its
// `CarParams`. The session puts the answers into each car's environment for the tick; the surface step and the
// vehicle model act on them.

const GRIP = WEATHER_TUNING.grip
const WATER = WEATHER_TUNING.water
const AIR = WEATHER_TUNING.air

const unit = (value: number): number => Math.min(Math.max(value, 0), 1)

/**
 * What a surface keeps of its own dry grip at a wetness: 1 on a dry one, exactly; the tuning's `wetShare` on a
 * soaked one; in between a smooth curve that never rises with the wetness, steepest at the first of the water.
 */
export function wetGripFactor(surface: SurfaceKind, wetness: number): number {
  const w = unit(wetness)
  if (w === 0) return 1
  return 1 - (1 - GRIP.wetShare[surface]) * (1 - Math.pow(1 - w, GRIP.curve))
}

/**
 * The multiplier on tyre grip that a surface gives at a wetness, 1 being dry asphalt. Grass and a kerb start from
 * their own dry values, which are the surface tuning's (F-207): at wetness 0 this is exactly those.
 */
export function surfaceGrip(surface: SurfaceKind, wetness: number, dry: SurfaceTuning): number {
  const dryGrip = surface === 'grass' ? dry.grass.gripScale : surface === 'kerb' ? dry.kerb.gripScale : 1
  return dryGrip * wetGripFactor(surface, wetness)
}

/** How far a car goes on grass of a wetness before it is stuck, given how far it goes on dry grass: less, in a straight line with the wetness. */
export function grassStuckAfterM(dryM: number, wetness: number): number {
  return dryM * (1 - (1 - GRIP.grassStuckShare) * unit(wetness))
}

/**
 * The wetness under a car that is `lateralFromLineM` to either side of the racing line: the line's own within
 * `onLineWithinM` of it, the surface's from `offLineBeyondM` out, and a straight blend between the two.
 */
export function localWetness(weather: Pick<WeatherSnapshot, 'wetness' | 'lineWetness'>, lateralFromLineM: number): number {
  const off = unit((Math.abs(lateralFromLineM) - GRIP.onLineWithinM) / (GRIP.offLineBeyondM - GRIP.onLineWithinM))
  return weather.lineWetness + (weather.wetness - weather.lineWetness) * off
}

/** The water a place is in: the deepest puddle whose water reaches it, or null where it is in none. */
export function puddleAt(weather: Pick<WeatherSnapshot, 'puddles'>, x: number, y: number): { depth: number } | null {
  let depth = 0
  for (const puddle of weather.puddles) {
    if (puddle.depth <= depth) continue
    const dx = x - puddle.x
    const dy = y - puddle.y
    if (dx * dx + dy * dy <= puddle.r * puddle.r) depth = puddle.depth
  }
  return depth > 0 ? { depth } : null
}

/**
 * The speed at and above which a car floats on water of a depth, m/s. It rises with the car's tyre load (the cars'
 * tyres are one width, so that is its mass) and falls as the water deepens; in no water at all nothing floats.
 */
export function aquaplaneSpeedMS(depth: number, car: Pick<CarParams, 'massKg'>): number {
  if (depth <= 0) return Infinity
  return WATER.aquaplaneSpeedMS * Math.sqrt(car.massKg / WATER.refMassKg) * Math.sqrt(WATER.refDepth / depth)
}

/**
 * What water of a depth does to a car moving at a speed: a drag that grows with the depth and with the square of
 * the speed, and, at the car's aquaplane speed and faster, tyres that have all but lost their grip (`lateralGripScale`
 * is what they keep of it, to the side and along). Slower than that there is the drag and nothing else.
 */
export function puddleEffect(depth: number, speedMS: number, car: Pick<CarParams, 'massKg'>): { dragN: number; lateralGripScale: number; aquaplaning: boolean } {
  const deep = unit(depth)
  const aquaplaning = deep > 0 && speedMS >= aquaplaneSpeedMS(deep, car)
  return { dragN: WATER.dragPerDepth * deep * speedMS * speedMS, lateralGripScale: aquaplaning ? WATER.aquaplaneSideGrip : 1, aquaplaning }
}

type AirCar = Pick<CarParams, 'aeroK' | 'dragArea' | 'sideArea' | 'lengthM' | 'windShare'>

/**
 * What the wind adds to the force of the air on a car, world frame, N, and the yaw torque that comes with it, N·m:
 * the air's force at the car's speed through the moving air, less its force at the same speed through still air,
 * which the vehicle model already has. In no wind it is nothing, exactly.
 *
 * The air pushes back along the car in proportion to the square of its speed past the car along the car's length,
 * with the car's drag coefficient, and across it in proportion to the square of its speed across the car, with the
 * side coefficient (the drag's, times `sideArea / dragArea`): the two do not mix, so a crosswind pushes a car as
 * hard whatever its speed. The wind is the world's, in the Stock car's scale: a car's air has `windShare` of it,
 * which makes the push of a wind the same on every car of one side area, and leaves the lighter car to be moved
 * more by it. The side force acts a little ahead of the centre of mass. A car that is all but standing feels the
 * wind in proportion to its speed.
 */
export function airForce(car: AirCar, velocity: Readonly<Vec2>, headingRad: number, wind: Readonly<Vec2>): { fx: number; fy: number; torque: number } {
  const windX = wind.x * car.windShare
  const windY = wind.y * car.windShare
  if (windX === 0 && windY === 0) return { fx: 0, fy: 0, torque: 0 }
  const cos = Math.cos(headingRad)
  const sin = Math.sin(headingRad)
  // The car's own velocity, and its velocity through the air, along and across its heading.
  const vLong = cos * velocity.x + sin * velocity.y
  const vLat = -sin * velocity.x + cos * velocity.y
  const airLong = vLong - (cos * windX + sin * windY)
  const airLat = vLat - (-sin * windX + cos * windY)
  const sideK = car.dragArea > 0 ? (car.aeroK * car.sideArea) / car.dragArea : 0
  const speed = Math.sqrt(vLong * vLong + vLat * vLat)
  const felt = AIR.windFeel * (AIR.holdsBelowMS > 0 ? Math.min(1, speed / AIR.holdsBelowMS) : 1)
  const long = -car.aeroK * (Math.abs(airLong) * airLong - Math.abs(vLong) * vLong) * felt
  const lat = -sideK * (Math.abs(airLat) * airLat - Math.abs(vLat) * vLat) * felt
  return { fx: cos * long - sin * lat, fy: sin * long + cos * lat, torque: lat * car.lengthM * AIR.pressureAheadShare }
}
