import type { CarId, Pose, Vec2 } from '../core'
import type { ControlInput } from './controls'
import type { CarClassId, CarParams, StepEnvironment } from '../vehicle/types'
import type { SessionConfig } from './types'

/**
 * The seam between the session and whatever moves the cars. Internal to the sim: the session only ever
 * advances cars through this interface, so the vehicle model and physics world can be swapped in behind it.
 * Arrays passed to `step` are indexed by `CarId`.
 */
export interface CarStepper {
  /**
   * Called once per car, in `CarId` order, before the first `step`. `params` are the car's own resolved parameters
   * (`SessionEntry.params`, F-811), to drive it with in place of its class's; left out, its class's.
   */
  add(id: CarId, carClass: CarClassId, pose: Pose, params?: CarParams): void
  /**
   * Advance every car by DT given shaped-or-raw inputs; fills `out` in place. A caller that wants to know what
   * touched during the step passes `contacts`, and the stepper appends one record to it per pair of things that
   * pressed on each other. A stepper with nothing solid in it appends nothing.
   */
  step(inputs: readonly ControlInput[], env: readonly StepEnvironment[], out: CarKinematics[], contacts?: StepContact[]): void
  setPose(id: CarId, pose: Pose, zeroVelocity: boolean): void
  /**
   * Forgets what the car's driver was in the middle of (F-501): pedals that were ramping, a wheel that was turned, a
   * brake that had become reverse. A car that is picked up and set down is handed back with all of it at rest. A
   * stepper that shapes no input has nothing to forget, and leaves this out.
   */
  resetControls?(id: CarId): void
  /**
   * The marshals who are out on the track (F-502): solid circles for the next step, and all of them each time. A
   * stepper with nothing solid in it leaves this out, and cars pass through them.
   */
  setMarshals?(marshals: ReadonlyArray<{ id: number; pos: Readonly<Vec2>; radiusM: number }>): void
  /**
   * Where the centre of each of the track's markers is now, written over the entries of `out` in the track's own
   * order (F-308). A stepper in which no marker can move leaves this out, and the markers stay where the track has them.
   */
  markersInto?(out: Vec2[]): void
  /** Append every number of the stepper's own state, in a fixed order. */
  hashInto(buffer: number[]): void
}

/** A car and something solid that pressed on each other during one step (F-302). */
export interface StepContact {
  /** The car; of two cars, the one with the lower id. */
  a: CarId
  b: CarId | 'wall' | 'marker' | 'marshal'
  /** Which marshal, where `b` is one (F-502). */
  marshal?: number
  /** Normal impulse over the step, N·s; greater than zero. */
  impulseNs: number
  /**
   * Which way the touch pressed at its hardest, from `a` toward `b`, a unit vector in the world frame (F-501): what
   * tells a touch on a car's side from one on its nose or its tail (F-507). A stepper that cannot say leaves it out,
   * and such a touch rolls nobody.
   */
  normal?: Readonly<Vec2>
}

export interface CarKinematics {
  pose: Pose
  /** World frame, m/s. */
  velocity: Vec2
  /** rad/s, positive to the right. */
  yawRate: number
  /** Road-wheel angle after shaping. */
  steerRad: number
  /** After shaping, 0..1. */
  throttle: number
  /** After shaping, 0..1. */
  brake: number
  motorRadS: number
  /** 0..1+ saturation of the front axle's grip budget. */
  slipFront: number
  /** 0..1+ saturation of the rear axle's grip budget. */
  slipRear: number
}

/** Builds the stepper for one session. Called once, by `createSessionWith`. */
export type StepperFactory = (config: SessionConfig) => CarStepper

/** Dry, level asphalt in still air: what every car is given until surfaces and weather exist. */
export function neutralEnvironment(): StepEnvironment {
  return { grip: 1, dragN: 0, airborne: false, puddle: null, wind: { x: 0, y: 0 } }
}
