import { clamp } from '../core'
import { airForce } from '../weather/coupling'
import { availableDriveForceN, motorSpeedRadS } from './motor'
import { brakedStaticBudgetN, frontAxleDriven, rearAxleDriven, rearBrakeShare } from './resolve'
import type { BodyState, CarParams, ShapedControls, StepEnvironment, VehicleModel, VehicleTelemetry, Wrench } from './types'

// The vehicle model (ADR-003): a three-degree-of-freedom single-track ("bicycle") car. It reads one rigid
// body's state and returns the net force and yaw torque for this tick. It is a pure function of its arguments:
// no memory, no clock, no randomness, and no knowledge of what will integrate the result.
//
// The one mechanism that separates the classes is the friction budget: an axle can transmit at most
// grip × load, and whatever it spends driving or braking is taken out of what it has left for cornering.
// Every rule below is the same for every car; cars differ only in the numbers in `CarParams`.

/** Passes of the load ↔ acceleration fixed point. The coupling term a·h/L is under 0.1, so three leave an error below 0.1 %. */
const LOAD_PASSES = 3

/** What each axle did this tick. Read by the tests and by anything that wants more than the telemetry. */
export interface AxleForces {
  /** Vertical load, N: static split plus longitudinal transfer. The two always sum to mass × gEff. */
  loadFrontN: number
  loadRearN: number
  /** Friction budget, N: grip × load × the ground's grip multiplier. */
  budgetFrontN: number
  budgetRearN: number
  /** Along the wheel, N: drive positive, braking against the direction of travel. */
  longFrontN: number
  longRearN: number
  /** Of `long…N`, the part that is motor drive. */
  driveFrontN: number
  driveRearN: number
  /** Across the wheel, N. */
  latFrontN: number
  latRearN: number
}

export interface VehicleForces extends Wrench {
  tel: VehicleTelemetry
  axles: AxleForces
}

/**
 * Side force as a share of what the axle has left, from its slip angle: sin(C·atan(B·slip)), which peaks at 1.
 * Past the peak it is never allowed below `postPeakKeep`, so a sliding tyre keeps most of its side force and a
 * slide slows down and ends instead of feeding itself.
 */
function lateralShare(slipRad: number, p: CarParams): number {
  const curve = p.tyreC * Math.atan(p.tyreB * slipRad)
  const share = Math.sin(curve)
  if (Math.abs(curve) <= Math.PI / 2) return share
  return slipRad < 0 ? Math.min(share, -p.postPeakKeep) : Math.max(share, p.postPeakKeep)
}

/**
 * The share of its braking a tyre keeps at a slip angle whose tangent is `slipTan`. A tyre sliding sideways
 * pushes back along the way it slides, so the more it slides the less of its grip goes to braking and the more
 * comes back as side force. With a give of 0 the brake keeps all of its share at any slip angle.
 */
function brakeKept(slipTan: number, p: CarParams): number {
  const given = p.brakeSlideGive * slipTan
  return 1 / Math.sqrt(1 + given * given)
}

/** The model's full working for one tick. `vehicleModel.step` returns the contract's part of it. */
export function vehicleForces(body: BodyState, c: ShapedControls, p: CarParams, env: StepEnvironment, dt: number): VehicleForces {
  const cosA = Math.cos(body.pose.angle)
  const sinA = Math.sin(body.pose.angle)
  const vx = body.velocity.x
  const vy = body.velocity.y
  const yawRate = body.yawRate
  const vLong = cosA * vx + sinA * vy
  const vLat = -sinA * vx + cosA * vy
  const speed = Math.sqrt(vx * vx + vy * vy)

  // The angle the wheels are held at, and the angle they steer the car by: the same on anything a car drives on,
  // less while a kerb hop has the front tyres barely touching.
  const steerRad = c.steer * p.maxSteerRad
  const steeredRad = steerRad * (env.steerScale ?? 1)
  const cosS = Math.cos(steeredRad)
  const sinS = Math.sin(steeredRad)

  // Contact-patch velocities, in each wheel's own frame.
  const latVelFront = vLat + p.cgToFrontAxleM * yawRate
  const latVelRear = vLat - p.cgToRearAxleM * yawRate
  const wheelLongFront = vLong * cosS + latVelFront * sinS
  const wheelLatFront = -vLong * sinS + latVelFront * cosS
  const rollFrontMS = Math.max(Math.abs(wheelLongFront), p.slipSpeedFloorMS)
  const rollRearMS = Math.max(Math.abs(vLong), p.slipSpeedFloorMS)
  const slipFrontRad = Math.atan2(wheelLatFront, rollFrontMS)
  const slipRearRad = Math.atan2(latVelRear, rollRearMS)

  // Mid hop the wheels are off the ground: the motor and the brake reach it not at all.
  const drive = env.airborne ? 0 : c.throttle * availableDriveForceN(p, Math.sign(c.throttle), vLong)

  // Braking goes through the drivetrain, so only driven axles brake. The pedal asks for a share of the braked
  // tyres' friction budget, not a force, which keeps it honest as load moves forward. A braked rear axle is
  // asked for less than a front one (the rear reserve), so on a 4WD car the front is the end that gives up first.
  const coasting = c.throttle === 0 && c.brake === 0
  const staticBudgetN = brakedStaticBudgetN(p)
  const demandN = env.airborne ? 0 : c.brake * p.brakeForceN + (coasting ? p.dragBrakeForceN : 0)
  const pedalShare = staticBudgetN > 0 ? Math.min(1, demandN / staticBudgetN) : 0
  // A tyre that is sliding sideways gives some of that braking up (see `brakeKept`).
  const brakeShareFront = frontAxleDriven(p) ? pedalShare * brakeKept(wheelLatFront / rollFrontMS, p) : 0
  const brakeShareRear = rearAxleDriven(p) ? Math.min(1, pedalShare * rearBrakeShare(p)) * brakeKept(latVelRear / rollRearMS, p) : 0
  // Brakes and rolling resistance may stop the car within the tick but never push it backwards.
  const stopCapN = (p.massKg * Math.abs(vLong)) / dt
  const against = -Math.sign(vLong)

  // What the ground gives the tyres: the surface's grip, and in standing water that floats the car (F-602) only
  // a share of that, for the side force and for driving and braking alike.
  const puddle = env.puddle
  const grip = puddle === null ? env.grip : env.grip * puddle.lateralGripScale

  // Axle loads and the drive split depend on the longitudinal acceleration, which depends on them.
  const weightN = p.massKg * p.gEff
  const staticFrontN = (weightN * p.cgToRearAxleM) / p.wheelbaseM
  const transferPerAccel = (p.massKg * p.cgHeightM) / p.wheelbaseM
  let loadFrontN = staticFrontN
  let loadRearN = weightN - staticFrontN
  let budgetFrontN = 0
  let budgetRearN = 0
  let driveFrontN = 0
  let driveRearN = 0
  let longFrontN = 0
  let longRearN = 0
  let rollN = 0
  let accelEstimate = 0
  for (let pass = 0; pass < LOAD_PASSES; pass++) {
    loadFrontN = clamp(staticFrontN - transferPerAccel * accelEstimate, 0, weightN)
    loadRearN = weightN - loadFrontN
    budgetFrontN = p.muFront * loadFrontN * grip
    budgetRearN = p.muRear * loadRearN * grip
    // Traction cap: a driven axle may spend only part of its budget on drive, so full throttle mid-corner
    // costs cornering grip without deleting it. A locked centre sends torque where the load is.
    const frontDriveShare = p.centreLocked ? loadFrontN / weightN : p.driveFront
    const capFrontN = p.tractionShareMax * budgetFrontN
    const capRearN = p.tractionShareMax * budgetRearN
    driveFrontN = clamp(drive * frontDriveShare, -capFrontN, capFrontN)
    driveRearN = clamp(drive * (1 - frontDriveShare), -capRearN, capRearN)
    const brakeFrontN = brakeShareFront * budgetFrontN
    const brakeRearN = brakeShareRear * budgetRearN
    const brakeTotalN = brakeFrontN + brakeRearN
    const brakeScale = brakeTotalN > stopCapN ? stopCapN / brakeTotalN : 1
    longFrontN = driveFrontN + against * brakeFrontN * brakeScale
    longRearN = driveRearN + against * brakeRearN * brakeScale
    rollN = against * Math.min(p.rollForceN, Math.max(0, stopCapN - brakeTotalN))
    accelEstimate = (longFrontN * cosS + longRearN + rollN) / p.massKg
  }

  // Friction ellipse: an axle's side-force capacity is what its longitudinal force left over.
  const useFront = budgetFrontN > 0 ? Math.min(1, Math.abs(longFrontN) / budgetFrontN) : 0
  const useRear = budgetRearN > 0 ? Math.min(1, Math.abs(longRearN) / budgetRearN) : 0
  const sideCapFrontN = budgetFrontN * Math.sqrt(1 - useFront * useFront)
  const sideCapRearN = budgetRearN * Math.sqrt(1 - useRear * useRear)
  let latFrontN = -sideCapFrontN * lateralShare(slipFrontRad, p)
  let latRearN = -sideCapRearN * lateralShare(slipRearRad, p)

  // A tyre can cancel at most a set share of its own sideways motion within one tick. This bites at low speed
  // and small slip, where it turns the stiff slip curve into the no-slip constraint it approximates, and it is
  // what keeps integration at a fixed tick from overshooting.
  const massAtFront = p.slipCancelShare / (1 / p.massKg + (p.cgToFrontAxleM * p.cgToFrontAxleM) / p.yawInertiaKgM2)
  const massAtRear = p.slipCancelShare / (1 / p.massKg + (p.cgToRearAxleM * p.cgToRearAxleM) / p.yawInertiaKgM2)
  const cancelFrontN = (massAtFront * Math.abs(wheelLatFront)) / dt
  const cancelRearN = (massAtRear * Math.abs(latVelRear)) / dt
  latFrontN = clamp(latFrontN, -cancelFrontN, cancelFrontN)
  latRearN = clamp(latRearN, -cancelRearN, cancelRearN)

  // A car that is held to a yaw rate is on its roof (F-507): its tyres are off the road, and the drag the ground gives
  // it is all that slows it (F-512), so that it slides exactly as far and as long as it is meant to.
  const heldYawRadS = env.yawRateRadS ?? null
  const onRoof = heldYawRadS !== null
  const bodyLongN = longFrontN * cosS - latFrontN * sinS + longRearN + (onRoof ? 0 : rollN)
  const bodyLatN = longFrontN * sinS + latFrontN * cosS + latRearN
  // Yaw settling: tyre scrub at walking pace, so a spun car stops rotating instead of pirouetting on saturated
  // tyres. Full below `belowMS`, fading to nothing at twice that. It is the tyres' friction, so on a wet surface
  // there is as much less of it as there is less grip (F-602): at its dry strength it takes most of what soaked
  // tyres can turn the car with, and a car cannot be got round a slow corner.
  let settlePerS = p.yawSettle.ratePerS * clamp(2 - speed / p.yawSettle.belowMS, 0, 1)
  if (env.wetGrip !== undefined && env.wetGrip !== 1) settlePerS *= env.wetGrip
  // A car that is held to a yaw rate (one on its roof, F-507) is given the torque that takes it there within the
  // tick; what its tyres would have turned it by counts for nothing.
  const torque =
    heldYawRadS !== null
      ? (p.yawInertiaKgM2 * (heldYawRadS - yawRate)) / dt
      : p.cgToFrontAxleM * (longFrontN * sinS + latFrontN * cosS) - p.cgToRearAxleM * latRearN - p.yawInertiaKgM2 * settlePerS * yawRate
  // Aerodynamic drag in still air plus whatever the ground adds (grass, standing water); together they may stop
  // the car but not reverse it. On its roof, the ground's drag alone (the session gives a car on its roof neither
  // standing water nor wind, F-602).
  const groundDragN = puddle === null ? env.dragN : env.dragN + puddle.dragN
  const resistPerSpeed = Math.min((onRoof ? 0 : p.aeroK * speed) + (speed > 0 ? groundDragN / speed : 0), p.massKg / dt)
  let fx = cosA * bodyLongN - sinA * bodyLatN - resistPerSpeed * vx
  let fy = sinA * bodyLongN + cosA * bodyLatN - resistPerSpeed * vy
  let yawTorque = torque
  // The wind (F-602): what moving air adds to that drag, along the car and across it. In still air, nothing is added at all.
  if (env.wind.x !== 0 || env.wind.y !== 0) {
    const air = airForce(p, body.velocity, body.pose.angle, env.wind)
    fx += air.fx
    fy += air.fy
    yawTorque += air.torque
  }

  return {
    fx,
    fy,
    torque: yawTorque,
    tel: {
      speedMS: speed,
      vLong,
      vLat,
      slipFrontRad,
      slipRearRad,
      steerRad,
      satFront: budgetFrontN > 0 ? Math.min(1, Math.sqrt(longFrontN * longFrontN + latFrontN * latFrontN) / budgetFrontN) : 1,
      satRear: budgetRearN > 0 ? Math.min(1, Math.sqrt(longRearN * longRearN + latRearN * latRearN) / budgetRearN) : 1,
      useFront,
      useRear,
      accelLongMS2: bodyLongN / p.massKg,
      accelLatMS2: bodyLatN / p.massKg,
      motorRadS: motorSpeedRadS(p, vLong),
    },
    axles: { loadFrontN, loadRearN, budgetFrontN, budgetRearN, longFrontN, longRearN, driveFrontN, driveRearN, latFrontN, latRearN },
  }
}

/**
 * The model behind the contract's interface. Of the environment it acts on `grip`, `dragN`, `airborne` and
 * `steerScale`, which the surfaces set (F-207, and in the wet F-602), on `yawRateRadS`, which a car on its roof is
 * given (F-507), and on `puddle` and `wind`, which the weather sets (F-602). It knows nothing of the weather itself:
 * only what is under and round the car on this tick.
 */
export const vehicleModel: VehicleModel = Object.freeze({
  step(body: BodyState, c: ShapedControls, p: CarParams, env: StepEnvironment, dt: number): Wrench & { tel: VehicleTelemetry } {
    const forces = vehicleForces(body, c, p, env, dt)
    return { fx: forces.fx, fy: forces.fy, torque: forces.torque, tel: forces.tel }
  },
})
