import type { Pose } from '../core'
import type { TrackRuntime } from '../track'

// The pit lane as a driver needs it (F-303): the route through it, and where on that route the pit lane ends at
// the lap's own asphalt. The racing line never enters the pit lane, so a car that is in it follows this instead.
// And the way into it (F-306): where on the lap the pit route begins, and the lap's own route up to there, which a
// car that is coming in for a stop takes to in good time.

export interface PitPath {
  /** Length of the pit route, m. */
  lengthM: number
  /** The pit route at a distance along it; `s` is held to its two ends. */
  pose(s: number): Pose
  /** The point of the pit route nearest to a place: how far along it is, and how far to its right the place lies. */
  nearest(x: number, y: number): { s: number; lateralM: number }
  /**
   * How far along the pit route the pit lane begins to be a lane of its own, m. Before that the pit route runs
   * in the lap's lane, and a car there is still racing.
   */
  ownFromS: number
  /** How far along the pit route the pit lane ends and a car's centre comes onto the lap's lane, m. */
  joinS: number
  /** The distance along the lap's route abeam of that place, m. */
  joinRouteS: number
  /** Length of the lap's route, m. */
  lapLengthM: number
  /** The distance along the lap's route at which the pit route begins, in the middle of the lap's lane, m. */
  entryRouteS: number
  /** Which side of the lap the pit lane leaves it on, for a car on its way in: -1 left, 1 right. */
  side: -1 | 1
  /**
   * The way in at a distance `u` from the pit entry, m: the pit route from there on, and before it (`u` below
   * zero) the middle of the lap's lane leading up to it.
   */
  wayIn(u: number): Pose
}

/** How finely the end of the pit lane is looked for along the pit route, m. */
const STEP_M = 0.05

/** The pit path of a track, or null if it has no pit lane. */
export function pitPathOf(track: TrackRuntime): PitPath | null {
  const pit = track.data.pitLane
  const end = track.pitRoutePose(track.pitLengthM)
  if (pit === undefined || end === null) return null
  const pose = (s: number): Pose => track.pitRoutePose(s) ?? end
  const own = (s: number): boolean => {
    const at = pose(s)
    return track.inPitLane(at.x, at.y)
  }
  // From each end of the pit route inward, the first place that is the pit lane's alone.
  let ownFromS = 0
  while (ownFromS < track.pitLengthM && !own(ownFromS)) ownFromS += STEP_M
  let joinS = track.pitLengthM
  while (joinS > ownFromS && !own(joinS - STEP_M)) joinS -= STEP_M
  const join = pose(joinS)
  const mouth = pose(ownFromS)
  return {
    lengthM: track.pitLengthM,
    pose,
    nearest: (x, y) => track.nearestPitRoute(x, y) ?? { s: 0, lateralM: 0 },
    ownFromS,
    joinS,
    joinRouteS: track.nearestRoute(join.x, join.y, pit.exitS).s,
    lapLengthM: track.lengthM,
    entryRouteS: pit.entryS,
    side: track.nearestRoute(mouth.x, mouth.y, pit.entryS + ownFromS).lateralM < 0 ? -1 : 1,
    wayIn: (u) => (u < 0 ? track.routePose(pit.entryS + u) : pose(u)),
  }
}
