/** Raw driver intent for one car for one tick, before shaping. */
export interface ControlInput {
  /** 0..1 */
  throttle: number
  /** 0..1 (held at standstill = reverse) */
  brake: number
  /** -1..1 (+ = right) */
  steer: number
}

/** Everything released. Frozen: it is shared by every session. */
export const NO_INPUT: ControlInput = Object.freeze({ throttle: 0, brake: 0, steer: 0 })
