import type { CarId, DriverId, Rng } from '../core'
import type { SessionConfig } from '../session/types'
import type { TrackRuntime } from '../track'
import type { CarParams } from '../vehicle/types'
import { createAiDriver, lineStyleFor, plannedLapS, type AiDriver, type AiDriverConfig, type DriverProfile } from './driver'
import { pitPathOf } from './pit-lane'
import { planPitLaps, type PitPlan } from './pit-plan'
import { createPullOver, type ParkingBoard, type PullOver } from './pull-over'
import { DEFAULT_LINE_STYLE, measureCorridor, relaxLine, type Corridor, type LineStyle, type RacingLine } from './racing-line'

// The AI drivers of one session (F-301): one per entry whose controller is 'ai', each with the racing line its
// skill and temperament ask for and its own stream of randomness. And what parks each car once it has finished
// (F-303), the human's included.

/** What a session needs in order to drive its AI cars. */
export interface AiSetup {
  /** The profile of an AI entry's driver. It throws when there is none: an AI entry nobody can drive is a mistake in the configuration. */
  profile(driverId: DriverId): DriverProfile
  /** Car `id`'s resolved parameters, as the stepper has them. */
  car(id: CarId): CarParams
  /** The speed over a kerb that risks rolling a car, m/s: lines that take kerbs are planned below it. */
  kerbRollSpeedMS?: number
  /** False for a field whose drivers never make the big mistake that puts a car off; left out, they make them as `AI_TUNING.accidents` says. */
  accidents?: boolean
}

/**
 * The racing lines of one track, each found once: the lane is measured once per car width and a line is relaxed
 * once per style, however many drivers share them.
 */
export interface LineBook {
  line(carWidthM: number, style: LineStyle): RacingLine
}

export function createLineBook(track: TrackRuntime): LineBook {
  const corridors = new Map<number, Corridor>()
  const lines = new Map<string, RacingLine>()
  return {
    line(carWidthM, style) {
      const key = `${carWidthM}|${style.marginM}|${style.kerbs}`
      let line = lines.get(key)
      if (line === undefined) {
        let corridor = corridors.get(carWidthM)
        if (corridor === undefined) {
          corridor = measureCorridor(track, carWidthM)
          corridors.set(carWidthM, corridor)
        }
        line = relaxLine(corridor, style)
        lines.set(key, line)
      }
      return line
    },
  }
}

/**
 * Builds the drivers, indexed by `CarId`, with `null` for a car a human drives. Driver `id` draws from
 * `rng.fork('ai/' + id)`. Lines come from `lines`, so that whatever else the session builds on the same track
 * shares them. `pitStops` is how many pit stops each car of the session owes (F-306): with any, each driver is
 * given the lap to make its stop on, the laps drawn from `rng.fork('ai/pit-laps')`; with none, which is every
 * session but a final of a class that has the rule, nothing is drawn and no driver knows of pit stops. In a session
 * with reverse off (F-508: `config.reverse`) every driver is told its car has none.
 */
export function createAiDrivers(config: SessionConfig, track: TrackRuntime, setup: AiSetup, rng: Rng, lines: LineBook = createLineBook(track), pitStops = 0): Array<AiDriver | null> {
  const pit = pitPathOf(track)
  const made = config.entries.map((entry, id) => {
    if (entry.controller !== 'ai') return null
    const profile = setup.profile(entry.driverId)
    const car = setup.car(id)
    const line = lines.line(car.widthM, lineStyleFor(profile, config.difficulty))
    const driver: AiDriverConfig = { profile, difficulty: config.difficulty, car, ...(setup.kerbRollSpeedMS === undefined ? {} : { kerbRollSpeedMS: setup.kerbRollSpeedMS }), ...(setup.accidents === false ? { accidents: false } : {}), ...(config.reverse === false ? { reverse: false } : {}) }
    return { driver, line }
  })
  let plans: Array<PitPlan | null> = made.map(() => null)
  if (pit !== null && pitStops > 0) {
    // Each driver's own plan for a lap, and how far from the line it starts: a final starts from the grid.
    const cars = made.map((one, id) => {
      if (one === null) return null
      const place = config.track.grid[config.entries[id].startSlot]
      return { lapS: plannedLapS(one.driver, one.line), toLineM: track.lengthM - track.nearestRoute(place.x, place.y).s }
    })
    const laps = planPitLaps(cars, { durationS: config.durationS, lapLengthM: track.lengthM, entryRouteS: pit.entryRouteS }, rng.fork('ai/pit-laps'))
    plans = cars.map((car, id) => (car === null || laps[id] === null ? null : { lap: laps[id], lapS: car.lapS }))
  }
  return made.map((one, id) => (one === null ? null : createAiDriver(one.driver, one.line, rng.fork(`ai/${id}`), pit, plans[id])))
}

/**
 * What parks each car of a session once it has finished (F-303), indexed by `CarId`: every car has one, whoever
 * drives it. Each keeps clear of the line a careful driver at the limit of skill takes in that car.
 */
export function createPullOvers(config: SessionConfig, setup: AiSetup, lines: LineBook): PullOver[] {
  // The places the finished cars choose, one board for the session: each keeps off the places the others have taken.
  const board: ParkingBoard = config.entries.map(() => null)
  return config.entries.map((_, id) => {
    const car = setup.car(id)
    return createPullOver(id, car, lines.line(car.widthM, DEFAULT_LINE_STYLE), board)
  })
}
