import type { Vec2 } from '../core'
import type { TrackData, TrackRuntime } from '../track'
import { distanceToPolyline } from '../track/geometry'

// The kerbs as things with a start and an end (F-507). The ground under a car is read point by point
// (`TrackRuntime.surfaceAt`), which says that a point is on a kerb and not which kerb, nor where on it. The two ways
// a kerb rolls a car need more: whether the middle of a car's nose came onto a kerb over its start, and whether a
// car that hopped off a kerb came down on the same one. Both are asked only at the moment they matter, never tick
// by tick, and answered from the track's own kerb lines. Pure functions.

/** A car is driving along a kerb, into its start, when its heading is within this of the kerb's own direction there: nearer along it than across it. */
const ALONG_KERB_COS = Math.SQRT1_2
/** How finely the place where a point came onto a kerb is found, as halvings of the way it moved in the tick. Seven of them put it within a third of a millimetre at any speed a car reaches. */
const ENTRY_HALVINGS = 7
/** A point this near a kerb's end, m, short of it or past it, is at the end: what is left of the search above, and more. */
const AT_END_M = 0.001

/** The kerb a point is on: its place in `TrackData.kerbs`, the first if two overlap there; -1 on none. */
export function kerbUnder(track: TrackData, x: number, y: number): number {
  for (let k = 0; k < track.kerbs.length; k++) if (onKerbStrip(track, k, x, y)) return k
  return -1
}

/** Whether a point is on kerb `kerb` of the track: within half its width of its line. */
export function onKerbStrip(track: TrackData, kerb: number, x: number, y: number): boolean {
  const strip = track.kerbs[kerb]
  return strip !== undefined && strip.polyline.length >= 2 && distanceToPolyline(x, y, strip.polyline, strip.closed) <= strip.widthM / 2
}

/**
 * Whether a point that moved from `from`, off every kerb, to `to`, on one, came onto it over the start of a kerb while
 * heading along that kerb: the nose of a car run onto a kerb's start, and not over its side. A kerb's start is either
 * end of its line (a kerb that closes on itself has none): the rounded end of the strip, as wide as the kerb.
 * `headingRad` is the way the car points. The place the point came onto the kerb is found on the way between the two.
 */
export function ontoKerbStart(track: TrackRuntime, from: Readonly<Vec2>, to: Readonly<Vec2>, headingRad: number): boolean {
  // Where it came on: the last place off the kerb and the first on it, closed in on.
  let offX = from.x
  let offY = from.y
  let onX = to.x
  let onY = to.y
  if (track.surfaceAt(offX, offY) === 'kerb') {
    // It was reckoned to have been on the kerb already where it came from: that is where it came on.
    onX = offX
    onY = offY
  } else {
    for (let i = 0; i < ENTRY_HALVINGS; i++) {
      const midX = (offX + onX) / 2
      const midY = (offY + onY) / 2
      if (track.surfaceAt(midX, midY) === 'kerb') {
        onX = midX
        onY = midY
      } else {
        offX = midX
        offY = midY
      }
    }
  }
  const headX = Math.cos(headingRad)
  const headY = Math.sin(headingRad)
  for (const kerb of track.data.kerbs) {
    const points = kerb.polyline
    if (kerb.closed || points.length < 2) continue
    const half = kerb.widthM / 2
    for (const end of [0, points.length - 1]) {
      const [endX, endY] = points[end]
      // The way the kerb runs from this end: toward the first point of its line that is at least half its width on.
      const step = end === 0 ? 1 : -1
      let inX = 0
      let inY = 0
      let lengthM = 0
      for (let i = end + step; i >= 0 && i < points.length; i += step) {
        inX = points[i][0] - endX
        inY = points[i][1] - endY
        lengthM = Math.hypot(inX, inY)
        if (lengthM >= half) break
      }
      if (lengthM === 0) continue
      inX /= lengthM
      inY /= lengthM
      const dx = onX - endX
      const dy = onY - endY
      // On this kerb's rounded end: within half its width of the end of its line, and not past that end along the kerb.
      if (Math.hypot(dx, dy) > half + AT_END_M || dx * inX + dy * inY > AT_END_M) continue
      if (headX * inX + headY * inY >= ALONG_KERB_COS) return true
    }
  }
  return false
}
