import { TICK_RATE, type CarId, type Pose, type Tick, type Vec2 } from '../core'
import type { SurfaceKind } from '../track'
import type { SimEvent } from './events'
import type { StepContact } from './stepper'

// What the session makes of how the cars moved on a tick (F-302): which touches are worth telling the rest of the
// game about, which car has spun, and which has left the lane. Detection only: nothing here moves a car.
//
// The three numbers below are thresholds for telling, not handling numbers, so they are constants here and not in
// the tuning block.

/**
 * A car and one kind of thing (another car, the walls, the tyres) are reported touching no more often than once
 * in this long, however long they stay together: four times a second.
 */
export const CONTACT_EVENT_GAP_S = 0.25
/** A car has spun when it is travelling more than this far round from where its nose points. */
export const SPIN_ANGLE_RAD = (120 * Math.PI) / 180
/** Slower than this a car is not spinning whatever way it points, and its next spin has to start from fresh. */
export const SPIN_ABOVE_MS = 1

const CONTACT_GAP_TICKS = Math.round(CONTACT_EVENT_GAP_S * TICK_RATE)
/** The kinds of solid thing a car can touch that are not cars: the walls, the tyres, the marshals. */
const SOLID_KINDS = 3
/** Travelling further round than the spin angle is the same as this much of the speed pointing backwards. */
const SPIN_BACKWARD_SHARE = -Math.cos(SPIN_ANGLE_RAD)

/** What incident detection remembers between ticks. One per session; all of it is in the state hash. */
export interface IncidentState {
  readonly carCount: number
  /**
   * Per car and thing it can touch — every car, then the walls, then the tyres, then the marshals (F-502): the tick
   * that pairing was last reported on. Two cars share the slot of the lower id.
   */
  readonly reportedTick: number[]
  /** Beside each: the hardest single step's impulse of the touches left unreported since then, N·s. */
  readonly heldNs: number[]
  /** Per car: travelling nose first and fast enough that turning right round would be a spin. */
  readonly noseFirst: boolean[]
  /** Per car: on the grass, and already said so. */
  readonly offTrack: boolean[]
}

export function createIncidentState(carCount: number): IncidentState {
  const pairings = carCount * (carCount + SOLID_KINDS)
  return {
    carCount,
    reportedTick: Array.from({ length: pairings }, () => -Infinity),
    heldNs: Array.from({ length: pairings }, () => 0),
    noseFirst: Array.from({ length: carCount }, () => false),
    offTrack: Array.from({ length: carCount }, () => false),
  }
}

/**
 * Turns one step's touches into `contact` events, appended to `events`. A pairing is reported the moment it first
 * touches, with that step's impulse, and then not again until the gap has passed: a bounce, a scrape or a long
 * push is one event every gap, not one a tick. A touch that goes unreported is not lost if the two are still
 * together when the gap ends: the next event carries the hardest step of those held back, so a crash that follows
 * a brush is told a moment late and at its own strength. Held touches older than one more gap are forgotten.
 */
export function reportContacts(state: IncidentState, contacts: readonly StepContact[], tick: Tick, events: SimEvent[]): void {
  for (const contact of contacts) {
    const other = contact.b === 'wall' ? state.carCount : contact.b === 'marker' ? state.carCount + 1 : contact.b === 'marshal' ? state.carCount + 2 : contact.b
    const slot = contact.a * (state.carCount + SOLID_KINDS) + other
    const quietFor = tick - state.reportedTick[slot]
    if (quietFor < CONTACT_GAP_TICKS) {
      state.heldNs[slot] = Math.max(state.heldNs[slot], contact.impulseNs)
      continue
    }
    const held = quietFor < 2 * CONTACT_GAP_TICKS ? state.heldNs[slot] : 0
    events.push({ type: 'contact', tick, car: contact.a, other: contact.b, impulseNs: Math.max(contact.impulseNs, held) })
    state.reportedTick[slot] = tick
    state.heldNs[slot] = 0
  }
}

/**
 * True on the tick a car spins: it was travelling nose first faster than the spin speed and, without slowing below
 * that speed, has come to travel more than the spin angle round from where its nose points. Once per spin: the car
 * has to be travelling nose first again before it can spin again. A car that is backed up on purpose has stopped
 * first, so reversing is never a spin; nor is being shoved backwards from a standstill.
 */
export function hasSpun(state: IncidentState, car: CarId, pose: Readonly<Pose>, velocity: Readonly<Vec2>): boolean {
  const speed = Math.hypot(velocity.x, velocity.y)
  if (speed <= SPIN_ABOVE_MS) {
    state.noseFirst[car] = false
    return false
  }
  const forward = Math.cos(pose.angle) * velocity.x + Math.sin(pose.angle) * velocity.y
  if (!state.noseFirst[car]) {
    if (forward > 0) state.noseFirst[car] = true
    return false
  }
  if (-forward <= SPIN_BACKWARD_SHARE * speed) return false
  state.noseFirst[car] = false
  return true
}

/**
 * True on the tick a car is first found on the grass: `surface` is what the ground says is under its centre, which
 * the session already knows. False while it stays there, and for a car that comes back and leaves again it is true again.
 */
export function hasLeftTrack(state: IncidentState, car: CarId, surface: SurfaceKind): boolean {
  const off = surface === 'grass'
  const left = off && !state.offTrack[car]
  state.offTrack[car] = off
  return left
}

/** Appends everything incident detection remembers, in a fixed order. */
export function hashIncidents(state: IncidentState, buffer: number[]): void {
  for (let slot = 0; slot < state.reportedTick.length; slot++) buffer.push(state.reportedTick[slot], state.heldNs[slot])
  for (let car = 0; car < state.carCount; car++) buffer.push(state.noseFirst[car] ? 1 : 0, state.offTrack[car] ? 1 : 0)
}
