import type { Point } from './types'

// Plane geometry for track data. World metres, x right, y down; angles clockwise from +x.
// tools/track-import runs this same code when it builds a track file.

/** A path vertex: x and y, and whatever a caller keeps after them (a route point carries its half-width). */
export type Vertex = readonly [x: number, y: number, ...rest: number[]]

export function distance(a: Vertex, b: Vertex): number {
  return Math.hypot(b[0] - a[0], b[1] - a[1])
}

/** How many segments a path of `count` vertices has. */
function segmentCount(count: number, closed: boolean): number {
  if (count < 2) return 0
  return closed ? count : count - 1
}

/** Arc length at each vertex, starting at 0. A closed path gets one more entry: its full length. */
export function cumulativeLengths(points: readonly Vertex[], closed: boolean): number[] {
  const lengths = [0]
  const segments = segmentCount(points.length, closed)
  for (let i = 0; i < segments; i++) {
    lengths.push(lengths[i] + distance(points[i], points[(i + 1) % points.length]))
  }
  return lengths
}

export function polylineLength(points: readonly Vertex[], closed: boolean): number {
  const lengths = cumulativeLengths(points, closed)
  return lengths[lengths.length - 1]
}

/** Shoelace area. With y down it is positive for a ring that runs clockwise on screen. */
export function signedArea(ring: readonly Vertex[]): number {
  let twice = 0
  for (let i = 0; i < ring.length; i++) {
    const a = ring[i]
    const b = ring[(i + 1) % ring.length]
    twice += a[0] * b[1] - b[0] * a[1]
  }
  return twice / 2
}

export function isClockwise(ring: readonly Vertex[]): boolean {
  return signedArea(ring) > 0
}

/** Even-odd test. A point exactly on an edge may fall either way. */
export function pointInRing(x: number, y: number, ring: readonly Vertex[]): boolean {
  let inside = false
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const a = ring[i]
    const b = ring[j]
    if (a[1] > y !== b[1] > y && x < ((b[0] - a[0]) * (y - a[1])) / (b[1] - a[1]) + a[0]) inside = !inside
  }
  return inside
}

export function pointInPolygon(x: number, y: number, polygon: readonly Vertex[], holes: readonly (readonly Vertex[])[]): boolean {
  if (!pointInRing(x, y, polygon)) return false
  for (const hole of holes) if (pointInRing(x, y, hole)) return false
  return true
}

export function distanceToSegment(x: number, y: number, ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax
  const dy = by - ay
  const lengthSq = dx * dx + dy * dy
  const t = lengthSq === 0 ? 0 : Math.min(1, Math.max(0, ((x - ax) * dx + (y - ay) * dy) / lengthSq))
  return Math.hypot(x - (ax + t * dx), y - (ay + t * dy))
}

export interface PolylineHit {
  distance: number
  /** Index of the segment's first vertex. */
  segment: number
  /** 0..1 along that segment. */
  t: number
  x: number
  y: number
}

/** The nearest point of a path to (x, y). A single vertex counts as a path of one point. */
export function closestOnPolyline(x: number, y: number, points: readonly Vertex[], closed: boolean): PolylineHit {
  let best: PolylineHit = { distance: Infinity, segment: 0, t: 0, x: NaN, y: NaN }
  if (points.length === 1) {
    return { distance: Math.hypot(x - points[0][0], y - points[0][1]), segment: 0, t: 0, x: points[0][0], y: points[0][1] }
  }
  const segments = segmentCount(points.length, closed)
  for (let i = 0; i < segments; i++) {
    const a = points[i]
    const b = points[(i + 1) % points.length]
    const dx = b[0] - a[0]
    const dy = b[1] - a[1]
    const lengthSq = dx * dx + dy * dy
    const t = lengthSq === 0 ? 0 : Math.min(1, Math.max(0, ((x - a[0]) * dx + (y - a[1]) * dy) / lengthSq))
    const px = a[0] + t * dx
    const py = a[1] + t * dy
    const d = Math.hypot(x - px, y - py)
    if (d < best.distance) best = { distance: d, segment: i, t, x: px, y: py }
  }
  return best
}

export function distanceToPolyline(x: number, y: number, points: readonly Vertex[], closed: boolean): number {
  return closestOnPolyline(x, y, points, closed).distance
}

function cross(ax: number, ay: number, bx: number, by: number): number {
  return ax * by - ay * bx
}

/**
 * Where segments a–b and c–d meet, counting a touch at an end as meeting. Collinear segments that overlap return
 * a point of the overlap. Null when they stay apart.
 */
export function segmentIntersection(a: Vertex, b: Vertex, c: Vertex, d: Vertex): Point | null {
  const rx = b[0] - a[0]
  const ry = b[1] - a[1]
  const sx = d[0] - c[0]
  const sy = d[1] - c[1]
  const qpx = c[0] - a[0]
  const qpy = c[1] - a[1]
  const denominator = cross(rx, ry, sx, sy)
  const scale = Math.hypot(rx, ry) * Math.hypot(sx, sy)
  if (Math.abs(denominator) <= 1e-12 * scale) {
    const lengthSq = rx * rx + ry * ry
    if (lengthSq === 0) {
      return distanceToSegment(a[0], a[1], c[0], c[1], d[0], d[1]) <= 1e-12 ? [a[0], a[1]] : null
    }
    if (Math.abs(cross(qpx, qpy, rx, ry)) > 1e-12 * Math.max(scale, lengthSq)) return null
    const t0 = (qpx * rx + qpy * ry) / lengthSq
    const t1 = t0 + (sx * rx + sy * ry) / lengthSq
    const from = Math.max(0, Math.min(t0, t1))
    const to = Math.min(1, Math.max(t0, t1))
    if (from > to) return null
    return [a[0] + rx * from, a[1] + ry * from]
  }
  const t = cross(qpx, qpy, sx, sy) / denominator
  const u = cross(qpx, qpy, rx, ry) / denominator
  if (t < 0 || t > 1 || u < 0 || u > 1) return null
  return [a[0] + rx * t, a[1] + ry * t]
}

/** The first place a path crosses or touches itself, other than where neighbouring segments join. */
export function selfIntersection(points: readonly Vertex[], closed: boolean): Point | null {
  const count = points.length
  const segments = segmentCount(count, closed)
  for (let i = 0; i < segments; i++) {
    const a = points[i]
    const b = points[(i + 1) % count]
    const minX = Math.min(a[0], b[0])
    const maxX = Math.max(a[0], b[0])
    const minY = Math.min(a[1], b[1])
    const maxY = Math.max(a[1], b[1])
    for (let j = i + 2; j < segments; j++) {
      if (closed && i === 0 && j === segments - 1) continue
      const c = points[j]
      const d = points[(j + 1) % count]
      if (Math.max(c[0], d[0]) < minX || Math.min(c[0], d[0]) > maxX) continue
      if (Math.max(c[1], d[1]) < minY || Math.min(c[1], d[1]) > maxY) continue
      const hit = segmentIntersection(a, b, c, d)
      if (hit) return hit
    }
  }
  return null
}

/** The first place two different paths cross or touch. */
export function pathIntersection(
  first: readonly Vertex[],
  firstClosed: boolean,
  second: readonly Vertex[],
  secondClosed: boolean,
): Point | null {
  const firstSegments = segmentCount(first.length, firstClosed)
  const secondSegments = segmentCount(second.length, secondClosed)
  for (let i = 0; i < firstSegments; i++) {
    const a = first[i]
    const b = first[(i + 1) % first.length]
    const minX = Math.min(a[0], b[0])
    const maxX = Math.max(a[0], b[0])
    const minY = Math.min(a[1], b[1])
    const maxY = Math.max(a[1], b[1])
    for (let j = 0; j < secondSegments; j++) {
      const c = second[j]
      const d = second[(j + 1) % second.length]
      if (Math.max(c[0], d[0]) < minX || Math.min(c[0], d[0]) > maxX) continue
      if (Math.max(c[1], d[1]) < minY || Math.min(c[1], d[1]) > maxY) continue
      const hit = segmentIntersection(a, b, c, d)
      if (hit) return hit
    }
  }
  return null
}

/** Unsigned change of direction at each vertex, in radians. The two ends of an open path, and repeated vertices, report 0. */
export function turnAngles(points: readonly Vertex[], closed: boolean): number[] {
  const count = points.length
  return points.map((vertex, i) => {
    if (count < 3 || (!closed && (i === 0 || i === count - 1))) return 0
    const before = points[(i - 1 + count) % count]
    const after = points[(i + 1) % count]
    const ux = vertex[0] - before[0]
    const uy = vertex[1] - before[1]
    const wx = after[0] - vertex[0]
    const wy = after[1] - vertex[1]
    if ((ux === 0 && uy === 0) || (wx === 0 && wy === 0)) return 0
    return Math.abs(Math.atan2(cross(ux, uy, wx, wy), ux * wx + uy * wy))
  })
}

/** Corners of a car-sized rectangle centred on a pose, in order round the rectangle. */
export function rectangleCorners(x: number, y: number, angle: number, length: number, width: number): Point[] {
  const cos = Math.cos(angle)
  const sin = Math.sin(angle)
  const halfLength = length / 2
  const halfWidth = width / 2
  const corner = (along: number, across: number): Point => [x + along * cos - across * sin, y + along * sin + across * cos]
  return [corner(halfLength, -halfWidth), corner(halfLength, halfWidth), corner(-halfLength, halfWidth), corner(-halfLength, -halfWidth)]
}

/** Whether two convex polygons share any area (separating-axis test). Touching edges do not count. */
export function convexPolygonsOverlap(first: readonly Vertex[], second: readonly Vertex[]): boolean {
  for (const polygon of [first, second]) {
    for (let i = 0; i < polygon.length; i++) {
      const a = polygon[i]
      const b = polygon[(i + 1) % polygon.length]
      const nx = b[1] - a[1]
      const ny = a[0] - b[0]
      let firstMin = Infinity
      let firstMax = -Infinity
      let secondMin = Infinity
      let secondMax = -Infinity
      for (const p of first) {
        const projection = p[0] * nx + p[1] * ny
        firstMin = Math.min(firstMin, projection)
        firstMax = Math.max(firstMax, projection)
      }
      for (const p of second) {
        const projection = p[0] * nx + p[1] * ny
        secondMin = Math.min(secondMin, projection)
        secondMax = Math.max(secondMax, projection)
      }
      if (firstMax <= secondMin || secondMax <= firstMin) return false
    }
  }
  return true
}
