import { createRng, type DriverId } from '../core'
import type { DriverProfile } from '../ai'
import type { Difficulty } from '../session'

// Who is entered (F-305 wrote these for the quick race; F-401 moved them here unchanged, so that a race day and a
// quick race choose their opponents with one function and the same seed gives both the same field).

/** The human's driver id (contracts.md §1). Every other entry of an event is a roster driver. */
export const PLAYER_DRIVER_ID: DriverId = 'player'

/**
 * The opponents are drawn from the roster by skill, weakest first: Club from the lower two thirds, Regional from the
 * middle two thirds (the weakest and strongest sixth sit out), National the strongest there are, no draw at all.
 */
const POOL_SHARE = 2 / 3

/** Roster sorted by skill, weakest first; equal skill falls back to the id so the order never depends on the roster's. */
function bySkill(roster: readonly DriverProfile[]): DriverProfile[] {
  return [...roster].sort((a, b) => a.skill - b.skill || a.id.localeCompare(b.id))
}

/** The part of the roster (weakest first) the difficulty draws from. */
export function opponentPool(difficulty: Difficulty, roster: readonly DriverProfile[], count: number): DriverProfile[] {
  const sorted = bySkill(roster)
  if (sorted.length < count) throw new Error(`chooseOpponents: ${count} opponents asked for but the roster has ${sorted.length} drivers`)
  if (difficulty === 'national') return sorted.slice(sorted.length - count)
  const size = Math.max(count, Math.ceil(sorted.length * POOL_SHARE))
  const start = difficulty === 'club' ? 0 : Math.floor((sorted.length - size) / 2)
  return sorted.slice(start, start + size)
}

/** The numbers 0..count-1 in an order drawn from `seed` (a Fisher-Yates shuffle with the sim's seeded generator). */
export function seededPermutation(count: number, seed: number, label: string): number[] {
  const rng = createRng(seed).fork(label)
  const order = Array.from({ length: count }, (_, i) => i)
  for (let i = count - 1; i > 0; i--) {
    const j = rng.int(0, i)
    const held = order[i] ?? i
    order[i] = order[j] ?? j
    order[j] = held
  }
  return order
}

/**
 * `count` opponents for the difficulty, strongest first. National takes the strongest; the others are a seeded draw
 * from their pool. The draw's label is the quick race's, where the function was written: changing it would change
 * every field the owner has raced.
 */
export function chooseOpponents(difficulty: Difficulty, count: number, roster: readonly DriverProfile[], seed: number): DriverProfile[] {
  const pool = opponentPool(difficulty, roster, count)
  let drawn = pool
  if (difficulty !== 'national') {
    const shuffled = seededPermutation(pool.length, seed, 'quick-race-opponents').flatMap((i) => pool[i] ?? [])
    drawn = shuffled.slice(0, count)
  }
  return bySkill(drawn).reverse()
}
