import { buildPitRoute, buildRoute } from './route'
import { asphaltBoundary } from './surface'
import type { GrassLook, Point, SurfaceKind, TrackData, TrackRuntime } from './types'

// The questions the rest of the simulation asks of a track, answered from tables built once (F-104).

/** Side of a cell of the surface cache and of the distance field. */
const CELL_M = 0.05

export function buildTrackRuntime(data: TrackData): TrackRuntime {
  const route = buildRoute(data)
  const pitRoute = data.pitLane ? buildPitRoute(data.pitLane.route) : null
  const { surfaceAt, grassLookAt } = buildSurfaceLookup(data)
  const distanceOffLane = buildDistanceField(data, surfaceAt)

  return {
    data,
    lengthM: route.length,
    surfaceAt,
    distanceOffLane,
    nearestRoute: route.nearest,
    routePose: route.pose,
    curvatureAt: route.curvature,
    wallSegments: () => data.walls.map((wall) => ({ polyline: wall.polyline.map((p): Point => [p[0], p[1]]), closed: wall.closed })),
    grassLookAt,
    pitLengthM: pitRoute ? pitRoute.length : 0,
    pitRoutePose: (s) => (pitRoute ? pitRoute.pose(s) : null),
    nearestPitRoute: (x, y) => (pitRoute ? pitRoute.nearest(x, y) : null),
    inPitLane: (x, y) => {
      if (!pitRoute) return false
      const pit = pitRoute.nearest(x, y)
      if (Math.abs(pit.lateralM) > pit.halfWidthM) return false
      // Where the pit route leaves the lap and where it rejoins, the two lanes are one: that is still the lap.
      const lap = route.nearest(x, y)
      return Math.abs(lap.lateralM) > lap.halfWidthM
    },
  }
}

// ── Cells and segments ───────────────────────────────────────────────────────────────────────────────────────

interface Segments {
  count: number
  ax: Float64Array
  ay: Float64Array
  bx: Float64Array
  by: Float64Array
  /** What the segment belongs to: a surface index, or a kerb index. */
  owner: Uint16Array
}

function collectSegments(paths: ReadonlyArray<{ points: readonly Point[]; closed: boolean; owner: number }>): Segments {
  let count = 0
  for (const path of paths) count += path.points.length < 2 ? 0 : path.closed ? path.points.length : path.points.length - 1
  const segments: Segments = {
    count,
    ax: new Float64Array(count),
    ay: new Float64Array(count),
    bx: new Float64Array(count),
    by: new Float64Array(count),
    owner: new Uint16Array(count),
  }
  let at = 0
  for (const path of paths) {
    const size = path.points.length
    const sides = size < 2 ? 0 : path.closed ? size : size - 1
    for (let i = 0; i < sides; i++) {
      const a = path.points[i]
      const b = path.points[(i + 1) % size]
      segments.ax[at] = a[0]
      segments.ay[at] = a[1]
      segments.bx[at] = b[0]
      segments.by[at] = b[1]
      segments.owner[at] = path.owner
      at++
    }
  }
  return segments
}

function gapSq(x: number, y: number, ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax
  const dy = by - ay
  const lengthSq = dx * dx + dy * dy
  const t = lengthSq === 0 ? 0 : Math.min(1, Math.max(0, ((x - ax) * dx + (y - ay) * dy) / lengthSq))
  const px = x - (ax + dx * t)
  const py = y - (ay + dy * t)
  return px * px + py * py
}

interface CellLists {
  /** Entries for cell c are items[start[c]] … items[start[c + 1] - 1]. */
  start: Uint32Array
  items: Uint32Array
}

/** For every cell, the segments that pass within `reach(segment)` of the cell's centre. */
function segmentsByCell(segments: Segments, columns: number, rows: number, reach: (segment: number) => number): CellLists {
  const cells: number[] = []
  const members: number[] = []
  for (let s = 0; s < segments.count; s++) {
    const r = reach(s)
    const ax = segments.ax[s]
    const ay = segments.ay[s]
    const bx = segments.bx[s]
    const by = segments.by[s]
    const firstColumn = Math.max(0, Math.floor((Math.min(ax, bx) - r) / CELL_M))
    const lastColumn = Math.min(columns - 1, Math.floor((Math.max(ax, bx) + r) / CELL_M))
    const firstRow = Math.max(0, Math.floor((Math.min(ay, by) - r) / CELL_M))
    const lastRow = Math.min(rows - 1, Math.floor((Math.max(ay, by) + r) / CELL_M))
    for (let row = firstRow; row <= lastRow; row++) {
      for (let column = firstColumn; column <= lastColumn; column++) {
        if (gapSq((column + 0.5) * CELL_M, (row + 0.5) * CELL_M, ax, ay, bx, by) > r * r) continue
        cells.push(row * columns + column)
        members.push(s)
      }
    }
  }
  const start = new Uint32Array(columns * rows + 1)
  for (const cell of cells) start[cell + 1]++
  for (let c = 0; c < columns * rows; c++) start[c + 1] += start[c]
  const items = new Uint32Array(cells.length)
  const filled = new Uint32Array(columns * rows)
  cells.forEach((cell, index) => {
    items[start[cell] + filled[cell]++] = members[index]
  })
  return { start, items }
}

// ── Surfaces ─────────────────────────────────────────────────────────────────────────────────────────────────

const HALF_DIAGONAL_M = (CELL_M * Math.SQRT2) / 2
/**
 * Where in each cell the cached answer is taken. Off-centre by irrational amounts so that no track edge, whose
 * coordinates are decimals, runs exactly through one.
 */
const ANCHOR_X = Math.SQRT2 - 1
const ANCHOR_Y = Math.sqrt(3) - 1
/** A cell an edge passes through: its answer is worked out per point. */
const MIXED = -2
/** No surface covers the point. */
const UNCOVERED = -1

/**
 * The surface under a point: kerbs first, then surfaces from the last listed to the first. Its kind is one
 * answer; which grass it is, where it is grass, is the other.
 *
 * A uniform grid caches the topmost surface. A cell that no surface edge comes near holds it outright. A cell that
 * an edge passes through holds, for one anchor point inside it, which surfaces contain that point, and the few
 * edges near the cell; a query then counts which of those edges lie between it and the anchor, which gives the
 * exact answer without visiting the rest of the polygon. Kerbs are tested against the kerb segments near the cell.
 */
function buildSurfaceLookup(data: TrackData): Pick<TrackRuntime, 'surfaceAt' | 'grassLookAt'> {
  const { w, h } = data.bounds
  const columns = Math.max(1, Math.ceil(w / CELL_M))
  const rows = Math.max(1, Math.ceil(h / CELL_M))
  const surfaces = data.surfaces
  if (surfaces.length > 30) throw new Error(`a track may have at most 30 surfaces; this one has ${surfaces.length}`)

  // Which surfaces contain each cell's anchor, one bit per surface, by scanline fill.
  const inside = new Uint32Array(columns * rows)
  const crossings: number[] = []
  surfaces.forEach((surface, index) => {
    const rings = [surface.polygon, ...surface.holes]
    for (let row = 0; row < rows; row++) {
      const y = (row + ANCHOR_Y) * CELL_M
      crossings.length = 0
      for (const ring of rings) {
        for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
          const a = ring[i]
          const b = ring[j]
          if (a[1] > y !== b[1] > y) crossings.push(((b[0] - a[0]) * (y - a[1])) / (b[1] - a[1]) + a[0])
        }
      }
      crossings.sort((p, q) => p - q)
      for (let k = 0; k + 1 < crossings.length; k += 2) {
        const from = Math.max(0, Math.ceil(crossings[k] / CELL_M - ANCHOR_X))
        const to = Math.min(columns - 1, Math.ceil(crossings[k + 1] / CELL_M - ANCHOR_X) - 1)
        for (let column = from; column <= to; column++) inside[row * columns + column] |= 1 << index
      }
    }
  })

  const edges = collectSegments(surfaces.flatMap((surface, owner) => [surface.polygon, ...surface.holes].map((points) => ({ points, closed: true, owner }))))
  const edgesNear = segmentsByCell(edges, columns, rows, () => HALF_DIAGONAL_M)
  const kerbs = collectSegments(data.kerbs.map((kerb, owner) => ({ points: kerb.polyline, closed: kerb.closed, owner })))
  const kerbHalfSq = Float64Array.from(data.kerbs, (kerb) => (kerb.widthM / 2) ** 2)
  const kerbsNear = segmentsByCell(kerbs, columns, rows, (segment) => data.kerbs[kerbs.owner[segment]].widthM / 2 + HALF_DIAGONAL_M)

  const topOf = (bits: number): number => {
    for (let index = surfaces.length - 1; index >= 0; index--) if (bits & (1 << index)) return index
    return UNCOVERED
  }
  const cached = new Int8Array(columns * rows)
  for (let cell = 0; cell < columns * rows; cell++) {
    cached[cell] = edgesNear.start[cell + 1] > edgesNear.start[cell] ? MIXED : topOf(inside[cell])
  }
  const kinds: SurfaceKind[] = surfaces.map((surface) => surface.kind)
  // A grass surface that does not say which grass it is, is the slab's own: the infield.
  const looks: Array<GrassLook | null> = surfaces.map((surface) => (surface.kind === 'grass' ? (surface.look ?? 'infield') : null))

  const onKerb = (x: number, y: number, cell: number): boolean => {
    for (let k = kerbsNear.start[cell]; k < kerbsNear.start[cell + 1]; k++) {
      const s = kerbsNear.items[k]
      if (gapSq(x, y, kerbs.ax[s], kerbs.ay[s], kerbs.bx[s], kerbs.by[s]) <= kerbHalfSq[kerbs.owner[s]]) return true
    }
    return false
  }
  /** Index of the topmost surface containing a point inside the bounds, or UNCOVERED. */
  const topAt = (x: number, y: number, column: number, row: number, cell: number): number => {
    const top = cached[cell]
    if (top !== MIXED) return top

    // Walk from the cell's anchor to the point; each edge crossed on the way flips "inside" for its surface.
    const anchorX = (column + ANCHOR_X) * CELL_M
    const anchorY = (row + ANCHOR_Y) * CELL_M
    const walkX = x - anchorX
    const walkY = y - anchorY
    let bits = inside[cell]
    for (let k = edgesNear.start[cell]; k < edgesNear.start[cell + 1]; k++) {
      const e = edgesNear.items[k]
      const ax = edges.ax[e]
      const ay = edges.ay[e]
      const edgeX = edges.bx[e] - ax
      const edgeY = edges.by[e] - ay
      const startSide = walkX * (ay - anchorY) - walkY * (ax - anchorX) > 0
      const endSide = walkX * (edges.by[e] - anchorY) - walkY * (edges.bx[e] - anchorX) > 0
      if (startSide === endSide) continue
      const anchorSide = edgeX * (anchorY - ay) - edgeY * (anchorX - ax) > 0
      const pointSide = edgeX * (y - ay) - edgeY * (x - ax) > 0
      if (anchorSide !== pointSide) bits ^= 1 << edges.owner[e]
    }
    return topOf(bits)
  }

  return {
    surfaceAt: (x, y) => {
      if (!(x >= 0 && x < w && y >= 0 && y < h)) return 'grass'
      const column = Math.min(columns - 1, Math.floor(x / CELL_M))
      const row = Math.min(rows - 1, Math.floor(y / CELL_M))
      const cell = row * columns + column
      if (onKerb(x, y, cell)) return 'kerb'
      const top = topAt(x, y, column, row, cell)
      return top === UNCOVERED ? 'grass' : kinds[top]
    },
    grassLookAt: (x, y) => {
      if (!(x >= 0 && x < w && y >= 0 && y < h)) return 'outfield'
      const column = Math.min(columns - 1, Math.floor(x / CELL_M))
      const row = Math.min(rows - 1, Math.floor(y / CELL_M))
      const cell = row * columns + column
      if (onKerb(x, y, cell)) return null
      const top = topAt(x, y, column, row, cell)
      return top === UNCOVERED ? 'outfield' : looks[top]
    },
  }
}

// ── Distance off the lane ────────────────────────────────────────────────────────────────────────────────────

/**
 * Distance from a point to the lane (asphalt or kerb), from a field of exact distances held at the corners of
 * the same grid and blended between them.
 *
 * The field is built by spreading: corners next to an edge of the asphalt or to a kerb measure their distance to
 * it, and every other corner tries the edges its neighbours found nearest and keeps the best. Each corner's value
 * is a true distance to a real edge, not a count of cells.
 */
function buildDistanceField(data: TrackData, surfaceAt: TrackRuntime['surfaceAt']): TrackRuntime['distanceOffLane'] {
  const { w, h } = data.bounds
  const columns = Math.max(1, Math.ceil(w / CELL_M))
  const rows = Math.max(1, Math.ceil(h / CELL_M))
  const across = columns + 1
  const down = rows + 1

  // What the lane's limits are made of: the edges that have asphalt on exactly one side, and the kerbs, whose
  // band reaches half their width beyond their polyline.
  const limits: Array<{ points: readonly Point[]; closed: boolean; owner: number }> = asphaltBoundary(data).map((points) => ({ points, closed: false, owner: 0 }))
  const reaches: number[] = [0]
  data.kerbs.forEach((kerb) => {
    limits.push({ points: kerb.polyline, closed: kerb.closed, owner: reaches.length })
    reaches.push(kerb.widthM / 2)
  })
  const segments = collectSegments(limits)

  const field = new Float64Array(across * down).fill(Infinity)
  const nearest = new Int32Array(across * down).fill(-1)
  const measure = (node: number, segment: number): void => {
    const x = (node % across) * CELL_M
    const y = Math.floor(node / across) * CELL_M
    const gap = Math.sqrt(gapSq(x, y, segments.ax[segment], segments.ay[segment], segments.bx[segment], segments.by[segment])) - reaches[segments.owner[segment]]
    if (gap < field[node]) {
      field[node] = gap
      nearest[node] = segment
    }
  }

  for (let s = 0; s < segments.count; s++) {
    const margin = reaches[segments.owner[s]] + 2 * CELL_M
    const firstColumn = Math.max(0, Math.floor((Math.min(segments.ax[s], segments.bx[s]) - margin) / CELL_M))
    const lastColumn = Math.min(across - 1, Math.ceil((Math.max(segments.ax[s], segments.bx[s]) + margin) / CELL_M))
    const firstRow = Math.max(0, Math.floor((Math.min(segments.ay[s], segments.by[s]) - margin) / CELL_M))
    const lastRow = Math.min(down - 1, Math.ceil((Math.max(segments.ay[s], segments.by[s]) + margin) / CELL_M))
    for (let row = firstRow; row <= lastRow; row++) {
      for (let column = firstColumn; column <= lastColumn; column++) measure(row * across + column, s)
    }
  }

  const adopt = (node: number, column: number, row: number, stepColumn: number, stepRow: number): void => {
    const otherColumn = column + stepColumn
    const otherRow = row + stepRow
    if (otherColumn < 0 || otherColumn >= across || otherRow < 0 || otherRow >= down) return
    const candidate = nearest[otherRow * across + otherColumn]
    if (candidate >= 0 && candidate !== nearest[node]) measure(node, candidate)
  }
  for (let round = 0; round < 2; round++) {
    for (let row = 0; row < down; row++) {
      for (let column = 0; column < across; column++) {
        const node = row * across + column
        adopt(node, column, row, -1, 0)
        adopt(node, column, row, -1, -1)
        adopt(node, column, row, 0, -1)
        adopt(node, column, row, 1, -1)
      }
    }
    for (let row = down - 1; row >= 0; row--) {
      for (let column = across - 1; column >= 0; column--) {
        const node = row * across + column
        adopt(node, column, row, 1, 0)
        adopt(node, column, row, 1, 1)
        adopt(node, column, row, 0, 1)
        adopt(node, column, row, -1, 1)
      }
    }
  }

  // On the lane the distance is zero.
  for (let row = 0; row < down; row++) {
    for (let column = 0; column < across; column++) {
      const node = row * across + column
      if (field[node] <= 0 || surfaceAt(column * CELL_M, row * CELL_M) !== 'grass') field[node] = 0
    }
  }

  const maxX = columns * CELL_M
  const maxY = rows * CELL_M
  return (x, y) => {
    const insideX = Math.min(maxX, Math.max(0, x))
    const insideY = Math.min(maxY, Math.max(0, y))
    // Outside the grid: the distance at the nearest point of it, plus the way there.
    const beyond = insideX === x && insideY === y ? 0 : Math.hypot(x - insideX, y - insideY)
    const column = Math.min(columns - 1, Math.floor(insideX / CELL_M))
    const row = Math.min(rows - 1, Math.floor(insideY / CELL_M))
    const node = row * across + column
    const d00 = field[node]
    const d10 = field[node + 1]
    const d01 = field[node + across]
    const d11 = field[node + across + 1]
    if (beyond === 0 && ((d00 === 0 && d10 === 0 && d01 === 0 && d11 === 0) || surfaceAt(x, y) !== 'grass')) return 0
    const fx = insideX / CELL_M - column
    const fy = insideY / CELL_M - row
    return (d00 * (1 - fx) + d10 * fx) * (1 - fy) + (d01 * (1 - fx) + d11 * fx) * fy + beyond
  }
}
