import { angleDiff, wrapAngle } from '../core'
import type { TrackRuntime } from '../track'
import { AI_TUNING } from './tuning'

// The racing line (F-301): the smoothest closed path the lane has room for, found once per session and per style of
// driving. It starts as the route's centreline and is relaxed toward least curvature inside a corridor: the lane's
// own half-width, less half a car and a safety margin, kept off the kerbs (or let onto the inside one), and clear of
// walls and of the tyres on the islands. It never leaves the lap's lane, so it never enters the pit lane.

export interface LinePoint {
  /** Distance along the line, m. */
  s: number
  x: number
  y: number
  /** Direction of travel, rad. */
  headingRad: number
  /** 1/m, signed, positive = turning right. */
  curvature: number
  /** Half the width of the band the car's centre may use here: the mean of the room to either side. */
  halfRoomM: number
  /** How far the car's centre may move to the left and to the right of the line here, m. */
  roomLeftM: number
  roomRightM: number
  /** The distance along the track's route abeam of this point, m. */
  routeS: number
  /** Whether a car on the line here has a wheel on a kerb. */
  onKerb: boolean
}

export interface RacingLine {
  lengthM: number
  /** Spacing of `points` along the line, m: point i is at `i × stepM`. */
  stepM: number
  points: LinePoint[]
  /** The line at a distance along it; `s` wraps round the lap. A fresh object on each call. */
  at(s: number): LinePoint
  /** Index into `points` of the last point at or before `s`, wrapped round the lap. */
  indexAt(s: number): number
  /**
   * The point of the line nearest to a place: how far along the line it is, and how far to the right of the line the
   * place lies (negative to the left). With a hint only the stretch near it is searched.
   */
  nearest(x: number, y: number, hintS?: number): { s: number; lateralM: number }
  /** The distance along the line abeam of a distance along the track's route. */
  sAtRoute(routeS: number): number
  /**
   * For each point of `points`: how far to the left, and to the right, a car's centre can be moved off the line there
   * before one of its wheels is on a kerb, m. Nothing where the line itself has a wheel on one (`onKerb`), and
   * `Infinity` where there is no kerb within `AI_TUNING.line.kerbReachM` on that side. What a driver reads to know
   * a kerb is coming when it is not on its line (F-501).
   */
  kerbLeftM: Float64Array
  kerbRightM: Float64Array
}

/** How a driver wants the line drawn. */
export interface LineStyle {
  /** Clear asphalt kept between the side of the car and the limit of the lane, m. */
  marginM: number
  /** Whether the line may put the inside wheels on the kerb of a corner. */
  kerbs: boolean
}

/** What the lane allows, measured once per track and car width: every style of line is relaxed inside it. */
export interface Corridor {
  readonly track: TrackRuntime
  readonly carWidthM: number
  /** Spacing of the samples below along the route, m. */
  readonly stepM: number
  /** The route's centreline at each sample, and the unit vector to the right of the direction of travel there. */
  readonly x: Float64Array
  readonly y: Float64Array
  readonly rightX: Float64Array
  readonly rightY: Float64Array
  /** At each route sample, the width of plain asphalt to the left and to the right of the centreline, within the route's half-width. */
  readonly asphaltLeftM: Float64Array
  readonly asphaltRightM: Float64Array
  /** Whether that asphalt ends at a kerb on the inside of a corner. */
  readonly kerbLeft: Uint8Array
  readonly kerbRight: Uint8Array
}

const T = AI_TUNING.line

/** Measures the lane along the route: where the plain asphalt ends on each side, and where a kerb lines the inside of a bend. */
export function measureCorridor(track: TrackRuntime, carWidthM: number): Corridor {
  const count = Math.max(8, Math.round(track.lengthM / T.corridorStepM))
  const stepM = track.lengthM / count
  const x = new Float64Array(count)
  const y = new Float64Array(count)
  const rightXs = new Float64Array(count)
  const rightYs = new Float64Array(count)
  const asphaltLeftM = new Float64Array(count)
  const asphaltRightM = new Float64Array(count)
  const kerbLeft = new Uint8Array(count)
  const kerbRight = new Uint8Array(count)
  const bend = Math.round(T.insideWindowM / stepM)

  for (let j = 0; j < count; j++) {
    const s = j * stepM
    const pose = track.routePose(s)
    const halfWidthM = track.nearestRoute(pose.x, pose.y, s).halfWidthM
    // Which way the road bends here, judged over a stretch of it: a kerb counts only on the inside.
    let turn = 0
    for (let k = -bend; k <= bend; k++) turn += track.curvatureAt(s + k * stepM)
    turn /= 2 * bend + 1
    const rightX = -Math.sin(pose.angle)
    const rightY = Math.cos(pose.angle)
    x[j] = pose.x
    y[j] = pose.y
    rightXs[j] = rightX
    rightYs[j] = rightY
    for (const side of [-1, 1]) {
      let asphalt = halfWidthM
      let kerb = false
      for (let d = T.probeStepM; d <= halfWidthM + T.kerbSearchM; d += T.probeStepM) {
        const surface = track.surfaceAt(pose.x + side * rightX * d, pose.y + side * rightY * d)
        if (surface === 'asphalt') continue
        asphalt = Math.min(asphalt, d - T.probeStepM)
        kerb = surface === 'kerb'
        break
      }
      const inside = side * turn > T.insideCurvature
      if (side < 0) {
        asphaltLeftM[j] = asphalt
        kerbLeft[j] = kerb && inside ? 1 : 0
      } else {
        asphaltRightM[j] = asphalt
        kerbRight[j] = kerb && inside ? 1 : 0
      }
    }
  }
  return { track, carWidthM, stepM, x, y, rightX: rightXs, rightY: rightYs, asphaltLeftM, asphaltRightM, kerbLeft, kerbRight }
}

/** The racing line of a track for a car of a given width: `measureCorridor`, then `relaxLine`. */
export function buildRacingLine(track: TrackRuntime, carWidthM: number, style: LineStyle = DEFAULT_LINE_STYLE): RacingLine {
  return relaxLine(measureCorridor(track, carWidthM), style)
}

/** The line a careful driver at the limit of skill takes: the base margin, off every kerb. */
export const DEFAULT_LINE_STYLE: LineStyle = Object.freeze({ marginM: T.marginM, kerbs: false })

function gapSq(x: number, y: number, ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax
  const dy = by - ay
  const lengthSq = dx * dx + dy * dy
  const t = lengthSq === 0 ? 0 : Math.min(1, Math.max(0, ((x - ax) * dx + (y - ay) * dy) / lengthSq))
  const px = x - (ax + dx * t)
  const py = y - (ay + dy * t)
  return px * px + py * py
}

/**
 * How far the car's centre may be from the route's centreline at each route sample on one side (`side` is -1 for
 * the left, 1 for the right), for one style: the plain asphalt less half a car and the margin; or, where the style
 * takes kerbs and one lines the inside of the bend, far enough out for the inside wheels to be on it; and in either
 * case no nearer a wall or a tyre than half a car, the margin and a little more. Smoothed along the route so that it never steps,
 * and never above what it was before smoothing.
 */
function centreLimits(corridor: Corridor, side: -1 | 1, style: LineStyle): Float64Array {
  const asphaltM = side < 0 ? corridor.asphaltLeftM : corridor.asphaltRightM
  const kerb = side < 0 ? corridor.kerbLeft : corridor.kerbRight
  const count = asphaltM.length
  const clearM = corridor.carWidthM / 2 + style.marginM
  // Further from anything solid than from the edge of the asphalt: a car that strays over an edge loses a little
  // grip, one that strays into a wall stops; and it is the corners of a car that reach a wall first.
  const solidClearM = clearM + T.solidExtraM
  const walls = corridor.track.wallSegments()
  const markers = corridor.track.data.markers
  const clearOfSolids = (x: number, y: number): boolean => {
    for (const marker of markers) {
      const reach = marker.r + solidClearM
      const dx = x - marker.x
      const dy = y - marker.y
      if (dx * dx + dy * dy < reach * reach) return false
    }
    for (const wall of walls) {
      const points = wall.polyline
      const sides = wall.closed ? points.length : points.length - 1
      for (let i = 0; i < sides; i++) {
        const a = points[i]
        const b = points[(i + 1) % points.length]
        if (gapSq(x, y, a[0], a[1], b[0], b[1]) < solidClearM * solidClearM) return false
      }
    }
    return true
  }

  const raw = new Float64Array(count)
  for (let j = 0; j < count; j++) {
    const clean = asphaltM[j] - clearM
    // Onto the kerb: far enough to put the inside wheels on it, whatever margin the driver keeps elsewhere.
    const kerbed = asphaltM[j] - T.kerbInsetM
    let limit = Math.max(0, style.kerbs && kerb[j] === 1 ? Math.max(clean, kerbed) : clean)
    while (limit > 0 && !clearOfSolids(corridor.x[j] + side * corridor.rightX[j] * limit, corridor.y[j] + side * corridor.rightY[j] * limit)) {
      limit = Math.max(0, limit - T.probeStepM)
    }
    raw[j] = limit
  }
  const reach = Math.max(1, Math.round(T.limitSmoothM / corridor.stepM))
  const least = new Float64Array(count)
  for (let j = 0; j < count; j++) {
    let low = Infinity
    for (let k = -reach; k <= reach; k++) low = Math.min(low, raw[(((j + k) % count) + count) % count])
    least[j] = low
  }
  const smooth = new Float64Array(count)
  for (let j = 0; j < count; j++) {
    let sum = 0
    for (let k = -reach; k <= reach; k++) sum += least[(((j + k) % count) + count) % count]
    smooth[j] = sum / (2 * reach + 1)
  }
  return smooth
}

/** A closed loop of points at even spacing, as plain arrays. */
interface Loop {
  x: Float64Array
  y: Float64Array
  /** Where each point is abeam of the route, in route samples (a whole number and a fraction). */
  routeAt: Float64Array
  length: number
}

/** Curvature at each point of a loop: that of the circle through it and the points `reach` steps either side. Positive turning right. */
function curvatures(loop: Loop, reach: number): Float64Array {
  const n = loop.x.length
  const out = new Float64Array(n)
  for (let i = 0; i < n; i++) {
    const before = (i - reach + n) % n
    const after = (i + reach) % n
    const inX = loop.x[i] - loop.x[before]
    const inY = loop.y[i] - loop.y[before]
    const outX = loop.x[after] - loop.x[i]
    const outY = loop.y[after] - loop.y[i]
    const chord = Math.hypot(loop.x[after] - loop.x[before], loop.y[after] - loop.y[before])
    const product = Math.hypot(inX, inY) * Math.hypot(outX, outY) * chord
    out[i] = product === 0 ? 0 : (2 * (inX * outY - inY * outX)) / product
  }
  return out
}

/**
 * Relaxes a line inside a measured corridor. Each pass takes the line so far as its reference, measures how far
 * each of its points may move to either side along its own normal, and slides the points along those normals to
 * the offsets that bend the path least. The first pass starts from the route's centreline; later ones start from a
 * line that is already smooth, so a normal never reaches past its own centre of curvature, and the straight-line
 * estimate of curvature the sliding works with gets truer with every pass.
 */
export function relaxLine(corridor: Corridor, style: LineStyle): RacingLine {
  const { track } = corridor
  const limitLeft = centreLimits(corridor, -1, style)
  const limitRight = centreLimits(corridor, 1, style)
  const routeCount = limitLeft.length
  const window = Math.ceil(T.projectWindowM / corridor.stepM)

  /**
   * A place as the route sees it, looked for near route sample `hint`: which sample it is abeam of (with a fraction)
   * and how far to the right of the centreline it lies. The answer is left in `abeam`.
   */
  const abeam = { at: 0, lateralM: 0 }
  const project = (x: number, y: number, hint: number): void => {
    const first = Math.floor(hint) - window
    let bestSq = Infinity
    let bestIndex = 0
    let bestT = 0
    for (let k = 0; k <= 2 * window; k++) {
      const i = (((first + k) % routeCount) + routeCount) % routeCount
      const j = (i + 1) % routeCount
      const ax = corridor.x[i]
      const ay = corridor.y[i]
      const dx = corridor.x[j] - ax
      const dy = corridor.y[j] - ay
      const lengthSq = dx * dx + dy * dy
      const t = lengthSq === 0 ? 0 : Math.min(1, Math.max(0, ((x - ax) * dx + (y - ay) * dy) / lengthSq))
      const gapX = x - (ax + dx * t)
      const gapY = y - (ay + dy * t)
      const gap = gapX * gapX + gapY * gapY
      if (gap < bestSq) {
        bestSq = gap
        bestIndex = i
        bestT = t
      }
    }
    const j = (bestIndex + 1) % routeCount
    const side = (corridor.x[j] - corridor.x[bestIndex]) * (y - corridor.y[bestIndex]) - (corridor.y[j] - corridor.y[bestIndex]) * (x - corridor.x[bestIndex])
    abeam.at = bestIndex + bestT
    abeam.lateralM = Math.sign(side) * Math.sqrt(bestSq)
  }

  /** Whether the centre of a car may be at a point: within the limits of the lane where it is. */
  const allowed = (x: number, y: number, hint: number): boolean => {
    project(x, y, hint)
    const i = Math.floor(abeam.at) % routeCount
    const j = (i + 1) % routeCount
    const f = abeam.at - Math.floor(abeam.at)
    const limits = abeam.lateralM < 0 ? limitLeft : limitRight
    return Math.abs(abeam.lateralM) <= limits[i] + (limits[j] - limits[i]) * f
  }

  /** How far a car's centre may go from a point along a direction before it is no longer allowed, m. */
  const roomAlong = (x: number, y: number, dirX: number, dirY: number, hint: number): number => {
    if (!allowed(x, y, hint)) return 0
    if (allowed(x + dirX * T.probeMaxM, y + dirY * T.probeMaxM, hint)) return T.probeMaxM
    let near = 0
    let far: number = T.probeMaxM
    for (let step = 0; step < T.probeBisections; step++) {
      const mid = (near + far) / 2
      if (allowed(x + dirX * mid, y + dirY * mid, hint)) near = mid
      else far = mid
    }
    return near
  }

  /** The loop through `x`, `y` cut again into as many even steps of distance. `hints` say where each given point is abeam of the route. */
  const resample = (x: Float64Array, y: Float64Array, hints: Float64Array): Loop => {
    const n = x.length
    const travelled = new Float64Array(n + 1)
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n
      travelled[i + 1] = travelled[i] + Math.hypot(x[j] - x[i], y[j] - y[i])
    }
    const length = travelled[n]
    const out: Loop = { x: new Float64Array(n), y: new Float64Array(n), routeAt: new Float64Array(n), length }
    for (let i = 0, k = 0; i < n; i++) {
      const target = (i * length) / n
      while (k < n - 1 && travelled[k + 1] < target) k++
      const span = travelled[k + 1] - travelled[k]
      const f = span === 0 ? 0 : (target - travelled[k]) / span
      const j = (k + 1) % n
      out.x[i] = x[k] + (x[j] - x[k]) * f
      out.y[i] = y[k] + (y[j] - y[k]) * f
      project(out.x[i], out.y[i], hints[k])
      out.routeAt[i] = abeam.at
    }
    return out
  }

  // A count the coarse-to-fine relaxation can halve down to its coarsest spacing.
  const coarsest = T.strides[0]
  const count = coarsest * Math.max(2, Math.round(track.lengthM / (coarsest * T.stepM)))
  const startX = new Float64Array(count)
  const startY = new Float64Array(count)
  const startAt = new Float64Array(count)
  for (let i = 0; i < count; i++) {
    const s = (i * track.lengthM) / count
    const pose = track.routePose(s)
    startX[i] = pose.x
    startY[i] = pose.y
    startAt[i] = s / corridor.stepM
  }
  let loop = resample(startX, startY, startAt)

  const normalX = new Float64Array(count)
  const normalY = new Float64Array(count)
  const low = new Float64Array(count)
  const high = new Float64Array(count)
  const setFrame = (): void => {
    const bends = curvatures(loop, Math.max(1, Math.round(T.curvatureReachM / (loop.length / count))))
    for (let i = 0; i < count; i++) {
      const before = (i - 1 + count) % count
      const after = (i + 1) % count
      const tx = loop.x[after] - loop.x[before]
      const ty = loop.y[after] - loop.y[before]
      const size = Math.hypot(tx, ty) || 1
      // To the right of the direction of travel.
      normalX[i] = -ty / size
      normalY[i] = tx / size
      high[i] = roomAlong(loop.x[i], loop.y[i], normalX[i], normalY[i], loop.routeAt[i])
      low[i] = -roomAlong(loop.x[i], loop.y[i], -normalX[i], -normalY[i], loop.routeAt[i])
      // Never as far as the reference's own centre of curvature, where its normals cross.
      if (bends[i] > 0) high[i] = Math.min(high[i], T.foldGuard / bends[i])
      else if (bends[i] < 0) low[i] = Math.max(low[i], T.foldGuard / bends[i])
    }
  }

  for (let pass = 0; pass < T.passes; pass++) {
    setFrame()
    const offset = slide(loop, normalX, normalY, low, high)
    const x = new Float64Array(count)
    const y = new Float64Array(count)
    for (let i = 0; i < count; i++) {
      x[i] = loop.x[i] + normalX[i] * offset[i]
      y[i] = loop.y[i] + normalY[i] * offset[i]
    }
    loop = resample(x, y, loop.routeAt)
  }
  setFrame()

  const stepM = loop.length / count
  const bends = curvatures(loop, Math.max(1, Math.round(T.curvatureReachM / stepM)))
  const wheelM = (corridor.carWidthM / 2) * T.wheelShare
  const points: LinePoint[] = []
  for (let i = 0; i < count; i++) {
    const before = (i - 1 + count) % count
    const after = (i + 1) % count
    const x = loop.x[i]
    const y = loop.y[i]
    const onKerb =
      track.surfaceAt(x, y) === 'kerb' ||
      track.surfaceAt(x + normalX[i] * wheelM, y + normalY[i] * wheelM) === 'kerb' ||
      track.surfaceAt(x - normalX[i] * wheelM, y - normalY[i] * wheelM) === 'kerb'
    points.push({
      s: i * stepM,
      x,
      y,
      headingRad: Math.atan2(loop.y[after] - loop.y[before], loop.x[after] - loop.x[before]),
      curvature: bends[i],
      halfRoomM: (high[i] - low[i]) / 2,
      roomLeftM: -low[i],
      roomRightM: high[i],
      routeS: (loop.routeAt[i] * corridor.stepM) % track.lengthM,
      onKerb,
    })
  }
  return finishLine(points, loop.length, track, wheelM)
}

/**
 * Slides each point of a loop along its normal, within its limits, to the offsets that bend the path least. The
 * bend at a point is read as the part of its second difference (the two neighbours' midpoint less the point, twice)
 * that lies along its own normal, which for evenly spaced points is curvature times the spacing squared; the part
 * along the path, which only says the points are unevenly spread, is left out, or a shorter path would count as a
 * straighter one. The sum of the squares of those is brought down one point at a time, each to its own best place
 * given its neighbours, which inside box limits converges on the best of all. The widest spacing is settled first
 * and each finer one starts from it, so that long bends settle in a few hundred sweeps.
 */
function slide(loop: Loop, normalX: Float64Array, normalY: Float64Array, low: Float64Array, high: Float64Array): Float64Array {
  const count = loop.x.length
  const offset = new Float64Array(count)
  for (const stride of T.strides) {
    const nodes = count / stride
    // A node stands for the points half a stride either side of it: it may go only as far as the tightest of them.
    const nodeLow = new Float64Array(nodes)
    const nodeHigh = new Float64Array(nodes)
    const half = stride >> 1
    for (let k = 0; k < nodes; k++) {
      let least = -Infinity
      let most = Infinity
      for (let d = -half; d <= half; d++) {
        const i = (k * stride + d + count) % count
        least = Math.max(least, low[i])
        most = Math.min(most, high[i])
      }
      nodeLow[k] = Math.min(least, 0)
      nodeHigh[k] = Math.max(most, 0)
    }
    const px = new Float64Array(nodes)
    const py = new Float64Array(nodes)
    for (let k = 0; k < nodes; k++) {
      const i = k * stride
      offset[i] = Math.min(nodeHigh[k], Math.max(nodeLow[k], offset[i]))
      px[k] = loop.x[i] + normalX[i] * offset[i]
      py[k] = loop.y[i] + normalY[i] * offset[i]
    }
    for (let sweep = 0; sweep < T.sweeps; sweep++) {
      for (let step = 0; step < nodes; step++) {
        // Alternate sweeps run the other way round the lap, so that no direction is favoured.
        const k = sweep % 2 === 0 ? step : nodes - 1 - step
        const i = k * stride
        const a = (k - 2 + nodes) % nodes
        const b = (k - 1 + nodes) % nodes
        const c = (k + 1) % nodes
        const d = (k + 2) % nodes
        const rx = loop.x[i]
        const ry = loop.y[i]
        const nx = normalX[i]
        const ny = normalY[i]
        const bnx = normalX[b * stride]
        const bny = normalY[b * stride]
        const cnx = normalX[c * stride]
        const cny = normalY[c * stride]
        // The three bends this point takes part in, with the point at its reference place, and how each changes
        // as the point moves along its normal: by the cosine between the normals for its neighbours' bends, by
        // minus two for its own.
        const beforeBend = (px[a] - 2 * px[b] + rx) * bnx + (py[a] - 2 * py[b] + ry) * bny
        const ownBend = (px[b] + px[c] - 2 * rx) * nx + (py[b] + py[c] - 2 * ry) * ny
        const afterBend = (rx - 2 * px[c] + px[d]) * cnx + (ry - 2 * py[c] + py[d]) * cny
        const beforeGain = bnx * nx + bny * ny
        const afterGain = cnx * nx + cny * ny
        const free = (2 * ownBend - beforeBend * beforeGain - afterBend * afterGain) / (4 + beforeGain * beforeGain + afterGain * afterGain)
        const best = Math.min(nodeHigh[k], Math.max(nodeLow[k], free))
        offset[i] = best
        px[k] = rx + nx * best
        py[k] = ry + ny * best
      }
    }
    // The points between the nodes take the offsets on the straight line between them, each within its own limits.
    for (let k = 0; k < nodes; k++) {
      const from = offset[k * stride]
      const to = offset[((k + 1) % nodes) * stride]
      for (let d = 1; d < stride; d++) {
        const i = k * stride + d
        offset[i] = Math.min(high[i], Math.max(low[i], from + ((to - from) * d) / stride))
      }
    }
  }
  return offset
}

/** Wraps a loop of points into the line the drivers use: sampling, the nearest point, and the way across from route distance. */
function finishLine(points: LinePoint[], lengthM: number, track: TrackRuntime, wheelM: number): RacingLine {
  const count = points.length
  const stepM = lengthM / count
  const window = Math.ceil(T.nearestWindowM / stepM)

  // Where the kerbs are from the line: at each point, the least move of the car's centre to either side that puts
  // its middle or one of its wheels on a kerb.
  const kerbLeftM = new Float64Array(count)
  const kerbRightM = new Float64Array(count)
  const wheelOnKerb = (x: number, y: number, rightX: number, rightY: number): boolean =>
    track.surfaceAt(x, y) === 'kerb' || track.surfaceAt(x + rightX * wheelM, y + rightY * wheelM) === 'kerb' || track.surfaceAt(x - rightX * wheelM, y - rightY * wheelM) === 'kerb'
  for (let i = 0; i < count; i++) {
    const point = points[i]
    const rightX = -Math.sin(point.headingRad)
    const rightY = Math.cos(point.headingRad)
    for (const [reach, side] of [
      [kerbLeftM, -1],
      [kerbRightM, 1],
    ] as const) {
      reach[i] = Infinity
      for (let moved = 0; moved <= T.kerbReachM; moved += T.kerbReachStepM) {
        if (!wheelOnKerb(point.x + side * rightX * moved, point.y + side * rightY * moved, rightX, rightY)) continue
        reach[i] = moved
        break
      }
    }
  }

  const indexAt = (s: number): number => Math.min(count - 1, Math.floor(((((s % lengthM) + lengthM) % lengthM) / stepM) % count))

  const at = (s: number): LinePoint => {
    const u = ((((s % lengthM) + lengthM) % lengthM) / stepM) % count
    const i = Math.min(count - 1, Math.floor(u))
    const a = points[i]
    const b = points[(i + 1) % count]
    const f = u - i
    return {
      s: u * stepM,
      x: a.x + (b.x - a.x) * f,
      y: a.y + (b.y - a.y) * f,
      headingRad: wrapAngle(a.headingRad + angleDiff(a.headingRad, b.headingRad) * f),
      curvature: a.curvature + (b.curvature - a.curvature) * f,
      halfRoomM: a.halfRoomM + (b.halfRoomM - a.halfRoomM) * f,
      roomLeftM: a.roomLeftM + (b.roomLeftM - a.roomLeftM) * f,
      roomRightM: a.roomRightM + (b.roomRightM - a.roomRightM) * f,
      routeS: a.routeS,
      onKerb: a.onKerb,
    }
  }

  const found = { s: 0, lateralM: 0 }
  const nearest = (x: number, y: number, hintS?: number): { s: number; lateralM: number } => {
    let first = 0
    let span = count
    if (hintS !== undefined && 2 * window + 1 < count) {
      first = indexAt(hintS) - window
      span = 2 * window + 1
    }
    let bestSq = Infinity
    let bestIndex = 0
    let bestT = 0
    for (let k = 0; k < span; k++) {
      const i = (((first + k) % count) + count) % count
      const a = points[i]
      const b = points[(i + 1) % count]
      const dx = b.x - a.x
      const dy = b.y - a.y
      const lengthSq = dx * dx + dy * dy
      const t = lengthSq === 0 ? 0 : Math.min(1, Math.max(0, ((x - a.x) * dx + (y - a.y) * dy) / lengthSq))
      const gapX = x - (a.x + dx * t)
      const gapY = y - (a.y + dy * t)
      const gap = gapX * gapX + gapY * gapY
      if (gap < bestSq) {
        bestSq = gap
        bestIndex = i
        bestT = t
      }
    }
    const a = points[bestIndex]
    const b = points[(bestIndex + 1) % count]
    // Positive to the right of the direction of travel: y is down, so right is a quarter turn clockwise.
    const side = (b.x - a.x) * (y - a.y) - (b.y - a.y) * (x - a.x)
    found.s = ((bestIndex + bestT) * stepM) % lengthM
    found.lateralM = Math.sign(side) * Math.sqrt(bestSq)
    return found
  }

  // The way across from the route: for each short step of route distance, how far along the line is abeam of it.
  const bins = Math.max(1, Math.round(track.lengthM / stepM))
  const binM = track.lengthM / bins
  const across = new Float64Array(bins)
  let hint: number | undefined
  for (let k = 0; k < bins; k++) {
    const pose = track.routePose(k * binM)
    hint = nearest(pose.x, pose.y, hint).s
    across[k] = hint
  }
  const sAtRoute = (routeS: number): number => {
    const u = (((routeS % track.lengthM) + track.lengthM) % track.lengthM) / binM
    const k = Math.min(bins - 1, Math.floor(u))
    const from = across[k]
    let to = across[(k + 1) % bins]
    // Across the start of the line the distance wraps: carry on past its end, not back to its beginning.
    if (to < from - lengthM / 2) to += lengthM
    else if (to > from + lengthM / 2) to -= lengthM
    return (((from + (to - from) * (u - k)) % lengthM) + lengthM) % lengthM
  }

  return { lengthM, stepM, points, at, indexAt, nearest, sAtRoute, kerbLeftM, kerbRightM }
}
