import { createRng } from '../core'
import type { SessionConfig, SessionEntry } from '../session'
import { orientTrack, type TrackData } from '../track'
import { firstWeatherPlan } from '../weather'
import { PLAYER_DRIVER_ID, seededPermutation } from './field'
import type { RaceDayState, ScheduleItem } from './types'

// The session a schedule item is run as (F-401): who starts where, on what, for how long, from which seed.

/** How long a penalty holds a car where the event's settings do not say, s (F-508): as long as it always did. */
const DEFAULT_PENALTY_S = 5

/** The largest seed handed to a session: the range the game's own fresh seeds are in. */
const MAX_SEED = 2_147_483_646

/** What a session of the event is called: the name its config and its result carry. */
export function sessionLabel(item: ScheduleItem): string {
  return item.kind === 'qualifying' ? `Qualifying round ${item.round}` : `Final leg ${item.leg}`
}

/**
 * The seed of the session at a place in the schedule: drawn from the event's seed and the place, so that every
 * session is reproducible on its own and no two sessions of an event share their accidents.
 */
export function sessionSeed(eventSeed: number, scheduleIndex: number): number {
  return createRng(eventSeed).fork(`race-day-session-${scheduleIndex}`).int(0, MAX_SEED)
}

/**
 * The start slot of every entry, in entry order, for a qualifying round: a fresh draw for every round from the
 * event's seed and the round's number, the player included. The standings have no say in it.
 */
export function qualifyingStartSlots(eventSeed: number, round: number, cars: number): number[] {
  return seededPermutation(cars, eventSeed, `race-day-qualifying-order-${round}`)
}

/**
 * The next session of the event and its schedule item, or null when every session has been recorded.
 *
 * The entries are in car-number order in every session, so that a driver has the same car id all day; where each
 * starts is its `startSlot`: the draw in a qualifying round, the place in qualifying in a final leg, pole in slot 0.
 * The weather (F-601) is what the session before it handed on, `state.weather`; where there is none (the first
 * session of an event, and an event saved before there was weather) it is the forecast's own first draw from the
 * event's seed. Either way the plan names the forecast that was settled on: `surprise` is one of the other three.
 * The event's race settings (F-508: penalties and their length, reverse) go into every session's config.
 */
export function nextSession(state: RaceDayState, track: TrackData): { item: ScheduleItem; config: SessionConfig } | null {
  const item = state.schedule.at(state.cursor)
  if (item === undefined) return null
  const { settings } = state
  if (track.id !== settings.trackId) throw new Error(`nextSession: the event is at '${settings.trackId}' but was given the track '${track.id}'`)

  let slots: number[]
  if (item.kind === 'qualifying') {
    slots = qualifyingStartSlots(settings.seed, item.round, state.entries.length)
  } else {
    const grid = state.finalGrid
    if (grid === null) throw new Error('nextSession: a final leg is next but qualifying has set no grid')
    slots = state.entries.map((entry) => grid.indexOf(entry.driverId))
  }
  const entries: SessionEntry[] = state.entries.map((entry, i) => ({
    driverId: entry.driverId,
    number: entry.number,
    colour: entry.colour,
    controller: entry.driverId === PLAYER_DRIVER_ID ? 'human' : 'ai',
    startSlot: slots[i],
  }))

  const config: SessionConfig = {
    seed: sessionSeed(settings.seed, state.cursor),
    kind: item.kind,
    label: sessionLabel(item),
    track: orientTrack(track, settings.direction),
    carClass: settings.carClass,
    durationS: settings.roundMinutes * 60,
    entries,
    difficulty: settings.difficulty,
    weather: state.weather === undefined ? firstWeatherPlan(settings.forecast, settings.seed) : { ...state.weather },
  }
  if (item.kind === 'qualifying') config.qualifyingStart = settings.qualifyingStart
  // The race settings (F-508). An event that says nothing of them hands its sessions nothing, and they run as they
  // always did; one that gives either of the penalty settings gives the session both, the other at its default.
  if (settings.penalties !== undefined || settings.penaltySeconds !== undefined) config.penalties = { enabled: settings.penalties ?? true, holdS: settings.penaltySeconds ?? DEFAULT_PENALTY_S }
  if (settings.reverse !== undefined) config.reverse = settings.reverse
  return { item, config }
}
