// Fixed orders, so that a phase or a car state can be hashed as a number.
const PHASES: readonly SessionPhase[] = ['staging', 'countdown', 'running', 'time-up', 'finished']
const CAR_STATES: readonly CarState[] = ['driving', 'flipped', 'stuck', 'being-marshalled', 'held', 'finished', 'pit-hold', 'penalty-hold', 'lifted-out']
const SURFACES: readonly SurfaceKind[] = ['asphalt', 'kerb', 'grass']
const STRICKEN_CAUSES: ReadonlyArray<FlipCause | StuckCause> = ['kerb', 'impact', 'grass', 'wedged']

const MAX_ENTRIES = 7
/** The grip multiplier the AI drivers plan for until the weather sets one (F-604). */
const DRY_GRIP = 1
const NO_EVENTS: readonly SimEvent[] = Object.freeze([])
const NO_DRIVERS: ReadonlyArray<AiDriver | null> = Object.freeze([])
const HOLD_TICKS = Math.round(RULES.holdS * TICK_RATE)
const CLOCK_START_LATEST_TICKS = Math.round(RULES.clockStartLatestS * TICK_RATE)
const AT_REST: Readonly<Vec2> = Object.freeze({ x: 0, y: 0 })
const NOBODY: ReadonlyArray<Readonly<Vec2>> = Object.freeze([])
const FAIL_SAFE_TICKS = Math.round(INCIDENT_TUNING.marshal.failSafeS * TICK_RATE)
/** A car going at least this fast on the lane, m/s, squared, is circulating: its tyres are drying the racing line (F-601). */
const CIRCULATING_MIN_MS2 = WEATHER_TUNING.line.circulatingMinMS * WEATHER_TUNING.line.circulatingMinMS
/** A set-down place that is asked for again and comes out within this of what it was, m, is the same place. */
const SAME_PLACE_M = 1e-6
/** A car is set down with at least this much air between it and a marshal, m. */
const MARSHAL_CLEAR_M = 0.02
/** The lengths a session's settings may give its penalties, s (F-508). */
const PENALTY_LENGTHS_S: readonly number[] = [3, 4, 5]

/**
 * Where a car's centre stands with the cut rule (F-309), by the surfaces' own outlines of the grass. On a lane. Off
 * it, having driven off a lane onto the grass, to be judged when it is back on one. Or off it with nothing to answer
 * for when it is back: it has been penalised or set down there, or was not its driver's when it got there.
 */
/** The centre's move of one tick is looked along every so far, m: finer than the thinnest island that counts is wide. */
const FOLLOW_STEP_M = 0.02
const ON_A_LANE = 0
const OFF_TO_BE_JUDGED = 1
const OFF_AND_SETTLED = 2
type Excursion = typeof ON_A_LANE | typeof OFF_TO_BE_JUDGED | typeof OFF_AND_SETTLED

/** What the session itself knows about a car. How the car moves belongs to the stepper. */
interface CarRecord extends CarTiming {
  readonly human: boolean
  state: CarState
  stateSinceTick: Tick
  /** Where the car's centre was at the end of the previous tick: the start of this tick's move, for lap timing. */
  readonly prev: Vec2
  elapsedMs: number
  position: number
  gapAheadMs: number | null
  /** What the surfaces remember about the car: how far it has gone on the grass, how long it has left in the air (F-207). */
  surface: SurfaceState
  /** The lane the car's centre was last in, the lap or the pit lane: where it is set back if it gets stuck (F-207). */
  lane: Lane
  /**
   * Where the car was put to start, and the last tick before it may be driven (F-303). A car that is lifted out of
   * the pit queue (F-309) is not released while it stands aside, and gets both anew when it is put back.
   */
  readonly place: Pose
  releaseTick: Tick
  /** It was given throttle or brake before it was released. */
  droveEarly: boolean
  /** It jumped the start, and is to be held for it at its first crossing of the line. */
  holdOwed: boolean
  /**
   * Before its release, a car or a marshal has run into it and it is being moved by that, with its throttle closed
   * (F-508): its start place goes with it, so that being pushed out of its box is not a jumped start.
   */
  shoved: boolean
  /**
   * When its clock started, ms of session time: the start tone in a final; in qualifying its first crossing of the
   * line, or the rules' latest time after its release if it has not crossed by then. Null until then, and
   * throughout a practice session.
   */
  clockStartMs: number | null
  /** What its clock read when it completed its last counted lap, ms, not rounded; null with no lap. */
  raceMs: number | null
  /** How far along the route it has come since it last crossed the line, m; below zero on the way to its first crossing. */
  sinceLineM: number
  /** Pit stops it still has to make (F-306); nothing where none are owed. */
  pitStopsOwed: number
  /** Where it stands for its pit stop, while its state is 'pit-hold': the session keeps it exactly there. */
  readonly pitPlace: Pose
  /** It is in the pit lane, past where that becomes a lane of its own, and has been since it was last on the lap (F-306). */
  inPits: boolean
  /**
   * It came into the stop zone owing a stop and is being braked for it (F-306): its pedals are the session's until
   * it is at rest, wherever that is, and its hold begins there.
   */
  pitStopping: boolean
  /** How many ticks running the car has been on a green island while its driver's to drive (F-307); nothing anywhere else. */
  offTrackTicks: number
  /** Where it was stopped for its penalty, while its state is 'penalty-hold': the session keeps it exactly there. */
  readonly penaltyPlace: Pose
  /** How long the penalty it is standing for lasts, in ticks (F-309): a penalty names its own hold. */
  penaltyTicks: number
  /**
   * It is standing for a penalty where the grass has hold of it (F-309, F-502): it would be stuck the moment it was
   * let go, so a marshal is sent for it as the hold begins, and has it on the lane by the time the hold is over if
   * he can.
   */
  heldBogged: boolean
  /** The tick it was stricken on (F-502): rolled, stuck, or stopped for a penalty where the grass has it. What its downtime and the fail-safe are counted from. */
  strickenTick: Tick
  /** Where it stands with the cut rule (F-309). */
  excursion: Excursion
  /** While it is off a lane and to be judged: the point of the lane's edge its centre left over. */
  readonly leftAt: Vec2
  /** Whether any of the grass it has been over since was a green island: the surround alone is no cut. */
  overIsland: boolean
  /** Whether its centre has been further than the grace band from every lane since: on the grass as the surfaces read it (F-207). */
  pastBand: boolean
  /** Hits that count against it since the session began or since it was last stopped for them (F-309). */
  contactHits: number
  /**
   * Since it was released from its pit stop (F-309): the ticks it has been its driver's with its centre still in the
   * stop zone and the way out of it clear. Less than nothing once it has left the zone, and with no stop just served.
   */
  pitLeaveTicks: number
  /** The tick it first moved off from its start place, or was lifted from it (F-309); less than nothing until then. */
  movedOffTick: Tick
  /** Where it stands while its state is 'lifted-out': the session keeps it exactly there. */
  readonly liftPlace: Pose
  /**
   * Why it is out of its driver's hands (F-501), while its state is 'flipped', 'stuck' or 'being-marshalled': what
   * rolled it, or what holds it. Null in every other state.
   */
  strickenCause: FlipCause | StuckCause | null
  /** How many ticks running it has been jammed against something solid with its driver trying to move it (F-501). */
  wedgeTicks: number
  /** It is floating on standing water (F-602): from the tick it met a puddle at its aquaplane speed or faster until it is out of the water. */
  aquaplaning: boolean
  /** Where its centre was when it wedged, while it is stuck for that: it is free once it is clear of there. */
  readonly wedgedAt: Vec2
  /** How it moves while it is on its roof (F-507, F-512): the speed it went over at, and the length and the turn drawn for its slide. In any other state, as its last roll left it. */
  slide: RollSlide
  /** It has had the hit that stops it under the contact rule while it was on its roof (F-512): it is stopped the moment it is its driver's again. */
  contactStopOwed: boolean
  /** How many ticks running another car's nose has been against its tail with it going faster than its push speed (F-507). */
  pushedTicks: number
  /**
   * A marshal has lifted it and is walking with it (F-508). `liftedAt` is where it lay when he lifted it, or when its
   * set-down place was last changed; `setDown` is where it is to be put down, on the lane it left, with how far
   * round the lap that is. Kept from the lift until it is set down.
   */
  lifted: boolean
  readonly liftedAt: Pose
  readonly setDown: Pose
  setDownRouteS: number
  setDownLane: Lane
}

/** What a qualifying heat or a final keeps that a practice session does not (F-303). */
interface RaceState {
  /** Where the cars started from, the place of each start slot, and the cars in the order of their slots (F-303). */
  readonly startFrom: StartFrom
  readonly places: readonly Pose[]
  readonly bySlot: readonly CarId[]
  /** The car whose clock the on-screen timer shows in qualifying. */
  readonly timerCar: CarId
  /**
   * Pit stops each car owed as the session started (F-306): the class's number in a final on a track with a pit
   * lane, else none. With none, nothing of the pit-stop rule runs, is told or is hashed.
   */
  readonly pitStops: number
  /** The tick at whose end the cars that still owe a stop are reminded of it; null where there is no such tick. */
  readonly pitReminderTick: Tick | null
  /**
   * The stretch of the pit route, m along it, where the pit lane is a lane of its own, clear of the lap's asphalt
   * at both its ends: a car that is in it has come into the pits.
   */
  readonly pitOwn: { readonly fromS: number; readonly toS: number }
  readonly standings: Standings
  readonly finish: FinishWatch
  /** What race control has called so far (F-404): the PA's calls fall due as the phases and the clock on screen reach them. */
  readonly control: RaceControlSchedule
  /** Null until the session has finished. */
  result: SessionResult | null
  // Reused between ticks: what the end of the tick in progress has to tell, the cars that finished on it, and
  // how each car stands for the end of the session; and, for each car that had the stop zone as the pit stops were
  // settled, how far along the pit route it was, m, with less than nothing for a car that had not.
  readonly zoneHeldAtS: number[]
  readonly told: SimEvent[]
  readonly finishedNow: CarId[]
  readonly stillOut: StillOut[]
}

/** What passes between the session and the marshals on one tick (F-502). */
interface MarshalWork {
  tick: Tick
  readonly calls: MarshalCall[]
  readonly hit: number[]
  /** What the marshals did on the tick, to be told with the tick's other events. */
  readonly told: SimEvent[]
  surfaces: SurfaceSetup | null
}

/** Every piece of mutable state of one session. Nothing lives outside this object. */
interface SessionState {
  readonly config: SessionConfig
  /** Built once, from the config's track. */
  readonly track: TrackRuntime
  readonly gates: TimingGates
  /** The fastest lap of any car so far, in whole ms; null until one is done. */
  sessionBestMs: number | null
  tick: Tick
  phase: SessionPhase
  /** The session's one seeded source of randomness. Each subsystem draws from its own named fork of it. */
  readonly rng: Rng
  readonly stepper: CarStepper
  // One slot per car, indexed by CarId.
  readonly cars: CarRecord[]
  readonly inputs: ControlInput[]
  readonly env: StepEnvironment[]
  readonly kinematics: CarKinematics[]
  /** What puts ground under the cars (F-207); null for a session whose cars are all on dry asphalt whatever the track says. */
  readonly surfaces: SurfaceSetup | null
  /** The AI drivers (F-301), indexed by CarId, null for a car a human drives. Empty in a session that was given no AI setup: its AI cars are not driven. */
  readonly drivers: Array<AiDriver | null>
  /** What a race keeps beyond a practice session (F-303); null in practice. */
  readonly race: RaceState | null
  /**
   * What parks each car once it has finished (F-303), indexed by CarId. Empty in practice, where nobody finishes,
   * and in a session that was given no AI setup: its finished cars are left to roll to rest.
   */
  readonly pullOvers: PullOver[]
  /** The cars that bogged down on the tick in progress, noted before the cars move and emptied once they are stuck. */
  readonly bogged: CarId[]
  /** The cars that a kerb rolled on the tick in progress (F-507), and beside each which way, noted before the cars move and emptied once they are on their roofs. */
  readonly rolled: CarId[]
  readonly rolledHow: RollCase[]
  /** For each car, whether another car's nose was against its tail during the step in progress, with it going faster than its push speed (F-507), and which car's (F-512); -1 for none. Refilled every tick. */
  readonly pushedNow: boolean[]
  readonly pushedBy: CarId[]
  /** Where a rolled car's slide is drawn from (F-512): the session's `rolls` stream, and how many it has drawn, which is the stream's whole state and is hashed. */
  readonly rollRng: Rng
  rollDraws: number
  /** For each car, whether it pressed on a wall or a marker during the step in progress (F-501). Refilled every tick. */
  readonly touchingSolid: boolean[]
  /** For each car, whether another car or a marshal pressed on it during the step in progress (F-508). Refilled every tick of a race. */
  readonly shovedNow: boolean[]
  /** How long an off-track, track-cut or contact penalty holds a car, s (F-508): the settings' length; null in a session with those penalties off. */
  readonly penaltyHoldS: number | null
  /** Whether the cars have reverse (F-508). Without it a wedged car is helpless, and standing on the brake is being wedged. */
  readonly reverse: boolean
  /** The marshals (F-502): one at each of the track's posts, with their own stream of the session's randomness. */
  readonly marshals: MarshalSystem
  /** What the marshals are told on a tick and what they ask for back; one object for the session, refilled. */
  readonly marshalWork: MarshalWork
  /** The weather (F-601): the sky, the wetness, the puddles and the wind, with its own stream of the session's randomness. */
  readonly weather: WeatherSystem
  /** What the weather is told of the cars on a tick; one object for the session, refilled. */
  readonly traffic: { carsOnLine: number }
  /** The racing lines the AI setup found (F-301); null in a session that was given none. */
  lines: LineBook | null
  /**
   * The racing line whose wetness a car on it feels (F-602): the line of a driver of full skill in a car of the
   * session's class. Found the first time the line is drier than the surface, and never in a session where it never is.
   */
  feltLine: RacingLine | null
  /** What each car's environment says of the water it stands in, by car id: one object per car, refilled (F-602). */
  readonly inWater: Array<{ dragN: number; lateralGripScale: number }>
  /** The marshals' way of asking, made the first time they are asked. */
  marshalCtx: MarshalContext | null
  /** What the AI drivers are shown while marshals are out (F-502): the cars, and after them each marshal as a car standing still. */
  readonly aiSees: CarSnapshot[]
  readonly marshalStandIns: Array<Mutable<CarSnapshot>>
  /** What pressed on what during the step in progress (F-302): filled by the stepper, read by the incidents step. */
  readonly contacts: StepContact[]
  /** Where each car was and how it was moving as the tick in progress began (F-309): who ran into whom. Refilled every tick. */
  readonly before: Array<{ at: Vec2; velocity: Vec2 }>
  /** For each two cars, at the lower id times the number of cars plus the higher: the tick of the last hit between them that counted (F-309). */
  readonly lastHitTick: number[]
  /** Beside each, which of the two that hit counted against (F-512): 1 the lower id, 2 the higher, 3 both. A roll one of them caused is not counted again in the same touch. */
  readonly lastHitBy: number[]
  /** What incident detection remembers between ticks (F-302). */
  readonly incidents: IncidentState
  // Reused between calls.
  readonly view: Mutable<SessionSnapshot>
  readonly hashBuffer: number[]
  /** Set the first time any car's parameters are replaced (`allowTuning` sessions only). Never cleared, and not hashed. */
  tuned: boolean
}

function checkConfig(config: SessionConfig, places: readonly Pose[]): void {
  const count = config.entries.length
  if (count < 1 || count > MAX_ENTRIES) {
    throw new Error(`A session needs 1 to ${MAX_ENTRIES} entries, not ${count}`)
  }
  const taken = new Set<number>()
  for (const entry of config.entries) {
    const slot = entry.startSlot
    if (!Number.isInteger(slot) || slot < 0 || slot >= places.length) {
      throw new Error(`Entry '${entry.driverId}' has start slot ${slot}; the track has ${places.length} start slots for a ${config.kind} session`)
    }
    if (taken.has(slot)) throw new Error(`Entry '${entry.driverId}' shares start slot ${slot} with another entry`)
    taken.add(slot)
  }
  const holdS: number | undefined = config.penalties?.holdS
  if (holdS !== undefined && !PENALTY_LENGTHS_S.includes(holdS)) throw new Error(`A penalty holds a car for ${PENALTY_LENGTHS_S.join(', ')} seconds, not ${holdS}`)
}

function createState(config: SessionConfig, createStepper: StepperFactory, track: TrackRuntime, surfaces: SurfaceSetup | null, ai: AiSetup | null, mandatoryPitStops: number): SessionState {
  // Where the cars start (F-303): the grid, or for a qualifying heat the pit-lane queue or the start boxes.
  const { from, places } = startPlaces(config, track)
  checkConfig(config, places)
  // What each car owes in pit stops (F-306): the class's number, in a final, where there is a pit lane.
  const pitStops = pitStopsOwedIn(config.kind, track, mandatoryPitStops)
  const stepper = createStepper(config)
  const rng = createRng(config.seed)
  const standings = createStandings(
    config.kind,
    config.entries.map((entry) => entry.startSlot),
  )
  const state: SessionState = {
    config,
    track,
    gates: buildGates(track),
    sessionBestMs: null,
    tick: 0,
    phase: firstPhase(config.kind),
    rng,
    stepper,
    cars: [],
    inputs: [],
    env: [],
    kinematics: [],
    surfaces,
    drivers: [],
    race:
      config.kind === 'practice'
        ? null
        : {
            startFrom: from,
            places,
            bySlot: standings.order.slice(),
            timerCar: timerCarOf(config),
            pitStops,
            pitReminderTick: pitStops > 0 ? pitReminderTickOf(config.durationS) : null,
            pitOwn: pitLaneOwn(pitStops > 0 ? track : null),
            standings,
            finish: { allowanceFromTick: null },
            control: createRaceControlSchedule(),
            result: null,
            zoneHeldAtS: config.entries.map(() => -Infinity),
            told: [],
            finishedNow: [],
            stillOut: config.entries.map(() => ({ finished: false, outOfTime: false })),
          },
    pullOvers: [],
    bogged: [],
    rolled: [],
    rolledHow: [],
    pushedNow: config.entries.map(() => false),
    pushedBy: config.entries.map(() => -1),
    rollRng: rng.fork('rolls'),
    rollDraws: 0,
    touchingSolid: config.entries.map(() => false),
    shovedNow: config.entries.map(() => false),
    // The settings (F-508). Left out, the game as it was: penalties on, for the rules' five seconds, and reverse on.
    penaltyHoldS: config.penalties === undefined ? RULES.offTrackHoldS : config.penalties.enabled ? config.penalties.holdS : null,
    reverse: config.reverse !== false,
    marshals: createMarshalSystem(config.track.marshalPosts, rng.fork('marshals')),
    marshalWork: { tick: 0, calls: [], hit: [], told: [], surfaces: null },
    weather: createWeather(config.weather, config.track, rng.fork('weather')),
    traffic: { carsOnLine: 0 },
    lines: null,
    feltLine: null,
    inWater: config.entries.map(() => ({ dragN: 0, lateralGripScale: 1 })),
    marshalCtx: null,
    aiSees: [],
    marshalStandIns: [],
    contacts: [],
    before: config.entries.map(() => ({ at: { x: 0, y: 0 }, velocity: { x: 0, y: 0 } })),
    lastHitTick: Array.from({ length: config.entries.length * config.entries.length }, () => -Infinity),
    lastHitBy: Array.from({ length: config.entries.length * config.entries.length }, () => 0),
    incidents: createIncidentState(config.entries.length),
    view: {
      tick: 0,
      phase: firstPhase(config.kind),
      clockRemainingS: config.durationS,
      cars: [],
      // Every marker where the track has it (F-308); the stepper moves the ones that give.
      markers: config.track.markers.map((marker) => ({ x: marker.x, y: marker.y })),
      marshals: [],
      // The weather's own view (F-601), put in its place below, once there is a weather to ask.
      weather: { sky: config.weather.initialSky, rainIntensity: 0, wetness: 0, lineWetness: 0, wind: { x: 0, y: 0 }, puddles: [], cloudCover: 0 },
    },
    hashBuffer: [],
    tuned: false,
  }
  state.view.weather = state.weather.snapshot() as Mutable<SessionSnapshot>['weather']

  config.entries.forEach((entry, id) => {
    const slot = places[entry.startSlot]
    const onRoute = track.nearestRoute(slot.x, slot.y, routeHintOfPlace(slot, from, track))
    // An entry's own parameters (F-811), where it has them; its class's otherwise.
    stepper.add(id, config.carClass, { x: slot.x, y: slot.y, angle: slot.angle }, entry.params)
    state.cars.push({
      ...createCarTiming(onRoute.s),
      human: entry.controller === 'human',
      state: 'driving',
      stateSinceTick: 0,
      prev: { x: slot.x, y: slot.y },
      elapsedMs: 0,
      // A practice session has no order: its cars are numbered as they were entered. A race starts in the order of its start slots.
      position: config.kind === 'practice' ? id + 1 : standings.order.indexOf(id) + 1,
      gapAheadMs: null,
      surface: initialSurfaceState(),
      lane: laneUnder(track, slot, onRoute, 'lap'),
      place: { x: slot.x, y: slot.y, angle: slot.angle },
      releaseTick: releaseTickOf(config, entry.startSlot),
      droveEarly: false,
      holdOwed: false,
      shoved: false,
      clockStartMs: clockStartOf(config),
      raceMs: null,
      // Every car is on its way to the line: a whole lap less however far round it starts.
      sinceLineM: onRoute.s - track.lengthM,
      pitStopsOwed: pitStops,
      pitPlace: { x: slot.x, y: slot.y, angle: slot.angle },
      // A car that is put in the pit lane to start has not come into it.
      inPits: laneUnder(track, slot, onRoute, 'lap') === 'pit',
      pitStopping: false,
      offTrackTicks: 0,
      penaltyPlace: { x: slot.x, y: slot.y, angle: slot.angle },
      penaltyTicks: 0,
      heldBogged: false,
      strickenTick: 0,
      // A car that is put on the grass to start has not driven onto it.
      excursion: settled(track, slot, state.surfaces?.tuning.grass.edgeGraceM ?? 0),
      leftAt: { x: slot.x, y: slot.y },
      overIsland: false,
      pastBand: false,
      contactHits: 0,
      pitLeaveTicks: -1,
      movedOffTick: -1,
      liftPlace: { x: slot.x, y: slot.y, angle: slot.angle },
      strickenCause: null,
      wedgeTicks: 0,
      aquaplaning: false,
      wedgedAt: { x: slot.x, y: slot.y },
      slide: { fromMS: 0, lengthM: 0, turnRad: 0 },
      contactStopOwed: false,
      pushedTicks: 0,
      lifted: false,
      liftedAt: { x: slot.x, y: slot.y, angle: slot.angle },
      setDown: { x: slot.x, y: slot.y, angle: slot.angle },
      setDownRouteS: onRoute.s,
      setDownLane: 'lap',
    })
    state.inputs.push({ throttle: 0, brake: 0, steer: 0 })
    state.env.push(neutralEnvironment())
    state.kinematics.push({
      pose: { x: slot.x, y: slot.y, angle: slot.angle },
      velocity: { x: 0, y: 0 },
      yawRate: 0,
      steerRad: 0,
      throttle: 0,
      brake: 0,
      motorRadS: 0,
      slipFront: 0,
      slipRear: 0,
    })
    state.view.cars.push(blankCarSnapshot(id))
  })
  // The AI drivers (F-301), once every car is in the stepper: each gets its line and its own fork of the session's
  // randomness. And, in a race, what parks each car when it has finished (F-303).
  if (ai !== null) {
    const lines = createLineBook(track)
    state.lines = lines
    if (config.entries.some((entry) => entry.controller === 'ai')) state.drivers.push(...createAiDrivers(config, track, ai, state.rng, lines, pitStops))
    if (state.race !== null) state.pullOvers.push(...createPullOvers(config, ai, lines))
  }
  return state
}

function blankCarSnapshot(id: number): Mutable<CarSnapshot> {
  return {
    id,
    pose: { x: 0, y: 0, angle: 0 },
    velocity: { x: 0, y: 0 },
    speedMS: 0,
    yawRateRadS: 0,
    steerRad: 0,
    throttle: 0,
    brake: 0,
    motorRadS: 0,
    slipFront: 0,
    slipRear: 0,
    surface: 'asphalt',
    airborne: false,
    bog: 0,
    state: 'driving',
    stateSinceTick: 0,
    strickenCause: null,
    rollSlideTick: null,
    lap: 0,
    routeS: 0,
    lastLapMs: null,
    bestLapMs: null,
    lapStartMs: null,
    lapValid: true,
    elapsedMs: 0,
    position: id + 1,
    gapAheadMs: null,
    lane: 'lap',
    pitStopsOwed: 0,
    pitHoldRemainingS: null,
    offTrackS: 0,
    penaltyHoldRemainingS: null,
    holdOwed: false,
  }
}

/** A control value inside its legal range; anything that is not a number counts as released. */
function legal(value: number, min: number, max: number): number {
  return Number.isNaN(value) ? 0 : clamp(value, min, max)
}

/**
 * One tick, in the order fixed by architecture.md ("Tick order"): the phase (F-303); the weather (F-601); driver
 * inputs, the AI's among them (F-301); the ground under the cars; the cars themselves; incidents (F-302), and the
 * cars that have rolled over, bogged down or wedged (F-207, F-501); lap timing; and, in a race, the clocks, the
 * standings and the finish (F-303). Where pit stops are owed (F-306), a
 * car that has come into the stop zone owing one has its pedals taken in step 3 and, once at rest, is held in
 * step 6. Track limits (F-307, F-309) are the last thing settled in step 6.
 */
function advance(state: SessionState, human: Readonly<Record<number, ControlInput>>): readonly SimEvent[] {
  const tick = state.tick + 1
  let events: SimEvent[] | null = null
  const race = state.race

  // Phase (step 1). A practice session is running from its first tick; a race is staged, counted down, and runs
  // from the start tone. A phase is told on the first tick it is in.
  const phase = phaseAsStepStarts(state.config.kind, tick, state.phase)
  if (tick === 1 || phase !== state.phase) {
    state.phase = phase
    ;(events ??= []).push({ type: 'phase', tick, phase })
  }
  // Race control (F-404): the start calls fall with the phases. The clock calls wait for the end of the tick, when
  // the clocks have moved.
  if (race !== null) events = callRaceControl(state, race, tick, null, null, events)
  // A staggered start says when each car is let go.
  if (state.config.kind === 'qualifying') {
    for (let id = 0; id < state.cars.length; id++) {
      if (tick === state.cars[id].releaseTick + 1) (events ??= []).push({ type: 'car-released', tick, car: id })
    }
  }

  // Weather (step 2): the sky, the wetness, the puddles and the wind move on by a tick, and say what changed. All
  // they are told of the cars is how many are circulating as the tick starts, which dries the racing line.
  state.traffic.carsOnLine = carsCirculating(state, tick)
  const weatherTold = state.weather.update(tick, state.traffic)
  if (weatherTold.length > 0) {
    events ??= []
    for (const event of weatherTold) events.push(event)
  }

  // Driver inputs (step 3): the human's, and each AI driver's from what the session shows as the tick starts, all
  // limited to their legal range; a car nobody is driving, or that is on its roof, bogged down or held, has none; a
  // wedged car is still its driver's (F-501), unless the session has reverse off (F-508), when it is as helpless as
  // the rest. A car that has finished is parked by its controller, as every car is
  // once the session is over. A car that has not been
  // released is not driven: an AI driver is not asked, and a human's keys do nothing, except on the countdown,
  // when a human can creep forward and so jump the start (not backward: until its release a car has no reverse, F-508); one that has is stopped, and given nothing more until its release.
  // A car that owes a pit stop and has come into the stop zone keeps its driver's steering and is braked until it is
  // at rest, in the zone or beyond it (F-306).
  const seen = state.drivers.length > 0 || state.pullOvers.length > 0 ? fillSnapshot(state) : null
  const stopsOwed = race !== null && race.pitStops > 0 && (phase === 'running' || phase === 'time-up')
  // What the AI drivers go round: the cars, and the marshals who are out. Made on the first tick a driver is asked.
  let others: readonly CarSnapshot[] | null = null
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    const waiting = tick <= car.releaseTick
    // A car that has not been released cannot reverse, whatever the session's setting (F-508): a brake held on the
    // grid is only ever a brake, and backs nobody out of his box. Said only of a car that has ever waited: the
    // environment of a session in which nobody does is left as neutral as it was.
    const env = state.env[id]
    if (waiting || env.noReverse !== undefined) env.noReverse = waiting
    let given: ControlInput | undefined
    if (isHelpless(car, state.reverse) || car.state === 'held' || car.state === 'pit-hold' || car.state === 'penalty-hold' || car.state === 'lifted-out') given = undefined
    else if (car.state === 'finished' || phase === 'finished') given = seen === null ? undefined : state.pullOvers[id]?.control(seen.cars[id], seen.cars, state.weather.still ? DRY_GRIP : lineGrip(Math.max(seen.weather.wetness, seen.weather.lineWetness)))
    else if (waiting) given = car.human && phase === 'countdown' && !car.holdOwed ? human[id] : undefined
    else if (car.human) given = human[id]
    else if (seen !== null && (car.state === 'driving' || isWedged(car, state.reverse))) given = state.drivers[id]?.control(seen.cars[id], others ?? (others = withMarshals(state, seen)), state.weather.still ? DRY_GRIP : lineGrip(seen.weather.lineWetness), seen.clockRemainingS, state.weather.still ? undefined : seen.weather)
    const raw = given ?? NO_INPUT
    const input = state.inputs[id]
    input.throttle = legal(raw.throttle, 0, 1)
    input.brake = legal(raw.brake, 0, 1)
    input.steer = legal(raw.steer, -1, 1)
    if (waiting && (input.throttle > 0 || input.brake > 0)) car.droveEarly = true
    if (stopsOwed && !waiting && beingStopped(state, id)) {
      const kin = state.kinematics[id]
      brakeToRest(input, kin.velocity.x * Math.cos(kin.pose.angle) + kin.velocity.y * Math.sin(kin.pose.angle))
    }
  }

  // Vehicles and physics: first what is under each car, then the cars themselves. Where each car was and how it
  // was moving is kept for the step, for telling who ran into whom (F-309).
  if (state.surfaces !== null) events = groundUnderCars(state, state.surfaces, tick, phase !== 'finished', events)
  for (let id = 0; id < state.cars.length; id++) {
    const kin = state.kinematics[id]
    const was = state.before[id]
    was.at.x = kin.pose.x
    was.at.y = kin.pose.y
    was.velocity.x = kin.velocity.x
    was.velocity.y = kin.velocity.y
  }
  state.contacts.length = 0
  // The marshals who are out on the track are solid for the step (F-502), where they stood as the tick began.
  state.stepper.setMarshals?.(state.marshals.onTrack())
  state.stepper.step(state.inputs, state.env, state.kinematics, state.contacts)

  // Incidents (step 6): first what the step did (touches, spins, cars gone onto the grass), then the cars that are
  // out of their drivers' hands (F-207, F-501): the ones that rolled over, bogged down or wedged on this tick are
  // told so; they are held where they come to rest, and in time set back on the lane. Last, with every car's state settled,
  // track limits: a car that has stayed on a green island, or cut across one, is stopped and held (F-307, F-309).
  // Before that, the rules of F-309 that the others' outcome decides: a car that sits in the pit queue is lifted
  // out, a stop that is loitered over is void, and a driver who runs into other cars is warned and then stopped.
  events = noteIncidents(state, tick, events)
  if (state.surfaces !== null) events = settleStricken(state, state.surfaces, tick, phase !== 'finished', events)
  if (race !== null) events = settleStarts(state, tick, events)
  if (race !== null && race.startFrom === 'pit-lane' && (phase === 'running' || phase === 'time-up')) events = settleQueue(state, race, tick, events)
  if (race !== null && stopsOwed) {
    events = settlePitStops(state, race, tick, events)
    if (tick % PIT_WARN_EVERY_TICKS === 0) events = warnOfTakenPit(state, race, tick, events)
  }
  if (state.contacts.length > 0) events = settleContacts(state, tick, phase !== 'finished', events)
  // Only then is it settled whether another car rolled a car (F-507): the touch was its driver's to answer for while it was still on its wheels.
  if (state.surfaces !== null) events = rollStruckCars(state, state.surfaces, tick, phase !== 'finished', events)
  events = settleTrackLimits(state, tick, phase !== 'finished', events)

  // Lap timing (step 7): where each car's centre went this tick, against the gates. A car is timed from its
  // release until it has finished; once the session is over nobody is.
  const tickStartMs = ((tick - 1) * 1000) / TICK_RATE
  const lapM = state.track.lengthM
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    const pose = state.kinematics[id].pose
    const racing = car.state !== 'finished' && phase !== 'finished'
    const lapStartMs = car.lapStartMs
    const laps = car.lap
    if (racing && tick > car.releaseTick) {
      const made = updateTiming(car, state.gates, car.prev, pose, tickStartMs, {
        car: id,
        tick,
        sessionBestMs: state.sessionBestMs,
      })
      for (const event of made) {
        if (event.type === 'lap' && event.sessionBest) state.sessionBestMs = event.lapMs
        if (events === null) events = []
        events.push(event)
      }
    }
    car.prev.x = pose.x
    car.prev.y = pose.y
    const onRoute = state.track.nearestRoute(pose.x, pose.y, car.routeS)
    if (racing) {
      // How far round it came this tick, the short way: the route's distance wraps at the line.
      const moved = onRoute.s - car.routeS
      car.sinceLineM += moved > lapM / 2 ? moved - lapM : moved < -lapM / 2 ? moved + lapM : moved
    }
    car.routeS = onRoute.s
    car.lane = laneUnder(state.track, pose, onRoute, car.lane)
    // Off the lap and into the pit lane, where pit stops are owed (F-306): told once each time, when the car is
    // past where the pit lane leaves the lap's asphalt. A car that only runs wide across its mouth has not come in.
    if (race !== null && race.pitStops > 0) {
      if (car.lane === 'lap') car.inPits = false
      else if (!car.inPits) {
        const pitS = state.track.nearestPitRoute(pose.x, pose.y)?.s ?? -1
        if (pitS >= race.pitOwn.fromS && pitS <= race.pitOwn.toS) {
          car.inPits = true
          if (racing) (events ??= []).push({ type: 'pit-enter', tick, car: id })
        }
      }
    }
    // A new lap began on this tick: the car crossed the line going forward.
    if (race !== null && car.lapStartMs !== null && car.lapStartMs !== lapStartMs) events = crossedLine(state, race, id, car.lapStartMs, car.lap > laps, tick, events)
  }
  if (race !== null && (phase === 'running' || phase === 'time-up')) events = endOfRaceTick(state, race, tick, events)

  state.tick = tick
  return events ?? NO_EVENTS
}

/**
 * How many cars are circulating as `tick` starts (F-601): being driven, released, on the asphalt or a kerb, and
 * going at racing speed. The weather is told nothing else of the cars.
 */
function carsCirculating(state: SessionState, tick: Tick): number {
  let count = 0
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    if (car.state !== 'driving' || tick <= car.releaseTick || car.surface.lastSurface === 'grass') continue
    const { velocity } = state.kinematics[id]
    if (velocity.x * velocity.x + velocity.y * velocity.y >= CIRCULATING_MIN_MS2) count++
  }
  return count
}

/**
 * Starts and holds (F-303), once the cars have moved. A car that has left the box round its start place under
 * its own power before it was released has jumped the start: it is told so once, stopped where it is, and owes a
 * hold. A car that is being held is kept still; once it has been held for the rules' time it is its driver's again.
 *
 * Its own power (F-508): the throttle, since a car that has not been released has no reverse. A car that another
 * car or a marshal runs into before its release is moved by that, and for as long as it is, with its throttle
 * closed, its start place goes with it. So a driver who keeps to his
 * box and is pushed out of it has jumped nothing, whether or not he crept inside it first; and one who then drives
 * out of the box he has been pushed to has.
 */
function settleStarts(state: SessionState, tick: Tick, events: SimEvent[] | null): SimEvent[] | null {
  state.shovedNow.fill(false)
  for (const contact of state.contacts) {
    if (contact.b === 'marshal') state.shovedNow[contact.a] = true
    else if (typeof contact.b === 'number') state.shovedNow[contact.a] = state.shovedNow[contact.b] = true
  }
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    const kin = state.kinematics[id]
    // A car that has been lifted out of the pit queue (F-309) is not at its start place, and has not jumped anything.
    if (car.state === 'lifted-out') continue
    if (tick <= car.releaseTick && !car.holdOwed) {
      // The throttle is the one pedal that moves a car that has not been released: its brake is only a brake.
      if (state.inputs[id].throttle > 0) car.shoved = false
      else if (state.shovedNow[id]) car.shoved = true
      if (car.shoved) {
        car.place.x = kin.pose.x
        car.place.y = kin.pose.y
        car.place.angle = kin.pose.angle
        // At rest again and let alone: where it stands is its place from here on.
        if (!state.shovedNow[id] && Math.hypot(kin.velocity.x, kin.velocity.y) < RULES.shovedRestMS) car.shoved = false
      }
      if (car.droveEarly && outsideStartBox(kin.pose, car.place)) {
        car.holdOwed = true
        holdAt(state, id, kin.pose)
        ;(events ??= []).push({ type: 'jump-start', tick, car: id })
      }
    }
    if (car.state !== 'held') continue
    if (tick - car.stateSinceTick >= HOLD_TICKS) {
      car.state = 'driving'
      car.stateSinceTick = tick
    } else if (kin.velocity.x !== 0 || kin.velocity.y !== 0 || kin.yawRate !== 0) {
      holdAt(state, id, kin.pose)
    }
  }
  return events
}

/** Where along its pit route a track's pit lane is a lane of its own (F-306); nowhere on a track that has none, or when none is given. */
function pitLaneOwn(track: TrackRuntime | null): { fromS: number; toS: number } {
  const path = track === null ? null : pitPathOf(track)
  return path === null ? { fromS: Infinity, toS: -Infinity } : { fromS: path.ownFromS, toS: path.joinS }
}

/**
 * Whether car `id` is being stopped for a pit stop (F-306): it still owes one, is its driver's to drive, and has its
 * centre in the stop zone, or has had since it last stood still. Coming into the zone is what begins it, and it is
 * remembered: a car too fast to stop in the zone is braked on beyond it, and does not get its pedals back half-way.
 */
function beingStopped(state: SessionState, id: CarId): boolean {
  const car = state.cars[id]
  if (car.pitStopsOwed <= 0 || car.state !== 'driving') return false
  if (!car.pitStopping && inStopZone(state.track, car.lane, state.kinematics[id].pose)) car.pitStopping = true
  return car.pitStopping
}

/**
 * Pit stops (F-306), once the cars have moved. A car that is being stopped for its stop and has come to rest, in
 * the stop zone or beyond it, is held: it is told so, and kept exactly where it stands, whatever its driver presses
 * and whatever runs into it. Once it has been held for the rules' time the stop is counted and the car is its
 * driver's again.
 */
function settlePitStops(state: SessionState, race: RaceState, tick: Tick, events: SimEvent[] | null): SimEvent[] | null {
  // Who has the stop zone as the cars stand, before any of them is released or carried off on this tick: a car's
  // way out of the zone is judged against that, whatever order the cars are looked at in.
  for (let id = 0; id < state.cars.length; id++) race.zoneHeldAtS[id] = hasStopZone(state, id) ? pitSOf(state, id) : -Infinity
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    const kin = state.kinematics[id]
    if (car.state === 'pit-hold') {
      if (tick - car.stateSinceTick >= PIT_HOLD_TICKS) {
        car.state = 'driving'
        car.stateSinceTick = tick
        car.pitStopsOwed--
        // From here it has the rules' time to be out of the stop zone (F-309).
        car.pitLeaveTicks = 0
        ;(events ??= []).push({ type: 'pit-stop-done', tick, car: id })
      }
      // Still to the last tick of its hold: on the next it is driven from where it stood.
      const place = car.pitPlace
      if (kin.pose.x !== place.x || kin.pose.y !== place.y || kin.pose.angle !== place.angle || kin.velocity.x !== 0 || kin.velocity.y !== 0 || kin.yawRate !== 0) holdAt(state, id, place)
    } else if (tick > car.releaseTick && beingStopped(state, id) && Math.hypot(kin.velocity.x, kin.velocity.y) < RULES.pitRestMS) {
      car.state = 'pit-hold'
      car.stateSinceTick = tick
      car.pitStopping = false
      car.pitPlace.x = kin.pose.x
      car.pitPlace.y = kin.pose.y
      car.pitPlace.angle = kin.pose.angle
      holdAt(state, id, car.pitPlace)
      ;(events ??= []).push({ type: 'pit-stop-start', tick, car: id })
    } else if (car.pitLeaveTicks >= 0) {
      events = settleLeaving(state, race, id, tick, events)
    }
  }
  return events
}

/** Whether a car has the stop zone (F-309): it is being stopped for its stop, held for it, or its centre is in the zone. */
function hasStopZone(state: SessionState, id: CarId): boolean {
  const car = state.cars[id]
  return car.state === 'pit-hold' || car.pitStopping || inStopZone(state.track, car.lane, state.kinematics[id].pose)
}

/** How far along the pit route a car is, m; nothing on a track with no pit lane. */
function pitSOf(state: SessionState, id: CarId): number {
  const pose = state.kinematics[id].pose
  return state.track.nearestPitRoute(pose.x, pose.y)?.s ?? 0
}

/**
 * Loitering in the pit (F-309). A car that has been released from its stop is counted for each tick it is its
 * driver's with its centre still in the stop zone and nothing ahead of it there: a car that stands behind another
 * that still has the zone cannot leave, and is not counted. Out of the zone, by its own power or pushed, it has
 * left and its stop stands. Still in it when the rules' time is up, the stop is void: it owes one again and is put
 * back at rest at the pit lane's entry, as soon as there is room for it there. Being carried is not driving: lap
 * timing does not see the move, and a sector point it had passed in the pit lane is taken back, as it is for a car
 * that backs over one.
 */
function settleLeaving(state: SessionState, race: RaceState, id: CarId, tick: Tick, events: SimEvent[] | null): SimEvent[] | null {
  const car = state.cars[id]
  const track = state.track
  if (!inStopZone(track, car.lane, state.kinematics[id].pose)) {
    car.pitLeaveTicks = -1
    return events
  }
  if (car.state !== 'driving') return events
  const atS = pitSOf(state, id)
  for (let other = 0; other < state.cars.length; other++) {
    if (other !== id && race.zoneHeldAtS[other] > atS) return events
  }
  if (car.pitLeaveTicks < PIT_LEAVE_TICKS) car.pitLeaveTicks++
  if (car.pitLeaveTicks < PIT_LEAVE_TICKS) return events

  // The first place from the pit lane's entry on, short of the stop zone, that no other car stands in.
  const zone = track.data.pitLane?.stopZone
  const size = state.surfaces?.car(id)
  const clearM = size === undefined ? RULES.pitQueue.pitchM : Math.hypot(size.lengthM, size.widthM)
  let entry: Pose | null = null
  let entryS = race.pitOwn.fromS
  while (entry === null && zone !== undefined && entryS < zone.fromS - clearM) {
    const pose = track.pitRoutePose(entryS)
    if (pose !== null && track.inPitLane(pose.x, pose.y) && state.kinematics.every((kin, other) => other === id || Math.hypot(kin.pose.x - pose.x, kin.pose.y - pose.y) >= clearM)) entry = pose
    else entryS += clearM / 2
  }
  if (entry === null) return events

  car.pitLeaveTicks = -1
  car.pitStopsOwed++
  const sectors = state.gates.pit?.sectors
  for (const sector of [2, 1] as const) {
    const gate = sectors?.[sector - 1]
    if (gate === null || gate === undefined || car.lapStartMs === null || car.nextSector !== sector) continue
    const gateS = track.nearestPitRoute((gate.a.x + gate.b.x) / 2, (gate.a.y + gate.b.y) / 2)?.s ?? Infinity
    if (gateS > entryS && gateS <= atS) car.nextSector = sector === 2 ? 1 : 0
  }
  holdAt(state, id, entry)
  carried(state, id, track.nearestRoute(entry.x, entry.y, lapBesidePit(track, entryS)).s)
  events ??= []
  events.push({ type: 'pit-stop-void', tick, car: id })
  return events
}

/**
 * A car has been picked up and set down at its present pose (F-309): lap timing is not to see the move, so its last
 * place is its new one, and the session's figure for how far round it is, `routeS` now, takes the distance it has
 * come since the line with it.
 */
function carried(state: SessionState, id: CarId, routeS: number): void {
  const car = state.cars[id]
  const pose = state.kinematics[id].pose
  const lapM = state.track.lengthM
  const round = (((routeS - car.routeS) % lapM) + lapM) % lapM
  car.prev.x = pose.x
  car.prev.y = pose.y
  car.sinceLineM += round > lapM / 2 ? round - lapM : round
  car.routeS = routeS
}

/**
 * The pit is taken (F-309): told to every car that still owes a stop and is coming to it while another car has the
 * stop zone ahead of it. Coming to it is being its driver's and either on the lap within the rules' distance of
 * the pit entry, or in the pit lane behind the car that has the zone. It is told on a fixed beat, so that the view
 * can flash it, and needs nothing remembered.
 */
function warnOfTakenPit(state: SessionState, race: RaceState, tick: Tick, events: SimEvent[] | null): SimEvent[] | null {
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    if (car.pitStopsOwed <= 0 || car.state !== 'driving' || car.pitStopping || tick <= car.releaseTick) continue
    let fromS = -Infinity
    if (car.lane === 'pit') fromS = pitSOf(state, id)
    else if (!nearingPitEntry(state.track, car.routeS, race.pitOwn.fromS)) continue
    // The nearest car ahead that has the zone.
    let by = -1
    let byS = Infinity
    for (let other = 0; other < state.cars.length; other++) {
      if (other === id || !hasStopZone(state, other)) continue
      const otherS = pitSOf(state, other)
      if (otherS > fromS && otherS < byS) {
        by = other
        byS = otherS
      }
    }
    if (by >= 0) (events ??= []).push({ type: 'pit-occupied', tick, car: id, by })
  }
  return events
}

/**
 * Sitting in the pit queue (F-309), in a qualifying heat started from the pit lane. A car has moved off once it is
 * the rules' distance from its place. A car is free to go from its release, or from when the car in the slot ahead
 * of it moved off or was lifted out, whichever is later; one that has been free for the rules' time, has not moved
 * off and has a car still queued behind it is in the way. It is lifted out: set down beside the queue, off every
 * lane, and kept there, not released and not timed. When every other car has left the pit lane, the cars that were
 * lifted out are put back in the order they were lifted, from the head of the queue, and released there.
 */
function settleQueue(state: SessionState, race: RaceState, tick: Tick, events: SimEvent[] | null): SimEvent[] | null {
  // Once every car has moved off and none stands lifted out, the queue is history.
  let queued = false
  for (const car of state.cars) queued ||= car.movedOffTick < 0 || car.state === 'lifted-out'
  if (!queued) return events
  const lifted: CarId[] = []
  let othersGone = true
  let freeSince: Tick = -Infinity
  for (let n = 0; n < race.bySlot.length; n++) {
    const id = race.bySlot[n]
    const car = state.cars[id]
    const kin = state.kinematics[id]
    if (car.state === 'lifted-out') {
      if (!standsAt(kin, car.liftPlace)) holdAt(state, id, car.liftPlace)
      lifted.push(id)
      // Its place is empty from the tick it was lifted: the car behind is free from then.
      freeSince = Math.max(freeSince, car.movedOffTick)
      continue
    }
    if (car.movedOffTick < 0 && tick > car.releaseTick && Math.hypot(kin.pose.x - car.place.x, kin.pose.y - car.place.y) >= RULES.startBlockM) car.movedOffTick = tick
    if (car.movedOffTick < 0 || car.lane === 'pit') othersGone = false
    if (car.movedOffTick >= 0) {
      freeSince = Math.max(freeSince, car.movedOffTick)
      continue
    }
    // Still in its place. The cars behind it wait on it: none of them is free before it has gone.
    const since = Math.max(freeSince, car.releaseTick)
    freeSince = Infinity
    let queuedBehind = false
    for (let behind = n + 1; behind < race.bySlot.length; behind++) queuedBehind ||= state.cars[race.bySlot[behind]].movedOffTick < 0 && state.cars[race.bySlot[behind]].state !== 'lifted-out'
    if (car.state !== 'driving' || tick - since < START_BLOCK_TICKS || !queuedBehind) continue
    const aside = liftedOutPlace(state.track, car.place, state.cars.filter((other) => other.state === 'lifted-out').map((other) => other.liftPlace))
    car.liftPlace.x = aside.x
    car.liftPlace.y = aside.y
    car.liftPlace.angle = aside.angle
    car.state = 'lifted-out'
    car.stateSinceTick = tick
    car.movedOffTick = tick
    car.releaseTick = Infinity
    holdAt(state, id, car.liftPlace)
    carried(state, id, car.routeS)
    freeSince = tick
    events ??= []
    events.push({ type: 'start-blocked', tick, car: id })
  }
  if (lifted.length === 0 || !othersGone) return events

  // Back to the head of the queue, in the order they were lifted out, if nothing stands there now.
  lifted.sort((a, b) => state.cars[a].stateSinceTick - state.cars[b].stateSinceTick || a - b)
  const others = state.kinematics.filter((_, id) => state.cars[id].state !== 'lifted-out').map((kin) => kin.pose)
  if (lifted.some((_, n) => others.some((other) => Math.hypot(other.x - race.places[n].x, other.y - race.places[n].y) < RULES.pitQueue.pitchM))) return events
  lifted.forEach((id, n) => {
    const car = state.cars[id]
    const place = race.places[n]
    car.place.x = place.x
    car.place.y = place.y
    car.place.angle = place.angle
    holdAt(state, id, car.place)
    carried(state, id, state.track.nearestRoute(place.x, place.y, routeHintOfPlace(place, 'pit-lane', state.track)).s)
    car.lane = 'pit'
    car.surface = initialSurfaceState()
    car.state = 'driving'
    car.stateSinceTick = tick
    car.releaseTick = tick
    car.movedOffTick = -1
    car.droveEarly = false
    events ??= []
    events.push({ type: 'start-unblocked', tick, car: id })
  })
  return events
}

/**
 * Contact between cars (F-309), from what pressed on what during the step. A touch of the rules' impulse or more
 * is a hit, unless the same two cars had one counted within the rules' time. It counts against each of the two
 * that was closing on the other as the tick began, and is its driver's to drive: never against a car that was
 * struck from behind or standing still, nor one that is held, stuck, lifted out or finished. A driver is warned of
 * each hit up to the rules' number; the next stops the car where it is, for the settings' length, and starts the
 * count again. In a session with penalties off (F-508) no hit is counted, and nobody is warned or stopped.
 */
function settleContacts(state: SessionState, tick: Tick, racing: boolean, events: SimEvent[] | null): SimEvent[] | null {
  const holdS = state.penaltyHoldS
  if (holdS === null) return events
  const count = state.cars.length
  const answers = (id: CarId): boolean => racing && state.cars[id].state === 'driving' && tick > state.cars[id].releaseTick
  for (const contact of state.contacts) {
    if (typeof contact.b !== 'number' || contact.impulseNs < RULES.contactHitNs) continue
    const [first, second] = contact.a < contact.b ? [contact.a, contact.b] : [contact.b, contact.a]
    const pair = first * count + second
    if (tick - state.lastHitTick[pair] < CONTACT_AGAIN_TICKS) continue
    const ran = whoRanInto(state.before[first], state.before[second])
    const guilty: Array<readonly [CarId, CarId]> = []
    if (ran.a && answers(first)) guilty.push([first, second])
    if (ran.b && answers(second)) guilty.push([second, first])
    if (guilty.length === 0) continue
    state.lastHitTick[pair] = tick
    state.lastHitBy[pair] = 0
    for (const [id, other] of guilty) {
      state.lastHitBy[pair] |= id === first ? 1 : 2
      events = countHit(state, id, other, tick, holdS, events)
    }
  }
  return events
}

/**
 * One hit counted against car `id` for running into `other` (F-309), or for rolling it (F-512): a warning up to the
 * rules' number, and on the next the stop, where it is, with the count started again. A car that is on its roof when
 * its stop comes owes it, and is stopped the moment it is its driver's again (`serveOwedStops`).
 */
function countHit(state: SessionState, id: CarId, other: CarId, tick: Tick, holdS: number, events: SimEvent[] | null): SimEvent[] | null {
  const car = state.cars[id]
  car.contactHits++
  if (car.contactHits <= RULES.contactWarnings) {
    ;(events ??= []).push({ type: 'contact-warning', tick, car: id, other, warning: car.contactHits, of: RULES.contactWarnings })
    return events
  }
  car.contactHits = 0
  if (car.state === 'driving') return penalise(state, id, tick, 'contact', holdS, events)
  car.contactStopOwed = true
  return events
}

/**
 * A roll caused by another car counts one hit against the car that caused it (F-512): the car that ran in, side by
 * side; the car whose nose it was, nose into side; the car pushing, pushed. Not in a session with penalties off,
 * nor against a car that has not been let go or has finished, nor a second time for a touch that has counted
 * against that car already as a hit or as a roll: one touch counts once.
 */
function countRoll(state: SessionState, by: CarId, rolled: CarId, tick: Tick, racing: boolean, events: SimEvent[] | null): SimEvent[] | null {
  const holdS = state.penaltyHoldS
  const car = state.cars[by]
  if (holdS === null || by === rolled || !racing || tick <= car.releaseTick || (car.state !== 'driving' && car.state !== 'flipped')) return events
  const [first, second] = by < rolled ? [by, rolled] : [rolled, by]
  const pair = first * state.cars.length + second
  const bit = by === first ? 1 : 2
  const sameTouch = tick - state.lastHitTick[pair] < CONTACT_AGAIN_TICKS
  if (sameTouch && (state.lastHitBy[pair] & bit) !== 0) return events
  state.lastHitBy[pair] = sameTouch ? state.lastHitBy[pair] | bit : bit
  state.lastHitTick[pair] = tick
  return countHit(state, by, rolled, tick, holdS, events)
}

/** A car that owes a stop for contact (F-512) is stopped where it is on the first tick it is its driver's again. */
function serveOwedStops(state: SessionState, tick: Tick, events: SimEvent[] | null): SimEvent[] | null {
  const holdS = state.penaltyHoldS
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    if (!car.contactStopOwed || car.state !== 'driving') continue
    car.contactStopOwed = false
    if (holdS !== null) events = penalise(state, id, tick, 'contact', holdS, events)
  }
  return events
}

/**
 * Track limits (F-307, F-309), once the cars have moved and every other rule of the tick has had its say. Two
 * things are kept of a car that is its driver's to drive, from its release, while there is a session to race in
 * (`racing`): how many ticks running the ground the surfaces read under it (F-207, where it stood as the tick
 * began) was a green island, and its excursion off the lane.
 *
 * - **Staying on the green.** The tick that takes the count past the rules' limit it is stopped where it is.
 * - **Cutting.** The car's centre is followed along its move of the tick, by the surfaces' own outlines of the
 *   grass: an island is one however thin it is, grace band or no. Where the centre leaves a lane for an island an
 *   excursion begins, with the point of the edge it left over; over the surround it begins as it always did, once
 *   the surfaces read grass under the car. Where the centre is back on a lane the excursion is judged. It is a cut
 *   if any of the grass was a green island, the lane it came back to is on the far side of the grass from the edge
 *   it left, and that is further round the track. Back over the edge it left, or onto a lane behind, it is no cut;
 *   nor is one that never left the grace band of the edge it left, nor an excursion over the surround alone, nor
 *   one that was penalised on the green or ended with the car stuck and set back.
 *
 * A car that is stopped is held there for its penalty's time, the settings' length (F-508), whatever its driver
 * presses and whatever runs into it. In a session with penalties off no time on the green is counted and no cut is
 * penalised; a car's excursion is followed all the same, since that is also what keeps the session's figure for how
 * far round a car is right when it crosses from one stretch of the lap to another.
 */
function settleTrackLimits(state: SessionState, tick: Tick, racing: boolean, events: SimEvent[] | null): SimEvent[] | null {
  const graceM = state.surfaces?.tuning.grass.edgeGraceM ?? 0
  const holdS = state.penaltyHoldS
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    const kin = state.kinematics[id]
    if (car.state === 'penalty-hold') {
      if (tick - car.stateSinceTick >= car.penaltyTicks) events = endPenalty(state, id, tick, events)
      else if (!standsAt(kin, car.penaltyPlace)) holdAt(state, id, car.penaltyPlace)
      continue
    }
    const answers = racing && car.state === 'driving' && tick > car.releaseTick
    car.offTrackTicks = holdS !== null && answers && onIsland(state.track, car.surface.lastSurface, car.prev) ? car.offTrackTicks + 1 : 0
    if (holdS !== null && car.offTrackTicks > OFF_TRACK_LIMIT_TICKS) events = penalise(state, id, tick, 'off-track', holdS, events)
    else if (!answers) car.excursion = settled(state.track, kin.pose, graceM)
    else if (state.surfaces !== null && cutOnTheWay(state, id, graceM) && holdS !== null) {
      events = penalise(state, id, tick, 'cut-track', holdS, events)
      // The ground the surfaces read under it this tick was the grass it came over. It stands on the lane.
      car.surface = stepSurface(car.surface, standingAt(state.surfaces, id, car.penaltyPlace), state.track, state.surfaces.tuning, tick, id).state
    }
  }
  return events
}

/** A car at rest at `place`, as the surfaces are asked about it. */
function standingAt(surfaces: SurfaceSetup, id: CarId, place: Readonly<Pose>): SurfaceCar {
  const size = surfaces.car(id)
  return { pose: place, velocity: AT_REST, massKg: size.massKg, cgToFrontAxleM: size.cgToFrontAxleM, cgToRearAxleM: size.cgToRearAxleM, widthM: size.widthM }
}

/**
 * Follows a car's centre along its move of this tick (F-309), from where it stood as the tick began to where it is,
 * and says whether it cut the track on the way: whether it came back onto a lane on the far side of an island it
 * had driven onto, further round than it left. A car that has crossed from one stretch of the lap to another, or
 * into the pit lane, is not where the session's own figure for it, which follows a car along the stretch it is on,
 * would look for it: that figure is put right, and the distance the car has come since the line with it.
 */
function cutOnTheWay(state: SessionState, id: CarId, graceM: number): boolean {
  const car = state.cars[id]
  const track = state.track
  const to = state.kinematics[id].pose
  // Over the surround an excursion begins once the surfaces read grass under the car, where it stood as the tick
  // began: it is past the grace band of the edge it left, and that is the edge nearest to it.
  if (car.excursion === ON_A_LANE && car.surface.lastSurface === 'grass' && isGrass(track, car.prev.x, car.prev.y)) beginExcursion(car, nearestLaneEdge(track, car.prev))
  const steps = Math.max(1, Math.ceil(Math.hypot(to.x - car.prev.x, to.y - car.prev.y) / FOLLOW_STEP_M))
  let wasX = car.prev.x
  let wasY = car.prev.y
  for (let step = 1; step <= steps; step++) {
    const x = car.prev.x + ((to.x - car.prev.x) * step) / steps
    const y = car.prev.y + ((to.y - car.prev.y) * step) / steps
    if (isGrass(track, x, y)) {
      const island = track.grassLookAt(x, y) === 'infield'
      // Over an island it begins at the island's own outline; or, for a car that came onto the island from the
      // surround within the grace band of a lane, at that lane's edge.
      if (car.excursion === ON_A_LANE && island) beginExcursion(car, isGrass(track, wasX, wasY) ? nearestLaneEdge(track, { x: wasX, y: wasY }) : edgeBetween(track, { x: wasX, y: wasY }, { x, y }))
      if (car.excursion === OFF_TO_BE_JUDGED) {
        if (island) car.overIsland = true
        if (!car.pastBand && track.distanceOffLane(x, y) > graceM) car.pastBand = true
      }
    } else if (car.excursion !== ON_A_LANE) {
      const back = edgePointAt(track, edgeBetween(track, { x, y }, { x: wasX, y: wasY }))
      // A seam where two pieces of grass meet is no lane: the car is on the grass still, as it was a step ago.
      if (back === null && onASeam(track, { x, y })) continue
      const judged = car.excursion === OFF_TO_BE_JUDGED
      car.excursion = ON_A_LANE
      if (back === null || !judged) {
        // Set down or held on the grass, and off it now wherever that is.
        followFrom(state, id, back === null ? lanePlaceOf(track, { x, y }) : back.place, x, y)
      } else {
        const crossing = crossingBetween(track, edgePointAt(track, car.leftAt), back, graceM, car.pastBand)
        if (crossing.farSide) followFrom(state, id, back.place, x, y)
        if (car.overIsland && isCut(track, crossing)) return true
      }
    }
    wasX = x
    wasY = y
  }
  return false
}

/** A car's centre has left a lane over the point `edge` of its edge: an excursion to be judged when it is back on one. */
function beginExcursion(car: CarRecord, edge: Readonly<Vec2>): void {
  car.excursion = OFF_TO_BE_JUDGED
  car.leftAt.x = edge.x
  car.leftAt.y = edge.y
  car.overIsland = false
  car.pastBand = false
}

/**
 * Where a car that is not to be judged stands with the cut rule: off the lane, and answered for, if its centre is
 * on an island, or on the surround past the grace band; otherwise on a lane.
 */
function settled(track: TrackRuntime, pose: Readonly<Pose>, graceM: number): Excursion {
  if (!isGrass(track, pose.x, pose.y)) return ON_A_LANE
  return track.grassLookAt(pose.x, pose.y) === 'infield' || track.distanceOffLane(pose.x, pose.y) > graceM ? OFF_AND_SETTLED : ON_A_LANE
}

/** Puts the session's figure for how far round a car is onto the lane place it has come out at, and the distance it has come since the line with it. */
function followFrom(state: SessionState, id: CarId, place: Readonly<LanePlace>, x: number, y: number): void {
  const car = state.cars[id]
  const track = state.track
  const routeS = place.lane === 'lap' ? place.at : track.nearestRoute(x, y, lapBesidePit(track, place.at)).s
  const lapM = track.lengthM
  const round = (((routeS - car.routeS) % lapM) + lapM) % lapM
  car.sinceLineM += round > lapM / 2 ? round - lapM : round
  car.routeS = routeS
}

/** Whether a car is at rest exactly at `place`. */
function standsAt(kin: Readonly<CarKinematics>, place: Readonly<Pose>): boolean {
  return kin.pose.x === place.x && kin.pose.y === place.y && kin.pose.angle === place.angle && kin.velocity.x === 0 && kin.velocity.y === 0 && kin.yawRate === 0
}

/** Stops a car where it is and holds it there for `holdS` (F-307): it is told why, and is its driver's no longer until the hold is over. */
function penalise(state: SessionState, id: CarId, tick: Tick, reason: PenaltyReason, holdS: number, events: SimEvent[] | null): SimEvent[] {
  const car = state.cars[id]
  const kin = state.kinematics[id]
  car.offTrackTicks = 0
  // Stopped on the grass, it has answered for being there; stopped on a lane, it is on a lane.
  car.excursion = settled(state.track, kin.pose, state.surfaces?.tuning.grass.edgeGraceM ?? 0)
  car.state = 'penalty-hold'
  car.stateSinceTick = tick
  car.penaltyTicks = Math.round(holdS * TICK_RATE)
  car.penaltyPlace.x = kin.pose.x
  car.penaltyPlace.y = kin.pose.y
  car.penaltyPlace.angle = kin.pose.angle
  holdAt(state, id, car.penaltyPlace)
  events ??= []
  events.push({ type: 'penalty', tick, car: id, reason, holdS })
  return events
}

/**
 * The end of a penalty's hold. The car is still to the last tick of it, and on the next is driven from where it
 * stood: unless the grass has hold of it there (F-309), by the same test the surfaces use to call a car stuck. A
 * marshal was sent for such a car as its hold began (F-502), and if he has set it down on the lane by now it is
 * driven from there. If he has not, it is stuck as any bogged car is, and told so, until he has.
 */
function endPenalty(state: SessionState, id: CarId, tick: Tick, events: SimEvent[] | null): SimEvent[] {
  const car = state.cars[id]
  car.state = 'driving'
  car.stateSinceTick = tick
  if (!standsAt(state.kinematics[id], car.penaltyPlace)) holdAt(state, id, car.penaltyPlace)
  events ??= []
  events.push({ type: 'penalty-served', tick, car: id })
  const surfaces = state.surfaces
  if (surfaces === null) return events
  if (car.heldBogged) {
    // The marshal who was sent as the hold began has not set it down yet: it is stuck, as it has been in all but
    // name, and is counted so from when it was stopped. If he has reached it, he has it.
    const since = car.strickenTick
    car.heldBogged = false
    events = stick(state, id, 'grass', tick, events)
    car.strickenTick = since
    if (state.marshals.hasInHand(id)) car.state = 'being-marshalled'
    return events
  }
  if (!stepSurface(car.surface, standingAt(surfaces, id, car.penaltyPlace), state.track, surfaces.tuning, tick, id).stuck) return events
  return stick(state, id, 'grass', tick, events)
}

/**
 * A car of a race has crossed the line going forward, at `atMs` of session time (F-303). In qualifying the first
 * crossing starts the car's clock. A car that jumped the start is stopped there and held. A car whose time was up
 * as it crossed has finished: it is its driver's no longer, and it is timed no more.
 */
function crossedLine(state: SessionState, race: RaceState, id: CarId, atMs: number, counted: boolean, tick: Tick, events: SimEvent[] | null): SimEvent[] | null {
  const car = state.cars[id]
  const lapM = state.track.lengthM
  car.sinceLineM = car.routeS > lapM / 2 ? car.routeS - lapM : car.routeS
  car.clockStartMs ??= atMs
  if (counted) car.raceMs = atMs - car.clockStartMs
  if (car.holdOwed) {
    car.holdOwed = false
    car.state = 'held'
    car.stateSinceTick = tick
    holdAt(state, id, state.kinematics[id].pose)
    ;(events ??= []).push({ type: 'hold', tick, car: id, seconds: RULES.holdS })
  } else if (timeIsUp(car.clockStartMs, atMs, state.config.durationS)) {
    car.state = 'finished'
    car.stateSinceTick = tick
    car.elapsedMs = clockMs(car.clockStartMs, atMs)
    race.finishedNow.push(id)
  }
  return events
}

/**
 * The end of a tick of a race that is under way (F-303): the clocks, the standings and their events, the cars
 * that finished on this tick, time running out, and the session's own finish.
 */
function endOfRaceTick(state: SessionState, race: RaceState, tick: Tick, events: SimEvent[] | null): SimEvent[] | null {
  const { kind, durationS } = state.config
  const nowMs = msOfTick(tick)
  const told = race.told
  told.length = 0
  for (const car of state.cars) {
    // A clock that no crossing of the line has started is started for the car, so long after its release: nothing
    // else is changed by it, and no lap is begun. A car that stands lifted out of the pit queue (F-309) has no
    // release to count from until it is put back: for as long as it stands there, it is counted from when it was
    // lifted, so that a heat ends even if the pit lane never clears.
    const latestTick = (car.state === 'lifted-out' ? car.stateSinceTick : car.releaseTick) + CLOCK_START_LATEST_TICKS
    if (car.clockStartMs === null && tick >= latestTick) car.clockStartMs = msOfTick(latestTick)
    if (car.state !== 'finished') car.elapsedMs = clockMs(car.clockStartMs, nowMs)
  }

  // With a minute left, a car that still owes its pit stop and is not serving it is reminded (F-306).
  if (tick === race.pitReminderTick) {
    state.cars.forEach((car, id) => {
      if (car.pitStopsOwed > 0 && car.state !== 'pit-hold' && car.state !== 'finished') told.push({ type: 'pit-reminder', tick, car: id, clockRemainingS: RULES.pitReminderAtS })
    })
  }

  placeCars(race.standings, state.cars, kind, tick, told)
  if (kind === 'final') measureGaps(race.standings, state.cars, state.track.lengthM, tick)
  for (const id of race.finishedNow) {
    const car = state.cars[id]
    told.push({ type: 'car-finished', tick, car: id, laps: car.lap, timeMs: car.raceMs === null ? 0 : Math.round(car.raceMs), position: car.position })
  }

  // Time is up for the session when the first clock reaches its length; race control calls it when the clock on
  // screen does. In a final those are one clock.
  if (state.phase === 'running' && state.cars.some((car) => timeIsUp(car.clockStartMs, nowMs, durationS))) {
    state.phase = 'time-up'
    told.push({ type: 'phase', tick, phase: 'time-up' })
  }
  // The clock calls (halfway, the last minute, time up) follow the clock on screen. They are told in `told`, among
  // this tick's other events, after the phase's own.
  const clockStartMs = timerClockOf(state, race)
  const onScreenS = clockStartMs === null ? null : remainingS(clockStartMs, nowMs, durationS)
  callRaceControl(state, race, tick, onScreenS, null, told)
  if (state.phase === 'time-up') {
    state.cars.forEach((car, id) => {
      race.stillOut[id].finished = car.state === 'finished'
      race.stillOut[id].outOfTime = timeIsUp(car.clockStartMs, nowMs, durationS)
    })
    if (sessionOver(race.finish, race.stillOut, race.finishedNow.length > 0, tick)) {
      state.phase = 'finished'
      race.result = buildResult(
        state.config,
        state.cars.map((car, id) => {
          const entry = state.config.entries[id]
          return { carId: id, driverId: entry.driverId, number: entry.number, startSlot: entry.startSlot, laps: car.lap, raceMs: car.raceMs, bestLapMs: car.bestLapMs, finished: car.state === 'finished', pitStopsMissed: car.pitStopsOwed }
        }),
      )
      // What the next session of the event begins with (F-601): the weather as it stands, after the pause between two sessions.
      race.result.weatherNext = state.weather.carryOver(WEATHER_TUNING.carryOver.gapS)
      told.push({ type: 'phase', tick, phase: 'finished' })
      callRaceControl(state, race, tick, onScreenS, tick, told)
      told.push({ type: 'session-finished', tick })
    }
  }
  race.finishedNow.length = 0
  if (told.length === 0) return events
  events ??= []
  for (const event of told) events.push(event)
  return events
}

/**
 * Asks race control (F-404) for the calls that have fallen due at the end of `tick`, and tells them: into `events` if
 * given one, else a new list; the list they went into is returned. `onScreenS` is what the clock on screen reads, or
 * null before it has started or where the clocks have not moved yet; `finishedTick` is the tick the session finished
 * on, once it has.
 */
function callRaceControl(state: SessionState, race: RaceState, tick: Tick, onScreenS: number | null, finishedTick: Tick | null, events: SimEvent[] | null): SimEvent[] | null {
  const { kind, durationS } = state.config
  const calls = race.control.due({ tick, phase: state.phase, phaseTick: tick - phaseStartTick(state.phase), kind, durationS, referenceClockS: onScreenS, allFinishedTick: finishedTick, skyChangedTick: state.weather.skyChangedTick })
  for (const call of calls) (events ??= []).push({ type: 'race-control', tick, call })
  return events
}

/** When the clock the on-screen timer shows started: the shared one in a final, the timer car's own in qualifying. */
function timerClockOf(state: SessionState, race: RaceState): number | null {
  return state.cars[state.config.kind === 'final' ? 0 : race.timerCar].clockStartMs
}

/**
 * Step 4, before the vehicle model: what is under each car's centre, and so what its tyres have to work with on
 * this tick (F-207). A car that bogs down on this tick is noted in `state.bogged`, and one that a kerb rolls
 * (F-507) in `state.rolled`; they become stuck and flipped in step 6. A car standing for a penalty (F-307) is kept
 * where it is: it is given what a stuck car is, and what the surfaces remember of it stays as it was when it was
 * stopped, so the grass cannot call it stuck while it stands. Whether the grass has hold of it is asked on the tick
 * it is let go (F-309). A car lifted out of the pit queue (F-309) stands on the grass on purpose, and is left alone
 * in the same way. A car on its roof has nothing under its tyres at all, from the tick it goes over. A wedged car
 * is on the ground as any driven car is: it has to be able to drive out. Unless the session has reverse off (F-508):
 * then it cannot, and is held as a bogged car is.
 *
 * The weather (F-602) is what else a car on its wheels has under and round it: the wetness where it is (the racing
 * line's on the line, the surface's off it), which the surface step turns into grip; the water it stands in, which
 * drags at it and, met fast enough, floats it until it is out; and the wind, on a car that is being raced. A car
 * that is out of its driver's hands or held has none of the three. In a session with no weather to feel (`still`) nothing
 * of this is asked, and every car is stepped as it was before there was weather.
 */
function groundUnderCars(state: SessionState, surfaces: SurfaceSetup, tick: Tick, racing: boolean, events: SimEvent[] | null): SimEvent[] | null {
  const weather = state.weather.still ? null : state.weather.snapshot()
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    const kin = state.kinematics[id]
    const size = surfaces.car(id)
    const massKg = size.massKg
    const env = state.env[id]
    let ground: SurfaceEnvironment
    let inWater: StepEnvironment['puddle'] = null
    let windX = 0
    let windY = 0
    let wetGrip = 1
    // The yaw rate a car on its roof is held to (F-507); any other car turns as its tyres turn it.
    let yawRateRadS: number | null = null
    if (car.state === 'flipped') {
      const rolled = rolledEnvironment(massKg, car.slide, (tick - car.stateSinceTick) / TICK_RATE, surfaces.tuning.roll)
      ground = rolled
      yawRateRadS = rolled.yawRateRadS
      car.aquaplaning = false
    } else if (isHelpless(car, state.reverse) || car.state === 'penalty-hold' || car.state === 'lifted-out') {
      ground = stuckEnvironment(massKg, surfaces.tuning)
      car.aquaplaning = false
    } else {
      const body: SurfaceCar = { pose: kin.pose, velocity: kin.velocity, yawRateRadS: kin.yawRate, massKg, cgToFrontAxleM: size.cgToFrontAxleM, cgToRearAxleM: size.cgToRearAxleM, widthM: size.widthM }
      // Only a car that is being driven can be rolled: any other is given no shape to roll by, and hops.
      if (isDriven(car, tick, racing)) body.stabilityFactor = size.stabilityFactor
      const wetness = weather === null ? 0 : wetnessUnder(state, weather, kin.pose, car.routeS, size.widthM)
      const step = stepSurface(car.surface, body, state.track, surfaces.tuning, tick, id, wetness)
      car.surface = step.state
      if (step.rolled !== null) {
        // It goes over on this tick, from the speed it has now: its slide is drawn now.
        car.slide = drawSlide(state, surfaces.tuning.roll, kin.velocity)
        const rolled = rolledEnvironment(massKg, car.slide, 0, surfaces.tuning.roll)
        ground = rolled
        yawRateRadS = rolled.yawRateRadS
        state.rolled.push(id)
        state.rolledHow.push(step.rolled)
      } else {
        ground = step.env
        if (step.stuck) state.bogged.push(id)
      }
      for (const event of step.events) (events ??= []).push(event)
      // The wet part of the grip under the car by itself: what the tyres' scrub at walking pace goes with.
      if (wetness > 0) wetGrip = wetGripFactor(step.state.lastSurface, wetness)

      if (weather !== null && !step.rolled) {
        // Standing water, for a car whose tyres are on the ground and not in the grass.
        const water = ground.airborne || step.state.lastSurface === 'grass' ? null : puddleAt(weather, kin.pose.x, kin.pose.y)
        if (water === null) car.aquaplaning = false
        else {
          const effect = puddleEffect(water.depth, Math.hypot(kin.velocity.x, kin.velocity.y), size)
          if (effect.aquaplaning && !car.aquaplaning) {
            car.aquaplaning = true
            ;(events ??= []).push({ type: 'aquaplane', tick, car: id })
          }
          inWater = state.inWater[id]
          inWater.dragN = effect.dragN
          // Once it floats it floats until it is out of the water, however much the water slows it.
          inWater.lateralGripScale = car.aquaplaning ? WEATHER_TUNING.water.aquaplaneSideGrip : 1
        }
        // The wind, on a car that is being raced: not one waiting to be let go, nor one that has finished and is being parked.
        if (car.state === 'driving' && tick > car.releaseTick) {
          windX = weather.wind.x
          windY = weather.wind.y
        }
      } else car.aquaplaning = false
    }
    env.grip = ground.grip
    env.dragN = ground.dragN
    env.airborne = ground.airborne
    env.steerScale = ground.steerScale
    env.yawRateRadS = yawRateRadS
    env.puddle = inWater
    env.wind.x = windX
    env.wind.y = windY
    if (weather !== null) env.wetGrip = wetGrip
  }
  return events
}

/**
 * How wet the ground is under a car's centre (F-602): the surface's wetness, or nearer the racing line the line's
 * own, which the cars' tyres have dried. The line is looked for only while the two differ.
 */
function wetnessUnder(state: SessionState, weather: Readonly<SessionSnapshot['weather']>, pose: Readonly<Pose>, routeS: number, carWidthM: number): number {
  if (weather.lineWetness === weather.wetness) return weather.wetness
  const line = (state.feltLine ??= state.lines === null ? buildRacingLine(state.track, carWidthM) : state.lines.line(carWidthM, DEFAULT_LINE_STYLE))
  // The line is looked for on the stretch abeam of where the car is on the lap, not where another stretch runs close by.
  return localWetness(weather, line.nearest(pose.x, pose.y, line.sAtRoute(routeS)).lateralM)
}

/**
 * Whether a car is out of its driver's hands and waiting to be fetched (F-501): on its roof, being seen to, or stuck
 * in a way it cannot drive out of. That is bogged down; and wedged too where the cars have no `reverse` (F-508).
 */
function isHelpless(car: Readonly<CarRecord>, reverse: boolean): boolean {
  return car.state === 'flipped' || car.state === 'being-marshalled' || (car.state === 'stuck' && (car.strickenCause !== 'wedged' || !reverse))
}

/** Whether a car is wedged and still its driver's to get out (F-501): told as stuck, in a session whose cars have `reverse`. */
function isWedged(car: Readonly<CarRecord>, reverse: boolean): boolean {
  return reverse && car.state === 'stuck' && car.strickenCause === 'wedged'
}

/**
 * Whether a car is being driven, which is what it takes to roll one or to wedge one (F-501): its driver's, released,
 * in a session that is still on. Not one that is finished, held, standing for a pit stop or a penalty, lifted out,
 * stuck, or on its roof already.
 */
function isDriven(car: Readonly<CarRecord>, tick: Tick, racing: boolean): boolean {
  return racing && car.state === 'driving' && tick > car.releaseTick
}

/**
 * Step 6, as soon as the cars have moved (F-302): the `contact`, `spin` and `off-track` events of this tick. A car
 * is off the track when the ground under its centre, as step 4 found it, is grass.
 */
function noteIncidents(state: SessionState, tick: Tick, events: SimEvent[] | null): SimEvent[] | null {
  if (state.contacts.length > 0) reportContacts(state.incidents, state.contacts, tick, (events ??= []))
  for (let id = 0; id < state.cars.length; id++) {
    const kin = state.kinematics[id]
    if (hasSpun(state.incidents, id, kin.pose, kin.velocity)) (events ??= []).push({ type: 'spin', tick, car: id })
    const surface = state.cars[id].surface.lastSurface
    if (hasLeftTrack(state.incidents, id, surface)) (events ??= []).push({ type: 'off-track', tick, car: id, surface })
  }
  return events
}

/**
 * Step 6, after the cars have moved (F-207, F-501): the cars that are out of their drivers' hands. In order:
 *
 * 1. **Struck down on this tick.** A car that a kerb rolled is on its roof (F-507). A car that bogged down is stuck. A
 *    car that has been jammed against a wall or a tyre for the tuning's time with its driver trying to move it is
 *    wedged: stuck too, but still its driver's. Each is told once, on this tick. Only a car that is being driven
 *    (`isDriven`) can roll or wedge. A car that another car rolls goes over later in step 6, once the
 *    contact rule has had its say (`rollStruckCars`), and is first seen here on the next tick.
 * 2. **While it waits.** A car on its roof or bogged down that has all but stopped is held still, and again
 *    whenever something moves it; one a marshal has is kept exactly where he has it. A wedged car that has got clear
 *    of where it wedged is its driver's again, with nothing told; with reverse off (F-508) it waits as a bogged car does. A car stopped for a penalty where the grass has hold
 *    of it is marked as one to be fetched, on the tick after it was stopped.
 * 3. **Fetched.** The marshals are told which cars are waiting, and do the rest (`fetchStricken`, F-502).
 */
function settleStricken(state: SessionState, surfaces: SurfaceSetup, tick: Tick, racing: boolean, events: SimEvent[] | null): SimEvent[] | null {
  // A car a kerb rolled began its slide before the cars moved, from the speed it went over at.
  for (let i = 0; i < state.rolled.length; i++) events = flip(state, state.rolled[i], state.rolledHow[i], tick, events, false)
  state.rolled.length = 0
  state.rolledHow.length = 0
  for (const id of state.bogged) {
    const car = state.cars[id]
    // A car that has finished stays finished wherever it has come to rest; one that went over on this tick is on its roof.
    if (car.state === 'finished' || car.state === 'flipped') continue
    events = stick(state, id, 'grass', tick, events)
  }
  state.bogged.length = 0
  events = wedgeJammedCars(state, tick, racing, events)

  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    const kin = state.kinematics[id]
    if (car.state === 'penalty-hold') {
      // Stopped for a penalty on the tick before: if the grass has hold of it where it stands, it is as good as stuck already.
      if (tick === car.stateSinceTick + 1 && stepSurface(car.surface, standingAt(surfaces, id, car.penaltyPlace), state.track, surfaces.tuning, tick, id).stuck) {
        car.heldBogged = true
        car.strickenTick = car.stateSinceTick
      }
    } else if (isWedged(car, state.reverse)) {
      if (hasWorkedFree(car.wedgedAt, kin.pose)) {
        car.state = 'driving'
        car.stateSinceTick = tick
        car.strickenCause = null
      }
    } else if (car.state === 'flipped' || car.state === 'stuck' || car.state === 'being-marshalled') {
      // A car a marshal has is kept exactly where it is; one that is waiting for him is held once it has all but stopped,
      // and one on its roof not before its slide is over (F-512): it slows to rest at the end of it by itself.
      const restMS = car.state === 'being-marshalled' ? Infinity : car.state === 'flipped' ? INCIDENT_TUNING.flipped.restMS : surfaces.tuning.grass.stuckBelowMS
      const sliding = car.state === 'flipped' && (tick - car.stateSinceTick) / TICK_RATE < surfaces.tuning.roll.goingOverS + surfaces.tuning.roll.slideTimeS
      if (!sliding && Math.hypot(kin.velocity.x, kin.velocity.y) < restMS && (kin.velocity.x !== 0 || kin.velocity.y !== 0 || kin.yawRate !== 0)) holdAt(state, id, kin.pose)
    }
  }
  return fetchStricken(state, surfaces, tick, events)
}

/** Whether a car wants a marshal (F-502): on its roof, stuck, in a marshal's hands, or stopped for a penalty where the grass has it. */
function wantsFetching(car: Readonly<CarRecord>): boolean {
  return car.state === 'flipped' || car.state === 'stuck' || car.state === 'being-marshalled' || (car.state === 'penalty-hold' && car.heldBogged)
}

/**
 * The marshals (F-502), once every car's state is settled for the tick. They are told which cars want fetching and
 * where each is (a car stuck in the grass round the outside of the track, off every island, is run to), and which
 * of them a car ran into during the step; they give out the work and move, and what they ask for is done here: a car
 * that is reached is its marshal's; when he lifts it he is told where it goes, by the recovery rule, and it moves
 * with him at each step he takes (F-508); and one that is put down there is set on the lane. Last, the fail-safe: a
 * car that nobody has righted `failSafeS` after it was stricken is set back regardless.
 */
function fetchStricken(state: SessionState, surfaces: SurfaceSetup, tick: Tick, events: SimEvent[] | null): SimEvent[] | null {
  const work = state.marshalWork
  work.tick = tick
  work.surfaces = surfaces
  work.calls.length = 0
  work.hit.length = 0
  work.told.length = 0
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    if (!wantsFetching(car)) continue
    const pose = state.kinematics[id].pose
    const inGrass = car.strickenCause === 'grass' || car.state === 'penalty-hold'
    const look = inGrass ? state.track.grassLookAt(pose.x, pose.y) : null
    // Where its lane is from it, for a car still waiting to be lifted (F-508): the marshal goes to its far side from there.
    const call: MarshalCall = { car: id, at: pose, run: look !== null && look !== 'infield' }
    if (!car.lifted) call.lane = laneFor(state, surfaces, id, { pose, routeS: car.routeS, lane: car.lane }, null, false).pose
    work.calls.push(call)
  }
  // A marshal flinches from a car that runs into him: not from the stricken car he is standing over, and not from
  // a car that was standing in his way when he walked into it (F-508), which holds nobody up.
  for (const contact of state.contacts) if (contact.b === 'marshal' && contact.marshal !== undefined && !wantsFetching(state.cars[contact.a]) && ranInto(state, contact.a, contact.marshal)) work.hit.push(contact.marshal)
  state.marshals.update((state.marshalCtx ??= marshalContextOf(state)))
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    if (!wantsFetching(car) || tick - car.strickenTick < FAIL_SAFE_TICKS) continue
    if (car.state === 'penalty-hold') setDownStillHeld(state, surfaces, id)
    else setBackOnLane(state, surfaces, id, tick)
  }
  if (work.told.length === 0) return events
  events ??= []
  for (const event of work.told) events.push(event)
  return events
}

/**
 * Whether a car that touched a marshal ran into him (F-508), by the test the contact rule has for two cars: as the
 * tick began it was moving toward where he stood at more than the rules' closing speed. A car at rest, or going
 * away, that he walked into did not.
 */
function ranInto(state: SessionState, id: CarId, marshal: number): boolean {
  const stood = state.marshals.onTrack().find((one) => one.id === marshal)
  if (stood === undefined) return false
  const was = state.before[id]
  const dx = stood.pos.x - was.at.x
  const dy = stood.pos.y - was.at.y
  const apartM = Math.hypot(dx, dy)
  return apartM > 0 && (was.velocity.x * dx + was.velocity.y * dy) / apartM > RULES.contactClosingMS
}

/** What the marshals ask of the session (F-502). One object for the session's life; it reads the tick in progress from `state.marshalWork`. */
function marshalContextOf(state: SessionState): MarshalContext {
  const work = state.marshalWork
  return {
    get tick() {
      return work.tick
    },
    calls: work.calls,
    hit: work.hit,
    distracted: (marshal, car) => work.told.push({ type: 'marshal-distracted', tick: work.tick, marshal, car }),
    dispatched: (marshal, car) => work.told.push({ type: 'marshal-dispatched', tick: work.tick, marshal, car }),
    reached(_marshal, id) {
      const car = state.cars[id]
      // A car that is standing for a penalty goes on standing for it: he has it where it is.
      if (car.state === 'penalty-hold') return
      car.state = 'being-marshalled'
      car.stateSinceTick = work.tick
      holdAt(state, id, state.kinematics[id].pose)
    },
    setDownPlace(marshal, id) {
      const car = state.cars[id]
      const surfaces = work.surfaces
      const pose = state.kinematics[id].pose
      if (surfaces === null) return pose
      // Lifted: by the recovery rule from where it lies, on the lane it left. There with it: by the same rule from
      // the place that was chosen, which gives that place again unless a car or a marshal has come to stand in it.
      const from = car.lifted ? { pose: car.setDown, routeS: car.setDownRouteS, lane: car.setDownLane, again: true } : { pose, routeS: car.routeS, lane: car.lane }
      const placed = laneFor(state, surfaces, id, from, marshal)
      if (car.lifted && Math.hypot(placed.pose.x - car.setDown.x, placed.pose.y - car.setDown.y) < SAME_PLACE_M) return car.setDown
      car.lifted = true
      car.liftedAt.x = pose.x
      car.liftedAt.y = pose.y
      car.liftedAt.angle = pose.angle
      car.setDown.x = placed.pose.x
      car.setDown.y = placed.pose.y
      car.setDown.angle = placed.pose.angle
      car.setDownRouteS = placed.routeS
      car.setDownLane = placed.lane
      return car.setDown
    },
    carried(_marshal, id, at) {
      const car = state.cars[id]
      // It turns to face the way it will be set down as it goes: by as much of the turn as it has come of the way.
      const wholeM = Math.hypot(car.setDown.x - car.liftedAt.x, car.setDown.y - car.liftedAt.y)
      const share = wholeM > 0 ? clamp(1 - Math.hypot(car.setDown.x - at.x, car.setDown.y - at.y) / wholeM, 0, 1) : 1
      holdAt(state, id, { x: at.x, y: at.y, angle: wrapAngle(car.liftedAt.angle + angleDiff(car.liftedAt.angle, car.setDown.angle) * share) })
      carriedAlong(state, id)
    },
    putDown(marshal, id) {
      const car = state.cars[id]
      const surfaces = work.surfaces
      if (surfaces === null) return
      const placed: SetBack = { pose: car.setDown, routeS: car.setDownRouteS, lane: car.setDownLane }
      // Its driver has it again now, or when the hold it is standing for has run out, whichever is later.
      let backTick = work.tick
      if (car.state === 'penalty-hold') {
        backTick = Math.max(backTick, car.stateSinceTick + car.penaltyTicks)
        setDownStillHeld(state, surfaces, id, placed)
      } else setBackOnLane(state, surfaces, id, work.tick, placed)
      work.told.push({ type: 'car-righted', tick: work.tick, marshal, car: id, downtimeS: (backTick - car.strickenTick) / TICK_RATE })
    },
  }
}

/**
 * A car that a marshal is walking with has been moved a step (F-508). Being carried is not driving: lap timing is
 * not to see the move, so its last place is its new one, and the session's figure for how far round it is goes with
 * it without the distance it has come since the line changing, as when a car was set back in one move. A car that
 * is standing for a penalty stands for it where the marshal has it.
 */
function carriedAlong(state: SessionState, id: CarId): void {
  const car = state.cars[id]
  const pose = state.kinematics[id].pose
  car.prev.x = pose.x
  car.prev.y = pose.y
  car.routeS = state.track.nearestRoute(pose.x, pose.y, car.routeS).s
  if (car.state === 'penalty-hold') {
    car.penaltyPlace.x = pose.x
    car.penaltyPlace.y = pose.y
    car.penaltyPlace.angle = pose.angle
  }
}

/**
 * A car is on its roof from this tick, and told so, with which of the five ways it went over (F-507). Whatever hop it
 * was in the middle of is over: it is not in the air. Unless its slide was drawn already (`slideFromNow` false: a kerb
 * rolled it before the cars moved), it goes over from the speed it has now, and its slide is drawn now (F-512).
 */
function flip(state: SessionState, id: CarId, how: RollCase, tick: Tick, events: SimEvent[] | null, slideFromNow = true): SimEvent[] {
  const car = state.cars[id]
  const cause = causeOf(how)
  car.state = 'flipped'
  car.stateSinceTick = tick
  car.strickenTick = tick
  car.strickenCause = cause
  car.wedgeTicks = 0
  car.pushedTicks = 0
  if (slideFromNow && state.surfaces !== null) car.slide = drawSlide(state, state.surfaces.tuning.roll, state.kinematics[id].velocity)
  if (car.surface.airborneTicks > 0) car.surface = { ...car.surface, airborneTicks: 0, hopKerb: -1 }
  events ??= []
  events.push({ type: 'flip', tick, car: id, cause, how })
  return events
}

/** The slide of a car going over at `velocity` (F-512): its length, turn and way of turning, drawn from the session's `rolls` stream. */
function drawSlide(state: SessionState, roll: SurfaceTuning['roll'], velocity: Readonly<Vec2>): RollSlide {
  state.rollDraws += 3
  return beginSlide(velocity, state.rollRng, roll)
}

/** A car is stuck from this tick, and told so. */
function stick(state: SessionState, id: CarId, cause: StuckCause, tick: Tick, events: SimEvent[] | null): SimEvent[] {
  const car = state.cars[id]
  car.state = 'stuck'
  car.stateSinceTick = tick
  car.strickenTick = tick
  car.strickenCause = cause
  car.wedgeTicks = 0
  events ??= []
  events.push({ type: 'stuck', tick, car: id, cause })
  return events
}

/**
 * One car rolling another (F-507), from what pressed on what during the step. Every touch between two cars is judged
 * by where it landed on each and how each was moving as the tick began (`judgeTouch`): a car run into by one alongside
 * it at speed goes over, and so do both when a nose is driven into a side. A car with another's nose against its
 * tail, going faster than its push speed, has its count of pushed ticks put up, and goes over when that has lasted
 * longer than the push time; on any tick it is not so pushed the count is back to nothing. No chance is drawn. Only a
 * car that is being driven (`isDriven`) goes over, whatever the car that touched it is doing. Touches with walls,
 * tyres and marshals are never looked at, and neither is a touch whose direction the stepper did not give.
 */
function rollStruckCars(state: SessionState, surfaces: SurfaceSetup, tick: Tick, racing: boolean, events: SimEvent[] | null): SimEvent[] | null {
  const roll = surfaces.tuning.roll
  events = serveOwedStops(state, tick, events)
  state.pushedNow.fill(false)
  state.pushedBy.fill(-1)
  for (const contact of state.contacts) {
    if (typeof contact.b !== 'number' || contact.normal === undefined) continue
    const ids = [contact.a, contact.b] as const
    const verdict = judgeTouch(touchingCar(state, surfaces, contact.a), touchingCar(state, surfaces, contact.b), contact.normal, contact.impulseNs, roll)
    if (verdict.pushed !== null) {
      state.pushedNow[ids[verdict.pushed]] = true
      state.pushedBy[ids[verdict.pushed]] = ids[1 - verdict.pushed]
    }
    for (const side of [0, 1] as const) {
      const how = verdict.rolls[side]
      const by = verdict.rolledBy[side]
      if (how === null || !isDriven(state.cars[ids[side]], tick, racing)) continue
      events = flip(state, ids[side], how, tick, events)
      if (by !== null) events = countRoll(state, ids[by], ids[side], tick, racing, events)
    }
  }
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    car.pushedTicks = isDriven(car, tick, racing) ? pushTicksAfter(car.pushedTicks, state.pushedNow[id]) : 0
    if (!pushedOver(car.pushedTicks, roll)) continue
    events = flip(state, id, 'pushed', tick, events)
    events = countRoll(state, state.pushedBy[id], id, tick, racing, events)
  }
  return events
}

/** One car of a touch as `judgeTouch` wants it: how it was moving as the tick began, the way it points, and its shape. */
function touchingCar(state: SessionState, surfaces: SurfaceSetup, id: CarId): TouchingCar {
  return { velocity: state.before[id].velocity, headingRad: state.kinematics[id].pose.angle, stabilityFactor: surfaces.car(id).stabilityFactor }
}

/**
 * Wedged cars (F-501). What each car pressed on during the step is read from the stepper's reports; a car that is
 * being driven, pressed on a wall or a tyre, is all but still and has a pedal down has its count put up, and any
 * other has it put back to nothing. At the tuning's time it is wedged, where it stands. In a session with reverse
 * off (F-508) a car that is all but still with its brake held counts too, whatever it touches: it cannot get away
 * forwards, and its driver is asking for the only other way there was.
 */
function wedgeJammedCars(state: SessionState, tick: Tick, racing: boolean, events: SimEvent[] | null): SimEvent[] | null {
  state.touchingSolid.fill(false)
  for (const contact of state.contacts) if (contact.b === 'wall' || contact.b === 'marker') state.touchingSolid[contact.a] = true
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    if (!isDriven(car, tick, racing)) {
      car.wedgeTicks = 0
      continue
    }
    const kin = state.kinematics[id]
    const input = state.inputs[id]
    const speedMS = Math.hypot(kin.velocity.x, kin.velocity.y)
    car.wedgeTicks = state.reverse
      ? wedgeTicksAfter(car.wedgeTicks, state.touchingSolid[id], speedMS, input.throttle > 0 || input.brake > 0)
      : wedgeTicksWithoutReverse(car.wedgeTicks, state.touchingSolid[id], speedMS, input.throttle > 0, input.brake > 0)
    if (car.wedgeTicks < WEDGED_AFTER_TICKS) continue
    car.wedgedAt.x = kin.pose.x
    car.wedgedAt.y = kin.pose.y
    events = stick(state, id, 'wedged', tick, events)
  }
  return events
}

/**
 * What a marshal does with a car he has carried to its place (F-207, F-501, F-502, F-508), and what the fail-safe
 * does with one nobody has: sets it on the lane it left, the right way up, at rest and its driver's to drive, with
 * nothing of the grass left on it and nothing of what its driver was doing left in its controls. `placed` is the
 * place the marshal carried it to; left out, the place is found now, and the car is put there in one move.
 */
function setBackOnLane(state: SessionState, surfaces: SurfaceSetup, id: CarId, tick: Tick, placed?: SetBack): void {
  const car = state.cars[id]
  placeOnLane(state, surfaces, id, placed)
  state.stepper.resetControls?.(id)
  car.strickenCause = null
  car.wedgeTicks = 0
  car.state = 'driving'
  car.stateSinceTick = tick
}

/**
 * The same for a car that is standing for a penalty (F-502): it is set down on the lane and goes on standing there
 * for what is left of its hold, with the grass no longer in question when it is let go.
 */
function setDownStillHeld(state: SessionState, surfaces: SurfaceSetup, id: CarId, placed?: SetBack): void {
  const car = state.cars[id]
  placeOnLane(state, surfaces, id, placed)
  const pose = state.kinematics[id].pose
  car.penaltyPlace.x = pose.x
  car.penaltyPlace.y = pose.y
  car.penaltyPlace.angle = pose.angle
  car.heldBogged = false
}

/**
 * Where `standInRecover`'s rule puts a car, looked for from `from` (where the car lies, or the place already chosen
 * for it, `again`): on the lane it left, clear of the other cars and of the marshals who are out, but for the one who has it
 * in his hands, `carrier`, who goes where it goes. With `clear` false nothing is kept clear of: the place the lane
 * itself gives, which is where the car's marshal takes its lane to be while he walks to it.
 */
function laneFor(state: SessionState, surfaces: SurfaceSetup, id: CarId, from: { pose: Readonly<Pose>; routeS: number; lane: Lane; again?: boolean }, carrier: number | null, clear = true): SetBack {
  const car = state.cars[id]
  const size = surfaces.car(id)
  const progress = { started: car.lapStartMs !== null, valid: car.valid, nextSector: car.nextSector }
  if (!clear) return standInRecover({ ...from, progress }, NOBODY, state.track, 0, state.gates)
  // The other cars where they are; but one that a marshal is walking with, where it is being taken to. Two cars
  // that went over together are then given two places once, and neither marshal finds his taken by the other's car
  // as it goes by, moves on, and takes the other's in turn.
  const others: Array<Readonly<Vec2>> = []
  for (let other = 0; other < state.cars.length; other++) if (other !== id) others.push(state.cars[other].lifted ? state.cars[other].setDown : state.kinematics[other].pose)
  // A marshal is kept clear of by the car's own reach and his: half its diagonal and his radius, and a finger more.
  const out = state.marshals.onTrack().filter((marshal) => marshal.id !== carrier)
  const marshals = { at: out.map((marshal) => marshal.pos), clearM: Math.hypot(size.lengthM, size.widthM) / 2 + INCIDENT_TUNING.marshal.marshalRadiusM + MARSHAL_CLEAR_M }
  return standInRecover({ ...from, progress }, others, state.track, Math.hypot(size.lengthM, size.widthM), state.gates, marshals)
}

/**
 * Puts a car on the lane it left, at rest: at `placed`, where its marshal has carried it; or, with none given,
 * where `standInRecover`'s rule says now, clear of the other cars and of the marshals who are out. Being carried is
 * not driving: lap timing does not see the move.
 */
function placeOnLane(state: SessionState, surfaces: SurfaceSetup, id: CarId, placed: SetBack = laneFor(state, surfaces, id, { pose: state.kinematics[id].pose, routeS: state.cars[id].routeS, lane: state.cars[id].lane }, null)): void {
  const car = state.cars[id]
  holdAt(state, id, placed.pose)
  car.prev.x = placed.pose.x
  car.prev.y = placed.pose.y
  car.routeS = placed.routeS
  car.surface = initialSurfaceState()
  car.excursion = ON_A_LANE
  car.lifted = false
}

/**
 * What the AI drivers are shown of the others on the track (F-502): the cars, and each marshal who is away from his
 * post as one more car standing still across their way, which they go round as they go round any car that is.
 */
function withMarshals(state: SessionState, seen: SessionSnapshot): readonly CarSnapshot[] {
  const out = state.marshals.onTrack()
  if (out.length === 0) return seen.cars
  const sees = state.aiSees
  sees.length = 0
  for (const car of seen.cars) sees.push(car)
  for (let n = 0; n < out.length; n++) {
    const marshal = out[n]
    const standIn = state.marshalStandIns[n] ?? (state.marshalStandIns[n] = blankCarSnapshot(0))
    const onRoute = state.track.nearestRoute(marshal.pos.x, marshal.pos.y)
    standIn.id = state.cars.length + marshal.id
    standIn.pose.x = marshal.pos.x
    standIn.pose.y = marshal.pos.y
    // Square to the lane, so that he is no wider to them than he is.
    standIn.pose.angle = state.track.routePose(onRoute.s).angle
    standIn.routeS = onRoute.s
    sees.push(standIn)
  }
  return sees
}

/** Puts a car at `pose`, at rest, in the stepper and in what the session reports of it. */
function holdAt(state: SessionState, id: CarId, pose: Readonly<Pose>): void {
  const kin = state.kinematics[id]
  kin.pose.x = pose.x
  kin.pose.y = pose.y
  kin.pose.angle = pose.angle
  kin.velocity.x = 0
  kin.velocity.y = 0
  kin.yawRate = 0
  state.stepper.setPose(id, kin.pose, true)
}

function fillSnapshot(state: SessionState): SessionSnapshot {
  const view = state.view
  view.tick = state.tick
  view.phase = state.phase
  view.clockRemainingS =
    state.race === null
      ? Math.max(0, state.config.durationS - state.tick / TICK_RATE)
      : remainingS(timerClockOf(state, state.race), msOfTick(state.tick), state.config.durationS)
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    const kin = state.kinematics[id]
    const out = view.cars[id]
    out.pose.x = kin.pose.x
    out.pose.y = kin.pose.y
    out.pose.angle = kin.pose.angle
    out.velocity.x = kin.velocity.x
    out.velocity.y = kin.velocity.y
    out.speedMS = kin.velocity.x * Math.cos(kin.pose.angle) + kin.velocity.y * Math.sin(kin.pose.angle)
    out.yawRateRadS = kin.yawRate
    out.steerRad = kin.steerRad
    out.throttle = kin.throttle
    out.brake = kin.brake
    out.motorRadS = kin.motorRadS
    out.slipFront = kin.slipFront
    out.slipRear = kin.slipRear
    out.surface = car.surface.lastSurface
    out.airborne = car.surface.airborneTicks > 0
    out.bog = car.surface.bog
    out.state = car.state
    out.stateSinceTick = car.stateSinceTick
    out.strickenCause = car.state === 'flipped' || car.state === 'stuck' || car.state === 'being-marshalled' ? car.strickenCause : null
    out.rollSlideTick = car.state === 'flipped' && state.surfaces !== null ? slideBeginsTick(car.stateSinceTick, state.surfaces.tuning.roll) : null
    out.lap = car.lap
    out.routeS = car.routeS
    out.lastLapMs = car.lastLapMs
    out.bestLapMs = car.bestLapMs
    out.lapStartMs = car.lapStartMs
    out.lapValid = car.valid
    out.elapsedMs = car.elapsedMs
    out.position = car.position
    out.gapAheadMs = car.gapAheadMs
    out.lane = car.lane
    out.pitStopsOwed = car.pitStopsOwed
    out.pitHoldRemainingS = car.state === 'pit-hold' ? pitHoldRemainingS(car.stateSinceTick, state.tick) : null
    out.offTrackS = car.offTrackTicks / TICK_RATE
    out.penaltyHoldRemainingS = car.state === 'penalty-hold' ? penaltyHoldRemainingS(car.stateSinceTick, state.tick, car.penaltyTicks) : null
    out.holdOwed = car.holdOwed
  }
  state.stepper.markersInto?.(view.markers)
  view.marshals = state.marshals.snapshot() as Mutable<SessionSnapshot>['marshals']
  view.weather = state.weather.snapshot() as Mutable<SessionSnapshot>['weather']
  return view
}

/**
 * Tick, phase, the session's best lap, every car's kinematics, timing fields (including the lap in progress), what
 * the surfaces remember of it, what track limits do (F-307, F-309) and the hits against it (F-309), why it is
 * stricken and how near it is to wedged (F-501), where a marshal is carrying it to (F-508), how it slides on its roof and how long it has been pushed along (F-507), what incident detection
 * remembers, what a race keeps of its starts, clocks, standings and finish (F-303, F-309), what race
 * control has called (F-404) and, where pit stops are owed, of those (F-306, F-309), then each subsystem through its
 * own `hashInto`, the weather among them (F-601).
 */
function hashOf(state: SessionState): string {
  const buffer = state.hashBuffer
  buffer.length = 0
  buffer.push(state.tick, PHASES.indexOf(state.phase), state.sessionBestMs ?? NaN)
  for (let id = 0; id < state.cars.length; id++) {
    const car = state.cars[id]
    const kin = state.kinematics[id]
    buffer.push(
      kin.pose.x,
      kin.pose.y,
      kin.pose.angle,
      kin.velocity.x,
      kin.velocity.y,
      kin.yawRate,
      kin.steerRad,
      kin.throttle,
      kin.brake,
      kin.motorRadS,
      kin.slipFront,
      kin.slipRear,
      CAR_STATES.indexOf(car.state),
      car.stateSinceTick,
      car.lap,
      car.routeS,
      car.lapStartMs ?? NaN,
      car.nextSector,
      car.valid ? 1 : 0,
      car.behindLine ? 1 : 0,
      car.prev.x,
      car.prev.y,
      // NaN stands for "none yet": hashState treats every NaN alike and unlike any number.
      car.lastLapMs ?? NaN,
      car.bestLapMs ?? NaN,
      car.elapsedMs,
      car.position,
      car.gapAheadMs ?? NaN,
      car.surface.offLaneM,
      car.surface.bog,
      car.surface.airborneTicks,
      car.surface.lastHopTick,
      SURFACES.indexOf(car.surface.lastSurface),
      car.surface.onKerb ? 1 : 0,
      car.surface.noseOnKerb ? 1 : 0,
      car.surface.hopKerb,
      car.slide.fromMS,
      car.slide.lengthM,
      car.slide.turnRad,
      car.contactStopOwed ? 1 : 0,
      car.pushedTicks,
      car.lane === 'pit' ? 1 : 0,
      car.offTrackTicks,
      car.penaltyPlace.x,
      car.penaltyPlace.y,
      car.penaltyPlace.angle,
      car.penaltyTicks,
      car.heldBogged ? 1 : 0,
      car.strickenTick,
      car.excursion,
      car.leftAt.x,
      car.leftAt.y,
      car.overIsland ? 1 : 0,
      car.pastBand ? 1 : 0,
      car.contactHits,
      car.strickenCause === null ? -1 : STRICKEN_CAUSES.indexOf(car.strickenCause),
      car.wedgeTicks,
      car.wedgedAt.x,
      car.wedgedAt.y,
      car.aquaplaning ? 1 : 0,
      car.lifted ? 1 : 0,
      car.liftedAt.x,
      car.liftedAt.y,
      car.liftedAt.angle,
      car.setDown.x,
      car.setDown.y,
      car.setDown.angle,
      car.setDownRouteS,
      car.setDownLane === 'pit' ? 1 : 0,
    )
  }
  buffer.push(state.rollDraws)
  for (const by of state.lastHitBy) buffer.push(by)
  state.marshals.hashInto(buffer)
  state.weather.hashInto(buffer)
  for (const hitTick of state.lastHitTick) buffer.push(hitTick)
  hashIncidents(state.incidents, buffer)
  if (state.race !== null) {
    for (const car of state.cars) {
      buffer.push(car.droveEarly ? 1 : 0, car.holdOwed ? 1 : 0, car.shoved ? 1 : 0, car.clockStartMs ?? NaN, car.raceMs ?? NaN, car.sinceLineM)
      buffer.push(car.releaseTick, car.place.x, car.place.y, car.place.angle, car.movedOffTick, car.liftPlace.x, car.liftPlace.y, car.liftPlace.angle)
    }
    buffer.push(state.race.finish.allowanceFromTick ?? NaN)
    state.race.control.hashInto(buffer)
    hashStandings(state.race.standings, buffer)
    if (state.race.pitStops > 0) for (const car of state.cars) buffer.push(car.pitStopsOwed, car.pitPlace.x, car.pitPlace.y, car.pitPlace.angle, car.inPits ? 1 : 0, car.pitStopping ? 1 : 0, car.pitLeaveTicks)
  }
  for (const driver of state.drivers) driver?.hashInto(buffer)
  for (const parker of state.pullOvers) parker.hashInto(buffer)
  state.stepper.hashInto(buffer)
  return hashState(buffer)
}

/**
 * The session shell with the car stepper supplied by the caller. Internal to the sim; the public
 * `createSession` binds the stepper in use. `track` is the runtime of `config.track` when the caller has already
 * built it (it is the slow part of a session's creation); otherwise it is built here. `surfaces` puts grass and
 * kerbs under the cars (F-207); left out, every car is on dry asphalt whatever the track says. `ai` is what drives
 * the entries whose controller is 'ai' (F-301); left out, nobody drives them. `mandatoryPitStops` is the number of
 * that name on the row of the session's car class (F-306): the pit stops each car owes in a final; left out, none.
 */
export function createSessionWith(
  config: SessionConfig,
  createStepper: StepperFactory,
  track: TrackRuntime = buildTrackRuntime(config.track),
  surfaces: SurfaceSetup | null = null,
  ai: AiSetup | null = null,
  mandatoryPitStops = 0,
): Session {
  const state = createState(config, createStepper, track, surfaces, ai, mandatoryPitStops)
  const session: Session = {
    config,
    get tick() {
      return state.tick
    },
    get phase() {
      return state.phase
    },
    step: (human) => advance(state, human),
    snapshot: () => fillSnapshot(state),
    hash: () => hashOf(state),
    result: () => state.race?.result ?? null,
  }
  // The development seam (F-206) exists only on a session that asked for it, so there is nothing to guard against
  // on any other: the members are simply not there.
  // The AI drivers are there to be looked at by tests and the development overlay (F-301), never to be driven from outside.
  if (state.drivers.length > 0) Object.defineProperty(session, 'aiDrivers', { value: state.drivers, enumerable: true })
  if (config.allowTuning === true) {
    Object.defineProperties(session, {
      tuned: { get: () => state.tuned },
      setCarParams: { value: (car: CarId, params: CarParams) => retune(state, car, params) },
      setSurfaceTuning: { value: (next: SurfaceTuning) => retuneSurface(state, next) },
      setContactTuning: { value: (next: ContactTuning) => retuneContact(state, next) },
      forceWeather: { value: (hold: WeatherForce | null) => holdWeather(state, hold) },
    })
  }
  return session
}

/**
 * A session created with `allowTuning: true` (F-206): the one way to change a car's parameters while it runs. Never
 * present on a session made for race day.
 */
export interface TunableSession extends Session {
  /** True once any car's parameters have been replaced, whatever they were replaced with; never cleared. Lap times from a tuned session must not count. */
  readonly tuned: boolean
  /** Replaces the car's resolved parameters from the next tick on. Its position, velocity and input shaping carry on as they were. */
  setCarParams(car: CarId, params: CarParams): void
  /**
   * Replaces the grass and kerb tuning this session's ground reads, from the next tick on. The session keeps a copy of
   * `next`, and the shipped tuning block is not touched. Throws on a session that has no ground under its cars.
   */
  setSurfaceTuning(next: SurfaceTuning): void
  /**
   * Replaces what the walls, the tyres and the cars are made of where they touch (`contact`, `marker`, `carContact`),
   * and how the loose tyres give, from the next step on: the next touch of each kind uses the new figures. Nothing is
   * rebuilt and nothing moves. The shipped tuning block is not touched.
   */
  setContactTuning(next: ContactTuning): void
  /**
   * Sets the fields of the weather that are given and holds them there (F-601), while what is not given goes on by
   * itself; `null` lets all of it go from where it stands. Holding anything counts the session as tuned.
   */
  forceWeather(hold: WeatherForce | null): void
}

/** The three contact blocks of the tuning (walls, tyres, cars): what `setContactTuning` takes. */
export type ContactTuning = Readonly<Pick<Tuning, 'contact' | 'marker' | 'carContact'>>

/**
 * The AI drivers of a session, indexed by CarId, with null for a car a human drives (F-301). Empty for a session
 * with no AI cars. For tests and development tools: the line each follows and the point it is aiming at.
 */
export function aiDriversOf(session: Session): ReadonlyArray<AiDriver | null> {
  return isDrivenSession(session) ? session.aiDrivers : NO_DRIVERS
}

/** A session that has AI drivers, as `createSessionWith` makes it. */
interface DrivenSession extends Session {
  readonly aiDrivers: ReadonlyArray<AiDriver | null>
}

function isDrivenSession(session: Session): session is DrivenSession {
  return 'aiDrivers' in session
}

export function isTunableSession(session: Session): session is TunableSession {
  return 'setCarParams' in session && 'tuned' in session
}

/** A car stepper that can take new parameters for a car that is already in it. */
interface RetunableStepper extends CarStepper {
  setParams(car: CarId, params: CarParams): void
}

function isRetunable(stepper: CarStepper): stepper is RetunableStepper {
  return 'setParams' in stepper
}

/** A car stepper whose world can take new contact figures. */
interface ContactStepper extends CarStepper {
  setContact(next: ContactTuning): void
}

function isContactStepper(stepper: CarStepper): stepper is ContactStepper {
  return 'setContact' in stepper
}

function retune(state: SessionState, car: CarId, params: CarParams): void {
  if (!Number.isInteger(car) || car < 0 || car >= state.cars.length) throw new RangeError(`setCarParams: there is no car ${car}`)
  if (!isRetunable(state.stepper)) throw new Error("setCarParams: this session's car stepper cannot take new parameters")
  state.stepper.setParams(car, params)
  state.tuned = true
}

function retuneSurface(state: SessionState, next: SurfaceTuning): void {
  if (state.surfaces === null) throw new Error('setSurfaceTuning: this session has no ground under its cars')
  state.surfaces.tuning = { ...next, grass: { ...next.grass }, kerb: { ...next.kerb } }
  state.tuned = true
}

function retuneContact(state: SessionState, next: ContactTuning): void {
  if (!isContactStepper(state.stepper)) throw new Error("setContactTuning: this session's car stepper cannot take new contact figures")
  // The stepper keeps copies of the numbers, so that nothing the caller holds is shared with the session.
  state.stepper.setContact({ contact: { ...next.contact }, marker: { ...next.marker }, carContact: { ...next.carContact } })
  state.tuned = true
}

function holdWeather(state: SessionState, hold: WeatherForce | null): void {
  state.weather.force(hold)
  if (hold !== null) state.tuned = true
}
