import { clamp, type Rng } from '../core'
import { WEATHER_TUNING } from './tuning'
import type { Sky } from './types'

// What the sky does to the ground (F-601): the rain's intensity and the cloud cover easing toward what the sky
// asks for; the wetness of the surface, rising in rain and falling as it runs off and dries; the wetness of the
// racing line, which the cars' tyres dry besides; and the water gathering in the track's low spots. Every rate is
// in `WEATHER_TUNING`. All of it is stepped by a time given in seconds, so that the pause between two sessions can
// be worked through in coarser steps than a tick.

const T = WEATHER_TUNING
// The rates the ground is stepped by, read once: this runs 120 times a second for every session there is.
const SETTLED_WITHIN = T.settledWithin
const RAIN_EASE_S = T.rain.easeS
const CLOUD_EASE_S = T.cloud.easeS
const WET_PER_S = T.wetness.wetPerS
const WIND_LOSS_PER_MS = T.wetness.windLossPerMS
const DRY_BELOW = T.wetness.dryBelow
const LINE_LOSS_PER_CAR_PER_S = T.line.lossPerCarPerS
const PUDDLE_RAIN_ABOVE = T.puddle.rainAbove
const PUDDLE_FILL_PER_S = T.puddle.fillPerS
const PUDDLE_DRAIN_PER_S = T.puddle.drainPerS
const PUDDLE_DRAIN_FLOOR_PER_S = T.puddle.drainFloorPerS
const PUDDLE_ANNOUNCE_ABOVE = T.puddle.announceAbove

const unit = (value: number): number => Math.min(Math.max(value, 0), 1)

/** The rain, the cloud and the water on the ground. Plain numbers: everything here is hashed. */
export interface GroundWater {
  /** 0..1 */
  rain: number
  /** 0..1 */
  cloud: number
  /** 0..1, the surface on average. */
  wetness: number
  /** 0..1, on the racing line; never above `wetness` unless it is held there. */
  lineWetness: number
  /** The depth of the water at each of the track's puddle spots, 0..1. */
  readonly depth: number[]
  /** For each spot, whether the puddle that is there has had its `puddle` event (or was there before the session). False again once the spot is empty. */
  readonly told: boolean[]
  /** For each spot, its own share of the fill rate. */
  readonly fill: readonly number[]
}

/** The depth the low spots hold at the start of a session that begins this wet: none up to the wetness light rain can reach, full at 1. */
export function startingDepth(wetness: number): number {
  const from = T.puddle.startAboveWetness
  return clamp((wetness - from) / (1 - from), 0, 1)
}

/**
 * The ground as a session begins: rain and cloud already as the sky has them, the surface and the line equally
 * wet, and the low spots holding what that wetness implies. A spot that begins deeper than a puddle is announced
 * at was there before the session and is not announced in it. Each spot draws its own share of the fill rate from
 * `rng`; given none, every spot fills at the rate itself.
 */
export function createGroundWater(sky: Sky, wetness: number, spots: number, rng: Rng | null): GroundWater {
  const wet = clamp(wetness, 0, 1)
  const depth = startingDepth(wet)
  const [least, most] = T.puddle.fillSpread
  return {
    rain: T.rain.target[sky],
    cloud: T.cloud.target[sky],
    wetness: wet,
    lineWetness: wet,
    depth: Array.from({ length: spots }, () => depth),
    told: Array.from({ length: spots }, () => depth > T.puddle.announceAbove),
    fill: Array.from({ length: spots }, () => (rng === null ? 1 : rng.range(least, most))),
  }
}

/**
 * What the ground is stepped by under one sky: where the rain and the cloud are going, and the share of the water
 * on the surface that leaves it each second in still air. Looked up once when the sky changes, not on every tick.
 */
export interface GroundRates {
  readonly rainTarget: number
  readonly cloudTarget: number
  readonly lossPerS: number
}

export function groundRates(sky: Sky): GroundRates {
  return { rainTarget: T.rain.target[sky], cloudTarget: T.cloud.target[sky], lossPerS: T.wetness.lossPerS[sky] }
}

/** A value eased toward its target over `dtS` with a time constant, and put on the target once it is as good as there. */
function eased(value: number, target: number, easeS: number, dtS: number): number {
  if (value === target) return target
  const next = target + (value - target) * Math.exp(-dtS / easeS)
  return Math.abs(next - target) < SETTLED_WITHIN ? target : next
}

/** A wetness after `dtS` of rain at `rain` falling on it and `loss` of it leaving each second. */
function wetted(wetness: number, rain: number, loss: number, dtS: number): number {
  if (wetness === 0 && rain === 0) return 0
  const next = unit(wetness + (rain * WET_PER_S * (1 - wetness) - loss * wetness) * dtS)
  return rain === 0 && next < DRY_BELOW ? 0 : next
}

/**
 * Moves the rain, the cloud, the two wetnesses and the puddles on by `dtS` under the sky that `rates` are of, in a
 * wind of `windMS` with `carsOnLine` cars circulating.
 */
export function advanceGround(ground: GroundWater, rates: GroundRates, windMS: number, carsOnLine: number, dtS: number): void {
  ground.rain = eased(ground.rain, rates.rainTarget, RAIN_EASE_S, dtS)
  ground.cloud = eased(ground.cloud, rates.cloudTarget, CLOUD_EASE_S, dtS)

  // What leaves the surface each second: more in a wind.
  const loss = rates.lossPerS * (1 + WIND_LOSS_PER_MS * Math.max(0, windMS))
  ground.wetness = wetted(ground.wetness, ground.rain, loss, dtS)
  ground.lineWetness = wetted(ground.lineWetness, ground.rain, loss + LINE_LOSS_PER_CAR_PER_S * Math.max(0, carsOnLine), dtS)

  const over = unit((ground.rain - PUDDLE_RAIN_ABOVE) / (1 - PUDDLE_RAIN_ABOVE))
  const depths = ground.depth
  for (let i = 0; i < depths.length; i++) {
    const depth = depths[i]
    if (depth <= 0 && over <= 0) continue
    const filling = PUDDLE_FILL_PER_S * ground.fill[i] * over * (1 - depth)
    // Rain heavy enough to fill a spot keeps it from draining, by as much as it is over the threshold. An empty spot
    // drains too: it holds nothing until the rain fills it faster than it runs away.
    const draining = (PUDDLE_DRAIN_PER_S * depth + PUDDLE_DRAIN_FLOOR_PER_S) * (1 - over)
    depths[i] = unit(depth + (filling - draining) * dtS)
  }
}

/**
 * Appends to `announce` the index of every spot that is deeper than the announcing depth and whose puddle has not
 * been announced, and marks it announced. A spot that has drained to nothing has no puddle: the next one to form
 * there is a new one, and is announced.
 */
export function announcePuddles(ground: GroundWater, announce: number[]): void {
  for (let i = 0; i < ground.depth.length; i++) {
    const depth = ground.depth[i]
    if (depth <= 0) ground.told[i] = false
    else if (!ground.told[i] && depth > PUDDLE_ANNOUNCE_ABOVE) {
      ground.told[i] = true
      announce.push(i)
    }
  }
}

/** The radius of the water at a spot of radius `spotR` that is `depth` deep, m. */
export function puddleRadius(spotR: number, depth: number): number {
  return depth <= 0 ? 0 : spotR * Math.pow(depth, T.puddle.radiusExponent)
}
