import type { ForecastPreset } from '@content/weather'
import { clamp, DT, TICK_RATE, type Rng } from '../core'
import { WEATHER_TUNING } from './tuning'
import type { Sky } from './types'

// The wind (F-601). Its speed wanders about a mean that the forecast sets and the sky scales, and its direction
// wanders about the one the session began with, never turning fast. On top of that come the gusts: now and then
// the wind rises by a share of itself for a second or a few and falls back. A direction is where the wind blows
// towards, radians clockwise from +x, the way a car's heading is measured.

const W = WEATHER_TUNING.wind
const G = WEATHER_TUNING.gust
// The rates of one tick, worked out once: this is stepped 120 times a second for every session there is.
const SPEED_EASE_PER_TICK = DT / W.speedEaseS
const SPEED_WANDER_EASE_PER_TICK = DT / W.speedWanderS
const TURN_EASE_PER_TICK = DT / W.turnEaseS
const TICK_S = DT
const HOME_EASE = 1 / W.homeEaseS
const MAX_TURN_RAD_S = W.maxTurnRadS
const NOISE_EVERY_TICKS = W.noiseEveryTicks
/** The wander is redrawn every so many ticks; this turns a draw into what one tick adds of it. */
const NOISE_PER_TICK = Math.sqrt(W.noiseEveryTicks * DT) / W.noiseEveryTicks
/** A draw from [0, 1) made into one with no mean and a variance of 1. */
const UNIT = Math.sqrt(12)
/** What one tick adds to the turning for each unit of its wander. */
const TURN_NOISE_PER_TICK = W.turnSpreadRadS * Math.sqrt(2 / W.turnEaseS) * NOISE_PER_TICK
/** What one tick adds, for each unit of its wander, to how far from the sky's mean the speed is drawn: that distance has a variance of 1. */
const SPEED_NOISE_PER_TICK = Math.sqrt(2 / W.speedWanderS) * NOISE_PER_TICK

type WindPreset = ForecastPreset['wind']

/** Everything the wind remembers. Plain numbers: all of it is hashed. */
export interface WindState {
  /** The wind without its gust, m/s. */
  baseMS: number
  /** How far from the sky's mean the wind is being drawn, in standard deviations: it wanders about none. */
  speedPull: number
  /** Where it blows towards, rad; not wrapped, so that it can be compared from one tick to the next. */
  dirRad: number
  /** The direction it is drawn back to: the session's first. */
  readonly homeRad: number
  /** How fast the direction would turn by itself, rad/s. */
  turnRadS: number
  /** The draws the wander is being made from until the next redraw. */
  speedNoise: number
  turnNoise: number
  /** Ticks until they are redrawn. */
  noiseTicks: number
  /** The gust that is blowing: how much of the wind it adds at its height, how long it lasts and how much of that is left, ticks. None blowing: all 0. */
  gustShare: number
  gustTicks: number
  gustTicksLeft: number
  /** Ticks until the next gust begins, counted while none is blowing. */
  nextGustTicks: number
}

/** The most the wind blows without a gust under a forecast, m/s: its maximum less the room the least gust needs. */
export function baseCeilingMS(preset: WindPreset): number {
  return preset.maxMS / W.gustRoom
}

/** The least it blows without a gust, m/s. */
export function baseFloorMS(preset: WindPreset): number {
  return Math.min(preset.meanMS * W.calmShare, baseCeilingMS(preset))
}

/** The speed the wind settles toward under a sky, m/s. */
export function settledWindMS(preset: WindPreset, sky: Sky): number {
  return clamp(preset.meanMS * W.skyFactor[sky], baseFloorMS(preset), baseCeilingMS(preset))
}

/**
 * What the wind is stepped by under one forecast and one sky: worked out once when the sky changes, not on every
 * tick. `settledMS` is the speed it is drawn to, `floorMS` and `ceilingMS` the least and the most it blows without a gust.
 */
export interface WindRates {
  readonly preset: WindPreset
  readonly settledMS: number
  /** One standard deviation of what the wind is drawn to, m/s. */
  readonly spreadMS: number
  readonly floorMS: number
  readonly ceilingMS: number
}

export function windRates(preset: WindPreset, sky: Sky): WindRates {
  return { preset, settledMS: settledWindMS(preset, sky), spreadMS: W.speedSpreadShare * preset.meanMS, floorMS: baseFloorMS(preset), ceilingMS: baseCeilingMS(preset) }
}

/** The time from one gust ending to the next beginning, ticks: drawn so that gusts begin `gustsPerMinute` times a minute on average. */
function gustGapTicks(preset: WindPreset, rng: Rng): number {
  if (preset.gustsPerMinute <= 0) return Infinity
  const meanGustS = (G.durationS[0] + G.durationS[1]) / 2
  const meanGapS = Math.max(G.minGapS, 60 / preset.gustsPerMinute - meanGustS)
  return Math.max(1, Math.round((G.minGapS - (meanGapS - G.minGapS) * Math.log(1 - rng.next())) * TICK_RATE))
}

/** The wind as a session begins: blowing as the plan has it (no slower and no faster than it ever blows without a gust), with no gust, and the first gust drawn. */
export function createWind(preset: WindPreset, dirRad: number, speedMS: number, gusts: Rng): WindState {
  return {
    baseMS: clamp(Number.isFinite(speedMS) ? speedMS : 0, baseFloorMS(preset), baseCeilingMS(preset)),
    speedPull: 0,
    dirRad: Number.isFinite(dirRad) ? dirRad : 0,
    homeRad: Number.isFinite(dirRad) ? dirRad : 0,
    turnRadS: 0,
    speedNoise: 0,
    turnNoise: 0,
    noiseTicks: 0,
    gustShare: 0,
    gustTicks: 0,
    gustTicksLeft: 0,
    nextGustTicks: gustGapTicks(preset, gusts),
  }
}

/** How much of its height a gust has `left` ticks from its end: nothing at either end, all of it halfway, smooth between. */
function gustEnvelope(ticks: number, left: number): number {
  if (ticks <= 0 || left <= 0) return 0
  const sine = Math.sin((Math.PI * (ticks - left)) / ticks)
  return sine * sine
}

/** The wind's speed now, gust included, m/s: never above the forecast's maximum (`maxMS`). */
export function windSpeedMS(wind: Readonly<WindState>, maxMS: number): number {
  if (wind.gustTicksLeft <= 0) return Math.min(maxMS, wind.baseMS)
  return Math.min(maxMS, wind.baseMS * (1 + wind.gustShare * gustEnvelope(wind.gustTicks, wind.gustTicksLeft)))
}

/** What a gust that has just begun will take the wind to at its height. */
export interface GustStart {
  speedMS: number
  dirRad: number
}

/**
 * One tick of the wind under the forecast and the sky that `rates` were worked out for. `wander` draws the
 * wandering of speed and direction, `gusts` the gusts: when one comes, how strong it is and how long. Returns the
 * gust that began on this tick, else null.
 */
export function stepWind(wind: WindState, rates: WindRates, wander: Rng, gusts: Rng): GustStart | null {
  const preset = rates.preset
  if (wind.noiseTicks <= 0) {
    wind.speedNoise = (wander.next() - 0.5) * UNIT
    wind.turnNoise = (wander.next() - 0.5) * UNIT
    wind.noiseTicks = NOISE_EVERY_TICKS
  }
  wind.noiseTicks -= 1

  // Speed: what it is drawn to wanders about the sky's mean, and the wind follows that, so that it never jolts.
  wind.speedPull += wind.speedNoise * SPEED_NOISE_PER_TICK - wind.speedPull * SPEED_WANDER_EASE_PER_TICK
  const drawnTo = rates.settledMS + rates.spreadMS * wind.speedPull
  const speed = wind.baseMS + (drawnTo - wind.baseMS) * SPEED_EASE_PER_TICK
  wind.baseMS = Math.min(Math.max(speed, rates.floorMS), rates.ceilingMS)

  // Direction: the turning it would do by itself wanders about none; it is drawn back home, and never turns fast.
  wind.turnRadS += wind.turnNoise * TURN_NOISE_PER_TICK - wind.turnRadS * TURN_EASE_PER_TICK
  const turn = wind.turnRadS - (wind.dirRad - wind.homeRad) * HOME_EASE
  wind.dirRad += Math.min(Math.max(turn, -MAX_TURN_RAD_S), MAX_TURN_RAD_S) * TICK_S

  // Gusts: one at a time.
  if (wind.gustTicksLeft > 0) {
    wind.gustTicksLeft -= 1
    if (wind.gustTicksLeft === 0) {
      wind.gustShare = 0
      wind.gustTicks = 0
      wind.nextGustTicks = gustGapTicks(preset, gusts)
    }
    return null
  }
  wind.nextGustTicks -= 1
  if (wind.nextGustTicks > 0) return null
  // No gust takes the wind past the forecast's maximum: the wind without one is always low enough for the least gust.
  const room = wind.baseMS > 0 ? preset.maxMS / wind.baseMS - 1 : G.strength[1]
  wind.gustShare = Math.min(gusts.range(G.strength[0], G.strength[1]), room)
  wind.gustTicks = Math.max(2, Math.round(gusts.range(G.durationS[0], G.durationS[1]) * TICK_RATE))
  wind.gustTicksLeft = wind.gustTicks
  return { speedMS: wind.baseMS * (1 + wind.gustShare), dirRad: wind.dirRad }
}

/** Appends everything the wind remembers, in a fixed order. */
export function hashWind(wind: Readonly<WindState>, buffer: number[]): void {
  buffer.push(wind.baseMS, wind.speedPull, wind.dirRad, wind.homeRad, wind.turnRadS, wind.speedNoise, wind.turnNoise, wind.noiseTicks, wind.gustShare, wind.gustTicks, wind.gustTicksLeft, wind.nextGustTicks)
}
