import { distanceToSegment, pointInPolygon, type Vertex } from './geometry'
import type { GrassLook, Point, SurfaceKind, TrackData } from './types'

// The meaning of the surface layers, computed directly from the polygons. The runtime's grid cache answers the
// same question faster and must agree with this; the validator uses this as it stands.

/** Whether a point is on a kerb: within half the kerb's width of its polyline. */
export function onKerb(data: TrackData, x: number, y: number): boolean {
  for (const kerb of data.kerbs) {
    const points = kerb.polyline
    const half = kerb.widthM / 2
    const segments = kerb.closed ? points.length : points.length - 1
    for (let i = 0; i < segments; i++) {
      const a = points[i]
      const b = points[(i + 1) % points.length]
      if (distanceToSegment(x, y, a[0], a[1], b[0], b[1]) <= half) return true
    }
  }
  return false
}

/** Kerbs first, then surfaces from the last listed to the first. Anything no surface covers is grass. */
export function surfaceAtExact(data: TrackData, x: number, y: number): SurfaceKind {
  if (onKerb(data, x, y)) return 'kerb'
  for (let i = data.surfaces.length - 1; i >= 0; i--) {
    const surface = data.surfaces[i]
    if (pointInPolygon(x, y, surface.polygon, surface.holes)) return surface.kind
  }
  return 'grass'
}

/** Which grass a point is on, from the topmost surface there: null on asphalt and on kerbs, outfield where nothing covers it. */
export function grassLookExact(data: TrackData, x: number, y: number): GrassLook | null {
  if (onKerb(data, x, y)) return null
  for (let i = data.surfaces.length - 1; i >= 0; i--) {
    const surface = data.surfaces[i]
    if (pointInPolygon(x, y, surface.polygon, surface.holes)) return surface.kind === 'grass' ? (surface.look ?? 'infield') : null
  }
  return 'outfield'
}

/**
 * Every ring that can be an edge of the asphalt: the rings of each asphalt surface, and of whatever is laid over
 * it later in the list.
 */
export function asphaltEdgeRings(data: TrackData): Point[][] {
  const first = data.surfaces.findIndex((surface) => surface.kind === 'asphalt')
  if (first < 0) return []
  return data.surfaces.slice(first).flatMap((surface) => [surface.polygon, ...surface.holes])
}

/** Shortest distance from a point to any of the given closed rings. */
export function distanceToRings(x: number, y: number, rings: readonly (readonly Vertex[])[]): number {
  let best = Infinity
  for (const ring of rings) {
    for (let i = 0; i < ring.length; i++) {
      const a = ring[i]
      const b = ring[(i + 1) % ring.length]
      best = Math.min(best, distanceToSegment(x, y, a[0], a[1], b[0], b[1]))
    }
  }
  return best
}

/** How far either side of an edge to look when deciding whether it is an edge of the asphalt. */
const EDGE_PROBE_M = 0.002

/**
 * The edge of the asphalt itself, as segments: those stretches of the surface rings that have asphalt on one side
 * and not on the other. A ring shared by two grass surfaces, or lying inside the asphalt, is not an edge of it.
 */
export function asphaltBoundary(data: TrackData): Array<[Point, Point]> {
  const isAsphalt = (x: number, y: number): boolean => {
    for (let i = data.surfaces.length - 1; i >= 0; i--) {
      const surface = data.surfaces[i]
      if (pointInPolygon(x, y, surface.polygon, surface.holes)) return surface.kind === 'asphalt'
    }
    return false
  }
  const boundary: Array<[Point, Point]> = []
  for (const ring of asphaltEdgeRings(data)) {
    for (let i = 0; i < ring.length; i++) {
      const a = ring[i]
      const b = ring[(i + 1) % ring.length]
      const length = Math.hypot(b[0] - a[0], b[1] - a[1])
      if (length === 0) continue
      const nx = (-(b[1] - a[1]) / length) * EDGE_PROBE_M
      const ny = ((b[0] - a[0]) / length) * EDGE_PROBE_M
      const mx = (a[0] + b[0]) / 2
      const my = (a[1] + b[1]) / 2
      if (isAsphalt(mx + nx, my + ny) !== isAsphalt(mx - nx, my - ny)) boundary.push([a, b])
    }
  }
  return boundary
}

/** Shortest distance from a point to any of the given segments. */
export function distanceToSegments(x: number, y: number, segments: ReadonlyArray<readonly [Vertex, Vertex]>): number {
  let best = Infinity
  for (const [a, b] of segments) best = Math.min(best, distanceToSegment(x, y, a[0], a[1], b[0], b[1]))
  return best
}
