import { angleDiff, clamp, DT, lerp, TWO_PI, type DriverId, type Rng, type Vec2 } from '../core'
import type { ControlInput } from '../session/controls'
import type { CarColour, CarSnapshot, Difficulty } from '../session/types'
import { lockFraction } from '../vehicle/shaping'
import type { CarParams } from '../vehicle/types'
import { aquaplaneSpeedMS } from '../weather/coupling'
import { createGripJudgement, lineGrip, type Conditions } from './conditions'
import type { PitPath } from './pit-lane'
import type { PitPlan } from './pit-plan'
import { steerToward } from './pursuit'
import type { LineStyle, RacingLine } from './racing-line'
import { buildSpeedProfile, carLimits, type PacePlan } from './speed-profile'
import { AI_TUNING, type TemperamentTraits } from './tuning'

// An AI driver (F-301). It sees what a player sees — its own car and the others, as the session's snapshot has
// them — and gives back what a player gives: throttle, brake and steering for the tick. It follows its racing line
// by aiming at a point ahead on it, holds the speed its plan gives for where it is, makes room for and goes round
// other cars, and turns the car round when it finds itself facing the wrong way. In the pit lane, where its line
// does not go, it follows the pit route out to the lap (F-303). In a session whose cars have no reverse it does none
// of its backing up: where it would, it stands on the brake, which is how a car that cannot get away forwards calls
// its marshal (F-508). A driver that owes a pit stop comes in for it on
// the lap it was given, or sooner if the clock would not let it wait: it slows for the pit entry, takes the pit
// route, and drives it at the pit lane's pace; the session stops the car in the stop zone and lets it go again
// (F-306). Everything it remembers is in the object `createAiDriver` returns; its only randomness is the generator
// it is given.

/** One of the roster's drivers (contracts.md §9). Plain data. */
export interface DriverProfile {
  id: DriverId
  name: string
  shortName: string
  /** 0..1 */
  skill: number
  temperament: 'clean' | 'aggressive' | 'erratic' | 'rain-specialist' | 'steady'
  preferredColour: CarColour
  /** Facts for commentary filler. */
  bio: string[]
}

export interface AiDriverConfig {
  profile: DriverProfile
  difficulty: Difficulty
  car: CarParams
  /** The speed over a kerb that risks rolling a car, m/s: a line that takes kerbs is planned below it. Left out, kerbs are planned like asphalt. */
  kerbRollSpeedMS?: number
  /** False for a driver that never makes the big mistake that puts a car off (`AI_TUNING.accidents`); left out, it makes them as often as its difficulty, skill and temperament say. */
  accidents?: boolean
  /** False in a session whose cars have no reverse (F-508): the driver never asks for it, and where it would have backed up it stands on the brake until a marshal puts the car back. Left out, the car has reverse. */
  reverse?: boolean
}

export interface AiDriver {
  /**
   * One tick. Reads only the snapshot; returns intent. `others` is every car of the session, the driver's own
   * included (it skips itself). `clockRemainingS` is what the on-screen timer shows (F-306): a driver with a pit
   * stop to make reads it as a player does; left out, there is all the time in the world. `grip` is what the racing
   * line's asphalt truly has of its dry grip, 1 on a dry track; the driver plans on what it believes of that (F-604).
   * `weather` is the wetness of the track off the line, the puddles and the wind as they are; left out, the track
   * is as wet as its line, with no puddles and no wind. The object returned is reused by the next call.
   */
  control(self: CarSnapshot, others: readonly CarSnapshot[], grip: number, clockRemainingS?: number, weather?: Pick<Conditions, 'wetness' | 'puddles' | 'wind'>): ControlInput
  /** The grip its plan of speeds was last made for, and how many times it has made one (F-604). */
  readonly planGrip: number
  readonly planBuilds: number
  /** The line this driver follows. */
  readonly line: RacingLine
  /** The point it steered for on its latest tick, world metres. */
  readonly target: Readonly<Vec2>
  /** Whether it is turning the car round, backing away from something, or waiting for a marshal with no way of doing either (F-508): not racing. */
  readonly recovering: boolean
  /** The lap it was given to make its pit stop on, as a count of laps completed (F-306); null for a driver with no stop to make. */
  readonly pitLap: number | null
  /** Appends everything the driver remembers between ticks, in a fixed order. */
  hashInto(buffer: number[]): void
}

const T = AI_TUNING
const C = AI_TUNING.conditions

/** A driver's skill once the difficulty setting has scaled it, 0..1. */
export function effectiveSkill(profile: Pick<DriverProfile, 'skill'>, difficulty: Difficulty): number {
  return clamp(profile.skill * T.difficulty[difficulty], 0, 1)
}

/** The line a driver wants: a margin to the lane's limit that grows as skill falls, and kerbs or not by temperament. */
export function lineStyleFor(profile: Pick<DriverProfile, 'skill' | 'temperament'>, difficulty: Difficulty): LineStyle {
  const skill = effectiveSkill(profile, difficulty)
  return { marginM: T.line.marginM + T.line.marginPerSkillLostM * (1 - skill), kerbs: T.temperament[profile.temperament].kerbs }
}

const bySkill = (pair: readonly number[], skill: number): number => lerp(pair[0], pair[1], skill)

/** How much of its car a driver plans on using: more of it the more skill it has. */
function pacePlanFor(cfg: AiDriverConfig): PacePlan {
  const skill = effectiveSkill(cfg.profile, cfg.difficulty)
  return {
    cornerShare: bySkill(T.pace.cornerShare, skill),
    brakeShare: bySkill(T.pace.brakeShare, skill),
    driveShare: bySkill(T.pace.driveShare, skill),
    kerbCapMS: cfg.kerbRollSpeedMS === undefined ? Infinity : cfg.kerbRollSpeedMS * T.pace.kerbRollShare,
  }
}

/** What a driver's own plan makes a lap of its line on a dry track, s: the line driven at the planned speed all the way round. */
export function plannedLapS(cfg: AiDriverConfig, line: RacingLine): number {
  const speeds = buildSpeedProfile(line, cfg.car, 1, pacePlanFor(cfg))
  let seconds = 0
  for (let i = 0; i < speeds.length; i++) seconds += line.stepM / speeds[i]
  return seconds
}

const NO_PUDDLES: Conditions['puddles'] = Object.freeze([])
const REBUILD_TICKS = Math.round(C.rebuildEveryS / DT)

const RACING = 0
/** Driving forward on full lock to bring the nose round. */
const TURNING = 1
/** Reversing on the opposite lock, which turns the car the same way. */
const REVERSING = 2
/** Reversing away from whatever stopped the car. */
const BACKING_OFF = 3
/** In the pit lane, following the pit route out. */
const IN_PITS = 4
/** Standing on the brake where it would have backed up, in a car with no reverse (F-508): it waits to be called wedged and put back. */
const WAITING = 5

const BRAKING_POINT = 1
const APEX = 2
/** A jump of more line points than this in one tick is the car having been moved, not driven. */
const MOST_POINTS_PER_TICK = 30

/**
 * A driver for one car. `pit` is the track's pit lane as a driver needs it; left out, or null on a track that has
 * none, the driver knows only its line. `pitPlan` is the lap it is to make its pit stop on, in a session in which
 * its car owes one (F-306); left out, it never comes in of its own accord.
 */
export function createAiDriver(cfg: AiDriverConfig, line: RacingLine, rng: Rng, pit: PitPath | null = null, pitPlan: PitPlan | null = null): AiDriver {
  const { car } = cfg
  const skill = effectiveSkill(cfg.profile, cfg.difficulty)
  const traits: TemperamentTraits = T.temperament[cfg.profile.temperament]
  const style = lineStyleFor(cfg.profile, cfg.difficulty)
  const points = line.points
  const count = points.length
  const plan = pacePlanFor(cfg)
  /** What it does where it would back up, by `how`: that, in a car that has reverse; and with none, it waits. */
  const backUp = (how: number): number => (cfg.reverse === false ? WAITING : how)

  // Everything random about the driver comes from its own generator: where its wander starts, and its mistakes.
  const wanderRng = rng.fork('wander')
  const mistakeRng = rng.fork('mistakes')
  const accidentRng = rng.fork('accidents')
  const wanderPhase = [wanderRng.range(0, TWO_PI), wanderRng.range(0, TWO_PI)]
  const wanderM = T.wander.amplitudeM * (1 - skill) * traits.wander
  /** How many braking zones this driver gets through, on average, between one mistake and the next. */
  const mistakeChance = clamp(T.mistakes.perZone * (1 - skill) ** 2 * traits.mistakes, 0, 1)
  const zonesPerMistake = mistakeChance > 0 ? 1 / mistakeChance : Infinity
  /** How long this driver races, on average, between one big mistake and the next, in ticks; for ever for a driver that makes none. */
  const accidentsPerMinute = cfg.accidents === false ? 0 : T.accidents.perMinute[cfg.difficulty] * bySkill(T.accidents.bySkill, skill) * traits.accidents
  const ticksPerAccident = accidentsPerMinute > 0 ? 60 / accidentsPerMinute / DT : Infinity
  /** The racing still to do before the next one, in ticks: as likely at one moment as at another. */
  const drawAccidentGap = (): number => (ticksPerAccident === Infinity ? Infinity : -Math.log(1 - accidentRng.next()) * ticksPerAccident)
  /** How long this driver's mistakes last, against those of a driver of no skill. */
  const severity = (1 - skill) ** T.mistakes.severityPower
  /** The share of its plan a shaken driver slows to before it trusts the car again. */
  const shakenShare = bySkill(T.save.shakenShare, skill)
  const shakenForTicks = Math.round(bySkill(T.save.shakenS, skill) / DT)
  /** How far beyond its own corridor the driver will put the car to get past another, m. */
  const passSpareM = Math.max(0, style.marginM - T.traffic.leastMarginM) * traits.passMarginUse
  /** The same, to get round a car that is standing still: all the margin it has. */
  const stoppedSpareM = Math.max(0, style.marginM - T.traffic.leastMarginM)
  /** Cars are clear of each other sideways when their centres are this far apart, m. */
  const clearM = car.widthM + traits.passClearM * T.traffic.clearShare
  const passM = car.widthM + traits.passClearM
  /** Nearer than this sideways, two cars would touch if one came up on the other, m. */
  const touchM = car.widthM + T.traffic.touchClearM
  /** A point may be this far outside the corridor and still be on the lane: half a car and the margin, less a little. */
  const edgeSlackM = car.widthM / 2 + style.marginM - T.recovery.edgeKeepM

  // The plan: a target speed at each point of the line, and where its braking points and apexes are.
  let profile: Float64Array = new Float64Array(0)
  let marks: Uint8Array = new Uint8Array(0)
  /** At a braking point, how long the zone it opens is, m, and how much speed the plan sheds over it, m/s. */
  let zoneM: Float64Array = new Float64Array(0)
  let zoneDropMS: Float64Array = new Float64Array(0)
  let profileGrip = NaN
  /** The driver's judgement of the grip (F-604), the tick its plan was last made on, and how many plans it has made. */
  const judgement = createGripJudgement(cfg.profile, skill, rng.fork('conditions'))
  let builtTick = 0
  let builds = 0
  /** The puddles it was told of on the tick in progress; and where each stands on its line, found once: they do not move. */
  let puddles: Conditions['puddles'] = NO_PUDDLES
  /** The grip it believes the asphalt has off the racing line, where the pit lane is, on the tick in progress: the line's on a track that is evenly wet, less where the cars have dried the line. */
  let offLineGrip = 1
  const puddleOnLine: Array<{ x: number; y: number; s: number; lateralM: number }> = []
  let followBrakeMS2 = 1
  let topSpeedMS = 0
  /** How far before the pit entry a car at its top speed has to begin slowing for it, m; never less than the lead-in. */
  let comeInFromM: number = T.pit.leadInM
  let limits = carLimits(car, 1)
  const setPlan = (grip: number): void => {
    profile = buildSpeedProfile(line, car, grip, plan)
    profileGrip = grip
    limits = carLimits(car, grip)
    followBrakeMS2 = limits.brakeMS2(0, 0, plan.brakeShare)
    topSpeedMS = limits.topSpeedMS
    comeInFromM = Math.max(T.pit.leadInM, (topSpeedMS * topSpeedMS - T.pit.speedMS * T.pit.speedMS) / (2 * followBrakeMS2))
    marks = new Uint8Array(count)
    zoneM = new Float64Array(count)
    zoneDropMS = new Float64Array(count)
    // A braking zone runs from where the plan starts to fall to where it stops falling.
    const falling = (i: number): boolean => profile[(i + 1) % count] < profile[i]
    for (let i = 0; i < count; i++) {
      if (!falling(i) || falling((i - 1 + count) % count)) continue
      let end = i
      while (falling(end % count) && end < i + count) end++
      if (profile[i] - profile[end % count] >= T.mistakes.zoneDropMS) {
        marks[i] = BRAKING_POINT
        marks[end % count] = APEX
        zoneM[i] = (end - i) * line.stepM
        zoneDropMS[i] = profile[i] - profile[end % count]
      }
    }
  }

  // What the driver remembers between ticks. All of it goes into `hashInto`.
  let ticks = 0
  /** The tick the spell of driving it is in began, as the car's snapshot tells it; -1 before the driver's first tick. */
  let drivingSinceTick = -1
  let mode = RACING
  /** While not racing: which way it is turning the car, 1 to the right; and how long the present move has lasted. */
  let turnDir = 1
  let moveTicks = 0
  let stalledTicks = 0
  /** How many times running it has had to back away at the same place, and where on the line that place is. */
  let stalls = 0
  let stalledAtS = 0
  /** Where it means the car to be, to the right of its line, m. It moves there at a limited rate. */
  let offsetM = 0
  /** Which side it is passing the car ahead on: -1 left, 1 right, 0 not passing; which car that is; and for how long it has been at it. */
  let passSide = 0
  let passCar = -1
  let passTicks = 0
  /** How long the car ahead has been holding it below its own plan, in ticks; negative while it waits after giving a pass up. */
  let heldTicks = 0
  /** The line point it was last at, for noticing braking points and apexes go by; -1 before the first tick. */
  let lastIndex = -1
  /** Metres still to run of a late-braking or an early-throttle mistake. */
  let lateM = 0
  let earlyM = 0
  /** The late braking in progress is the big mistake (`AI_TUNING.accidents`), not a small one: nothing holds the car back until it is over, not even a kerb. */
  let missedBraking = false
  /** Braking zones still to come before its next mistake; the first is due anywhere within the longest gap between two. */
  let zonesToMistake = zonesPerMistake === Infinity ? Infinity : zonesPerMistake * mistakeRng.range(0, T.mistakes.gap[1])
  /** Ticks of racing still to do before its next big mistake: it is made at the first hard braking zone after that. */
  let accidentInTicks = drawAccidentGap()
  /** The mistake that is due is an early throttle: it is made at the apex of the zone the car is in. */
  let earlyDue = false
  /** Ticks still to run of driving well under its plan, shaken by the mistake it has just made. */
  let shakenTicks = 0
  /** Metres still to run at the pit lane's pace, having just come out of it onto the lap. */
  let joiningM = 0
  /** For how many ticks it has been backing away from a car that is standing still in front of it, to have room to steer round it; 0 while it is not. */
  let roomTicks = 0
  /** Ticks it has stood behind a car that is standing still with no way round it inside its own margins (F-604). */
  let squeezeTicks = 0
  /** It is coming in for its pit stop this time round: from the way to the pit entry until it is back on the lap. */
  let pitting = false

  const target: Vec2 = { x: 0, y: 0 }
  const out: ControlInput = { throttle: 0, brake: 0, steer: 0 }
  // The other cars near this one, as the driver's line sees them. Reused every tick.
  /** Set by `traffic` for the tick in progress: the car is right behind one that is standing still. */
  let boxedIn = false
  /** Set by `traffic`: the clear road to the nearest car standing still in its way, m; infinite with none. */
  let blockGapM = Infinity
  /** Set by `traffic`: a car is close behind, where backing up would meet it. */
  let closeBehind = false
  /** Set by `traffic`: the clear road to the tail of the car it is going round, m; infinite when it is going round none. */
  let passRoomM = Infinity
  /** Set by `traffic`: the side it is going round water on, -1 left, 1 right, 0 none (F-606); and the distance along its line at which it is past it. */
  let holdSide = 0
  let holdUntilS = 0
  /** Set by `traffic`: how far it is from where it means to be across the lane, m. */
  let toMoveOverM = 0
  /** Set by `traffic`: how many cars it found near, in the lists below. */
  let nearCount = 0
  const nearId: number[] = []
  const nearGap: number[] = []
  const nearLateral: number[] = []
  const nearSpeed: number[] = []
  const nearRoomLeft: number[] = []
  const nearRoomRight: number[] = []
  /** How much more of the lane a car that is standing still takes up, each side, than one that lies along the line, m: it may lie askew. */
  const nearWider: number[] = []

  /** A distance along the line, taken the short way round: positive ahead. */
  const ahead = (fromS: number, toS: number): number => {
    const gap = (((toS - fromS) % line.lengthM) + line.lengthM) % line.lengthM
    return gap > line.lengthM / 2 ? gap - line.lengthM : gap
  }

  /** Which side the inside of the next bend is on, looking a few metres along the line from `s`: -1 left, 1 right, 0 for none near. */
  const insideAhead = (s: number): number => {
    const first = line.indexAt(s)
    const reach = Math.round(T.traffic.bendAheadM / line.stepM)
    for (let k = 0; k < reach; k++) {
      const bend = points[(first + k) % count].curvature
      if (Math.abs(bend) > T.traffic.bendCurvature) return bend > 0 ? 1 : -1
    }
    return 0
  }

  /** Whether a point is on the lane, as far as the line knows: within the corridor where it is, and the slack. */
  const onLane = (x: number, y: number, hintS: number): boolean => {
    const near = line.nearest(x, y, hintS)
    const lateralM = near.lateralM
    const point = points[line.indexAt(near.s)]
    return lateralM >= -(point.roomLeftM + edgeSlackM) && lateralM <= point.roomRightM + edgeSlackM
  }

  /** The steering input that points the car at `target`: pure pursuit, as a share of the lock available at this speed. */
  const steerFor = (self: CarSnapshot): number => steerToward(self.pose, self.speedMS, target, car)

  /** Aims at the line `aheadM` on from `s`, moved `offset` to its right, kept within `spareM` of the corridor there. */
  const aimAt = (s: number, aheadM: number, offset: number, spareM: number): void => {
    const u = ((s + aheadM) / line.stepM) % count
    const i = Math.min(count - 1, Math.floor(u))
    const a = points[i]
    const b = points[(i + 1) % count]
    const f = u - i
    const heading = a.headingRad + angleDiff(a.headingRad, b.headingRad) * f
    const roomLeft = a.roomLeftM + (b.roomLeftM - a.roomLeftM) * f
    const roomRight = a.roomRightM + (b.roomRightM - a.roomRightM) * f
    const aside = Math.max(-(roomLeft + spareM), Math.min(roomRight + spareM, offset))
    target.x = a.x + (b.x - a.x) * f - Math.sin(heading) * aside
    target.y = a.y + (b.y - a.y) * f + Math.cos(heading) * aside
  }

  /** Where puddle `n` of those it was told of stands on its line: found once, since puddles do not move. */
  const puddlePlace = (n: number): { x: number; y: number; s: number; lateralM: number } => {
    const puddle = puddles[n]
    let at = puddleOnLine[n]
    if (at === undefined || at.x !== puddle.x || at.y !== puddle.y) {
      const on = line.nearest(puddle.x, puddle.y)
      at = puddleOnLine[n] = { x: puddle.x, y: puddle.y, s: on.s, lateralM: on.lateralM }
    }
    return at
  }

  /**
   * Whether a car `position` to the right of the line would have its side in water, anywhere from `fromM` behind
   * `s` to `toM` ahead of it, or as far ahead as it would take to move from there across the whole of the water at
   * `acrossMS` going at `speedMS` (F-606): a pass is not made through a puddle, nor begun too close to one to get
   * round it.
   */
  const wetAlong = (s: number, position: number, fromM: number, toM: number, speedMS: number, acrossMS: number): boolean => {
    for (let n = 0; n < puddles.length; n++) {
      const puddle = puddles[n]
      if (puddle.depth < C.puddleLeastDepth || puddle.r <= 0) continue
      const at = puddlePlace(n)
      const gapM = ahead(s, at.s)
      const reachM = puddle.r + car.widthM / 2 + C.puddleClearM
      if (gapM + puddle.r < -fromM || gapM - puddle.r > Math.max(toM, speedMS * ((2 * reachM) / acrossMS + C.puddleSettleS))) continue
      if (Math.abs(at.lateralM - position) < reachM) return true
    }
    return false
  }

  /** The room the corridor has on one side of the line at `atS`, m (`side` -1 left, 1 right), between its points. */
  const sideRoomAt = (atS: number, side: number): number => {
    const u = (((atS / line.stepM) % count) + count) % count
    const i = Math.min(count - 1, Math.floor(u))
    const a = points[i]
    const b = points[(i + 1) % count]
    return side < 0 ? a.roomLeftM + (b.roomLeftM - a.roomLeftM) * (u - i) : a.roomRightM + (b.roomRightM - a.roomRightM) * (u - i)
  }

  /**
   * The most speed the car may have now if it is to be down to the kerb cap by the time its front wheels are on the
   * next kerb in its way (F-501); no limit with no kerb near, or for a driver that was told of no roll speed. The
   * way ahead is read off the line: from the rear wheels forward as far as the car needs to slow down in, at each
   * point the band across the line the car's centre may be in by then, between where it is, where it is drifting and
   * where it means to be. A kerb within that band's reach of the wheels is in the way.
   */
  const kerbLimitMS = (s: number, lateralM: number, facing: number, speedMS: number): number => {
    const capMS = plan.kerbCapMS
    if (capMS === Infinity) return Infinity
    const slowMS2 = followBrakeMS2 * T.kerb.brakeUse
    // Nearer than this, the front wheels are as good as on it: the pedals will not have answered before they are.
    const nearM = car.cgToFrontAxleM + speedMS * T.kerb.lagS
    const toKerbM = kerbInWay(s, lateralM, facing, nearM + Math.max(0, speedMS * speedMS - capMS * capMS) / (2 * slowMS2) + line.stepM)
    return toKerbM === Infinity ? Infinity : Math.sqrt(capMS * capMS + 2 * slowMS2 * Math.max(0, toKerbM - nearM))
  }

  /** How far ahead of the car's centre, along the line, the first kerb in its wheels' way is, m, looking from its rear wheels to `aheadM`; `Infinity` with none. */
  const kerbInWay = (s: number, lateralM: number, facing: number, aheadM: number): number => {
    // Across the line, the car moves over as far as it is pointed across it, less what it will have steered out.
    const driftPerM = clamp(Math.tan(clamp(facing, -1, 1)), -1, 1) * T.kerb.driftShare
    for (let d = -car.cgToRearAxleM; d <= aheadM; d += line.stepM) {
      const k = line.indexAt(s + d)
      const drifted = lateralM + Math.max(0, d) * driftPerM
      const low = Math.min(lateralM, offsetM, drifted) - T.kerb.padM
      const high = Math.max(lateralM, offsetM, drifted) + T.kerb.padM
      if (-low >= line.kerbLeftM[k] || high >= line.kerbRightM[k]) return Math.max(0, d)
    }
    return Infinity
  }

  /**
   * The pedals that take the car toward a speed: throttle below it, nothing just above it, brake further above.
   * Never both. The throttle is held to `mostThrottle` and the brake to `mostBrake`: what the tyres can take of
   * each as the car is cornering now.
   */
  const pedalsFor = (speedMS: number, wantedMS: number, mostThrottle: number, mostBrake: number): void => {
    const short = wantedMS - speedMS
    out.throttle = short >= 0 ? Math.min(mostThrottle, clamp(T.speed.holdThrottle + T.speed.throttlePerMS * short, 0, 1)) : 0
    out.brake = short < -T.speed.brakeOverMS ? Math.min(mostBrake, clamp(T.speed.brakePerMS * (-short - T.speed.brakeOverMS), 0, 1)) : 0
  }

  /** Standing on the brake with the wheels straight: all that a car with no reverse can do where it would back up (F-508). */
  const wait = (): void => {
    out.steer = 0
    out.throttle = 0
    out.brake = 1
  }

  /**
   * Not racing: bring the car round to face along the line. Forward on full lock while there is lane ahead of the
   * nose; when there is not, back on the opposite lock, which keeps the car turning the same way. In a car with no
   * reverse (F-508) there is no backing: where it would, it stands on the brake, wheels straight, and stays so until
   * the car has been out of its hands and is handed back.
   */
  const recover = (self: CarSnapshot, s: number, lateralM: number, facing: number): void => {
    const R = T.recovery
    moveTicks++
    const cos = Math.cos(self.pose.angle)
    const sin = Math.sin(self.pose.angle)
    target.x = self.pose.x + cos * R.noseAheadM
    target.y = self.pose.y + sin * R.noseAheadM
    if (mode === WAITING) {
      wait()
      return
    }
    if (Math.abs(facing) < R.eitherWayRad && mode !== BACKING_OFF) turnDir = facing < 0 ? -1 : 1
    const noseFree = onLane(
      self.pose.x + cos * R.noseAheadM - sin * turnDir * R.noseAsideM,
      self.pose.y + sin * R.noseAheadM + cos * turnDir * R.noseAsideM,
      s,
    )
    const tailFree = onLane(self.pose.x - cos * R.tailBehindM, self.pose.y - sin * R.tailBehindM, s)

    // Not moving in the middle of a move: something solid is in the way of it. Do the other thing: back away from
    // what stops the car going forward, or go forward, turning the other way, from what stops it backing.
    stalledTicks = Math.abs(self.speedMS) < R.stalledMS ? stalledTicks + 1 : 0
    if (stalledTicks >= R.stalledS / DT) {
      stalledTicks = 0
      moveTicks = 0
      if (mode === TURNING) {
        stalls = Math.abs(ahead(stalledAtS, s)) < R.samePlaceM ? stalls + 1 : 1
        stalledAtS = s
        mode = backUp(BACKING_OFF)
      } else {
        mode = TURNING
        turnDir = -turnDir
      }
    }

    if (mode === BACKING_OFF) {
      // Away from whatever stopped the car, lane behind it or not: staying against it is the one thing that cannot
      // work. Further each time it has to be done again at the same place.
      if (moveTicks >= (R.backOffS * Math.min(stalls, R.backOffMostTimes)) / DT) {
        mode = TURNING
        moveTicks = 0
      }
    }
    if (mode === TURNING) {
      if (Math.abs(facing) < R.exitRad) {
        mode = RACING
        stalledTicks = 0
        return
      }
      if (!noseFree && tailFree) {
        mode = backUp(REVERSING)
        moveTicks = 0
      }
    } else if (mode === REVERSING && moveTicks >= R.reverseMinS / DT && (!tailFree || moveTicks >= R.reverseMaxS / DT || (noseFree && Math.abs(facing) < Math.PI / 2))) {
      mode = TURNING
      moveTicks = 0
    }

    if (mode === TURNING) {
      out.steer = turnDir
      out.brake = 0
      // Rolling backward out of a reverse, the throttle is what stops the car and sends it forward again.
      out.throttle = self.speedMS < 0 ? 1 : clamp(T.speed.holdThrottle + T.speed.throttlePerMS * (R.speedMS - self.speedMS), 0, 1)
    } else if (mode === WAITING) {
      wait()
    } else {
      // Held at a standstill the brake is reverse. Going backward the wheels turn the car the other way: backing
      // off, they swing the nose toward the line and its direction; and, tried again at the same place, the other
      // way, since whatever is in the way may be passable on its other side.
      const swing = (facing - lateralM * R.backOffSwingPerM) * (stalls % 2 === 0 ? -1 : 1)
      out.steer = mode === BACKING_OFF ? (Math.abs(swing) > R.backOffDeadbandRad ? -Math.sign(swing) : stalls % 2 === 0 ? 1 : 0) : -turnDir
      out.throttle = 0
      out.brake = 1
    }
  }

  /** The speed a car may have this far before the pit entry, m/s, to be down to the pit lane's pace there with the braking it plans on. */
  const comeInMS = (toEntryM: number): number => Math.sqrt(T.pit.speedMS * T.pit.speedMS + 2 * followBrakeMS2 * Math.max(0, toEntryM))

  /**
   * Whether this is the time round to come in for the stop it owes: the lap it was given, or any lap after it; or
   * an earlier one, when the clock would not see it round again and through its stop. On its first lap it waits
   * even so, unless the clock would not see it round again at all: a stop that ends after time is up is still a
   * stop, and the first lap is no place for one while there is another to be had.
   */
  const comesIn = (self: CarSnapshot, stop: PitPlan, clockRemainingS: number): boolean => {
    if (self.lap >= stop.lap) return true
    const lapS = self.lastLapMs === null ? stop.lapS * T.pitStop.lapSlack : self.lastLapMs / 1000
    return clockRemainingS < lapS * T.pitStop.lastChanceLapShare + (self.lap === 0 ? 0 : T.pitStop.reserveS)
  }

  /** What the cars beside a driver that is on its way in ask of it: see `pitSideTraffic`. */
  const wayIn = { behindMS: Infinity, dropBackMS: Infinity, beside: false }

  /**
   * On its way in for a stop (F-306), the moving cars on the side of it that the pit lane is on are between it and
   * the pit entry: turning in across one would be a collision, and holding station beside one carries this car
   * past the entry. So the driver goes in behind them. This fills `wayIn` with the two speeds that does it, m/s,
   * infinite where there is no such car: `behindMS`, to come up no nearer than its following gap to the tail of
   * one that is ahead, as it would behind a car in its own path; and `dropBackMS`, to let one get away that is
   * alongside, or nearer ahead than that gap, or close behind and catching it up, since that one will be
   * alongside by the pit entry. `beside` says that a car is alongside on either side: until it is gone the driver
   * does not move across the lane. To be called after `traffic`, which finds the cars near; with `pitSide` 0, for a
   * driver that is not on its way in, it asks nothing.
   */
  const pitSideTraffic = (lateralM: number, pitSide: number, speedMS: number): void => {
    const P = T.pit
    const keepM = traits.followGapM + traits.headwayS * speedMS
    wayIn.behindMS = Infinity
    wayIn.dropBackMS = Infinity
    wayIn.beside = false
    for (let k = 0; pitSide !== 0 && k < nearCount; k++) {
      // A car that is standing still is gone round, not waited for.
      if (nearSpeed[k] < T.traffic.stationaryMS) continue
      /** The clear road from this car's nose to its tail, m: below zero while the two overlap, or it is behind. */
      const gapM = nearGap[k] - car.lengthM
      const clearAhead = nearGap[k] <= -(car.lengthM + P.giveWayClearM)
      const toPitSideM = (nearLateral[k] - lateralM) * pitSide
      if (!clearAhead && gapM < P.giveWayClearM && Math.abs(toPitSideM) < 2 * passM) wayIn.beside = true
      // Only the cars on the pit lane's side are in the way; and of those behind, only one that is catching up.
      if (toPitSideM < car.widthM * T.traffic.besideShare || (clearAhead && nearSpeed[k] <= speedMS)) continue
      if (gapM >= keepM) wayIn.behindMS = Math.min(wayIn.behindMS, Math.sqrt(nearSpeed[k] * nearSpeed[k] + 2 * followBrakeMS2 * (gapM - keepM)))
      else wayIn.dropBackMS = Math.min(wayIn.dropBackMS, Math.max(0, nearSpeed[k] - P.dropBackPerS * (keepM - gapM)))
    }
  }

  /**
   * In the pit lane: along the pit route toward its end, at the pit lane's own modest speed and slower through
   * its bends; behind any car that is in the way on it; and not out onto the lap in front of a car that is coming.
   * It does not stop for a pit stop of its own accord: the session brakes a car that owes one in the stop zone,
   * holds it and lets it go, and the driver steers and waits. Returns the speed it is trying for, m/s.
   */
  const leavePits = (self: CarSnapshot, others: readonly CarSnapshot[], path: PitPath, pitS: number): number => {
    const P = T.pit
    const speedNow = Math.max(0, self.speedMS)
    const aim = path.pose(Math.min(path.lengthM, pitS + P.lookaheadM + P.lookaheadPerMS * speedNow))
    target.x = aim.x
    target.y = aim.y
    out.steer = steerFor(self)

    const bend = Math.abs(angleDiff(path.pose(pitS).angle, path.pose(Math.min(path.lengthM, pitS + P.bendAheadM)).angle)) / P.bendAheadM
    let wantedMS = Math.min(P.speedMS, Math.sqrt((P.bendMS2 * offLineGrip) / Math.max(bend, 1e-6)))
    if (offLineGrip < 1) {
      // On a wet pit lane (F-604) the brakes do not shed that speed within the stretch the bend is measured over:
      // it looks as far on as it takes to slow from the lane's pace, and is down to each bend's speed by the bend.
      const slowingMS2 = followBrakeMS2 * Math.min(1, offLineGrip / profileGrip)
      const reachM = (P.speedMS * P.speedMS) / (2 * slowingMS2)
      for (let aheadM = P.wetStepM; aheadM <= reachM && pitS + aheadM < path.lengthM; aheadM += P.wetStepM) {
        const there = Math.abs(angleDiff(path.pose(pitS + aheadM).angle, path.pose(Math.min(path.lengthM, pitS + aheadM + P.bendAheadM)).angle)) / P.bendAheadM
        const bendMS = Math.sqrt((P.bendMS2 * offLineGrip) / Math.max(there, 1e-6))
        wantedMS = Math.min(wantedMS, Math.sqrt(bendMS * bendMS + 2 * slowingMS2 * aheadM))
      }
    }
    let coming = false
    for (const other of others) {
      if (other.id === self.id) continue
      const its = path.nearest(other.pose.x, other.pose.y)
      if (its.s > pitS && its.s - pitS < P.aheadM && Math.abs(its.lateralM) < touchM) {
        // A car in the pit lane that still owes its stop is about to be stopped where it is, or is standing for it:
        // there has to be room to stop behind it, and a little more than behind a car that is on its way.
        const stopping = other.lane === 'pit' && other.pitStopsOwed > 0
        const roomM = its.s - pitS - car.lengthM - P.gapM - (stopping ? P.stopGapM : 0)
        const itsSpeed = stopping ? 0 : Math.max(0, other.speedMS)
        wantedMS = Math.min(wantedMS, roomM > 0 ? Math.sqrt(itsSpeed * itsSpeed + 2 * followBrakeMS2 * roomM) : 0)
      }
      if (other.lane === 'lap' && other.speedMS > T.traffic.stationaryMS) {
        const toExitM = (((path.joinRouteS - other.routeS) % path.lapLengthM) + path.lapLengthM) % path.lapLengthM
        if (toExitM < Math.max(P.giveWayM, other.speedMS * P.giveWayS)) coming = true
      }
    }
    // Short of the lap's asphalt it waits for a car that is coming; once it is on its way out it goes.
    const toHoldM = path.joinS - P.holdShortM - pitS
    if (coming && toHoldM > -P.committedM) wantedMS = Math.min(wantedMS, Math.sqrt(2 * followBrakeMS2 * Math.max(0, toHoldM)))
    pedalsFor(self.speedMS, wantedMS, P.mostThrottle, 1)
    return wantedMS
  }

  /**
   * Looks at the cars near this one and decides where across the lane to be and how fast it may go. Returns the speed
   * limit they set, m/s. With `mayPass` false it goes round nothing but a car that is standing still: a driver on its
   * way into the pit lane follows the car ahead of it there (F-306).
   */
  const traffic = (self: CarSnapshot, others: readonly CarSnapshot[], s: number, lateralM: number, here: (typeof points)[number], wanderOffset: number, planMS: number, mayPass: boolean): number => {
    const X = T.traffic
    const speedNow = Math.max(0, self.speedMS)
    const lookM = X.aheadM + X.aheadPerMS * speedNow
    /** How fast it moves across the lane at this speed, m/s: the rate `offsetM` is moved at, below. */
    const acrossMS = X.offsetRateMS * Math.min(1, X.offsetFullRateBelowMS / Math.max(speedNow, 1e-6))
    let found = 0
    boxedIn = false
    blockGapM = Infinity
    closeBehind = false
    for (const other of others) {
      if (other.id === self.id) continue
      const hint = line.sAtRoute(other.routeS)
      const rough = ahead(s, hint)
      if (rough < -X.behindM - line.stepM * MOST_POINTS_PER_TICK || rough > lookM + line.stepM * MOST_POINTS_PER_TICK) continue
      const near = line.nearest(other.pose.x, other.pose.y, hint)
      const gap = ahead(s, near.s)
      const lateral = near.lateralM
      if (gap < -X.behindM || gap > lookM) continue
      const first = line.indexAt(near.s)
      const point = points[first]
      const itsSpeed = other.velocity.x * Math.cos(point.headingRad) + other.velocity.y * Math.sin(point.headingRad)
      // The room beside it is the least there is over the stretch it will cover while it is being passed.
      const stretch = Math.round(clamp(itsSpeed * X.passTakesS, X.passLeastM, X.passMostM) / line.stepM)
      let roomLeft = point.roomLeftM
      let roomRight = point.roomRightM
      for (let k = 1; k <= stretch; k++) {
        const on = points[(first + k) % count]
        roomLeft = Math.min(roomLeft, on.roomLeftM)
        roomRight = Math.min(roomRight, on.roomRightM)
      }
      nearId[found] = other.id
      nearGap[found] = gap
      nearLateral[found] = lateral
      nearSpeed[found] = itsSpeed
      nearRoomLeft[found] = roomLeft
      nearRoomRight[found] = roomRight
      const askew = angleDiff(point.headingRad, other.pose.angle)
      nearWider[found] = itsSpeed < X.stationaryMS ? (Math.abs(Math.sin(askew)) * car.lengthM + (Math.abs(Math.cos(askew)) - 1) * car.widthM) / 2 : 0
      found++
    }
    nearCount = found

    // The car to go round, if there is room. A car that is standing still comes before any other, the nearest that
    // is in the way of where the driver means to be or of where the car is now: it will not move, and it has to be
    // gone round. Otherwise the one a pass is already being made on, while it is still ahead and not pulling away;
    // otherwise the nearest car ahead that is in the way and is slower than the driver's own plan, or has been
    // holding the driver up.
    let slow = -1
    for (let k = 0; k < found; k++) {
      if (nearGap[k] <= 0 || nearSpeed[k] >= X.stationaryMS || (slow >= 0 && nearGap[k] >= nearGap[slow])) continue
      if (Math.abs(nearLateral[k] - wanderOffset) < clearM + nearWider[k] || Math.abs(nearLateral[k] - lateralM) < touchM + nearWider[k]) slow = k
    }
    if (slow < 0 && mayPass && passCar >= 0 && passTicks < X.passMaxS / DT) {
      for (let k = 0; k < found; k++) {
        if (nearId[k] === passCar && nearGap[k] > 0 && nearSpeed[k] < speedNow + X.pullingAwayMS) slow = k
      }
    }
    if (slow < 0 && mayPass) {
      // A pass given up is not tried again at once.
      if (passCar >= 0 && passTicks >= X.passMaxS / DT) heldTicks = -Math.round(X.passAgainS / DT)
      for (let k = 0; k < found; k++) {
        if (nearGap[k] <= 0 || Math.abs(nearLateral[k] - wanderOffset) >= clearM) continue
        const slower = nearSpeed[k] < planMS - X.slowerByMS || heldTicks >= X.heldUpS / DT
        if (slower && (slow < 0 || nearGap[k] < nearGap[slow])) slow = k
      }
    }

    let wanted = wanderOffset
    let spareM = -T.wander.keepInsideM
    let side = 0
    if (slow >= 0) {
      const standing = nearSpeed[slow] < X.stationaryMS
      // Round a car that is standing still the driver uses all the lane there is; round a moving one, as much of its own margin as its temperament gives up.
      const giveM = standing ? stoppedSpareM : passSpareM
      /** What is in the lane it would pass in at `position`: nothing (0), cars that are on their way (1), or one that is standing still (2). */
      const taken = (position: number): number => {
        let by = 0
        for (let k = 0; k < found; k++) {
          if (k === slow) continue
          if (nearGap[k] > -car.lengthM && nearGap[k] < nearGap[slow] + X.passLaneLengths * car.lengthM && Math.abs(nearLateral[k] - position) < clearM + nearWider[k]) {
            if (nearSpeed[k] < X.stationaryMS) return 2
            by = 1
          }
        }
        return by
      }
      let left = nearLateral[slow] - passM - nearWider[slow]
      let right = nearLateral[slow] + passM + nearWider[slow]
      // Going round a car that is standing still, it goes round any other that stands just beyond it as well.
      if (standing) {
        for (let k = 0; k < found; k++) {
          if (k === slow || nearGap[k] <= nearGap[slow] || nearSpeed[k] >= X.stationaryMS) continue
          if (Math.abs(nearLateral[k] - left) < clearM + nearWider[k]) left = nearLateral[k] - passM - nearWider[k]
          if (Math.abs(nearLateral[k] - right) < clearM + nearWider[k]) right = nearLateral[k] + passM + nearWider[k]
        }
      }
      // To go round a car that is standing still it has to be over to one side before it gets there: the room that
      // counts is the least there is from here to there. (A point the line's last smoothing left a hair outside its
      // corridor has none measured either way, and says nothing.)
      let roomLeft = nearRoomLeft[slow]
      let roomRight = nearRoomRight[slow]
      if (standing) {
        const from = line.indexAt(s)
        const steps = Math.round(nearGap[slow] / line.stepM)
        for (let k = 0; k < steps; k++) {
          const on = points[(from + k) % count]
          if (on.roomLeftM + on.roomRightM <= 0) continue
          roomLeft = Math.min(roomLeft, on.roomLeftM)
          roomRight = Math.min(roomRight, on.roomRightM)
        }
      }
      // Standing behind a car that is standing still, with no way round it inside its own margins, the driver does
      // not wait for ever (F-604): the longer it has stood there, the more of the lane's edge it will take.
      const patienceM = standing ? clamp((squeezeTicks * DT - X.squeezeAfterS) * X.squeezePerS, 0, X.squeezeMostM) : 0
      const leftSpare = left + roomLeft + giveM + patienceM
      const rightSpare = roomRight + giveM + patienceM - right
      // Once alongside, the driver is committed to the side it is on: there is no way back but to drop behind.
      const alongside = nearGap[slow] < car.lengthM
      const sameCar = nearId[slow] === passCar
      const leftTaken = taken(left)
      const rightTaken = taken(right)
      // A moving car is not passed through standing water (F-606), unless the driver is already alongside it there;
      // and no pass is begun with water on the driver's own way ahead, near enough that it has to be gone round.
      const passLaneM = nearGap[slow] + X.passLaneLengths * car.lengthM
      const holdOff = !standing && !(sameCar && passSide !== 0) && (wetAlong(s, wanderOffset, car.lengthM, 0, speedNow, acrossMS) || wetAlong(s, lateralM, car.lengthM, 0, speedNow, acrossMS))
      const leftWet = !standing && !(alongside && passSide < 0) && (holdOff || wetAlong(s, left, car.lengthM, passLaneM, speedNow, acrossMS))
      const rightWet = !standing && !(alongside && passSide > 0) && (holdOff || wetAlong(s, right, car.lengthM, passLaneM, speedNow, acrossMS))
      const leftOk = (leftSpare >= 0 || (alongside && passSide < 0)) && leftTaken === 0 && !leftWet
      const rightOk = (rightSpare >= 0 || (alongside && passSide > 0)) && rightTaken === 0 && !rightWet
      // A side once taken round a car is kept while there is room on it: changing sides at speed unsettles the car.
      // Round a car that is standing still, the side the driver is already off to is the nearer way: with room on
      // that side, and cars going by on it, it waits for them rather than cross behind the standing car to the
      // other. With a free choice, it takes the inside of the next bend to pass a car that is moving, and the side
      // with more room to go round one that is not.
      const offTo = standing && Math.abs(lateralM - nearLateral[slow]) > X.offToM ? Math.sign(lateralM - nearLateral[slow]) : 0
      if (sameCar && passSide < 0 && leftOk) side = -1
      else if (sameCar && passSide > 0 && rightOk) side = 1
      else if (offTo !== 0 && (offTo < 0 ? leftSpare : rightSpare) >= 0 && (offTo < 0 ? leftTaken : rightTaken) < 2) side = (offTo < 0 ? leftOk : rightOk) ? offTo : 0
      else if (leftOk && rightOk) side = (standing ? 0 : insideAhead(s)) || (leftSpare > rightSpare ? -1 : 1)
      else if (leftOk) side = -1
      else if (rightOk) side = 1
      if (side !== 0) {
        wanted = side < 0 ? left : right
        spareM = (alongside ? stoppedSpareM : giveM) + patienceM
      } else if (standing && Math.abs(nearLateral[slow] - lateralM) >= passM + nearWider[slow]) {
        // No room to move over to where it would pass, but it is clear of that car where it is, off to one side of
        // its line: it goes by on the side it is on, without coming back toward its line until it is past.
        side = lateralM < nearLateral[slow] ? -1 : 1
        wanted = side < 0 ? Math.min(lateralM, left) : Math.max(lateralM, right)
        spareM = stoppedSpareM
      }
    }
    // How long it has stood behind a standing car with no way round. Kept while it is going round one, so that the
    // way it found by waiting is not lost the moment it moves; gone as soon as no standing car is in its way.
    if (slow < 0 || nearSpeed[slow] >= X.stationaryMS) squeezeTicks = 0
    else if (side === 0 && Math.abs(self.speedMS) < T.recovery.stalledMS) squeezeTicks++
    passSide = side
    // Round a car that is standing still, the clear road to its tail, while the driver still has to move out from
    // behind it: one that is already wide of it has no need to hurry.
    passRoomM = side !== 0 && nearSpeed[slow] < X.stationaryMS && Math.abs(nearLateral[slow] - lateralM) < passM + nearWider[slow] ? nearGap[slow] - car.lengthM : Infinity
    passTicks = side !== 0 && nearId[slow] === passCar ? passTicks + 1 : 0
    passCar = side !== 0 ? nearId[slow] : -1

    // A car alongside is not to be driven into: stay the far side of it.
    let least = -Infinity
    let most = Infinity
    for (let k = 0; k < found; k++) {
      if (Math.abs(nearGap[k]) > car.lengthM + X.alongsideM || Math.abs(nearLateral[k] - lateralM) < car.widthM * X.besideShare) continue
      if (nearLateral[k] < lateralM) least = Math.max(least, nearLateral[k] + passM + nearWider[k])
      else most = Math.min(most, nearLateral[k] - passM - nearWider[k])
    }
    if (least > -Infinity || most < Infinity) {
      wanted = least > most ? lateralM : clamp(wanted, least, most)
      spareM = Math.max(spareM, passSpareM)
    }
    // Puddles (F-604): water that is in the way of where the driver means to be is gone round on a dry side, if
    // there is one inside its own lane; if there is none, or it is busy with a car, it goes through no faster than
    // it can without floating. Where its line bends at the water, the dry side it takes is the outside, a wider
    // entry (F-606). It begins as far ahead as it takes to move over at the rate it moves across the lane, and it
    // keeps its place across the lane while its line swings away under it toward the bend, as a line does at a
    // turn-in: it means to pass the water as far in from the edge of its corridor on that side as clears it.
    let puddleLimitMS = Infinity
    holdSide = 0
    for (let n = 0; n < puddles.length; n++) {
      const puddle = puddles[n]
      if (puddle.depth < C.puddleLeastDepth || puddle.r <= 0) continue
      const at = puddlePlace(n)
      const gapM = ahead(s, at.s)
      if (gapM < -(puddle.r + car.lengthM / 2)) continue
      const reachM = puddle.r + car.widthM / 2 + C.puddleClearM
      const leftOf = at.lateralM - reachM
      const rightOf = at.lateralM + reachM
      // The room its corridor has beside the water, the least of it along the water's length; and how the line bends there.
      const from = line.indexAt(at.s - puddle.r)
      const steps = Math.max(1, Math.round((2 * puddle.r) / line.stepM))
      let roomLeft = Infinity
      let roomRight = Infinity
      let bend = 0
      for (let k = 0; k <= steps; k++) {
        const on = points[(from + k) % count]
        roomLeft = Math.min(roomLeft, on.roomLeftM)
        roomRight = Math.min(roomRight, on.roomRightM)
        bend += on.curvature / (steps + 1)
      }
      const leftDry = leftOf >= -roomLeft
      const rightDry = rightOf <= roomRight
      /** The side it goes by on: the outside of a bend if that is dry, else the dry side nearer the car; 0 with neither. */
      const outside = Math.abs(bend) > C.puddleBendCurvature ? -Math.sign(bend) : 0
      const way = outside < 0 && leftDry ? -1 : outside > 0 && rightDry ? 1 : leftDry && (!rightDry || Math.abs(leftOf - lateralM) <= Math.abs(rightOf - lateralM)) ? -1 : rightDry ? 1 : 0
      // Looked for as far ahead as the move across takes, and the car to settle behind its aim; never nearer than before.
      const shiftM = way < 0 ? Math.max(0, -leftOf) : way > 0 ? Math.max(0, rightOf) : 0
      const leadM = speedNow * (shiftM / acrossMS + C.puddleSettleS)
      if (gapM > Math.max(C.puddleAheadM, speedNow * C.puddleAheadS, leadM) + puddle.r) continue
      if (Math.abs(at.lateralM - wanted) >= reachM && Math.abs(at.lateralM - lateralM) >= reachM) continue
      // Passing a car on the dry side, it goes round the water as well; passing on the wet side, it is committed.
      const goingRound = way !== 0 && (side === 0 || side === way)
      if (goingRound) {
        // As far in from the corridor's edge on that side, here, as it has to be beside the water.
        const inFromEdgeM = sideRoomAt(at.s, way) - (way < 0 ? -leftOf : rightOf)
        const there = way * (sideRoomAt(s, way) - inFromEdgeM)
        wanted = way < 0 ? Math.min(wanted, there) : Math.max(wanted, there)
        spareM = Math.max(spareM, 0)
        holdSide = way
        holdUntilS = at.s + puddle.r + car.lengthM / 2
      }
      // Still in it, or bound to be: no faster at its near edge than the car can go without floating.
      if ((!goingRound && Math.abs(at.lateralM - wanted) < reachM) || (gapM < car.lengthM && Math.abs(at.lateralM - lateralM) < reachM - C.puddleClearM)) {
        const throughMS = C.aquaplaneShare * aquaplaneSpeedMS(puddle.depth, car)
        puddleLimitMS = Math.min(puddleLimitMS, Math.sqrt(throughMS * throughMS + 2 * followBrakeMS2 * Math.max(0, gapM - puddle.r - car.lengthM / 2)))
      }
    }
    wanted = clamp(wanted, -(here.roomLeftM + spareM), here.roomRightM + spareM)
    toMoveOverM = Math.abs(wanted - lateralM)
    // Going round water, the line swinging away from that side since the last tick does not move the car across
    // the lane: where it means to be is kept as far from the corridor's edge as it was.
    if (holdSide !== 0) offsetM += holdSide * Math.max(0, sideRoomAt(s, holdSide) - sideRoomAt(s - speedNow * DT, holdSide))
    // Across the lane at a walking pace when the car is slow, and more gently the faster it is going.
    const acrossM = acrossMS * DT
    offsetM += clamp(wanted - offsetM, -acrossM, acrossM)

    // How fast the cars ahead allow: one in the car's path, or in the path it means to take, is followed at a gap.
    let limit = puddleLimitMS
    for (let k = 0; k < found; k++) {
      const inLineNow = Math.abs(nearLateral[k] - lateralM) < touchM + nearWider[k]
      if (nearGap[k] <= 0) {
        if (inLineNow && nearGap[k] > -(car.lengthM + X.behindClearM)) closeBehind = true
        continue
      }
      const inLineNext = Math.abs(nearLateral[k] - wanted) < clearM + nearWider[k]
      if (!inLineNow && !inLineNext) continue
      const gapM = nearGap[k] - car.lengthM
      // A car that is backing up is given the room it is after. Behind one that is standing still, with no way
      // round it yet, the driver waits far enough back to steer round it when there is one.
      const rounding = side !== 0 && !inLineNext && (k === slow || nearSpeed[k] < X.stationaryMS)
      const keepM = rounding ? X.passGapM : nearSpeed[k] < -T.recovery.stalledMS ? X.roomBackToM : nearSpeed[k] < X.stationaryMS ? X.standOffM : traits.followGapM + traits.headwayS * speedNow
      const itsSpeed = Math.max(0, nearSpeed[k])
      const allowed = gapM >= keepM ? Math.sqrt(itsSpeed * itsSpeed + 2 * followBrakeMS2 * (gapM - keepM)) : Math.max(0, itsSpeed - X.gapGainPerS * (keepM - gapM))
      limit = Math.min(limit, allowed)
      // Stopped right behind a car that is standing still, there is no room to steer round it.
      if (itsSpeed < X.stationaryMS) {
        if (gapM < X.swingRoomM) boxedIn = true
        blockGapM = Math.min(blockGapM, gapM)
      }
    }
    // Held below its own plan by a car ahead, the driver soon looks for a way past, whatever that car's speed.
    if (heldTicks < 0) heldTicks++
    else heldTicks = limit < planMS - X.heldByMS ? heldTicks + 1 : 0
    return limit
  }

  return {
    line,
    target,
    get recovering() {
      return mode !== RACING && mode !== IN_PITS
    },
    pitLap: pitPlan?.lap ?? null,

    get planGrip() {
      return profileGrip
    },
    get planBuilds() {
      return builds
    },

    control(self, others, grip, clockRemainingS = Infinity, weather) {
      ticks++
      // The plan is for the grip the driver believes in (F-604). It is made again only when that has moved by a
      // whole step since the plan was made, and never twice within the rebuild time: a plan is a lap's worth of work.
      const believed = judgement.judge(grip)
      if (builds === 0 || (Math.abs(believed - profileGrip) > C.rebuildStep && ticks - builtTick >= REBUILD_TICKS)) {
        setPlan(believed)
        builtTick = ticks
        builds++
      }
      puddles = weather?.puddles ?? NO_PUDDLES
      offLineGrip = weather === undefined ? believed : Math.min(1, (believed / grip) * lineGrip(weather.wetness))

      // Where the car is on its line, and which way it faces against the line's direction there.
      const near = line.nearest(self.pose.x, self.pose.y, line.sAtRoute(self.routeS))
      const s = near.s
      const lateralM = near.lateralM
      const index = line.indexAt(s)
      const here = points[index]
      const facing = angleDiff(self.pose.angle, here.headingRad)

      // The car has been out of the driver's hands since its last tick — stuck and set back on the lane, held for a
      // penalty or a pit stop, lifted out of a queue — and is handed back. Whatever the driver was in the middle of
      // is over: the car may stand somewhere else, facing another way, and backing away from the grass it had
      // stalled in would now be backing down the lane. It takes the car as it finds it, from where it is across
      // the lane; if it faces the wrong way, turning it round begins afresh below. In the pit lane it goes on along
      // the pit route as before.
      if (drivingSinceTick >= 0 && self.stateSinceTick !== drivingSinceTick) {
        if (mode !== IN_PITS) {
          mode = RACING
          offsetM = lateralM
        }
        moveTicks = 0
        stalledTicks = 0
        stalls = 0
        roomTicks = 0
        squeezeTicks = 0
        passSide = 0
        passCar = -1
        passTicks = 0
        heldTicks = 0
        lateM = 0
        earlyM = 0
        earlyDue = false
        lastIndex = -1
      }
      drivingSinceTick = self.stateSinceTick

      // A pit stop that is owed (F-306). On the way to the pit entry the driver settles whether this is the time
      // round, while it can still slow for it; from then on it is coming in. At the entry it takes the pit route,
      // if the car is where that begins; if it has gone by, it comes in the next time round.
      /** How far the pit entry is ahead along the lap, m; below zero once it is behind. */
      let toEntryM = Infinity
      if (pit !== null && pitPlan !== null && mode === RACING && self.lane === 'lap') {
        const gapM = (((pit.entryRouteS - self.routeS) % pit.lapLengthM) + pit.lapLengthM) % pit.lapLengthM
        toEntryM = gapM > pit.lapLengthM / 2 ? gapM - pit.lapLengthM : gapM
        if (!pitting) {
          pitting = self.pitStopsOwed > 0 && toEntryM > 0 && toEntryM <= comeInFromM && Math.max(0, self.speedMS) <= comeInMS(toEntryM) + T.speed.brakeOverMS && comesIn(self, pitPlan, clockRemainingS)
        } else if (toEntryM <= 0) {
          const on = pit.nearest(self.pose.x, self.pose.y)
          if (on.s < pit.ownFromS && Math.abs(on.lateralM) < T.pit.entryStrayM) mode = IN_PITS
          else pitting = false
        } else if (toEntryM > comeInFromM) {
          pitting = false
        }
      }
      /** On the way in, short of the pit entry. */
      const comingIn = pit !== null && pitting && mode === RACING && toEntryM > 0

      // In the pit lane the line is no guide: the pit route is, and the driver follows it out to where it ends, in
      // the middle of the lap's lane. Where the pit route still runs in the lap's own lane on the way in, before
      // the pit lane leaves it, the car is racing, unless it is coming in for its stop.
      const inPits = pit !== null && (self.lane === 'pit' || mode === IN_PITS) ? pit.nearest(self.pose.x, self.pose.y) : null
      const onPitRoute =
        pit !== null &&
        inPits !== null &&
        (self.lane === 'pit'
          ? inPits.s >= pit.ownFromS || pitting
          : inPits.s < pit.lengthM - T.pit.endM && Math.abs(inPits.lateralM) < (pitting && inPits.s < pit.ownFromS ? T.pit.entryStrayM : T.pit.strayM))
      if (pit !== null && inPits !== null && onPitRoute) {
        if (mode !== RACING && mode !== IN_PITS) {
          recover(self, s, inPits.lateralM, angleDiff(self.pose.angle, pit.pose(inPits.s).angle))
          if (mode !== RACING) return out
        }
        mode = IN_PITS
        const wantedMS = leavePits(self, others, pit, inPits.s)
        if (Math.abs(self.speedMS) < T.recovery.stalledMS && wantedMS > T.recovery.tryingMS) stalledTicks++
        else stalledTicks = 0
        if (stalledTicks >= T.recovery.stalledS / DT) {
          stalls = Math.abs(ahead(stalledAtS, s)) < T.recovery.samePlaceM ? stalls + 1 : 1
          stalledAtS = s
          mode = backUp(BACKING_OFF)
          moveTicks = 0
          stalledTicks = 0
        }
        return out
      }
      if (mode === IN_PITS) {
        // Off the end of the pit route: it races from where it is across the lane, and moves over to its line from
        // there, gently for the first few metres.
        mode = RACING
        pitting = false
        offsetM = lateralM
        joiningM = T.pit.joinM
        lastIndex = -1
        stalledTicks = 0
        heldTicks = 0
        passSide = 0
        passCar = -1
      }

      if (mode === RACING && Math.abs(facing) > T.recovery.enterRad) {
        mode = TURNING
        moveTicks = 0
        // Facing nearly backward, either way round is as far: turn toward the side of the lane with more room. A
        // car facing backward that turns to its own right moves to the left of the lane.
        if (Math.abs(facing) >= T.recovery.eitherWayRad) turnDir = here.roomLeftM + lateralM > here.roomRightM - lateralM ? 1 : -1
        else turnDir = facing < 0 ? -1 : 1
        passSide = 0
        passCar = -1
        lateM = 0
        earlyM = 0
        earlyDue = false
        shakenTicks = 0
        roomTicks = 0
      }
      if (mode !== RACING) {
        recover(self, s, lateralM, facing)
        if (mode !== RACING) {
          lastIndex = index
          return out
        }
      }

      // Braking points and apexes passed since the last tick. Every braking zone brings the driver's next mistake
      // one nearer; when it is due it is made there, by braking late, or at that zone's apex, by getting on the
      // throttle early, and the gap to the one after is drawn.
      if (lastIndex >= 0) {
        const passed = (index - lastIndex + count) % count
        if (passed <= MOST_POINTS_PER_TICK) {
          for (let k = 1; k <= passed; k++) {
            const at = (lastIndex + k) % count
            if (marks[at] === BRAKING_POINT && accidentInTicks <= 0 && zoneDropMS[at] >= T.accidents.zoneDropMS) {
              // The big one: the braking point goes by as if it were not there, for longer than any pedal can make up.
              lateM = accidentRng.range(T.accidents.lateBrakeShare[0], T.accidents.lateBrakeShare[1]) * zoneM[at]
              missedBraking = true
              accidentInTicks = drawAccidentGap()
            } else if (marks[at] === BRAKING_POINT && --zonesToMistake <= 0) {
              if (mistakeRng.chance(T.mistakes.earlyThrottleShare)) earlyDue = true
              else lateM = mistakeRng.range(T.mistakes.lateBrakeShare[0], T.mistakes.lateBrakeShare[1]) * severity * zoneM[at]
              zonesToMistake += zonesPerMistake * mistakeRng.range(T.mistakes.gap[0], T.mistakes.gap[1])
            } else if (marks[at] === BRAKING_POINT && judgement.hopeful > C.caughtOutOver) {
              // Caught out (F-604): it has come to a bend believing in grip that is not there, and finds out on the
              // brakes, as late as any mistake of its own. It knows better afterwards, for a while.
              lateM = mistakeRng.range(T.mistakes.lateBrakeShare[0], T.mistakes.lateBrakeShare[1]) * severity * zoneM[at]
              judgement.learn()
            } else if (marks[at] === APEX && earlyDue) {
              earlyM = mistakeRng.range(T.mistakes.earlyThrottleM[0], T.mistakes.earlyThrottleM[1]) * severity
              earlyDue = false
            }
          }
        }
      }
      lastIndex = index
      accidentInTicks--
      const speedNow = Math.max(0, self.speedMS)
      const movedM = speedNow * DT
      const mistaken = lateM > 0 || earlyM > 0
      lateM = Math.max(0, lateM - movedM)
      earlyM = Math.max(0, earlyM - movedM)
      if (lateM === 0) missedBraking = false

      // The plan's speed for where the car will be when the pedals have answered.
      const u = ((s + speedNow * T.speed.leadS) / line.stepM) % count
      const i = Math.min(count - 1, Math.floor(u))
      const planMS = profile[i] + (profile[(i + 1) % count] - profile[i]) * (u - i)
      let wantedMS = planMS
      // A driver who has just made a mistake is shaken, and drives well under its plan for a while before it trusts
      // the car again. Well over its plan, the car is too fast for the bend it is coming to.
      if (mistaken && lateM === 0 && earlyM === 0) shakenTicks = shakenForTicks
      const tooFast = speedNow > planMS * (1 + T.save.overShare)

      const time = ticks * DT
      const wanderOffset = wanderM * (T.wander.shares[0] * Math.sin(TWO_PI * T.wander.hz[0] * time + wanderPhase[0]) + T.wander.shares[1] * Math.sin(TWO_PI * T.wander.hz[1] * time + wanderPhase[1]))
      const limit = traffic(self, others, s, lateralM, here, wanderOffset, wantedMS, !comingIn)

      // Passing, the driver pushes. Off the line toward the inside of a bend the radius is tighter, and the speed for it lower.
      if (passSide !== 0) wantedMS = Math.min(topSpeedMS, wantedMS * traits.passPush)
      wantedMS *= Math.sqrt(clamp(1 - here.curvature * offsetM, T.traffic.offLineFloor ** 2, 1))
      if (lateM > 0 || earlyM > 0) wantedMS = topSpeedMS
      if (shakenTicks > 0) {
        shakenTicks--
        wantedMS = Math.min(wantedMS, planMS * shakenShare)
      }
      if (joiningM > 0) {
        joiningM = Math.max(0, joiningM - movedM)
        wantedMS = Math.min(wantedMS, T.pit.joinSpeedMS)
      }
      // Coming in for its stop, it is down to the pit lane's pace by the pit entry, whatever else it had in mind.
      if (comingIn) wantedMS = Math.min(wantedMS, comeInMS(toEntryM))
      wantedMS = Math.min(wantedMS, limit)
      // And it goes in behind the cars on the pit lane's side of it: it keeps off the tail of one that is ahead, and
      // lets one that is alongside go ahead.
      pitSideTraffic(lateralM, pit !== null && comingIn ? pit.side : 0, speedNow)
      wantedMS = Math.min(wantedMS, wayIn.behindMS)
      // A strong wind across the car, where it is going fast: a little in hand (F-604).
      if (weather !== undefined && speedNow > C.crosswindAboveMS) {
        const acrossMS = Math.abs(-weather.wind.x * Math.sin(self.pose.angle) + weather.wind.y * Math.cos(self.pose.angle))
        if (acrossMS > C.crosswindFromMS) wantedMS *= 1 - C.crosswindShare * clamp((acrossMS - C.crosswindFromMS) / (C.crosswindFullMS - C.crosswindFromMS), 0, 1)
      }
      // Last of all, the kerb cap (F-501): whatever has raised the speed it wants, it meets a kerb no faster than that.
      if (!missedBraking) wantedMS = Math.min(wantedMS, kerbLimitMS(s, lateralM, facing, speedNow))
      const giveWayMS = wayIn.dropBackMS

      if (self.surface === 'grass') {
        // On the grass: the shortest way back to the asphalt, with the throttle held. Braking there only bogs the car.
        aimAt(s, T.grass.lookaheadM, 0, 0)
        out.steer = steerFor(self)
        out.throttle = speedNow < T.grass.fullThrottleBelowMS ? 1 : T.grass.throttle
        out.brake = 0
      } else {
        // Going round a car that is standing still, it has to be over to one side before its nose is at that
        // car's tail: it aims at a point short of that, so that close behind it the car turns hard and at once.
        const lookaheadM = Math.min(T.steer.lookaheadBaseM + T.steer.lookaheadPerMS * speedNow, Math.max(T.traffic.aimLeastM, passRoomM - T.traffic.aimShortM))
        if (pit !== null && comingIn && toEntryM <= T.pit.leadInM) {
          // The last metres before the pit entry: off its line and onto the way in, which begins in the middle of
          // the lane. With a car alongside it keeps as far to the side of the way in as it is, neither closing on
          // that car nor drifting off after its own line, and moves across when the car has gone.
          const abeam = pit.wayIn(-toEntryM)
          const asideM = wayIn.beside ? -Math.sin(abeam.angle) * (self.pose.x - abeam.x) + Math.cos(abeam.angle) * (self.pose.y - abeam.y) : 0
          const aim = pit.wayIn(lookaheadM - toEntryM)
          target.x = aim.x - Math.sin(aim.angle) * asideM
          target.y = aim.y + Math.cos(aim.angle) * asideM
        } else {
          // Moving out from behind a car, it steers for as far beyond where it means to be as it is short of it:
          // pursuit alone cuts inside its mark, and by a car that is standing still there is no room for that.
          const overM = passRoomM < Infinity ? clamp((offsetM - lateralM) * T.traffic.aimOverShare, -T.traffic.aimOverMostM, T.traffic.aimOverMostM) : 0
          // Going round water (F-606), it aims where it means to be, kept as far from the corridor's edge as it is
          // now: up to the water's far side, its line swinging away from that side ahead does not draw it in.
          const keptM = holdSide === 0 ? 0 : holdSide * Math.max(0, sideRoomAt(s + Math.min(lookaheadM, Math.max(0, ahead(s, holdUntilS))), holdSide) - sideRoomAt(s, holdSide))
          aimAt(s, lookaheadM, offsetM + overM + keptM, passSide !== 0 ? stoppedSpareM : 0)
        }
        out.steer = steerFor(self)
        // Too fast for the bend, the brakes come first: the wheels are turned no further than leaves the tyres
        // most of their grip for slowing the car. It runs wide, but it runs wide slowly.
        if (tooFast && lateM === 0 && earlyM === 0) {
          const mostRad = Math.atan((limits.lateralMS2 * T.save.cornerUse * car.wheelbaseM) / Math.max(speedNow * speedNow, 1e-6))
          const most = mostRad / (lockFraction(speedNow, car) * car.maxSteerRad)
          out.steer = clamp(out.steer, -most, most)
        }
        // How hard the car is cornering now, and how hard the line asks it to: the tyres have that much less for
        // the pedals. The throttle waits for both; the brake only for what the car is doing, since a car that is
        // too fast for the bend ahead has to be slowed whatever the bend asks.
        const ellipseMS2 = limits.lateralMS2 * T.pace.ellipseShare
        const turning = Math.abs(self.speedMS * self.yawRateRadS)
        const asked = speedNow * speedNow * Math.abs(here.curvature)
        const mostThrottle = earlyM > 0 ? 1 : Math.max(T.speed.leastThrottle, limits.throttleRoom(speedNow, Math.max(turning, asked) / ellipseMS2))
        const mostBrake = Math.max(T.speed.leastBrake, limits.brakeRoom(turning / ellipseMS2))
        pedalsFor(self.speedMS, wantedMS, mostThrottle, mostBrake)
        if (giveWayMS < wantedMS) {
          // Dropping behind a car alongside: off the throttle, and a light brake at most, on top of whatever
          // braking the road ahead already asks for. A car that is following has to be able to follow this.
          const needed = out.brake
          pedalsFor(self.speedMS, giveWayMS, mostThrottle, Math.min(mostBrake, T.pit.giveWayBrake))
          out.brake = Math.max(out.brake, needed)
          wantedMS = giveWayMS
        }
      }

      // Brought to a stop right behind a car that is standing still, with no room to steer round it: back up until
      // there is, and more the further it has to move over. It gives up backing when a car is close behind, or
      // when it has backed as long as it will. The side it had taken did not get it past: it chooses again.
      // In a car with no reverse (F-508) it stands on the brake for as long as that is how things are: if the car
      // ahead goes, so does this one; if not, it is called wedged and set down beyond it.
      if (cfg.reverse === false) {
        if (boxedIn && Math.abs(self.speedMS) < T.recovery.stalledMS) {
          wait()
          stalledTicks = 0
          return out
        }
      } else if (roomTicks === 0 && boxedIn && Math.abs(self.speedMS) < T.recovery.stalledMS && !closeBehind) {
        roomTicks = 1
        passSide = 0
        passCar = -1
      } else if (roomTicks > 0) {
        const enough = blockGapM >= T.traffic.roomBackToM + T.traffic.roomPerAsideM * toMoveOverM
        roomTicks = enough || closeBehind || roomTicks >= T.traffic.roomMostS / DT || self.surface === 'grass' ? 0 : roomTicks + 1
      }
      if (roomTicks > 0) {
        // Held at a standstill the brake is reverse. It backs straight along the line, so as to keep whatever it
        // has gained to the side: going backward, wheels turned one way bring the nose round the other.
        out.throttle = 0
        out.brake = T.traffic.roomBrake
        out.steer = clamp(-facing * T.traffic.roomStraightenPerRad, -1, 1)
        stalledTicks = 0
        return out
      }

      // Trying to move and not moving: the car is against something. Back away.
      if (Math.abs(self.speedMS) < T.recovery.stalledMS && wantedMS > T.recovery.tryingMS) stalledTicks++
      else stalledTicks = 0
      if (stalledTicks >= T.recovery.stalledS / DT) {
        stalls = Math.abs(ahead(stalledAtS, s)) < T.recovery.samePlaceM ? stalls + 1 : 1
        stalledAtS = s
        mode = backUp(BACKING_OFF)
        moveTicks = 0
        stalledTicks = 0
        passSide = 0
        passCar = -1
      }
      return out
    },

    hashInto(buffer) {
      buffer.push(ticks, drivingSinceTick, mode, turnDir, moveTicks, stalledTicks, stalls, stalledAtS, offsetM, passSide, passCar, passTicks, heldTicks, lastIndex, lateM, earlyM, zonesToMistake, accidentInTicks, earlyDue ? 1 : 0, shakenTicks, profileGrip, joiningM, roomTicks, missedBraking ? 1 : 0, squeezeTicks, builtTick, builds)
      judgement.hashInto(buffer)
      // Only a driver with a pit stop to make has anything more to remember (F-306).
      if (pitPlan !== null) buffer.push(pitPlan.lap, pitting ? 1 : 0)
    },
  }
}
