import { clamp, DT, type Rng, type Vec2 } from '../core'
import { wetGripFactor } from '../weather/coupling'
import type { DriverProfile } from './driver'
import { AI_TUNING } from './tuning'

// What a driver makes of the weather (F-604). The session tells every driver the truth: the grip of the racing
// line as it is, where the puddles are, the wind. A driver does not drive to the truth but to what it believes,
// which is the truth with an error of its own: slow to change, larger the less skill it has, and leaning the way
// of its temperament. On a dry track there is nothing to misjudge, and every driver believes exactly what is so.

/** The weather as a driver is told it, each tick. */
export interface Conditions {
  /** The racing line's wetness, 0..1. */
  lineWetness: number
  /** The wetness of the surface off the line, 0..1: the pit lane's, and what a car has under it once it is well off its line. */
  wetness: number
  /** The puddles as the snapshot has them: dry ones are there too, with no depth. */
  puddles: ReadonlyArray<{ readonly x: number; readonly y: number; readonly r: number; readonly depth: number }>
  /** m/s, world frame: the way the air moves. */
  wind: Readonly<Vec2>
}

const C = AI_TUNING.conditions
/** What soaked asphalt keeps of its dry grip. */
const SOAKED_GRIP = wetGripFactor('asphalt', 1)
const JUDGE_TICKS = Math.round(C.judgeEveryS / DT)

/** The grip of asphalt at a wetness, 1 being dry: what the cars' tyres have on the racing line at the line's wetness, and off it at the surface's (F-602). */
export function lineGrip(lineWetness: number): number {
  return wetGripFactor('asphalt', lineWetness)
}

/** One driver's judgement of the grip. Everything it remembers is in `hashInto`. */
export interface GripJudgement {
  /** One tick: the grip the driver believes the line has, given what it truly has. */
  judge(trueGrip: number): number
  /** As last judged: how much more grip it believes the line has than it has, as a share of it. Nothing or less for a driver who has it right or is careful; nothing on a dry track. */
  readonly hopeful: number
  /** It has felt what grip there is: its error is gone, and drifts off again from there. */
  learn(): void
  hashInto(buffer: number[]): void
}

/**
 * A driver's judgement. Its error is a share of the grip, wandering about the lean of its temperament and pulled
 * back toward it, with a spread of `errorSpread × (1 − skill)`; it is drawn anew every `judgeEveryS`, from `rng`,
 * which is the driver's own. It counts in proportion to how much of the dry grip the water has taken, so that it is
 * nothing on a dry track and whole on a soaked one. The rain specialist's error is halved, and it finds a little
 * more grip in the wet than there is on the line: that grip is real, and no part of how `hopeful` it is.
 */
export function createGripJudgement(profile: Pick<DriverProfile, 'temperament'>, skill: number, rng: Rng): GripJudgement {
  const lean = C.lean[profile.temperament]
  const specialist = profile.temperament === 'rain-specialist'
  const spread = C.errorSpread * (1 - skill) * (specialist ? C.specialistErrorShare : 1)
  // How much of the last error is kept at each new judgement, and how much new is added, for a steady spread.
  const kept = Math.exp(-C.judgeEveryS / C.errorHoldS)
  const fresh = Math.sqrt(1 - kept * kept)
  let error = 0
  let sinceTicks = JUDGE_TICKS
  let draws = 0
  let hopeful = 0
  return {
    get hopeful() {
      return hopeful
    },
    learn() {
      error = 0
    },
    judge(trueGrip) {
      if (++sinceTicks >= JUDGE_TICKS) {
        sinceTicks = 0
        draws++
        // The sum of three uniform numbers is near enough a bell: its spread is half of one.
        const bell = (rng.next() + rng.next() + rng.next() - 1.5) * 2
        error = kept * error + fresh * spread * bell
      }
      hopeful = 0
      if (trueGrip >= 1) return 1
      const lost = clamp((1 - trueGrip) / (1 - SOAKED_GRIP), 0, 1)
      const found = specialist ? C.specialistGripBonus * (1 - trueGrip) : 0
      hopeful = (lean * (1 - skill) + error) * lost
      return clamp(trueGrip * (1 + hopeful) + found, C.leastGrip, 1)
    },
    hashInto(buffer) {
      buffer.push(error, sinceTicks, draws, hopeful)
    },
  }
}
