import { TICK_RATE, type Pose, type Tick } from '../core'
import type { TrackRuntime } from '../track'
import type { ControlInput } from './controls'
import { startTickOf } from './phases'
import { RULES } from './rules'
import type { SessionKind } from './types'

// The mandatory pit stop (F-306). A class may make its cars owe pit stops in a final: `CarClass.mandatoryPitStops`,
// which the session is handed as a number and never looks up by class. A car that owes one and comes into the stop
// zone of the track's pit lane has its pedals taken from its driver and is braked until it is at rest: in the zone
// at the pit lane's own pace, beyond its end if it came in faster than its brakes can stop it there. Where it comes
// to rest it is held for `RULES.pitHoldS`, then released with the stop counted. Driving through the pit lane
// without coming into the zone serves nothing, and a car that owes no stop is never touched. This file holds what
// that rule is made of; the session applies it.

/** How long a car is held for its stop, in ticks. */
export const PIT_HOLD_TICKS = Math.round(RULES.pitHoldS * TICK_RATE)
/** How long a car has, in ticks, to take its centre out of the stop zone once it is released from its stop (F-309). */
export const PIT_LEAVE_TICKS = Math.round(RULES.pitLeaveS * TICK_RATE)
/** A car that is to be warned that the pit is taken is told on every tick that is a multiple of this (F-309). */
export const PIT_WARN_EVERY_TICKS = Math.round(RULES.pitWarnEveryS * TICK_RATE)

/**
 * How many pit stops each car of a session owes as it starts: the class's number in a final on a track that has a
 * pit lane to make them in, and none anywhere else.
 */
export function pitStopsOwedIn(kind: SessionKind, track: TrackRuntime, mandatoryPitStops: number): number {
  if (kind !== 'final' || track.data.pitLane === undefined) return 0
  return Number.isFinite(mandatoryPitStops) ? Math.max(0, Math.floor(mandatoryPitStops)) : 0
}

/**
 * Whether a car's centre is in the stop zone: in the pit lane, within the pit route's width of it, between the
 * zone's two ends along it. `lane` is the lane the session has the car in, which is the lap's wherever the two
 * lanes share their asphalt.
 */
export function inStopZone(track: TrackRuntime, lane: 'lap' | 'pit', at: Readonly<Pick<Pose, 'x' | 'y'>>): boolean {
  const zone = track.data.pitLane?.stopZone
  if (zone === undefined || lane !== 'pit') return false
  const onPit = track.nearestPitRoute(at.x, at.y)
  return onPit !== null && Math.abs(onPit.lateralM) <= onPit.halfWidthM && onPit.s >= zone.fromS && onPit.s <= zone.toS
}

/**
 * Whether a car on the lap is coming to the pit entry (F-309): within `RULES.pitWarnM` short of it along the lap,
 * or no further past it than `pastM`, which is how far the pit route runs in the lap's own lane before the pit
 * lane is a lane of its own.
 */
export function nearingPitEntry(track: TrackRuntime, routeS: number, pastM: number): boolean {
  const pit = track.data.pitLane
  if (pit === undefined) return false
  const lapM = track.lengthM
  const ahead = (((pit.entryS - routeS) % lapM) + lapM) % lapM
  const toEntryM = ahead > lapM / 2 ? ahead - lapM : ahead
  return toEntryM <= RULES.pitWarnM && toEntryM >= -pastM
}

/**
 * Takes the pedals from the driver of a car that is to be stopped, leaving it the steering: full brake while it
 * rolls forward, and the throttle against it while it rolls backward, where the brake would be reverse. Nothing
 * at all once it is as good as still, so that a brake held at rest never becomes reverse.
 */
export function brakeToRest(input: ControlInput, speedAlongMS: number): void {
  input.throttle = speedAlongMS < -RULES.pitRestMS ? 1 : 0
  input.brake = speedAlongMS > RULES.pitRestMS ? 1 : 0
}

/**
 * The lap's route beside a place of the pit lane, as a distance along it to look for the route near: as far along
 * the stretch the pit lane bypasses as the place is along the pit route. The nearest point of the whole lap to a
 * place in the pit lane may be on another part of the track altogether.
 */
export function lapBesidePit(track: TrackRuntime, pitS: number): number {
  const pit = track.data.pitLane
  if (pit === undefined || track.pitLengthM <= 0) return 0
  const lapM = track.lengthM
  const bypassedM = (((pit.exitS - pit.entryS) % lapM) + lapM) % lapM
  return pit.entryS + (pitS / track.pitLengthM) * bypassedM
}

/** What is left of a hold that began at the end of tick `sinceTick`, s, as tick `tick` ends. */
export function pitHoldRemainingS(sinceTick: Tick, tick: Tick): number {
  return Math.max(0, (PIT_HOLD_TICKS - (tick - sinceTick)) / TICK_RATE)
}

/**
 * The tick at whose end the clock of a final of `durationS` reads `RULES.pitReminderAtS`: when the cars that still
 * owe a stop are reminded. Null for a final no longer than that, which never has more on its clock.
 */
export function pitReminderTickOf(durationS: number): Tick | null {
  if (!Number.isFinite(durationS) || durationS <= RULES.pitReminderAtS) return null
  return startTickOf('final') + Math.round((durationS - RULES.pitReminderAtS) * TICK_RATE)
}
