import { wrapAngle } from '../core'
import type { Pose } from '../core'
import { closestOnPolyline, cumulativeLengths, type Vertex } from './geometry'
import { buildPitRoute, buildRoute } from './route'
import type { Direction, PitLane, TrackData } from './types'

/**
 * The same track raced the other way (contracts.md §4). The route is reversed, still starting on the timing
 * line; every start slot stays on its painted mark and turns to face the other way; the slots of each set are
 * listed frontmost first along the new direction of travel; the sector fractions are mirrored. The pit route is
 * reversed too, so that its entry is where its exit was; the pit blocks keep their numbers and their parked
 * poses. No other geometry changes. Returns `data` itself when the direction already matches.
 */
export function orientTrack(data: TrackData, direction: Direction): TrackData {
  if (data.direction === direction) return data

  const [first, ...rest] = data.route.points
  const points = [first, ...rest.reverse()]
  const [a, b] = data.timing.sectorFractions
  const turned: TrackData = {
    ...data,
    direction,
    route: { points, closed: true },
    timing: { line: data.timing.line, sectorFractions: [1 - b, 1 - a] },
    grid: turnRound(data.grid, points),
    staggerStart: turnRound(data.staggerStart, points),
  }
  return data.pitLane ? { ...turned, pitLane: reversePitLane(data.pitLane, buildRoute(data).length) } : turned
}

/**
 * The pit lane entered from its other end. A distance along the lap becomes the lap's length less itself, since
 * the reversed lap starts at the same point; a distance along the pit route, the pit route's length less itself.
 */
function reversePitLane(pit: PitLane, lapLength: number): PitLane {
  const pitLength = buildPitRoute(pit.route).length
  const alongLap = (s: number): number => (((lapLength - s) % lapLength) + lapLength) % lapLength
  return {
    route: [...pit.route].reverse(),
    entryS: alongLap(pit.exitS),
    exitS: alongLap(pit.entryS),
    blocks: pit.blocks,
    stopZone: { fromS: pitLength - pit.stopZone.toS, toS: pitLength - pit.stopZone.fromS },
  }
}

/** Turn each slot to face the other way and order the set by distance along the route, furthest ahead first. */
function turnRound(slots: readonly Pose[], route: readonly Vertex[]): Pose[] {
  const lengths = cumulativeLengths(route, true)
  const lap = lengths[route.length]
  const progress = slots.map((slot) => {
    const hit = closestOnPolyline(slot.x, slot.y, route, true)
    return lengths[hit.segment] + hit.t * (lengths[hit.segment + 1] - lengths[hit.segment])
  })
  // A set of slots is one group on one stretch of the lap. Measure each from the first, the short way round, so
  // that a group lying across the start of the lap is not split into its two ends.
  const ahead = progress.map((s) => {
    const fromFirst = (((s - progress[0]) % lap) + lap) % lap
    return fromFirst > lap / 2 ? fromFirst - lap : fromFirst
  })
  return slots
    .map((slot, index) => ({ slot, index }))
    .sort((p, q) => ahead[q.index] - ahead[p.index] || p.index - q.index)
    .map(({ slot }) => ({ x: slot.x, y: slot.y, angle: wrapAngle(slot.angle + Math.PI) }))
}
