import type { Vec2 } from '../core'
import type { TrackRuntime } from '../track'

// Cutting the track (F-309). A car that drives across a green island, from the lane on one side of it onto a lane
// on the far side, has cut the track: however thin the island is there, and however little is gained by it. A car
// that goes onto an island and comes back over the edge it left has not. This file holds what that is judged with;
// the session follows each car's excursion and gives the penalty.
//
// - **Where the lane ends**, beside an island, is where the surfaces say its grass begins: the island's own outline,
//   with no grace band. An island narrower than twice the grace band is never "grass" to the ground under a car
//   (F-207), and is an island all the same. Beside the surround the lane ends where it always did: a car has left it
//   once the surfaces read grass under it, past the band, and the edge it left is the nearest one.
// - **The far side** is told from the two places where the car's centre crossed the island's edge, out and back:
//   which way the lane lies from each, towards its own centre line. Back over the edge it left, the lane lies the
//   same way at both. Across the island, the two lanes lie on opposite sides of the grass. Round a tip, the lane
//   turns about the island: it is the far side once the lane at the place it came back lies more than a quarter
//   turn from the lane at the place it left. And the grass must lie between the two: a car that runs wide round the
//   outside of a hairpin comes back to a lane that lies the other way, but the straight line from where it left to
//   where it came back leads over that lane, not away from it.
// - **The grace band** still counts for something. A car has been on the island beyond the band if its centre was
//   ever further than the band's width from every lane (the grass of F-207): at the tip of an island as anywhere.
//   An island too thin for that is crossed all the same where it is a strip between two lanes: the grass is thicker
//   than the band behind both edges, and no lane's edge runs alongside the car's line within the band. Where one
//   does, the car has not left the band of the lane's edge, whatever is under it: that is the end of a tip, which
//   the lane's edge goes round with the car. And a strip thinner than the band is a painted double line.
// - **Forward** is the one thing the lap's distances are asked for: a car that comes out behind where it went in
//   has not cut the track. A point of the asphalt belongs to the stretch of the lap whose centre line it can reach
//   in a straight line without crossing grass: across a thin island the nearest piece of the route may be the lane
//   the car has just left.

/** A place on one of a track's two lanes: metres round the lap from the line, or metres along the pit route. */
export interface LanePlace {
  lane: 'lap' | 'pit'
  at: number
}

/** How finely a straight line is looked along for grass, m. */
const LOOK_STEP_M = 0.04
/** The lap's route is first looked at this often, m, for the stretches near a point. */
const COARSE_STEP_M = 0.5
/** A stretch of the lap further than this from a point is not the one the point is on, m: no lane is half as wide. */
const REACH_M = 4
/** Two answers nearer than this along the lap are one stretch, m. */
const SAME_STRETCH_M = 0.2
/**
 * The route is asked for its nearest point about a sample of it, and looks a couple of metres either way. An answer
 * further than this from the sample, m, is the end of where it looked and not a nearest point: another sample has that stretch.
 */
const ABOUT_M = 1.5
/**
 * A pit lane's half-width is the distance from its route to the nearer of its two edges. A point of its asphalt at
 * its other edge is this much further out at most, m.
 */
const PIT_EDGE_M = 0.15

/** A distance round the lap, the short way: from half a lap back to half a lap on. */
function wrapped(distanceM: number, lapM: number): number {
  const turns = ((distanceM % lapM) + lapM) % lapM
  return turns > lapM / 2 ? turns - lapM : turns
}

/** Whether a point is on the grass, by the surfaces' own outlines: no grace band. */
export function isGrass(track: TrackRuntime, x: number, y: number): boolean {
  return track.surfaceAt(x, y) === 'grass'
}

/** Whether the straight line between two points keeps off the grass. */
export function clearOfGrass(track: TrackRuntime, from: Readonly<Vec2>, to: Readonly<Vec2>): boolean {
  const lengthM = Math.hypot(to.x - from.x, to.y - from.y)
  const steps = Math.max(1, Math.ceil(lengthM / LOOK_STEP_M))
  for (let i = 0; i <= steps; i++) {
    const f = i / steps
    if (isGrass(track, from.x + (to.x - from.x) * f, from.y + (to.y - from.y) * f)) return false
  }
  return true
}

/**
 * Where on the lap a point of the asphalt is: the nearest point of the route that can be reached from it in a
 * straight line without crossing grass. Where no stretch within reach can, the nearest point of the route.
 */
export function lapPlaceOf(track: TrackRuntime, at: Readonly<Vec2>): ReturnType<TrackRuntime['nearestRoute']> {
  const lapM = track.lengthM
  const count = Math.ceil(lapM / COARSE_STEP_M)
  const tried: number[] = []
  let best: ReturnType<TrackRuntime['nearestRoute']> | null = null
  for (let k = 0; k < count; k++) {
    const s = (k * lapM) / count
    const coarse = track.routePose(s)
    if (Math.hypot(coarse.x - at.x, coarse.y - at.y) > REACH_M) continue
    // The nearest of the route on the stretch about this sample; one stretch is asked about once.
    const near = track.nearestRoute(at.x, at.y, s)
    if (Math.abs(wrapped(near.s - s, lapM)) > ABOUT_M || tried.some((other) => Math.abs(wrapped(near.s - other, lapM)) < SAME_STRETCH_M)) continue
    tried.push(near.s)
    if (best !== null && Math.abs(near.lateralM) >= Math.abs(best.lateralM)) continue
    if (clearOfGrass(track, at, track.routePose(near.s))) best = near
  }
  return best ?? track.nearestRoute(at.x, at.y)
}

/**
 * Which lane a point of the asphalt is on, and where. The lap, within the lap's own half-width of it. Otherwise
 * the pit lane, where the pit lane is a lane of its own and the point is on it. Otherwise the lap: asphalt that
 * is wider than the lane is still the lap's.
 */
export function lanePlaceOf(track: TrackRuntime, at: Readonly<Vec2>): LanePlace {
  const lap = lapPlaceOf(track, at)
  if (Math.abs(lap.lateralM) <= lap.halfWidthM) return { lane: 'lap', at: lap.s }
  const pit = track.nearestPitRoute(at.x, at.y)
  if (pit !== null && Math.abs(pit.lateralM) <= pit.halfWidthM + PIT_EDGE_M) {
    const centre = track.pitRoutePose(pit.s)
    if (centre !== null && track.inPitLane(centre.x, centre.y) && clearOfGrass(track, at, centre)) return { lane: 'pit', at: pit.s }
  }
  return { lane: 'lap', at: lap.s }
}

/**
 * How much further round the track `to` is than `from`, m, the short way: more than nothing is forward, less is
 * back, and what is forward one way is back the other. Between two places of the lap it is the distance along the
 * route, and between two of the pit lane the distance along that. The pit lane leaves the lap at its entry and
 * rejoins it at its exit, and is not the same length as the stretch it bypasses: a place in its first half is as
 * far round as the lap is the same distance on from the entry, and a place in its second half as far round as the
 * lap is the same distance short of the exit. Each end of the pit lane is measured against the lap that lies beside it.
 */
export function furtherRoundM(track: TrackRuntime, from: Readonly<LanePlace>, to: Readonly<LanePlace>): number {
  if (from.lane === 'pit' && to.lane === 'pit') return to.at - from.at
  return wrapped(roundLapOf(track, to) - roundLapOf(track, from), track.lengthM)
}

/** How far round the lap a place is, m from the line: for a place in the pit lane, the place of the lap that is as far round. */
function roundLapOf(track: TrackRuntime, place: Readonly<LanePlace>): number {
  const pit = track.data.pitLane
  if (place.lane === 'lap' || pit === undefined) return place.at
  return place.at < track.pitLengthM / 2 ? pit.entryS + place.at : pit.exitS - (track.pitLengthM - place.at)
}

// ── The edge of the lane, and which way the lane lies from it ───────────────────────────────────────────────────

/** The place where a lane ends is found to this, m. */
const EDGE_FOUND_TO_M = 0.001
/** Which way the lane lies from a point of its edge is read off a ring of this radius round the point, m, at this many places. */
const RING_M = 0.03
const RING_POINTS = 16
/** A place on the lane beside a point of its edge: this far in from the edge, m. */
const IN_FROM_EDGE_M = 0.03

/** The point where the lane ends on the straight line from `lane`, which is on a lane, to `grass`, which is on the grass. */
export function edgeBetween(track: TrackRuntime, lane: Readonly<Vec2>, grass: Readonly<Vec2>): Vec2 {
  let onLane = 0
  let onGrass = 1
  const lengthM = Math.hypot(grass.x - lane.x, grass.y - lane.y)
  while ((onGrass - onLane) * lengthM > EDGE_FOUND_TO_M) {
    const middle = (onLane + onGrass) / 2
    if (isGrass(track, lane.x + (grass.x - lane.x) * middle, lane.y + (grass.y - lane.y) * middle)) onGrass = middle
    else onLane = middle
  }
  return { x: lane.x + (grass.x - lane.x) * onLane, y: lane.y + (grass.y - lane.y) * onLane }
}

/**
 * The lane's edge nearest a point of the grass is looked for on rings about the point, this much wider each time, m,
 * at this many places, from as far out as the nearest thing that is not grass to this much further.
 */
const NEAREST_STEP_M = 0.02
const NEAREST_POINTS = 32
const NEAREST_FURTHER_M = 0.5

/**
 * The point of a lane's edge nearest to `at`, which is on the grass: for a car that has just passed the grace band
 * of the edge it left, that edge. A seam where two pieces of grass meet is no lane. `at` itself where no lane is
 * to be found.
 */
export function nearestLaneEdge(track: TrackRuntime, at: Readonly<Vec2>): Vec2 {
  const nearestM = track.distanceOffLane(at.x, at.y)
  for (let reachM = nearestM + NEAREST_STEP_M; reachM <= nearestM + NEAREST_FURTHER_M; reachM += NEAREST_STEP_M) {
    let x = 0
    let y = 0
    for (let i = 0; i < NEAREST_POINTS; i++) {
      const angle = (i * 2 * Math.PI) / NEAREST_POINTS
      const place = { x: at.x + reachM * Math.cos(angle), y: at.y + reachM * Math.sin(angle) }
      if (isGrass(track, place.x, place.y) || onASeam(track, place)) continue
      x += Math.cos(angle)
      y += Math.sin(angle)
    }
    const length = Math.hypot(x, y)
    if (length < 1e-9) continue
    const lane = { x: at.x + (x / length) * reachM, y: at.y + (y / length) * reachM }
    if (!isGrass(track, lane.x, lane.y) && !onASeam(track, lane)) return edgeBetween(track, lane, at)
  }
  return { x: at.x, y: at.y }
}

/**
 * Asphalt on fewer than this many of the ring's places is no lane: a seam where two pieces of grass meet, or a
 * sliver between them that no car is on.
 */
const LANE_PLACES = 3

/**
 * Which way the asphalt lies from a point of its edge: a unit vector, square to the edge there. Null for a point
 * with no lane, or nothing but lane, about it.
 */
export function laneSideAt(track: TrackRuntime, edge: Readonly<Vec2>): Vec2 | null {
  let x = 0
  let y = 0
  let places = 0
  for (let i = 0; i < RING_POINTS; i++) {
    const angle = (i * 2 * Math.PI) / RING_POINTS
    if (isGrass(track, edge.x + RING_M * Math.cos(angle), edge.y + RING_M * Math.sin(angle))) continue
    x += Math.cos(angle)
    y += Math.sin(angle)
    places++
  }
  const length = Math.hypot(x, y)
  return places < LANE_PLACES || length < 1e-9 ? null : { x: x / length, y: y / length }
}

/** Whether a point that is not on the grass is on no lane either: grass all about it, but for a seam. */
export function onASeam(track: TrackRuntime, at: Readonly<Vec2>): boolean {
  let places = 0
  for (let i = 0; i < RING_POINTS && places < LANE_PLACES; i++) {
    const angle = (i * 2 * Math.PI) / RING_POINTS
    if (!isGrass(track, at.x + RING_M * Math.cos(angle), at.y + RING_M * Math.sin(angle))) places++
  }
  return places < LANE_PLACES
}

/** What the cut rule knows of a point where a lane ends and the grass begins. */
export interface EdgePoint {
  at: Vec2
  /** Which way the asphalt lies from it, square to the edge there: a unit vector. */
  side: Vec2
  /** The place on a lane that is beside it. */
  place: LanePlace
  /** Which way that lane lies from it: towards the lane's centre line at that place, a unit vector. */
  lane: Vec2
}

/** What is known of the point `at` of a lane's edge. Null for a point with no lane, or nothing but lane, about it. */
export function edgePointAt(track: TrackRuntime, at: Readonly<Vec2>): EdgePoint | null {
  const side = laneSideAt(track, at)
  if (side === null) return null
  const place = lanePlaceOf(track, { x: at.x + side.x * IN_FROM_EDGE_M, y: at.y + side.y * IN_FROM_EDGE_M })
  const centre = place.lane === 'lap' ? track.routePose(place.at) : (track.pitRoutePose(place.at) ?? track.routePose(place.at))
  const awayM = Math.hypot(centre.x - at.x, centre.y - at.y)
  // A centre line that runs along the very edge of its lane tells nothing of which way the lane lies: the edge does.
  const lane = awayM < IN_FROM_EDGE_M ? side : { x: (centre.x - at.x) / awayM, y: (centre.y - at.y) / awayM }
  return { at: { x: at.x, y: at.y }, side, place, lane }
}

/**
 * The straight line from where a car left a lane to where it came back leads over the grass between two lanes if it
 * leads away from the first and towards the second. It need not be square to either, and a lane's centre line is
 * not always square to its edge: the line may lean this far the wrong way, as a share of its length, and no further.
 * Half is thirty degrees. The line of a car that ran wide round the outside of a bend and came back to a lane that
 * lies the other way leans seven tenths and more.
 */
const LEAN = 0.5

/** Whether the lanes at two points of an island's edge lie on opposite sides of the grass between them. */
export function onFarSides(out: Readonly<EdgePoint>, back: Readonly<EdgePoint>): boolean {
  const x = back.at.x - out.at.x
  const y = back.at.y - out.at.y
  const lengthM = Math.hypot(x, y)
  return out.lane.x * back.lane.x + out.lane.y * back.lane.y < 0 && x * out.lane.x + y * out.lane.y < LEAN * lengthM && x * back.lane.x + y * back.lane.y > -LEAN * lengthM
}

/** "Behind" a point of a lane's edge is looked at along this many lines either side of straight back from the asphalt, this far apart, rad: an eighth of a turn each way. */
const BEHIND_LINES = 3
const BEHIND_STEP_RAD = Math.PI / 12

/**
 * Whether the grass is thicker than `graceM` behind a point of a lane's edge: it goes on that far straight back
 * from the asphalt, and along every line up to an eighth of a turn either side of that. Across a strip it is as
 * thick as the strip is wide, however the car came over it. At the last of a tip it is not.
 */
function grassBehind(track: TrackRuntime, edge: Readonly<EdgePoint>, graceM: number): boolean {
  const { at, side } = edge
  const straightBack = Math.atan2(-side.y, -side.x)
  for (let line = -BEHIND_LINES; line <= BEHIND_LINES; line++) {
    const x = Math.cos(straightBack + line * BEHIND_STEP_RAD)
    const y = Math.sin(straightBack + line * BEHIND_STEP_RAD)
    if (!isGrass(track, at.x + x * graceM, at.y + y * graceM) || !isGrass(track, at.x + (x * graceM) / 2, at.y + (y * graceM) / 2)) return false
  }
  return true
}

/** A lane's edge is alongside a car's line if it is no further from it than the grace band and this much, m, at each of these shares of the line's length. */
const ALONGSIDE_MARGIN_M = 0.02
const ALONGSIDE_AT: readonly number[] = [0.25, 0.5, 0.75]

/**
 * Whether a lane's edge runs alongside the straight line from where a car left the lane to where it came back,
 * within the grace band of that line all the way and on one side of it: round the end of a tip, which the lane's
 * edge goes round with the car. Told by walking the asphalt beside the line, from the lane at one end of it to the
 * lane at the other, without crossing grass. Beside a line over a strip between two lanes there is no such way:
 * the asphalt within the band is one lane's or the other's, and the grass lies between.
 */
export function edgeRunsAlongside(track: TrackRuntime, out: Readonly<EdgePoint>, back: Readonly<EdgePoint>, graceM: number): boolean {
  const x = back.at.x - out.at.x
  const y = back.at.y - out.at.y
  const lengthM = Math.hypot(x, y)
  if (lengthM < 1e-9) return true
  const start = { x: out.at.x + out.side.x * IN_FROM_EDGE_M, y: out.at.y + out.side.y * IN_FROM_EDGE_M }
  const end = { x: back.at.x + back.side.x * IN_FROM_EDGE_M, y: back.at.y + back.side.y * IN_FROM_EDGE_M }
  const asideM = graceM + ALONGSIDE_MARGIN_M
  for (const hand of [1, -1]) {
    const asideX = ((-y / lengthM) * hand) * asideM
    const asideY = ((x / lengthM) * hand) * asideM
    let from = start
    let alongside = true
    for (const share of ALONGSIDE_AT) {
      const beside = { x: out.at.x + x * share + asideX, y: out.at.y + y * share + asideY }
      if (isGrass(track, beside.x, beside.y) || !clearOfGrass(track, from, beside)) {
        alongside = false
        break
      }
      from = beside
    }
    if (alongside && clearOfGrass(track, from, end)) return true
  }
  return false
}

/** A crossing of the grass from one edge of it to another, as the cut rule judges it. */
export interface Crossing {
  /** The lane the car came back to lies on the far side of the grass from the lane it left, and the car has been beyond the grace band. */
  farSide: boolean
  /** Where on the lanes the car left and came back; null where an edge has no lane about it. */
  left: LanePlace | null
  back: LanePlace | null
}

/**
 * What a car did that left a lane at the edge point `out` and came back onto one at the edge point `back`. It is
 * on the far side if the two lanes lie on opposite sides of the grass, and the car has been beyond the grace band:
 * `pastBand` says that its centre was further than `graceM` from every lane on the way. Failing that, the grass
 * must be thicker than `graceM` behind both edges, and no lane's edge may run alongside the car's line within the band.
 */
export function crossingOf(track: TrackRuntime, out: Readonly<Vec2>, back: Readonly<Vec2>, graceM: number, pastBand: boolean): Crossing {
  const to = edgePointAt(track, back)
  return to === null ? { farSide: false, left: null, back: null } : crossingBetween(track, edgePointAt(track, out), to, graceM, pastBand)
}

/** As `crossingOf`, of the two edge points themselves; `from` is null where the car left no lane's edge. */
export function crossingBetween(track: TrackRuntime, from: Readonly<EdgePoint> | null, to: Readonly<EdgePoint>, graceM: number, pastBand: boolean): Crossing {
  if (from === null) return { farSide: false, left: null, back: to.place }
  const farSide = onFarSides(from, to) && (pastBand || (grassBehind(track, from, graceM) && grassBehind(track, to, graceM) && !edgeRunsAlongside(track, from, to, graceM)))
  return { farSide, left: from.place, back: to.place }
}

/** Whether a crossing is a cut: onto a lane on the far side, further round than the place it left. */
export function isCut(track: TrackRuntime, crossing: Readonly<Crossing>): boolean {
  return crossing.farSide && crossing.left !== null && crossing.back !== null && furtherRoundM(track, crossing.left, crossing.back) > 0
}
