import type { Pose, Vec2 } from '../core'
import type { TimingGate, TimingGates, TrackRuntime } from '../track'

// Where a stricken car is set back (F-207): on the lane it left, the lap or the pit lane. It was written for the
// stand-in for the marshals; the marshals (F-502) set a car down by the same rule, and keep clear of each other too.

/** How far along the lane the next place is tried when the first is taken. */
const SEARCH_STEP_M = 0.25
/** How far clear of a timing gate a car is set down, so that there is no doubt which side of it its centre is on. */
const GATE_CLEAR_M = 0.1
/** A car found within this far round the lap beyond the gate its lap has next to cross, m, went by that gate off the lane: no further than a car slides on the grass. */
const SLID_PAST_M = 3

/** One of a track's two lanes: the lap, or the pit lane beside it. */
export type Lane = 'lap' | 'pit'

/** What the lap in progress has done so far, as lap timing keeps it. */
export interface LapProgress {
  /** The car has crossed the line at least once: there is a lap in progress. */
  started: boolean
  /** That lap can still count. */
  valid: boolean
  /** How many of the two sector points it has passed. */
  nextSector: 0 | 1 | 2
}

/** Where a stuck car is set back. */
export interface SetBack {
  pose: Pose
  /** Metres along the lap of the place: on the lap itself, or of the lap's route beside the pit lane. */
  routeS: number
  lane: Lane
}

/**
 * Which lane a car's centre is in, given where the lap's route is from it (`onRoute`, the session's own answer for
 * this tick) and which lane it was last in (`was`). Within the lap's half-width of the lap's route it is the lap,
 * which settles the stretches where the pit route still runs inside the lap's own lane. Otherwise, within the
 * pit route's half-width of the pit route, it is the pit lane. Anywhere else — on grass, on a kerb's far side, on
 * asphalt that is wider than either lane, in the air — it has not changed lanes, and the answer is `was`.
 */
export function laneUnder(track: TrackRuntime, pose: Readonly<Pose>, onRoute: { lateralM: number; halfWidthM: number }, was: Lane): Lane {
  if (Math.abs(onRoute.lateralM) <= onRoute.halfWidthM) return 'lap'
  const onPit = track.nearestPitRoute(pose.x, pose.y)
  return onPit !== null && Math.abs(onPit.lateralM) <= onPit.halfWidthM ? 'pit' : was
}

/** What a car is set down clear of: the other cars, each by `clearM` from centre to centre, and the marshals who are out (F-502), each by `marshalClearM`. */
export interface KeepClear {
  cars: ReadonlyArray<Readonly<Vec2>>
  clearM: number
  marshals?: ReadonlyArray<Readonly<Vec2>>
  marshalClearM?: number
}

/** The first place from `fromS` on, in quarter-metre steps up to `tries` of them, that is clear of every car and every marshal. */
function firstClear(fromS: number, tries: number, poseAt: (s: number) => Pose | null, clear: KeepClear): { pose: Pose; s: number } | null {
  const marshals = clear.marshals ?? []
  const marshalClearM = clear.marshalClearM ?? clear.clearM
  for (let i = 0; i < tries; i++) {
    const s = fromS + i * SEARCH_STEP_M
    const pose = poseAt(s)
    if (pose === null) return null
    if (clear.cars.every((other) => Math.hypot(other.x - pose.x, other.y - pose.y) >= clear.clearM) && marshals.every((marshal) => Math.hypot(marshal.x - pose.x, marshal.y - pose.y) >= marshalClearM)) return { pose, s }
  }
  return null
}

/** On the lap, from `fromS` on round: the rule a track with no pit lane has always had. */
function ontoTheLap(fromS: number, clear: KeepClear, track: TrackRuntime): { pose: Pose; routeS: number } {
  const tries = Math.max(1, Math.ceil(track.lengthM / SEARCH_STEP_M))
  const found = firstClear(fromS, tries, (s) => track.routePose(s), clear)
  // The whole lap is taken, which seven cars cannot do: the nearest place will have to serve.
  if (found === null) return { pose: track.routePose(fromS), routeS: fromS }
  return { pose: found.pose, routeS: found.s % track.lengthM }
}

/**
 * The place on the pit route, at `s` or further along, where a car can be set down without lap timing counting a
 * gate against it: past every pit gate that stands in for a place the lap in progress has already passed. Driving
 * over such a gate a second time would spoil the lap. A gate the lap has not reached is left where it is: a car
 * set down beyond one has been carried past a sector point, as it can be on the lap, and that lap will not count.
 */
function pastWhatItHasPassed(s: number, progress: LapProgress | undefined, gates: TimingGates | undefined, track: TrackRuntime): number {
  const pit = gates?.pit
  if (progress === undefined || pit === undefined || !progress.started || !progress.valid) return s
  let from = s
  const behind = (gate: TimingGate | null, passed: boolean): void => {
    if (gate === null || !passed) return
    const at = track.nearestPitRoute((gate.a.x + gate.b.x) / 2, (gate.a.y + gate.b.y) / 2)
    if (at !== null) from = Math.max(from, at.s + GATE_CLEAR_M)
  }
  // The line is behind a car until it has both sector points; a sector point is behind it once it is counted.
  behind(pit.line, progress.nextSector < 2)
  behind(pit.sectors[0], progress.nextSector >= 1)
  behind(pit.sectors[1], progress.nextSector >= 2)
  return from
}

/**
 * The place on the lap, at `s` or back from it, where a car can be set down without having been carried over the
 * timing gate its lap in progress has next to cross: the line, or a sector point. A car that left the lane just
 * short of such a gate and came to rest beyond it has not crossed it, and set down where it lies it never would:
 * the lap it was on could not count, nor, at the line, the whole lap it would drive next. It is set down just
 * short of the gate instead, and crosses it itself (F-604: one mistake at the last bend cost two laps of seven).
 * A car with no lap in progress, or one that is already lost, goes to the nearest place whatever the gates.
 */
function shortOfWhatIsNext(s: number, progress: LapProgress | undefined, gates: TimingGates | undefined, track: TrackRuntime): number {
  if (progress === undefined || gates === undefined || !progress.started || !progress.valid) return s
  const next = progress.nextSector === 2 ? gates.line : gates.sectors[progress.nextSector]
  const gateS = track.nearestRoute((next.a.x + next.b.x) / 2, (next.a.y + next.b.y) / 2).s
  const beyondM = (((s - gateS) % track.lengthM) + track.lengthM) % track.lengthM
  return beyondM < SLID_PAST_M ? (gateS - GATE_CLEAR_M + track.lengthM) % track.lengthM : s
}

/**
 * Where a stuck car is put back: on the centre of the lane it left, at rest, facing the way that lane runs. If
 * another car is within `clearM` of the place, or one of `marshals` within his own distance of it (F-502), the next
 * place a quarter of a metre further along the lane is tried, and so on.
 *
 * - **The lap**, for every car whose last lane was the lap (`car.lane`), and on every track with no pit lane. The
 *   point of the lap nearest the car on the stretch it was on: `car.routeS` is where it was last known to be, and
 *   a car stuck between two parts of the track goes back to the part it left, not to whichever is nearer. It is
 *   never set down beyond a timing gate that the lap it has in progress has next to cross and has not crossed:
 *   where it lies, that is. Asked `again` from a place this rule has already given (a marshal on his way with the
 *   car, F-508), the search for a clear place starts from that place itself, which may be beyond such a gate because
 *   the places short of it were taken, and gives it again unless a car or a marshal has come to stand in it.
 * - **The pit lane**, only for a car whose last lane was the pit lane: it was in the pit lane and went off beside
 *   it. The point of the pit route nearest the car; the car faces along the pit route, toward its exit. It is
 *   never set down short of a pit timing gate that the lap it has in progress (`car.progress`) has already
 *   passed, so that no gate is counted against it twice. Where the nearest of the pit route has already merged
 *   with the lap's own lane, and when no place in the pit lane is clear, it goes onto the lap instead.
 */
export function standInRecover(
  car: { pose: Readonly<Pose>; routeS: number; lane?: Lane; progress?: LapProgress; again?: boolean },
  others: ReadonlyArray<Readonly<Vec2>>,
  track: TrackRuntime,
  clearM: number,
  gates?: TimingGates,
  marshals?: { at: ReadonlyArray<Readonly<Vec2>>; clearM: number },
): SetBack {
  const clear: KeepClear = marshals === undefined ? { cars: others, clearM } : { cars: others, clearM, marshals: marshals.at, marshalClearM: marshals.clearM }
  const onLap = track.nearestRoute(car.pose.x, car.pose.y, car.routeS)
  const pitLane = track.data.pitLane
  const onPit = car.lane === 'pit' ? track.nearestPitRoute(car.pose.x, car.pose.y) : null
  const pitPlace = onPit === null ? null : track.pitRoutePose(onPit.s)
  if (pitLane === undefined || onPit === null || pitPlace === null || !track.inPitLane(pitPlace.x, pitPlace.y)) {
    return { ...ontoTheLap(car.again === true ? onLap.s : shortOfWhatIsNext(onLap.s, car.progress, gates, track), clear, track), lane: 'lap' }
  }

  const fromS = pastWhatItHasPassed(onPit.s, car.progress, gates, track)
  const tries = Math.floor((track.pitLengthM - fromS) / SEARCH_STEP_M) + 1
  const inThePits = (s: number): Pose | null => {
    const pose = track.pitRoutePose(s)
    return pose !== null && track.inPitLane(pose.x, pose.y) ? pose : null
  }
  const found = firstClear(fromS, tries, inThePits, clear)
  // No room left in the pit lane: onto the lap where the pit lane rejoins it.
  if (found === null) return { ...ontoTheLap(pitLane.exitS, clear, track), lane: 'lap' }
  // The lap's route beside that place: what a car that drove into the pit lane to there reports.
  const lap = track.lengthM
  const bypassedM = (((pitLane.exitS - pitLane.entryS) % lap) + lap) % lap
  const beside = pitLane.entryS + (found.s / track.pitLengthM) * bypassedM
  return { pose: found.pose, routeS: track.nearestRoute(found.pose.x, found.pose.y, beside).s, lane: 'pit' }
}
